window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["35519608"]={"book":{"id":35519608,"title":"非暴力沟通","author":"马歇尔·卢森堡 ","translator":"刘轶","publisher":"华夏出版社 ","pubdate":"2021-5","isbn":"9787522200514","tags":["沟通"],"memCount":null},"np":1,"pb":[45],"idx":[{"i":19936,"t":"思维转换的三步法","l":"TF2-2","c":"小魔女有点儿香","g":1,"p":1},{"i":19474,"t":"非暴力沟通四要素","l":"TF2-2","c":"东旭悦读","g":1,"p":1},{"i":19423,"t":"不得不变成我选择","l":"TF2-1","c":"张连英","g":1,"p":1},{"i":18932,"t":"解锁真诚表达的艺术","l":"TF2-2","c":"澄心","g":1,"p":1},{"i":18808,"t":"你知道感激的魅力吗？","l":"TF3-3","c":"余火说亲子","g":1,"p":1},{"i":18746,"t":"从“怒火中烧”到“心平气和”，解锁高情商沟通的终极密码  ","l":"TF2-1","c":"澄心","g":1,"p":1},{"i":18606,"t":"非暴力沟通四要素，探索和谐沟通的艺术","l":"TF1-2","c":"澄心","g":1,"p":1},{"i":18487,"t":"非暴力沟通的四要素","l":"TF2-1","c":"吴超","g":1,"p":1},{"i":18249,"t":"非暴力沟通","l":"TF1-1","c":"兴宝","g":1,"p":1},{"i":18125,"t":"和谐沟通的艺术：非暴力沟通四步法","l":"TF2-2","c":"冰冰Bella","g":1,"p":1},{"i":18005,"t":"非暴力沟通的四个要","l":"TF1-1","c":"天天学习","g":1,"p":1},{"i":17501,"t":"区分观察与评价，做有效沟通者","l":"TF3-1","c":"汤小敏","g":1,"p":1},{"i":17228,"t":"非暴力沟通化解冲突五步法","l":"TF2-1","c":"魏立","g":1,"p":1},{"i":17217,"t":"表达感激三要素","l":"TF1-1","c":"qixiyueya","g":1,"p":1},{"i":17181,"t":"表达愤怒的方法","l":"TF1-1","c":"刘雪","g":1,"p":1},{"i":16889,"t":"真诚感谢三步骤 夸到对方心坎里","l":"TF2-3","c":"长缨","g":1,"p":1},{"i":16846,"t":"非暴力沟通表达愤怒","l":"TF1-2","c":"彭丽","g":1,"p":1},{"i":16718,"t":"真诚感谢三步骤 夸到对方心坎里","l":"TF2-3","c":"长缨","g":1,"p":1},{"i":16693,"t":"用非暴力沟通表达感激，让生活更美好","l":"TF1-1","c":"向阳花","g":1,"p":1},{"i":16508,"t":"充分发达愤怒四步法","l":"TF1-1","c":"谢娜洁","g":1,"p":1},{"i":16428,"t":"真诚感谢三步骤 夸到对方心坎里","l":"TF2-3","c":"长缨","g":1,"p":1},{"i":16217,"t":"非暴力沟通四要素","l":"TF2-2","c":"汤小敏","g":1,"p":1},{"i":16215,"t":"充分表达感激 ","l":"TF2-1","c":"汤小敏","g":1,"p":1},{"i":15963,"t":"如何运用感激三要素，表达感激之情","l":"TF2-3","c":"ELIAUK","g":1,"p":1},{"i":15801,"t":"消极变积极，与自己握手言和的法宝","l":"TF2-4","c":"于枫","g":1,"p":1},{"i":15795,"t":"如何运用非暴力沟通化解冲突","l":"TF2-2","c":"ELIAUK","g":1,"p":1},{"i":15774,"t":"如何不带任何情绪，不急不躁，恰如其分诚实的表达出我们内心对美好事物真实的感受。","l":"TF2-4","c":"晚柠-","g":1,"p":1},{"i":15752,"t":"非暴力沟通之得体表达感激","l":"TF1-2","c":"皇甫胜男","g":1,"p":1},{"i":15751,"t":"用非暴力沟通，充分表达愤怒","l":"TF1-1","c":"皇甫胜男","g":1,"p":1},{"i":15727,"t":"表达愤怒的四个步骤 ","l":"TF2-2","c":"季草集美业","g":1,"p":1},{"i":15698,"t":"表达愤怒四步法","l":"TF2-1","c":"ELIAUK","g":1,"p":1},{"i":15656,"t":"表达内心感受，说出我的需要","l":"TF3-3","c":"严金英","g":1,"p":1},{"i":15591,"t":"如何合理地表达愤怒？","l":"TF2-2","c":"吴超","g":1,"p":1},{"i":15506,"t":"非暴力沟通","l":"TF2-4","c":"晚柠-","g":1,"p":1},{"i":15441,"t":"沟通四步法，有效表达需求","l":"TF2-2","c":"琛君","g":1,"p":1},{"i":15438,"t":"非暴力沟通的四要素","l":"TF2-1","c":"裴红如","g":1,"p":1},{"i":15404,"t":"非暴力沟通的四要素","l":"TF2-1","c":"吴超","g":1,"p":1},{"i":15348,"t":"非暴力沟通解决冲突的步骤","l":"TF1-1","c":"张培成001","g":1,"p":1},{"i":15316,"t":"表达感激","l":"TF1-2","c":"三宝","g":1,"p":1},{"i":15272,"t":"非暴力沟通","l":"TF2-4","c":"徐辉","g":1,"p":1},{"i":15238,"t":"表达感谢的三个要素","l":"TF1-2","c":"季草集美业","g":1,"p":1},{"i":15102,"t":"确认信息四步法","l":"TF2-3","c":"徐辉","g":1,"p":1},{"i":14894,"t":"非暴力沟通表达感激","l":"TF1-2","c":"李墨染","g":1,"p":1},{"i":14888,"t":"学会在日常生活中运用非暴力沟通的四个要素","l":"TF1-1","c":"李墨染","g":1,"p":1},{"i":14524,"t":"用非暴力沟通的方式表达感激","l":"TF1-2","c":"米老鼠vera","g":1,"p":1}],"ms":[{"id":19936,"topic":"思维转换的三步法","learn_goal":"","remark":"通过学习思维转换的三步法，将不得不做的小事情变成我选择做，探究原因和个人意图，把被迫转换为掌控，摆脱内耗。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"小魔女有点儿香","city":"大连市"},"club":{"name":"大连知行分舵","city":"大连"},"prologue":"\u003cp>【自我介绍】大家下午好，欢迎参加我的2-3拆页晋级。我的名字叫Hana,我的标签是立体纸艺艺术家，我希望9月底之前我能拥有3级拆书家的标签。\u003c/p>\u003cp>【学习目标】在跟随我学习完今天的拆页学习后，小伙伴们可以通过运用“横向结构演绎三段论”的方法，结合实际场景，设计符合该结构的说服方案，并通过小组演练在情境中学会应用这个方法。\u003c/p>\u003cp>今天需要小组讨论，我们来【分一下组】，左边一组右边一组。\u003c/p>\u003cp>【F（特点）】《非暴力沟通》是一本实用的沟通类书籍，作者马歇尔*卢森堡，他是美国临床心理学博士，“非暴力沟通”方式也被称为“爱的语言“。这门语言的四大核心要素是：讲事实、谈感受、探需求和提请求。通过这种方式可避免因我们的语言而引发自己和他人的痛苦,从而使个人生活更加美好、和谐。\u003c/p>\u003cp>【A（优势）】豆瓣上的评分高达8.4分，简单易懂，并且书中运用大量贴切的案例加深理解应用。可以满足各类读者的需求。\u003c/p>\u003cp>【B（好处）】这本书中的方法能帮我们觉察情绪、理顺内心，学会与自己和解。同时掌握温和有效的沟通方式，减少矛盾，拉近人与人之间的距离。\u003c/p>\u003cp>拆页好处：帮人跳出被动被迫的负面心态，厘清做事初衷，摆脱被琐事裹挟的无趣感，主动掌控日常选择，减少内心抵触与内耗。\u003c/p>\u003cp>【过渡句】请大家花2分钟时间看下我发给大家的拆页，读完抬头示意我。\u003c/p>","ratings_count":3,"texts":[{"id":24380,"quote":"\u003cp>\u003cstrong>片段来源：\u003c/strong>P127-128\u003c/p>\u003cp>\u003cstrong>主题\u003c/strong>：将被迫做事变为主动选择\u003c/p>\u003cp>用“我选择”代替“我不得不”\u003c/p>\u003cp>第一步：\u003c/p>\u003cp>在你的生活中，哪些事情让你觉得无趣，却又不得不做?你不想做它们，但还是去做了，因为你认为自己没有选择。请将这些事情列在一张纸上。\u003c/p>\u003cp>当我第一次审视我的清单时， 发现上面的事情可真不少，我恍然大悟自己为何常常无法享受生活。有许多事情，我之所以日复一日地去做，是因为我糊弄自己去相信那是不得不做的。\u003c/p>\u003cp>清单上的第一项是 “写临床报告&quot;。 我痛恨撰写这些报告，但却每天至少要花一个小时在上面，这让我苦不堪言。清单的第二项则是“开车送孩子们上学”。\u003c/p>\u003cp>第二步：\u003c/p>\u003cp>写完清单后，清楚地告诉自己:你之所以做这些事情，是因为你选择了它们，而非你不得不做。在你所列的每一件事情前加上“我选择做......”。\u003c/p>\u003cp>我记得当时我对这一步骤有些抗拒。我一直信誓旦旦的认为:“写临床报告不是我选择要做的事情，而是我不得不做的事。我是一名临床心理医生。当然必须要写这些报告。”\u003c/p>\u003cp>第三步：\u003c/p>\u003cp>一旦你认同了之所以做某件事是出于自己的选择，一旦你认同了之所以做某件事是出于自己的选择，就填写以下声明来了解你为什么要那么做：“我选择做 是因为我想要 ”\u003c/p>\u003cp>起初，我怎么也想不清楚我到底为什么要写临床报告。几个月前，我已经确信，对我的病人来说，临床报告用处并不大，花那么多时间是不值得的。既然如此，为什么我一直费尽苦心准备这些报告呢？最后，我终于明白了，我选择写临床报告，是因为我想从中得到收入。\u003c/p>\u003cp>我清单上的第二项是开车送孩子上学。当我琢磨自己为何要这么做时，我发现，我很欣赏我的孩子从他们现在的学校得到的教育。虽然他们可以步行到附近的学校上学，但他们所在的学校提供的教育更符合我的价值观。想到这一点，在开车送孩子上学时，我的感受就不一样了。在这以前，我会说：“倒霉！今天又不得不开车送孩子上学。”而在这之后，我理解自己为什么要这么做——那是为了孩子们能够得到我所看重的教育。当然，有的时候，在路上我需要提醒自己两三次开车送孩子上学的意义。\u003c/p>","explains":"\u003cp>【WHAT】 通过清单罗列、句式改写、探寻初衷三步，把“被迫做事”的认知转化为“主动选择做事”。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>大量内耗、生活无趣，根源是把日常琐事当成身不由己的负担，陷入被动受害者心态，忽略了行为背后的自我需求与选择权。\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>第一步，罗列所有觉得无趣、认为自己不得不做的事；比如每天接送孩子；做饭；做家务等等\u003c/p>\u003cp>第二步，将每件事前改为「我选择做……」，推翻被迫认知；以上面给出的内容为例：在每天接送孩子前面加上“我选择”，就成为“我选择”每天接送孩子；这样感觉更主动，没有了抱怨是不是\u003c/p>\u003cp>第三步，补全句式「我选择做……因为我想要……」，挖掘内在初衷。\u003c/p>\u003cp>举例：把第二步内容补充完成：“我选择”每天接送孩子，因为我想更多和孩子相处的时间，多增加聊天时间，增进亲子关系\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>适用于所有心生抵触、觉得身不由己的重复性琐事，涵盖生活、工作、亲子、家务等所有内耗场景。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>有的小伙伴可能会觉得这个方法太麻烦了，以前我就是随便抱怨两句。确实抱怨两句最省力。但是，让我们来看看不这么做的代价是什么？长期陷入无力感和不得不的委屈中，这种内耗，远比写一张便签消耗的精力和时间大得多。为了拿回你对生活的掌控感，这个短暂麻烦是非常值得的。\u003c/p>\u003cp>在说方法的时候，我用每天接送孩子给大家进行了示范，接下来，我要把方法用在更多地方。\u003c/p>\u003cp>【案例A2】\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong>明天晚上做家务时，我会应用思维转换的三步法，减少10分钟的焦虑和内耗。\u003c/p>\u003cp>\u003cstrong>行动：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：\u003c/strong>罗列被迫事项（举2个例子）\u003c/p>\u003cp>\u003cstrong>第二步：\u003c/strong>将每件事前改为「我选择做……」\u003c/p>\u003cp>\u003cstrong>第三步：\u003c/strong>「我选择做……因为我想要……」\u003c/p>\u003cp>1、我选择自己做一天三顿饭，因为我想要家人食物更安全、健康。让饭菜有爱的味道。\u003c/p>\u003cp>2、我选择周一到周四上午上瑜珈课，因为我想要拥有健康的体态，长更多肌肉。突破拉伸区、战胜畏难，建立自信。\u003c/p>\u003cp>写完之后，我不但不再内耗，反而成就感满满，有点上头。\u003c/p>\u003cp>\u003cstrong>［拆书家提问设计(逐字稿)\u003c/strong> \u003cstrong>］：\u003c/strong>\u003c/p>\u003cp>请大家想象一下在未来一到两周，工作或生活中可能会发生的事情，是你“不得不”去做的，比如：生活方面，接送孩子上学、辅导作业、收拾家务。工作方面：和难以沟通的合作部门拉扯、吃难吃的工作餐……大家可以用一分钟的时间写在便签上，请说出具体时间、场所、具体事件，只罗列不得不做的事情即可。写完之后每人用一分钟时间在小组内分享。之后一会邀请小伙伴分享一下。现在开始。\u003c/p>","interaction":"\u003ctable>\u003ctr>\u003ctd>\u003cstrong>［学习者案例记录］：\u003c/strong> \u003cbr>子枫：我罗列了一下，我未来一到两周不得不做的事。\u003cbr>1、每天不得不上班。\u003cbr>2、晚上我不得不在家里得陪儿子学习到11:30才能休息。\u003cbr>3、晚上我不得不做50个俯卧撑。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cstrong>［拆书家提问设计(逐字稿)\u003c/strong> \u003cstrong>］：\u003c/strong>根据我们刚才在便签上写下来的“不得不”去做的场景，我们思考一下这样做的初衷和背后的意图，你会怎么应用思维转换的三步法转换认知呢？\u003cbr>再请大家用2分钟在便签上写出来2-4条，写好之后每人一分钟在小组内分享你的应用。最后我们请1位伙伴各自分享2条清单内容。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cstrong>［学习者案例记录］：\u003c/strong>\u003cbr>子枫：我把我未来一到两周不得不做的其中两件事按照这个方法进行了转换：\u003cbr>1、我选择晚上在家里得陪儿子学习到11:30再休息，我希望我的陪伴让儿子学习的更加安心，有更好的成绩，将来考上更好的学校，有更好的工作和未来。\u003cbr>2、我选择晚上做50个俯卧撑，是因为身体更健康，未来有健康的晚年，不拖孩子后腿。\u003c/td>\u003c/tr>\u003c/table>\u003cp>谢谢小伙伴的分享，希望今天我们学习的思维转换三步骤，即——罗列被迫事项、将“不得不”改为“我选择”、最后通过挖掘内在初衷。让我们挣脱被动的桎梏，遵从本心生活，日日心安自在。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1781010977000,"updated_at":1782964919000,"ria":true},{"id":19474,"topic":"非暴力沟通四要素","learn_goal":"","remark":"当我们在沟通遇到障碍时，如何活用沟通四要素，让沟通更有效。","level":"TF2-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"东旭悦读","city":"衡阳市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>大家好，三个标签介绍自己，微峰法务衡阳分公司法佑运营中心负责人，人民法院调解平台中级调解员，线上悦读读书会发起人。2025年5月，结缘拆书帮，相信拆书可“拆为己用”，开启新征程。\u003c/p>\u003cp>今天要和大家分享的这本书叫《非暴力沟通》。\u003c/p>\u003cp>\u003cstrong>学习目标：（1-2分钟）\u003c/strong>\u003c/p>\u003cp>我今天分享的是“非暴力沟通四要素”的拆页学习。在跟随我完成本场RIA线上学习后，学习者能够了解非暴力沟通四要素是什么，在沟通遇到情绪卡点的沟通场景中把这四要素用起来。\u003c/p>\u003cp>\u003cstrong>F特征：\u003c/strong>\u003c/p>\u003cp>《非暴力沟通》是一本深入探讨如何通过有效沟通来建立和谐人际关系和解决冲突的实用书籍，作者是美国心理学家马歇尔·卢森堡博士，他是国际非暴力沟通中心的创始人，这本书融汇了他50多年的实践经验。\u003c/p>\u003cp>\u003cstrong>A优势:\u003c/strong> \u003c/p>\u003cp>这本书的出版发行，引起了全球35个国家和地区开展非暴力沟通培训的风潮。这本书与其它沟通类书籍相比，本书最大的优点是可读性特别强，简单易学，方法操作性强，案例生动容易理解。它不仅是一套沟通技巧，更是一种生活哲学。它教会我们如何用爱和理解去倾听他人，用非暴力的方式去表达自己的需求。\u003c/p>\u003cp>\u003cstrong>B利益：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B1：\u003c/strong>你有没有曾经想与同事、家人沟通，却得不到想要的回应？这本书会告诉你方法，避免你的热脸贴了冷屁股。他会通过具体的方式方法，让你简单的学会说话，并且爱上沟通。\u003c/p>\u003cp>\u003cstrong>B2：\u003c/strong>这次的拆页，可以让我们在沟通遇到障碍，比如对方出现明显的排斥情绪时，把这四要素用起来，达到让沟通顺利进行的目标。\u003c/p>\u003cp>【分组】我们今天线上会有讨论分享环节，因人数原因，今天大家共为一组。\u003c/p>","ratings_count":2,"texts":[{"id":23852,"quote":"\u003cp>下面我把原书片段截图发群里，给大家2分钟的时间看一下片段，看完之后请眼神示意我一下。\u003c/p>\u003cp>【片段来源】： 《非暴力沟通》\u003c/p>\u003cp>【页码】:p6\u003c/p>\u003cp>【主题】:非暴力沟通的要素\u003c/p>\u003cp>R原文片段：\u003c/p>\u003cp>要达到让双方都能发自内心地相互给予，我们需将注意力聚焦在四个方面——它们是非暴力沟通模式的四个要素。\u003c/p>\u003cp>首先，我们观察实际上发生了什么。不论他人的言行是否有益于我们，我们只是去观察。要做到清晰表达所观察到的，我们的挑战在于不夹杂任何评判。不论喜欢与否，我们只是说出人们做了什么。第二步，表达出我们看到这些行为时的感受：是感到伤心、害怕、喜悦、有趣，还是心烦呢？第三步，表达出我们的感受与什么需要相关联。通过对这三个要素的觉察，我们清晰和诚实地表达出自己的状态。\u003c/p>\u003cp>例如，一位母亲想和正值青春期的儿子用非暴力沟通的方式来说话，她可以这样来表达以上三个要素：“菲利克斯，看到咖啡桌下的两团脏袜子和电视机旁边的三团脏袜子，我很生气，因为我希望在我们共用的空间里能多些整洁。”\u003c/p>\u003cp>紧接着，她可以表达非暴力沟通的第四个要素——一个具体的请求：“你愿意把你的袜子放在你房间或放进洗衣机里吗？”我们借助这个要素提出对他人的期许，希望他（她）怎么做来满足我们的需要，让我们的生命更加美好。\u003c/p>","explains":"\u003cp>【\u003cstrong>What\u003c/strong>】\u003c/p>\u003cp>非暴力沟通是为了有爱的沟通而存在，它会让我们在沟通中照顾好感受和需求。它是由观察、感受、需求、请求这四要素构成的，这是非暴力沟通的核心。\u003c/p>\u003cp>【\u003cstrong>Why\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>一般做法的好处：\u003c/strong>\u003c/p>\u003cp>能让沟通双方清晰理解彼此，避免情绪对抗，像我调解交通事故医疗纠纷时，用这方法让肇事方和受伤方从争吵到平和协商，快速达成赔偿方案；处理债务优化客户时，客户从抵触方案到主动配合还款计划。\u003c/p>\u003cp>\u003cstrong>不这么做的坏处：\u003c/strong>\u003c/p>\u003cp>沟通易陷入指责、对抗，导致问题激化。比如调解时直接说“你这责任摆明了，赶紧赔钱”，对方会反驳“我才没全责”，纠纷拖很久；债务优化中说“你这债务再不处理就等着被起诉”，客户会直接挂电话，后续沟通更难。\u003c/p>\u003cp>【\u003cstrong>反面案例\u003c/strong>】\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>处理一起追尾事故调解，肇事方是个年轻司机，我一开始直接说“你追尾全责，必须赔对方医疗费和修车费”。他立刻反驳“我看他也超速了，凭什么我全责”，受伤方也跟着吵“你开车不长眼，我这伤得请假，误工费你得全赔”，双方越吵越凶，调解陷入僵局。这就是没运用非暴力沟通，直接评判指责导致的结果。\u003c/p>\u003cp>【\u003cstrong>How\u003c/strong>】\u003c/p>\u003cp>非暴力沟通包含四步：\u003c/p>\u003cp>第一步，观察事实。先表达我们观察到哪些所见、所闻、所触，注意，要区分开事实和评论。若我们在观察中夹杂了评价，别人可能会以为我们在批评他而心生抵触心理。\u003c/p>\u003cp>第二步，表达感受。看到第一步发生的事情，我内心有什么感受，比如开心、感激、恼火、担心等。注意，要区分感受和想法。\u003c/p>\u003cp>第三步，洞察需要。看见第二步情绪背后我们有什么需求，可以用“我感到（什么情绪）因为我想……”的句式来表达。\u003c/p>\u003cp>第四步，提出请求。使用正向、具体的语言，清楚地表达我们请求对方去做什么。\u003c/p>\u003cp>【\u003cstrong>正面案例\u003c/strong>】\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>还是那起追尾调解，我调整后说：\u003c/p>\u003cp>（观察事实）事故认定书显示你追尾，对方车辆尾部和你车辆前部都有损伤；\u003c/p>\u003cp>（表达感受）你现在一直强调对方可能超速，看起来很担心全责要承担太多费用，我能理解你的顾虑；\u003c/p>\u003cp>（洞察需要）因为你希望责任划分更公平，也不想承担超出能力的赔偿；\u003c/p>\u003cp>（提出请求）那我们一起再核对下事故细节，看看能不能和对方协商一个责任比例，你觉得怎么样？” 年轻司机听完，情绪缓和了很多，开始愿意和对方理性谈赔偿了。\u003c/p>\u003cp>【\u003cstrong>Where\u003c/strong>】\u003c/p>\u003cp>当沟通遇到挑战，沟通双方或者任何一方出现情绪性反应时，这个方法对推进沟通卡点是非常适用的, 如:纠纷调解、债务协商、亲子沟通等。当然，如果对方是胡搅盲缠不讲理，恶意要挑起冲突的，那这个方法可以慎用。\u003c/p>\u003cp>【\u003cstrong>常见异议\u003c/strong>】\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>1、习惯性的开启指责和评价；\u003c/p>\u003cp>2、自己的状态并不是想要的；\u003c/p>\u003cp>3、洞察不到他人的感受。\u003c/p>\u003cp>非暴力沟通的四个要素，我们知道了，但这不是固定的沟通公式，我们完全可以根据场景和个人倾向灵活地调整和处理的。我们最需要知道的是，要在沟通中看到情绪，看到需求，表达想法，但是不要带着评判和有色眼镜，不要根据个人的喜好去要求别人，这才是最重要的。\u003c/p>\u003cp>但是有个建议，当我们作为新手，严格按上面的步骤做练习，会更有利于我们从浅到深对各个要素做好觉察和运用。\u003c/p>","interaction":"\u003cp>【\u003cstrong>A2\u003c/strong>】\u003cstrong>：分步催化1 \u003c/strong>\u003c/p>\u003cp>接下来，我邀请大家一起来做个练习，帮助大家学以致用。\u003c/p>\u003cp>请大家想象下，在未来1-2个月里，在工作或生活中，在不了解非暴力沟通四要素\u003cstrong>时\u003c/strong>，你遇到一些沟通场景怎么应对?\u003c/p>\u003cp>比如：孩子才吃完饭就去打手机游戏，你忍不住想对TA发火\u003c/p>\u003cp>比如：你跟某个同事合作一个项目，同事说话比较直接比较冲，让你感觉到冒犯。\u003c/p>\u003cp>这里的爱人、孩子、同事可以换成其他人，比如父母、朋友、老师、同学、亲戚等等，设想，当你跟他们在日常相处或合作中出现了不愉快，是发生了什么，在学习这个工具前，你一般会有怎样沟通反应呢？\u003c/p>\u003cp>下面我们用2分钟的时间思考具体的场景，请大家先在小组内分享，稍后邀请小伙伴跟大家分享。\u003c/p>\u003cp>【学习者分享1】：\u003c/p>\u003cp>1、孩子，你吃了饭就去打手机游戏，已经玩了30分钟；\u003c/p>\u003cp>2、我非常生气，想教训你；\u003c/p>\u003cp>3、因为，你这样做时破坏我们的约定，要惩罚；\u003c/p>\u003cp>4、请马上把手机交上来……\u003c/p>\u003cp>往往，这种情况大概率会导致一场暴风雨。\u003c/p>\u003cp>【A2】：分步催化2 \u003c/p>\u003cp>接下来，我们把今天学习到工具，真正地用起来了！\u003c/p>\u003cp>请小伙伴们一起思考，如果基于刚才联想到的应用情境，运用“非暴力沟通四要素”的方法，你会怎么做沟通呢？\u003c/p>\u003cp>5分钟的时间，咱们先在群内分享。之后我会邀请小伙伴和大家分享。\u003c/p>\u003cp>【学习者案例实录】：\u003c/p>\u003cp>1、先观察事实：我观察到你吃了饭就在玩手机游戏，一玩就是半小时；\u003c/p>\u003cp>2、表达我的感受：我觉得很着急，很担心；\u003c/p>\u003cp>3、洞察需要：我希望你先照顾好自己，吃完饭先休息一会，再管好自己应该做的事情。\u003c/p>\u003cp>4、最后提出请求：你是否愿意放下手机，先看一会儿远的地方休息下眼睛，然后再安排一下自己要做的事情呢？\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>最后，我来简单总结下今天我们所学的内容。\u003c/p>\u003cp>非暴力沟通四要素，分别是\u003cstrong>观察事实-表达感受-洞察需要-提出请求\u003c/strong>，它的顺序是可以基于实际情景作灵活调整，核心是我们在日常沟通中保持对这4个要素的感知与运用，可以把沟通四要素的核心内容制作成小贴纸贴到家里醒目位置，学以致用、刻意练习，会收到意向不到的收获。\u003c/p>\u003cp>期待大家在接下来的工作生活中都能积极践行这个工具，帮助大家提高沟通技巧，拥有更高质量的人际关系。\u003c/p>\u003cp>以上就是我今天分享的内容，感谢大家的聆听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":23853,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1764213733000,"updated_at":1764820135000,"ria":true},{"id":19423,"topic":"不得不变成我选择","learn_goal":"","remark":"用积极的心态，把不得不做的事，变成我选择的事。\n\n录音：\n通过百度网盘分享的文件：张连英2-1  …\n链接:https://pan.baidu.com/s/1UT4ajiE1ASFlnOHKzM4GJg?pwd=1j1f \n复制这段内容打开「百度网盘APP 即可获取」\n\n\n逐字稿：\n开场：\n各位小伙伴大家晚上好，今天我跟大家分享的主题是从不得不到我选择转念三步法，那我们都知道在生活中或者是工作中都可能会遇到一些不得不做不愿意做，但是又不得不做的事情。我们就可以通过运用今天的转念三步法来进行这些事情。\n我们今天的学习目标就是在大家面对不想做，却又不得不做某些事情时，采用转变观念，三步法化，被动为主动，从而顺利，愉快，高效地完成那些不得不做的事儿，先来一个自我介绍。\n\n我叫张连英，是一位医务工作者，也是一位宝妈，也是渴望活出善意与慈悲，并且努力释放爱与温暖，非暴力沟通践行者。\n【学习目标】通过今天的学习，可以让大家学习到在面对自己不情愿做又不得不做的事时，通过转念三步法，化“被动”为“主动”，顺利、愉悦地做好那些不得不去做的事。\n\n\n【F】今天我们一起学习的拆页，选自《非暴力沟通》，作者是国际非暴力沟通中心创始人马歇尔.卢森堡博士，全球首位非暴力沟通专家。这是一本讲述怎样沟通更高效，更能传递彼此的善意与温暖的沟通类书籍。\n\n【A】\n沟通类的书籍这么多，为什么给大家推荐这本书呢？\n\n（专家）首先，这本书中文版销量超200万册，并且非暴力沟通被联合国教科文组织列为全球正式教育和非正式教育领域非暴力解决冲突的最佳实践之一。\n还有前国际非暴力沟通中心董事会主席凯瑟琳.韩.辛格，和非暴力沟通中文学院创始人刘轶等专家亲自作序推荐。能够得到这么权威机构及专家的推荐，说明这本书里确实值得一读。\n（公众）其次呢，这本书豆瓣评分8.4分，微信读书推荐值81.7%，樊登读书超6000万人次阅读，大家都认为值得一读。这也说明这本书受欢迎的程度。\n（个人）最后，给大家推荐这本书是首先他既有心理学的理论基础，又有作者几十年在世界各地开展化解冲突的经验，读起来丝毫不会枯燥，里边特别多的情境案例，读起来轻松好理解。\n\n【B1】\n通过阅读本书，可以摆脱过往因不擅长沟通导致谈话失败的困境；因情绪失控而使事情变得更糟的情况，比如你的先生衣服乱扔，你的孩子玩上游戏就不放手，等等。帮助大家提高沟通能力，能顺畅地、准确地表达自己的善意与慈悲，让以往辞不达意，矛盾被激化的概率大大降低。\n【B2】通过本片段的学习，可以让大家学习到，当我们抗拒做一件事但又不得不做的时候，通过转变观念三步法，与自己的内心对话，变被动为主动，更好的完成那些不得不做的事情。\n\t\nR原文片段：\n“不得不”转化为”我选择”\n第一步：\n在你的生活中哪些事情让你觉得无趣却又不得不去做，你不想做他们，但还是去做了，因为你认为自己没有选择，请将这些事情列在一张纸上。\n当我第一次审视我的清单时，发现上面的事情可真不少，我恍然大悟自己为何常常无法享受生活？有许多事情我之所以日复一日的去做，是因为我糊弄自己去相亲，那是不得不做的。\n清单上的第一项是写临床报告，我痛恨撰写这些报告，但却每天至少要花一个小时在上面，这让我苦不堪言。清单的第二项是开车送孩子们上学。\n第二步：\n写完清单后清楚的告诉自己。你之所以做这些事情是因为你选择了他们，而非你不得不做在你所列出的每一件事情上，每一件事情前加上我选择做。\n我记得当时我对这一部有些抗拒，我一直信誓旦旦的认为写临床报告不是我选择要做的事情，而是我不得不做的事，我是一名临床心理医生。当然必须要写这些报告。\n第三步：\n一旦你认同了之所以做某件事是出于自己的选择，请试着体会选择背后的意图是什么？然后以“我选择做……因为我想要……”来表述。\n起初我怎么也想不清楚到底为什么要写临床报告？几个月前我已经认定这些报告对我的咨询病人来说用处不大，不值得花那么多时间。既然如此，为什么我还投入那么多精力在这上面呢？最终我发现我选择写这些报告仅仅是因为想要获得这份工作带来的收入。意识到这点我再也没有写过任何临床报告了。想到这35年来自己少写了无数的报告，我就开心的不得了，当意识到金钱是我的首要驱动力时，我立刻就想到可以用别的方式来获得收入。事实上我宁愿在垃圾堆里觅食，也不愿再多写一份临床报告。\n我列出的第二项不情愿做的是开车送孩子们上学，当我仔细思索为什么要这么做时，我发现对于孩子们从学校收获的好处我心怀感恩，虽然他们可以步行到附近的学校上学，但现在的这所学校更符合我的教育理念，于是我还是继续开车送孩子们上学。不过心态已经不一样了，我不再对自己说。讨厌，今天我又必须坐车夫了，因为我已经清楚的知道这是为了让孩子们受到良好的教育，因为我很重视教育的品质，当然有时候我需要在开车时提醒自己好多次，重新关注这样做的目的。\n\n拆书家讲解引导：\n【Why不那么做的坏处】\n读完片段之后想问一下大家，在工作或生活中是不是也经常面对这种情况，就是好多事情都是我们不想做但是又不得不去做的，所以往往带有抵触情绪，导致做事的时候很难全心全意、心情平和的去做这件事，结果就是费力不讨好，事情做了，劲没少费，但结果往往不如人意。这样会对自信心造成很大的打击，同时会产生自责、懊恼、沮丧等不良情绪，影响别的事情，造成恶性循环。\n所以今天给大家介绍一种方法，就是\n\n【What】今天这个拆页讲述的方法：当你遇到一件事情比较抗拒去做但是又不得不去做时，可以采用转念三步法，与自己内心对话，进行心态上的转变，变抗拒为主动，顺利完成那些不愿意做却又不得不做的事。\n【How】 我把这个方法提炼成的三个步骤：\n1 列清单；列出自己不想做又不得不做的事情清单。\n2 做转念：告诉自己这是自己选择要做的事情。\n3 挖意图：挖掘这件事情的根本原因，找到我们选择做这件事的背后意图。\n\n【失败案例】回想我自己，上班时，特别不愿意整理病房，觉得会引起病人的反感，又浪费时间，与治疗没啥关系。每天只是被迫的、心不甘情不愿地去整理，总是敷衍了事。结果就是经常因为病房环境太乱被领导批评，也因此影响一天的心情，干什么都不痛快，降低上班及生活的幸福值。\n【成功案例】我学习了三步法后，就借助这个步骤来帮助我改变心态：\n第一步：列清单，列出自己不想做但又不得不做的事情清单。比如我不愿意整理病房，但规定必须得做这件事。\n第二步：做转念，告诉我自己，整理病房这件事情是我自己主动选择去做的，如同主动整理自家屋子一样。\n第三步：挖意图，挖掘我选择这件事的背后意图，也就是如同整理自家屋子一样，干净整洁了，工作时会更舒心、同时整理病房的时间也可以和病人多沟通，了解病人情况，会让护患关系更加和谐，更有利于开展工作。\n这样，依照以上三步法，让我成功从抗拒整理病房到主动地、心平气和地、高效地整理病房，并且会继续坚持下去。\n\n【Where适用边界】本方法适用于你在面对一些不想做又不得不做的事情时。\n\nA学习者拆为己用：学习者拆为己用：\n【A1显像提问】\n分享完我的案例，接下来请小伙伴们回想一下，你最近一个月有没有遇到一些什么不愿做又不得不做的事呢？\n比如：领导让你做宣传视频，但是你不愿意做，碍于命令又不得不做时；上了一天班，身心俱疲，特想休息一会儿，但是孩子又吵着让你陪他玩耍时；体检结果不理想，医生建议控制饮食、减肥锻炼身体，但是又难以抵御美食、迈不开腿时；下班回家，想安静一会儿，但是父母却拉着你不停说家长里短时等等……当时具体情况是什么样的，你的心情是样的怎么样的呢？\n请大家在小组内回忆一下，2-3分钟时间，稍后我们邀请1-2位小伙伴来做分享：\n好，哪一位小伙伴给大家做分享：时间2分钟\n【学习者案例记录A1】：\n人物:韧木\n事情:最近一个月内，听这节课之前，在学校不想备课写教案，所以写教案很拖拉\n\n【A1+反思加工】\n听了小伙伴的分享，大家也讨论分享了自己的类似情况，我们再回顾今天学习的三步法：\n1 列清单；列出自己不想做但又不得不做的事情清单。\n2 做转念：告诉自己这是自己选择要做的事情。\n3 挖意图：挖掘这件事情的根本原因，找到我们选择做这件事的背后意图。\n\n接下来，大家结合刚才分享的自己的案例，如果时光倒流，再次回到当时的情境下，用我们今天学习的三步法，你会如何转变心态更好地完成这件事情呢？请大家继续在组内讨论，“分享即是成长，每人都说一说”，时间为2-3分钟。然后我们请一位小伙伴来分享。\n好，哪一位小伙伴给大家做分享：时间2-3分钟\n【学习者案例记录A1＋】\n人物：韧木\n事件：\n回到没听这节课之前，我会把备课写教案列入我的不得不做的事情清单。\n告诉自己，备课这件事是我自己选择主动去做的。\n因为备课能迭代在拆书帮学到的技能，便于给学生讲课，便于把重心放到学习者身上，并且熟悉教学内容，对于讲课和教学竞赛都更有帮助。\n【结语】（感谢小伙伴的分享）\n今天我们学习了，变被动为主动的转念三步法：列清单、做转念、挖意图。希望大家将来在工作生活中多多运用，助力你顺利完成每一件事。\n今天的学习结束，感谢聆听。\n\n","level":"TF2-1","duration":26,"status":30,"type":0,"chaishujia":{"username":"张连英","city":"唐山市"},"club":{"name":"廊坊风陵分舵","city":"廊坊"},"prologue":"\u003cp>开场：\u003cbr>各位小伙伴大家晚上好，今天我跟大家分享的主题是从不得不到我选择转念三步法，那我们都知道在生活中或者是工作中都可能会遇到一些不得不做不愿意做，但是又不得不做的事情。我们就可以通过运用今天的转念三步法来进行这些事情。\u003cbr>我们今天的学习目标就是在大家面对不想做，却又不得不做某些事情时，采用转变观念，三步法化，被动为主动，从而顺利，愉快，高效地完成那些不得不做的事儿，先来一个自我介绍。\u003cbr>\u003cbr>我叫张连英，是一位医务工作者，也是一位宝妈，也是渴望活出善意与慈悲，并且努力释放爱与温暖，非暴力沟通践行者。\u003cbr>【学习目标】通过今天的学习，可以让大家学习到在面对自己不情愿做又不得不做的事时，通过转念三步法，化“被动”为“主动”，顺利、愉悦地做好那些不得不去做的事。\u003cbr>\u003cbr>\u003cbr>【F】今天我们一起学习的拆页，选自《非暴力沟通》，作者是国际非暴力沟通中心创始人马歇尔.卢森堡博士，全球首位非暴力沟通专家。这是一本讲述怎样沟通更高效，更能传递彼此的善意与温暖的沟通类书籍。\u003cbr>\u003cbr>【A】\u003cbr>沟通类的书籍这么多，为什么给大家推荐这本书呢？\u003cbr>\u003cbr>（专家）首先，这本书中文版销量超200万册，并且非暴力沟通被联合国教科文组织列为全球正式教育和非正式教育领域非暴力解决冲突的最佳实践之一。\u003cbr>还有前国际非暴力沟通中心董事会主席凯瑟琳.韩.辛格，和非暴力沟通中文学院创始人刘轶等专家亲自作序推荐。能够得到这么权威机构及专家的推荐，说明这本书里确实值得一读。\u003cbr>（公众）其次呢，这本书豆瓣评分8.4分，微信读书推荐值81.7%，樊登读书超6000万人次阅读，大家都认为值得一读。这也说明这本书受欢迎的程度。\u003cbr>（个人）最后，给大家推荐这本书是首先他既有心理学的理论基础，又有作者几十年在世界各地开展化解冲突的经验，读起来丝毫不会枯燥，里边特别多的情境案例，读起来轻松好理解。\u003cbr>\u003cbr>【B1】\u003cbr>通过阅读本书，可以摆脱过往因不擅长沟通导致谈话失败的困境；因情绪失控而使事情变得更糟的情况，比如你的先生衣服乱扔，你的孩子玩上游戏就不放手，等等。帮助大家提高沟通能力，能顺畅地、准确地表达自己的善意与慈悲，让以往辞不达意，矛盾被激化的概率大大降低。\u003cbr>【B2】通过本片段的学习，可以让大家学习到，当我们抗拒做一件事但又不得不做的时候，通过转变观念三步法，与自己的内心对话，变被动为主动，更好的完成那些不得不做的事情。\u003cbr> \u003cbr>R原文片段：\u003cbr>“不得不”转化为”我选择”\u003cbr>第一步：\u003cbr>在你的生活中哪些事情让你觉得无趣却又不得不去做，你不想做他们，但还是去做了，因为你认为自己没有选择，请将这些事情列在一张纸上。\u003cbr>当我第一次审视我的清单时，发现上面的事情可真不少，我恍然大悟自己为何常常无法享受生活？有许多事情我之所以日复一日的去做，是因为我糊弄自己去相亲，那是不得不做的。\u003cbr>清单上的第一项是写临床报告，我痛恨撰写这些报告，但却每天至少要花一个小时在上面，这让我苦不堪言。清单的第二项是开车送孩子们上学。\u003cbr>第二步：\u003cbr>写完清单后清楚的告诉自己。你之所以做这些事情是因为你选择了他们，而非你不得不做在你所列出的每一件事情上，每一件事情前加上我选择做。\u003cbr>我记得当时我对这一部有些抗拒，我一直信誓旦旦的认为写临床报告不是我选择要做的事情，而是我不得不做的事，我是一名临床心理医生。当然必须要写这些报告。\u003cbr>第三步：\u003cbr>一旦你认同了之所以做某件事是出于自己的选择，请试着体会选择背后的意图是什么？然后以“我选择做……因为我想要……”来表述。\u003cbr>起初我怎么也想不清楚到底为什么要写临床报告？几个月前我已经认定这些报告对我的咨询病人来说用处不大，不值得花那么多时间。既然如此，为什么我还投入那么多精力在这上面呢？最终我发现我选择写这些报告仅仅是因为想要获得这份工作带来的收入。意识到这点我再也没有写过任何临床报告了。想到这35年来自己少写了无数的报告，我就开心的不得了，当意识到金钱是我的首要驱动力时，我立刻就想到可以用别的方式来获得收入。事实上我宁愿在垃圾堆里觅食，也不愿再多写一份临床报告。\u003cbr>我列出的第二项不情愿做的是开车送孩子们上学，当我仔细思索为什么要这么做时，我发现对于孩子们从学校收获的好处我心怀感恩，虽然他们可以步行到附近的学校上学，但现在的这所学校更符合我的教育理念，于是我还是继续开车送孩子们上学。不过心态已经不一样了，我不再对自己说。讨厌，今天我又必须坐车夫了，因为我已经清楚的知道这是为了让孩子们受到良好的教育，因为我很重视教育的品质，当然有时候我需要在开车时提醒自己好多次，重新关注这样做的目的。\u003cbr>\u003cbr>拆书家讲解引导：\u003cbr>【Why不那么做的坏处】\u003cbr>读完片段之后想问一下大家，在工作或生活中是不是也经常面对这种情况，就是好多事情都是我们不想做但是又不得不去做的，所以往往带有抵触情绪，导致做事的时候很难全心全意、心情平和的去做这件事，结果就是费力不讨好，事情做了，劲没少费，但结果往往不如人意。这样会对自信心造成很大的打击，同时会产生自责、懊恼、沮丧等不良情绪，影响别的事情，造成恶性循环。\u003cbr>所以今天给大家介绍一种方法，就是\u003cbr>\u003cbr>【What】今天这个拆页讲述的方法：当你遇到一件事情比较抗拒去做但是又不得不去做时，可以采用转念三步法，与自己内心对话，进行心态上的转变，变抗拒为主动，顺利完成那些不愿意做却又不得不做的事。\u003cbr>【How】 我把这个方法提炼成的三个步骤：\u003cbr>1 列清单；列出自己不想做又不得不做的事情清单。\u003cbr>2 做转念：告诉自己这是自己选择要做的事情。\u003cbr>3 挖意图：挖掘这件事情的根本原因，找到我们选择做这件事的背后意图。\u003cbr>\u003cbr>【失败案例】回想我自己，上班时，特别不愿意整理病房，觉得会引起病人的反感，又浪费时间，与治疗没啥关系。每天只是被迫的、心不甘情不愿地去整理，总是敷衍了事。结果就是经常因为病房环境太乱被领导批评，也因此影响一天的心情，干什么都不痛快，降低上班及生活的幸福值。\u003cbr>【成功案例】我学习了三步法后，就借助这个步骤来帮助我改变心态：\u003cbr>第一步：列清单，列出自己不想做但又不得不做的事情清单。比如我不愿意整理病房，但规定必须得做这件事。\u003cbr>第二步：做转念，告诉我自己，整理病房这件事情是我自己主动选择去做的，如同主动整理自家屋子一样。\u003cbr>第三步：挖意图，挖掘我选择这件事的背后意图，也就是如同整理自家屋子一样，干净整洁了，工作时会更舒心、同时整理病房的时间也可以和病人多沟通，了解病人情况，会让护患关系更加和谐，更有利于开展工作。\u003cbr>这样，依照以上三步法，让我成功从抗拒整理病房到主动地、心平气和地、高效地整理病房，并且会继续坚持下去。\u003cbr>\u003cbr>【Where适用边界】本方法适用于你在面对一些不想做又不得不做的事情时。\u003cbr>\u003cbr>A学习者拆为己用：学习者拆为己用：\u003cbr>【A1显像提问】\u003cbr>分享完我的案例，接下来请小伙伴们回想一下，你最近一个月有没有遇到一些什么不愿做又不得不做的事呢？\u003cbr>比如：领导让你做宣传视频，但是你不愿意做，碍于命令又不得不做时；上了一天班，身心俱疲，特想休息一会儿，但是孩子又吵着让你陪他玩耍时；体检结果不理想，医生建议控制饮食、减肥锻炼身体，但是又难以抵御美食、迈不开腿时；下班回家，想安静一会儿，但是父母却拉着你不停说家长里短时等等……当时具体情况是什么样的，你的心情是样的怎么样的呢？\u003cbr>请大家在小组内回忆一下，2-3分钟时间，稍后我们邀请1-2位小伙伴来做分享：\u003cbr>好，哪一位小伙伴给大家做分享：时间2分钟\u003cbr>【学习者案例记录A1】：\u003cbr>人物:韧木\u003cbr>事情:最近一个月内，听这节课之前，在学校不想备课写教案，所以写教案很拖拉\u003cbr>\u003cbr>【A1+反思加工】\u003cbr>听了小伙伴的分享，大家也分享了自己的类似情况，我们再回顾今天学习的三步法：\u003cbr>1 列清单；列出自己不想做但又不得不做的事情清单。\u003cbr>2 做转念：告诉自己这是自己选择要做的事情。\u003cbr>3 挖意图：挖掘这件事情的根本原因，找到我们选择做这件事的背后意图。\u003cbr>\u003cbr>接下来，大家结合刚才分享的自己的案例，如果时光倒流，再次回到当时的情境下，用我们今天学习的三步法，你会如何转变心态更好地完成这件事情呢？请大家继续分享，“分享即是成长，每人都说一说”，时间为3分钟。然后我们请一位小伙伴来分享。\u003cbr>好，哪一位小伙伴给大家做分享：时间3分钟\u003cbr>【学习者案例记录A1＋】\u003cbr>人物：韧木\u003cbr>事件：\u003cbr>回到没听这节课之前，我会把备课写教案列入我的不得不做的事情清单。\u003cbr>告诉自己，备课这件事是我自己选择主动去做的。\u003cbr>因为备课能迭代在拆书帮学到的技能，便于给学生讲课，便于把重心放到学习者身上，并且熟悉教学内容，对于讲课和教学竞赛都更有帮助。\u003cbr>【结语】（感谢小伙伴的分享）\u003cbr>今天我们学习了，变被动为主动的转念三步法：列清单、做转念、挖意图。希望大家将来在工作生活中多多运用，助力你顺利完成每一件事。\u003cbr>今天的学习结束，感谢聆听。\u003c/p>","ratings_count":1,"texts":[{"id":23793,"quote":"\u003cp>R原文片段：\u003c/p>\u003cp>“不得不”转化为”我选择”\u003c/p>\u003cp>第一步：\u003c/p>\u003cp>在你的生活中哪些事情让你觉得无趣却又不得不去做，你不想做他们，但还是去做了，因为你认为自己没有选择，请将这些事情列在一张纸上。\u003c/p>\u003cp>当我第一次审视我的清单时，发现上面的事情可真不少，我恍然大悟自己为何常常无法享受生活？有许多事情我之所以日复一日的去做，是因为我糊弄自己去相亲，那是不得不做的。\u003c/p>\u003cp>清单上的第一项是写临床报告，我痛恨撰写这些报告，但却每天至少要花一个小时在上面，这让我苦不堪言。清单的第二项是开车送孩子们上学。\u003c/p>\u003cp>第二步：\u003c/p>\u003cp>写完清单后清楚的告诉自己。你之所以做这些事情是因为你选择了他们，而非你不得不做在你所列出的每一件事情上，每一件事情前加上我选择做。\u003c/p>\u003cp>我记得当时我对这一部有些抗拒，我一直信誓旦旦的认为写临床报告不是我选择要做的事情，而是我不得不做的事，我是一名临床心理医生。当然必须要写这些报告。\u003c/p>\u003cp>第三步：\u003c/p>\u003cp>一旦你认同了之所以做某件事是出于自己的选择，请试着体会选择背后的意图是什么？然后以“我选择做……因为我想要……”来表述。\u003c/p>\u003cp>起初我怎么也想不清楚到底为什么要写临床报告？几个月前我已经认定这些报告对我的咨询病人来说用处不大，不值得花那么多时间。既然如此，为什么我还投入那么多精力在这上面呢？最终我发现我选择写这些报告仅仅是因为想要获得这份工作带来的收入。意识到这点我再也没有写过任何临床报告了。想到这35年来自己少写了无数的报告，我就开心的不得了，当意识到金钱是我的首要驱动力时，我立刻就想到可以用别的方式来获得收入。事实上我宁愿在垃圾堆里觅食，也不愿再多写一份临床报告。\u003c/p>\u003cp>【Where适用边界】本方法适用于你在面对一些不想做又不得不做的事情时。\u003c/p>","explains":"\u003cp>【Why不那么做的坏处】\u003c/p>\u003cp>读完片段之后想问一下大家，在工作或生活中是不是也经常面对这种情况，就是好多事情都是我们不想做但是又不得不去做的，所以往往带有抵触情绪，导致做事的时候很难全心全意、心情平和的去做这件事，结果就是费力不讨好，事情做了，劲没少费，但结果往往不如人意。这样会对自信心造成很大的打击，同时会产生自责、懊恼、沮丧等不良情绪，影响别的事情，造成恶性循环。\u003c/p>\u003cp>所以今天给大家介绍一种方法，就是\u003c/p>\u003cp>【What】今天这个拆页讲述的方法：当你遇到一件事情比较抗拒去做但是又不得不去做时，可以采用转念三步法，与自己内心对话，进行心态上的转变，变抗拒为主动，顺利完成那些不愿意做却又不得不做的事。\u003c/p>\u003cp>【How】 我把这个方法提炼成的三个步骤：\u003c/p>\u003cp>1 列清单；列出自己不想做又不得不做的事情清单。\u003c/p>\u003cp>2 做转念：告诉自己这是自己选择要做的事情。\u003c/p>\u003cp>3 挖意图：挖掘这件事情的根本原因，找到我们选择做这件事的背后意图。\u003c/p>\u003cp>【失败案例】回想我自己，上班时，特别不愿意整理病房，觉得会引起病人的反感，又浪费时间，与治疗没啥关系。每天只是被迫的、心不甘情不愿地去整理，总是敷衍了事。结果就是经常因为病房环境太乱被领导批评，也因此影响一天的心情，干什么都不痛快，降低上班及生活的幸福值。\u003c/p>\u003cp>【成功案例】我学习了三步法后，就借助这个步骤来帮助我改变心态：\u003c/p>\u003cp>第一步：列清单，列出自己不想做但又不得不做的事情清单。比如我不愿意整理病房，但规定必须得做这件事。\u003c/p>\u003cp>第二步：做转念，告诉我自己，整理病房这件事情是我自己主动选择去做的，如同主动整理自家屋子一样。\u003c/p>\u003cp>第三步：挖意图，挖掘我选择这件事的背后意图，也就是如同整理自家屋子一样，干净整洁了，工作时会更舒心、同时整理病房的时间也可以和病人多沟通，了解病人情况，会让护患关系更加和谐，更有利于开展工作。\u003c/p>\u003cp>这样，依照以上三步法，让我成功从抗拒整理病房到主动地、心平气和地、高效地整理病房，并且会继续坚持下去。\u003c/p>\u003cp>【Where适用边界】本方法适用于你在面对一些不想做又不得不做的事情时。\u003c/p>","interaction":"\u003cp>A学习者拆为己用：学习者拆为己用：\u003cbr>【A1显像提问】\u003cbr>分享完我的案例，接下来请小伙伴们回想一下，你最近一个月有没有遇到一些什么不愿做又不得不做的事呢？\u003cbr>比如：领导让你做宣传视频，但是你不愿意做，碍于命令又不得不做时；上了一天班，身心俱疲，特想休息一会儿，但是孩子又吵着让你陪他玩耍时；体检结果不理想，医生建议控制饮食、减肥锻炼身体，但是又难以抵御美食、迈不开腿时；下班回家，想安静一会儿，但是父母却拉着你不停说家长里短时等等……当时具体情况是什么样的，你的心情是样的怎么样的呢？\u003cbr>请大家在小组内回忆一下，2-3分钟时间，稍后我们邀请1-2位小伙伴来做分享：\u003cbr>好，哪一位小伙伴给大家做分享：时间2分钟A学习者拆为己用：学习者拆为己用：\u003c/p>\u003cp>【A1显像提问】\u003c/p>\u003cp>分享完我的案例，接下来请小伙伴们回想一下，你最近一个月有没有遇到一些什么不愿做又不得不做的事呢？\u003c/p>\u003cp>比如：领导让你做宣传视频，但是你不愿意做，碍于命令又不得不做时；上了一天班，身心俱疲，特想休息一会儿，但是孩子又吵着让你陪他玩耍时；体检结果不理想，医生建议控制饮食、减肥锻炼身体，但是又难以抵御美食、迈不开腿时；下班回家，想安静一会儿，但是父母却拉着你不停说家长里短时等等……当时具体情况是什么样的，你的心情是样的怎么样的呢？\u003c/p>\u003cp>请大家在小组内回忆一下，2-3分钟时间，稍后我们邀请1-2位小伙伴来做分享：\u003c/p>\u003cp>好，哪一位小伙伴给大家做分享：时间2分钟\u003c/p>\u003cp>【学习者案例记录A1】：\u003c/p>\u003cp>人物:韧木\u003c/p>\u003cp>事情:最近一个月内，听这节课之前，在学校不想备课写教案，所以写教案很拖拉\u003c/p>\u003cp>【A1+反思加工】\u003c/p>\u003cp>听了小伙伴的分享，大家也讨论分享了自己的类似情况，我们再回顾今天学习的三步法：\u003c/p>\u003cp>1 列清单；列出自己不想做但又不得不做的事情清单。\u003c/p>\u003cp>2 做转念：告诉自己这是自己选择要做的事情。\u003c/p>\u003cp>3 挖意图：挖掘这件事情的根本原因，找到我们选择做这件事的背后意图。\u003c/p>\u003cp>接下来，大家结合刚才分享的自己的案例，如果时光倒流，再次回到当时的情境下，用我们今天学习的三步法，你会如何转变心态更好地完成这件事情呢？请大家继续在组内讨论，“分享即是成长，每人都说一说”，时间为2-3分钟。然后我们请一位小伙伴来分享。\u003c/p>\u003cp>好，哪一位小伙伴给大家做分享：时间2-3分钟\u003c/p>\u003cp>【学习者案例记录A1＋】\u003c/p>\u003cp>人物：韧木\u003c/p>\u003cp>事件：\u003c/p>\u003cp>回到没听这节课之前，我会把备课写教案列入我的不得不做的事情清单。\u003c/p>\u003cp>告诉自己，备课这件事是我自己选择主动去做的。\u003c/p>\u003cp>因为备课能迭代在拆书帮学到的技能，便于给学生讲课，便于把重心放到学习者身上，并且熟悉教学内容，对于讲课和教学竞赛都更有帮助。\u003c/p>\u003cp>【结语】（感谢小伙伴的分享）\u003c/p>\u003cp>今天我们学习了，变被动为主动的转念三步法：列清单、做转念、挖意图。希望大家将来在工作生活中多多运用，助力你顺利完成每一件事。\u003c/p>\u003cp>今天的学习结束，感谢聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1762984912000,"updated_at":1763021343000,"ria":true},{"id":18932,"topic":"解锁真诚表达的艺术","learn_goal":"","remark":"你是否常常：\n\n心里充满感谢，却只会说\"谢谢\"？\n收到赞美时，总觉得少了点什么？\n想让对方真切感受到你的心意？\n\n《非暴力沟通》将带我们发现表达感激的全新视角！\n\n在这场特别的拆书活动中，我们将通过书中真实生动的对话案例，探索一种让感谢更有温度的沟通方式。你会发现：\n\n为什么有些感谢让人印象深刻，有些却流于表面\n如何让简单的\"谢谢\"承载更多心意\n什么样的表达能让对方真切感受到你的真诚\n\n活动亮点：\n\n✅ 真实场景还原：工作、家庭中的典型情境\n✅ 互动体验环节：轻松有趣的现场演练\n✅ 实用沟通锦囊：立即上手的表达技巧\n\n你将收获的不仅是一种沟通方法，更是建立一个与他人心灵沟通的桥梁。\n","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"澄心","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>我再来跟大家正式的介绍一下我自己，我叫澄心，\u003c/p>\u003cp>三个标签：\u003cbr>第一个标签传媒行业的从业者，有十几年的工作的经验。\u003c/p>\u003cp>然后第二个标签是新晋的拆书帮的一级拆书家。\u003c/p>\u003cp>然后第三个标签是瑜伽冥想的一个爱好者。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>跟随我完成本次RIA现场学习后，学习者能够在需要表达感谢的场景中，不是只会说“谢谢”，而是用“表达感激三要素”让感谢更真诚，提升沟通质量。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>因为今天会有讨论的环节，为了方便讨论，我们先进行分组，两边各一组。\u003c/p>\u003cp>【FAB图书介绍】\u003c/p>\u003cp>然后今天我带来的是一本非常经典的这个图书，非暴力沟通啊。\u003c/p>\u003cp>F（Feature，特征）\u003c/p>\u003cp>非暴力沟通这本书的话，它是马歇尔卢森堡博士集合 50 年的这种案例的经验和心血去集合成的这样一本沟通类的著作嗯。这本书，它是把复杂的一个沟通给变成了简单的 4 个步骤，观察、感受、需求和请求，通过这样的一个 4 步骤的一个沟通公式来帮助我们去解决生活当中的一些沟通的难题，就像开车的时候导航一样，它会引领我们可以以最快捷的一个路线，然后达到我们最终的一个和他人沟通的共赢的一个目标。\u003c/p>\u003cp>A（Advantage，优势）\u003c/p>\u003cp>然后这本书的话，它对比于同类的这个沟通类的图书，它是会摒弃掉一些这个复杂的、技巧性的，这种学习更多的是可以直指沟通的一个核心，就是我们人与人之间的这种感受和需求的链接啊。然后这部分的链接的话，它可以帮助我们更好的去理解到彼此的这个就是整个沟通的一些初心和目标。\u003c/p>\u003cp>B（Benefit，学习这本书的利益）\u003c/p>\u003cp>然后这本书今天希望大家通过学习这个非暴力沟通的这个书，可以掌握到一个沟通的公式，然而这个公式的话可以应用我们生活当中，可以更高效、有质量的去解决我们的这个沟通的问题啊。\u003c/p>\u003cp>B1（Benefit，学习这个片段的利益）\u003c/p>\u003cp>而今天我们来学习的这个片段，它就是这个非暴力沟通的公式在表达感谢的这个场景当中的一个应用。然后如果你最近有想要去身边表达感谢的家人、朋友等等，你都可以尝试用这个公式来去跟他们做一些这个练习，然后来促进我们彼此关系的一个更和谐。\u003c/p>\u003cp>然后这个是今天的那个片段，然后我会发给大家，然后大家可以花一分钟的时间看一下，看好的朋友可以抬头示意我。 \u003c/p>","ratings_count":2,"texts":[{"id":23263,"quote":"\u003cp>R阅读原书拆页-TF2-2 《非暴力沟通》\u003c/p>\u003cp>表达感激的三个要素\u003c/p>\u003cp>在使用非暴力沟通表达感激时，我们会清楚地包含以下三个要素，\u003c/p>\u003cp>他人做了什么增进了我们的福祉。\u003c/p>\u003cp>我们有哪些需要因此得到了满足。\u003c/p>\u003cp>因为这些需要得到了满足，引起了我们什么样的愉悦感受。\u003c/p>\u003cp>表达这三个要素时，并不一定要遵照以上的顺序。有时哪怕是一个微笑或一句简单的“谢谢你”就足以传递这一切。不过，如果我们想要确保对方能够充分收到我们的心意，用语言完整地表达这三个要素是有意义的。在下文的对话中，大家可以看到如何用这三个要素来表达“赞赏”。\u003c/p>\u003cp>学员：（在工作坊结束后来找我）马歇尔，你太棒了！\u003c/p>\u003cp>马歇尔：我好像不太理解你为什么要这么称赞我。\u003c/p>\u003cp>学员：为什么？你的意思是？\u003c/p>\u003cp>马歇尔：人们给过我无数的头衔，但我却完全无法从这些表述中学到什么。我想从你对我的赞赏中有所学习，并且因此感到喜悦，但我需要你再多说一些。\u003c/p>\u003cp>学员：比如说？\u003c/p>\u003cp>马歇尔：首先，我想知道我说了什么或者做了什么让你的生命变得更加美好。\u003c/p>\u003cp>学员：嗯，你很有智慧。\u003c/p>\u003cp>马歇尔：恐怕你刚刚又给了我另一个评判。我依然想知道我做了什么让你的生命更美好。\u003c/p>\u003cp>学员：（思索了一会儿后，她指着自己在工作坊上写下的笔记）看这两处，就是你说的这两点。\u003c/p>\u003cp>马歇尔：噢，所以你赞赏的是我说的这两点？\u003c/p>\u003cp>学员：是的。\u003c/p>\u003cp>马歇尔：接下来，我想要知道这些话带给你的感受。\u003c/p>\u003cp>学员：感到充满希望，并且释然。\u003c/p>\u003cp>马歇尔：那么现在我想知道，我说了这两点满足了你哪些需要。\u003c/p>\u003cp>学员：我一直无法和我18岁的儿子沟通，一直在努力寻找一种更加情意相通的方式和他相处，你说的这两点让我找到了方向。\u003c/p>\u003cp>听到这三个要素的内容（我做了什么，她有何感受以及满足了她#些需要）后，我就能真正和她一起享受这份赞赏。如果一开始就用非暴力沟通的方式来表达，她可以说：“马歇尔，当你说这两点时（向我展示她的笔记），我感到充满了希望并且释然，因为我一直在寻找方法和儿子连结，你的这些话给了我方向。\u003c/p>","explains":"\u003cp>好的，我看到大部分朋友都已经那个看完了这个片段，我来分享一下我对这个片段的一个理解。\u003c/p>\u003cp>\u003cstrong>What\u003c/strong>\u003c/p>\u003cp>就是表达感激的这三要素的话，它是分别从这个行动、价值和感受这三个维度表达我们感谢的这样的一个表达的框架。然后这三个维度它会让我们整个的这个感谢会变得更加的有深度和温度。 \u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>\u003c/p>\u003cp>为什么要这样去表达呢？大家可能听上来会觉得有一点点复杂，其实这样的话它是会让我们可以比简单的这种表达一个”谢谢”这样的话太流于表面了，而这样的多维度多角度的、更具象化的这种表达的话，它会让我们可以更深度的让对方感觉到他的付出，他对我们的帮助，然后我们看见了，然后我们感受到了，从而加深彼此的这种理解和关系的连接，给对方一个正向的反馈，\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>\u003c/p>\u003cp>具体怎么来去做就是：\u003c/p>\u003cp>第一步行动，行动的话就是要告诉对方他具体做了什么样的一个事情啊。\u003c/p>\u003cp>第二步的话价值，就是对方做的这个事情实际给到我们的这个帮助，和改变是什么啊？\u003c/p>\u003cp>第三步的话就是感受，就是对方给到我们的这个行为和帮助，对于我们具体带来了什么样的一个美好的感受和积极的这种情绪？可以去更详细的去做一个表达。 \u003c/p>\u003cp>【案例】\u003c/p>\u003cp>最近的话其实我自己就有一个这样的一个例子，就是在工作当中。\u003c/p>\u003cp>项目上其实出了一点小的一个问题，因为客户跟老板之间就是关系是一个很熟悉的这么一个状况。所以客户直接就把这个小的问题可能直接投诉到了公司最大的这个老板那里，然后公司也是发了相应的邮件通报可能批评这件事情，所以当时造成了一个比较严重的这么一个情况。按公司的一些规章制度来说，这样可能会有一个比较重的奖金这方面的一个处罚的情况。我们领导因为他会比较了解事情的一个前因后果，也比较了解我们所在过程当中所做的一些努力，所以他就拿到我们对于这个事情的一个补救的方案，然后直接到 CEO 那里边，然后去跟 CEO 沟通了半个多小时这个事情，然后最终是把这个处罚相应的减轻了。我自己这件事情发生到结束可能前后也就是一个小时的时间，反正也是吓出一身冷汗，然后得到领导的这个回复之后，然后当时就是只是简单的干巴巴的说了一个“谢谢领导”，然后这件事就结束了。\u003c/p>\u003cp>【反例变正例】\u003c/p>\u003cp>但其实现在回想起来，如果说再给我一个机会的话，我如果跟领导去表达这个事情的话，其实可以尝试用这个三要素去进行一个表达：\u003c/p>\u003cp>1、就是领导拿到我们的这个方案，然后到 CEO 那里边很辛苦的游说了半个小时的这个时间；\u003c/p>\u003cp>2、然后第二部价值，他给到我们的这个支持的话，让我们感受到就是我们整个的这个努力的话没有白费，这个辛苦会被领导和公司所看见；\u003c/p>\u003cp>3、然后感受的话，得到了领导的这个力挺，会觉得就是在今后的话工作会更加的去出力，可以为公司就是更好的去做好这些，相应的一个工作的善后，然后也是希望后面的工作的话把这个项目可以做成一个标杆的项目，然后也让领导为我们扛下的这个压力。没有白费。\u003c/p>\u003cp>\u003cstrong>Where\u003c/strong>\u003c/p>\u003cp>其实这个沟通的三要素，在我们的生活当中大家听上来会觉得有一点点的这个复杂，它是其实不太适用于说这个普通的一些交情和一些陌生人之间。比如说人家可能只是简单的给你递滴一下水杯，您可能说到说一个谢谢就可以了，就已经很得体了，对，或者说没有那么熟悉的一些人和这个很小的一些帮助上。但是它会更适用于就是大家会有一些深度的这个交流沟通和比较重要的这种关系，比如说家人、好朋友等等，对方确实给你帮了一个比较大的忙，然后他会帮助到了你的生活和工作当中，所以它也是有它的一个适用的一个场景的。 \u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>当然有的小伙伴可能会觉得就是我这么复杂的去表达这些，会不会觉得就是有点刻意和肉麻等等嗯？但其实我并不这么看待这个问题，比如说如果说你想要搬家，然后你朋友来帮你搬家，然后你可能也不会简单的就跟朋友说一句“谢谢”，你可能会跟朋友说：“唉今天多亏了你来，然后大家一起搬这个柜子，才解决了我今天很大的一个这个问题，要不然我一个人肯定搞不定这个事情”，其实你看这样的一个场景当中，你就很自然的把对方做了什么，给你带来了什么样的帮助，和你在这个过程当中收获，就是很被温暖到的这个过程，你都已经很自然的流露和表达出来的，所以我们就要在下面的这个小组当中可以去进行这样的练习，在生活当中也可以去多练习，可以让我们这种应用这三要素去表达感谢的时候，更加的这个自然。\u003c/p>","interaction":"\u003cp>【A2分步催化-激活应用场景】\u003c/p>\u003cp>下面的话我们其实可以在这个小组当中可以去演练一下，就是我们想要感谢的这个场景在哪里啊？\u003c/p>\u003cp>大家可以去想一下，在未来的两周的时间，有没有你想要去感谢的人和这样的一个场景和事情啊？\u003c/p>\u003cp>它可能是比如说家人花好几个小时，用心的给你做了一顿很可口的饭菜；\u003c/p>\u003cp>也可能是你的，你在特别紧急的这个项目当中，同事主动的来去支持了你，给你提供了很大的一个帮助；\u003c/p>\u003cp>【分组讨论】\u003c/p>\u003cp>然后这样的这个场景，还按照刚才的这个小组，大家可以有 3 分钟的时间去讨论一下，不说感谢的具体的方法，只是说我们想要去感谢的一个场景和对象。 \u003c/p>\u003cp>我听到大家对于感谢的场景都特别带劲，可以请哪个伙伴来分享一下吗？可以请张老师来分享。张老师你有一分钟的时间啊。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>张老师：\u003c/p>\u003cp>这个我用这个三个步骤夸了一下咱们的拆书活动，对，感谢的场景就是感谢咱们拆书帮的这个活动。嗯，然后给我带来了非常多的收获啊。然后就这个场景。 \u003c/p>\u003cp>我：谢谢张老师，刚才我听到这边好像有要感谢妈妈的一个那个场景，可以分享一下。\u003c/p>\u003cp>高婷：\u003c/p>\u003cp>因为正好今天学习，我就突然反思了一下，就是前段时间不是那个母亲节嘛？我就想着说，就是这两年好像就是不知道是因为忙工作啊还是什么的，就是在感谢这个母亲这方面哈。太简单了，好像很少，只是说给我妈发那个妈母亲节快乐发了一个红包。 然后啥也就没有了。\u003c/p>\u003cp>我：就是感觉这种感性会比较流于表面。 \u003c/p>\u003cp>高婷：对，情感上就这两年有点不太深入，早些年上学那会儿好像特别还写信之类的啊。对，就是很有仪式感的那会儿。这几年好像就不知道太忙啥了在这方面。 \u003c/p>\u003cp>谢谢张老师跟高婷的那个分享啊，我觉得说到了一个特别好那个场景。\u003c/p>\u003cp>【A2催化应用-规划应用步骤】\u003c/p>\u003cp>所以我们的这个下一个环节就是来去针对这个场景去规划未来我们怎么用今天我们学的这个小小的一个片段，能在我们生活当中的这个场景，去应用这三要素去表达一个感谢。所以就是接下来的话，在未来一个月内你有没有想要感谢对方的这样的场景当中去应用一下这个三要素，再来帮助大家回顾一下这个三个小点。 \u003c/p>\u003cp>1、第一步的话就是行动，就是对方具体为你做了哪些行动事情，让你会特别的感动的，就比如说妈妈可能平时会为你做很多，然后给你做饭等等，然后关心你等等等的这些。\u003c/p>\u003cp>2、然后第二步的话价值就是他为你提供的这些帮助对你带来了什么样的改变，他可能会帮你减轻了很多的这些工作上的压力，给到了你很多情感上的支持和陪伴，给到你的这个价值是什么啊？\u003c/p>\u003cp>3、然后第三点的话是这个感受上的，就是他对你的帮助和这些行动给你带来了什么样的这个积极的情绪和美好的这种感受，他可能会让你觉得有家人的陪伴很温暖，母女之间有这种爱的流动。\u003c/p>\u003cp>所以待会我们就会针对刚才提到的场景，大家去用这 3 个方法去规划未来一个月内的感谢场景。\u003c/p>\u003cp>【分组讨论】好的，那现在每个小组，有 2 分钟的时间，大家可以讨论一下。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>走安娜：\u003c/p>\u003cp>那个我的美国大 boss 马上要退休了，5月底他就退休了，然后之前我可能脑子里没有太多词， thank you，然后通过今天澄心的这个启发，我说想出来几个几句话我觉得可以表达给。\u003c/p>\u003cp>我说首先您提供了给我一个特别安全有爱的工作氛围，以及强有力的工作支持。我知道你有好几百名员工都汇报给您，然而您却做到了，我找到您的事情之后居然事有回应我，这让我十足的体会到了来自美国大 boss 的关爱，如果有机会，我希望您以后来中国的时候一定告诉我，我愿意陪伴你，表达我的感谢。 \u003c/p>\u003cp>【总结】\u003c/p>\u003cp>特别棒的一个表达，然后特别感谢今天大家的这个参与，希望在后面可以多练习。然后再来回顾一下今天这个片段的那个学习，我们学习了那个表达感激三要素里边表达感谢的这个场景的，通过我们的行动、价值和感受这三要素，然后去多维度的表达我们的感谢，让我们的这个谢谢不再流于表面，可以说的更走心一些。然后特别感谢大家，然后可以在生活当中更多练习这个片子，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1747897504000,"updated_at":1748900070000,"ria":true},{"id":18808,"topic":"你知道感激的魅力吗？","learn_goal":"","remark":"带你认识感激的魅力，把冲突变黄金。","level":"TF3-3","duration":80,"status":19,"type":0,"chaishujia":{"username":"余火说亲子","city":""},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>\u003cstrong>分组；根据现场的情况，我们这里分成3组，左右各一组，后面一组，一共三组。\u003c/strong>\u003c/p>\u003cp>各位书友大家下午好！\u003c/p>\u003cp>欢迎大家来到拆书现场，我是2024年12月11日过了二级拆书家，今天根据《拆书家成长手册》，我拆的是TF3-2, 希望大家有新的体验。\u003c/p>\u003cp>我叫余火，用三个标签来介绍我自己。\u003c/p>\u003cp>大家好，我叫余火，年年有余，红红火火。用三个标签来给大家介绍一下，\u003c/p>\u003cp>我是一名一线教师，从事26年的教学，22年的班主任，用三个标签吧！\u003c/p>\u003cp>第一个是爱学生。因为热爱，我干了26年还是那么喜欢，今年是第27个年头。\u003c/p>\u003cp>第二个是爱创新。在班级里面打造了周末做菜，演讲，口语表达，等创新的活动。\u003c/p>\u003cp>第三个爱学习。从2015年到现在，我学习演讲，心理学，写作和读书。\u003c/p>\u003cp>\u003cstrong>请书友们分成两组，便于后面的讨论\u003c/strong>\u003c/p>\u003cp>学习目标：\u003c/p>\u003cp>【片段1学习目标】\u003c/p>\u003cp>学习片段1，懂得如何感激别人，以及感激的三个要素。\u003c/p>\u003cp>【片段2学习目标】\u003c/p>\u003cp>学习片段2，分析自己，认知感激别人的重要性，探索突破感激的内心障碍，不给自己留下遗憾。\u003c/p>\u003cp>【两个片段之间的逻辑关系】\u003c/p>\u003cp>两个片段是递进关系，先学会“感激的要素”，知道如何去感激别人。再到突破自己的感激层次。\u003c/p>\u003cp>二者可以单独使用，但是组合效果加倍。\u003c/p>\u003cp>图书介绍（1-2分钟）\u003c/p>\u003cp>1、事件场景 ：\u003c/p>\u003cp>感激别人，其实在我们的生活’中，也是时常会遇到，当别人感激我们时，有没有觉得是非常开心的事情，当然有时候，也可能没有带来好的体验，甚至会觉得有点摸不着头脑，比如我说感谢你今天能来听课。\u003c/p>\u003cp>2、提问：\u003c/p>\u003cp>大家有没有碰到过类似的情况，你想感激别人，但是不知道如何说，然后大家还挺尴尬。\u003c/p>\u003cp>3、影响：\u003c/p>\u003cp>其实生活中会遇到，直接或者间接帮助过我们的人，感激会让我们得到滋养，没有感激别人可能会有一些遗憾。\u003c/p>\u003cp>4、解决：\u003c/p>\u003cp>那怎么办呢？今天和大家拆的这本书是《非暴力沟通》，里面给了一些具体的案例启发，今天带大家拆解两个拆页，两个拆页是递进关系，围绕感激的方式和意义来做进一步推进。\u003c/p>\u003cp>第一个RIA\u003c/p>\u003cp>学习目标1：\u003c/p>\u003cp>大家跟随我完成本次RIA现场学习后，第一个目标懂得感激三要素，可以更好的感激别人，理解别人的感激。\u003c/p>\u003cp>现在大家先来阅读片段，请大家用2分钟的阅读时间，阅读完后给我一个眼神示意一下。\u003c/p>","ratings_count":5,"texts":[{"id":23137,"quote":"\u003cp>3-3原文片段1表达感激的三个要素\u003c/p>\u003cp> 在使用非暴力沟通表达感激时，我们会清楚地包含以下三个要素：\u003c/p>\u003cp>·他人做了什么增进了我们的福祉。\u003c/p>\u003cp>·我们有哪些需要因此得到了满足。\u003c/p>\u003cp>·因为这些需要得到了满足，引起了我们什么样的愉悦感受。\u003c/p>\u003cp> 表达这三个要素时，并不一定要遵照以上的顺序。有时哪怕是一个微笑或一句简单的“谢谢你”就足以传递这一切。不过，如果我们想要确保对方能够充分收到我们的心意，用语言完整地表达这三个要素是有意义的。在下文的对话中，大家可以看到如何用这三个要素来表达“赞赏”。\u003c/p>\u003cp>学员：（在工作坊结束后来找我）马歇尔，你太棒了！\u003c/p>\u003cp>马歇尔：我好像不太理解你为什么要这么称赞我。\u003c/p>\u003cp>学员：为什么？你的意思是？\u003c/p>\u003cp>马歇尔：人们给过我无数的头衔，但我却完全无法从这些表述中学到什么。我想从你对我的赞赏中有所学习，并且因此感到喜悦，但我需要你再多说一些。\u003c/p>\u003cp>学员：比如说？\u003c/p>\u003cp>马歇尔：首先，我想知道我说了什么或者做了什么让你的生命变得更加美好。\u003c/p>\u003cp>学员：嗯，你很有智慧。\u003c/p>\u003cp>马歇尔：恐怕你刚刚又给了我另一个评判。我依然想知道我做了什么让你的生命更美好。\u003c/p>\u003cp>学员：（思索了一会儿后，她指着自己在工作坊上写下的笔记）看这两处，就是你说的这两点。\u003c/p>\u003cp>马歇尔：噢，所以你赞赏的是我说的这两点？\u003c/p>\u003cp>学员：是的。\u003c/p>\u003cp>马歇尔：接下来，我想要知道这些话带给你的感受。\u003c/p>\u003cp>学员：感到充满希望，并且释然。\u003c/p>\u003cp>马歇尔：那么现在我想知道，我说了这两点满足了你哪些需要。\u003c/p>\u003cp>学员：我一直无法和我18岁的儿子沟通，一直在努力寻找一种更加情意相通的方式和他相处，你说的这两点让我找到了方向。\u003c/p>\u003cp> 听到这三个要素的内容（我做了什么，她有何感受以及满足了她哪些需要）后，我就能真正和她一起享受这份赞赏。如果一开始就用非暴力沟通的方式来表达，她可以说：“马歇尔，当你说这两点时（向我展示她的笔记），我感到充满了希望并且释然，因为我一直在寻找方法和儿子连结，你的这些话给了我方向。”\u003c/p>","explains":"\u003cp>好的，我看伙伴已经读完了，接下来，我来讲解一下这个片段。\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>（简单互动）大家阅读后哪里最有体会？\u003c/p>\u003cp>拆书家；你刚才看了，哪些地方你有感觉？\u003c/p>\u003cp>书友1；你表扬我，但是我很想知道我做了什么?你做了什么我有感觉。细节没有到位，带来什么感受，\u003c/p>\u003cp>拆书家；刚才看书，是否被里面的人和事触动，被别人感激是什么感觉。\u003c/p>\u003cp>书友2；我觉得生命被点亮。\u003c/p>\u003cp>拆书家；你总是能给到这么高能量的词语，生活中会有几个频率很高的词语，我给大家做几个词语的区别，这些词语在生活中程度不同，分别是感谢，感激，感恩和感动。\u003c/p>\u003cp>【概念讲解、对比强化】\u003c/p>\u003cp>感谢---细小帮助\u003c/p>\u003cp>感激---内心触动，不是小事\u003c/p>\u003cp>感恩---感恩别人摆脱困境，一辈子大事\u003c/p>\u003cp>感动---别人的善行引发内心触动。 \u003c/p>\u003cp>比如刚才他给我开了门，这是感谢。第二个内心有触动，比如刘同学从外地带了小熊猫，那么远带来，我内心很有感觉。感恩是别人帮助你摆脱困境，一辈子的感恩，可能是身体或者家庭遭遇困境，比如我小时候身体不佳，认了一个干爸，一路帮助我，到现在还是很感恩，多数运用于大的恩情。感动是别人做了一些事情，不一定是直接帮助你，但是他的行为带给你的影响，比如中国古语里的一方有难八方支援，白衣天使的行为感动无数中国人，说了这么多，你们学会了吗？\u003c/p>\u003cp>给大家做一个连线，检测学习成果。\u003c/p>\u003cp>感谢--你拿东西，别人帮你开门\u003c/p>\u003cp>感激--自己在遇到挫折受人指点\u003c/p>\u003cp>感恩--父母含辛茹苦抚养你上大学\u003c/p>\u003cp>感动--疫情的时候白衣天使的付出\u003c/p>\u003cp>总的来说，感谢是基础，感激和感恩是在感谢的基础上更进一步的情感表达，而感动则是更深刻的情感体验。\u003c/p>\u003cp>【HOW】聚焦三步法：\u003c/p>\u003cp>第一步；他人做了什么增进了我们的福祉。\u003c/p>\u003cp> 他人做了什么，可能是具体的行为。比如说，别人帮你倒了一杯水，或者是帮你背了包，也有可能是帮完成了某件事情。这种做了什么呢？可能是言语上，也有可能是具体行为上，一定是比较具体的动作。\u003c/p>\u003cp>第二步；我们有哪些需要得到了满足。\u003c/p>\u003cp>每个人都有不同的需要，按照马斯洛的这个五个层次的需要，在不同生活范围内，可能某一项需要被得到满足。当我们特别饿的时候，别人给了一个吃的。在学习成长中，别人为我们推荐了一本书，让我们走出了一个困境。\u003c/p>\u003cp>第三步；因为这些需要得到了满足，引起了我们什么样的愉悦感受。\u003c/p>\u003cp>1、生理感受：这是人类最基本、最直接的感觉，包括对食物、水的需求，以及对冷、热、疼痛等基本感觉。\u003c/p>\u003cp>2、心理感受：包括情感、情绪等，例如快乐、悲伤、愤怒、恐惧等。\u003c/p>\u003cp>3、认知感受：这是对外部世界和自身知识的理解和感知，包括对事物的认识、记忆、思考等。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>这个地方哪里比较难，当要感激别人时候，每个人感受可能不太一样。我们感受到的，有可能在别人那里，还没有引起共鸣。有的时候，会有一个不太同频的信息。如果不同频的话，可能会带来需求的满足或者体验感不一样。\u003c/p>\u003cp>【举例子】\u003c/p>\u003cp> 有一次，一位家长打电话告诉我，感激我给她孩子写的评语，爸爸看了特别激动，有些文字看了好几遍，都看哭了，我听了以后，心里特别开心。\u003c/p>\u003cp>【WHERE】\u003c/p>\u003cp>感激适用于我们生活当中的各种关系当中，不论是同事关系、亲子关系，或者是在陌生场合，当别人做出具体行为的时候，我们都可以表达这样的感激之情。可以通过面对面，也可以通过线上，或者以其他的书信等方式。\u003c/p>","interaction":"\u003cp>拆书家提问设计：\u003c/p>\u003cp>编剧本\u003c/p>\u003cp>为了让大家更好的掌握感激的方法，接下来模拟演练，未来如何使用这个方法。大家可以以现实为场景，与同事、朋友或者家人之间出现需要感激的地方，请利用感激三步法，帮助自己或他人滋养身边的关系，。\u003c/p>\u003cp>邀请大家编写一个剧本，设计出时间、地点、人物、角色、起因经过结果和双方的对话。给大家五分钟的时间，之后我邀请小伙伴来分享，另外一位小伙伴来点评。下面是具体格式：\u003c/p>\u003cp>要求：在对话中要体现感激三步法。\u003c/p>\u003cp>时间：\u003c/p>\u003cp>地点：\u003c/p>\u003cp>人物：\u003c/p>\u003cp>内容：（事件的大概过程，角色的定位，具体的演绎过程。）\u003c/p>\u003cp>对白：（演绎对话的具体内容）\u003c/p>\u003cp>旁白：（介绍演绎的背景、各种人物关系、人物的内心想法等）\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>A学习者\u003c/p>\u003cp>时间；未来的有一天\u003c/p>\u003cp>地点；从家到来拆书学习的路上\u003c/p>\u003cp>人物：我和儿子还有庆茹\u003c/p>\u003cp>内容：事情是儿子跟我说话最近很扎心，妈妈觉得心情不是很好，所以，我特别难过。\u003c/p>\u003cp>演绎过程；\u003c/p>\u003cp>妈妈；我儿子说话特别扎心，通过她告诉我，我感谢庆姑娘告诉我另一个视角。\u003c/p>\u003cp>庆姑娘；你可以换一个角度看你儿子，也许她是想告诉他爱你。\u003c/p>\u003cp>妈妈；真的感谢庆姑娘给我说这个，让我在那个当下视角打开了，我的心也更定了，再次看见孩子，心里还挺温暖的感觉。\u003c/p>\u003cp>庆姑娘；其实也没什么，听到你说这些，我也很开心。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":23138,"quote":"\u003cp>【过渡】\u003c/p>\u003cp>刚刚我们说到了感激的三个要素，运用这三个要素呢，可以让我们把想感激的人和事儿可以做得更好。但接下来还有一些困惑，不知道大家心中有没有，就是有一些人或者有一些事，你不太想去感激他，或者是你想感激，但是又不知道如何去跨过心里面的这道坎儿。\u003c/p>\u003cp>【学习目标2】希望跟随我完成下面的第二个RIA片段学习后，能够理解感激的重要性，跨越自己内心的这个障碍，让自己没有遗憾的去做。\u003c/p>\u003cp>一、【A1】请大家自测（1分钟）\u003c/p>\u003cp>首先，在开始之前，先请大家做一个简单的测试，这个测试能够帮助你快速的检定你的感激程度。请大家根据实际情况，快速地给自己打分。\u003c/p>\u003cp>自测量表内容：\u003c/p>\u003cp>请仔细阅读下面表格中的每个问题，然后根据自己的实际情况按照1~7的标准给自己打分。1分代表强烈不同意， 2分代表不同意  ，3分代表有点不同意 ， 4分代表中立，5分代表有点同意，6分代表同意，7分代表强烈同意。打分完成后，将以上五项自测分数的合计数加总起来。算好分数的小伙伴可以举手示意。好，我们现在开始，1分钟之后，我将解读这个自测量表\u003c/p>\u003cp>测试你的感恩水平－感恩问卷\u003c/p>\u003cp>这个量表是研究了15年感恩的心理学家Robert Emmon编写的，经过无数心理学实验被学术界认为是测量感恩的最靠谱的量表。\u003c/p>\u003cp>1、我生命中有特别多让我觉得感激的东西或者人。\u003c/p>\u003cp>A、强烈不同意    B、不同意     C、有点不同意     D、中立\u003c/p>\u003cp>E、有点同意      F、同意       G、强烈同意\u003c/p>\u003cp>2、如果我要列出所有我所感激的东西，那这个单子将会很长。\u003c/p>\u003cp>A、强烈不同意    B、不同意     C、有点不同意     D、中立\u003c/p>\u003cp>E、有点同意      F、同意       G、强烈同意\u003c/p>\u003cp>\u003cu>3、当我看这个世界时，我看不到很多值得我感激的东西或者人。\u003c/u>\u003c/p>\u003cp>A、强烈不同意    B、不同意     C、有点不同意     D、中立\u003c/p>\u003cp>E、有点同意      F、同意       G、强烈同意\u003c/p>\u003cp>4、我对很多不同的人感激。\u003c/p>\u003cp>A、强烈不同意 B、不同意 C、有点不同意 D、中立\u003c/p>\u003cp>E、有点同意 F、同意 G、强烈同意\u003c/p>\u003cp>5、随着岁月的增长我发现自己越来越能够欣赏那些在我个人历史中的人，\u003c/p>\u003cp>事件或者情境。\u003c/p>\u003cp>A、强烈不同意 B、不同意 C、有点不同意 D、中立\u003c/p>\u003cp>E、有点同意 F、同意 G、强烈同意\u003c/p>\u003cp>\u003cu>6、在我感觉到对什么事情或者人感激之前，可能已经过了很长时间。\u003c/u>\u003c/p>\u003cp>A、强烈不同意 B、不同意 C、有点不同意 D、中立\u003c/p>\u003cp>E、有点同意 F、同意 G、强烈同意\u003c/p>\u003cp>7、我的人生被深深地祝福了。\u003c/p>\u003cp>A、强烈不同意 B、不同意 C、有点不同意 D、中立\u003c/p>\u003cp>E、有点同意 F、同意 G、强烈同意\u003c/p>\u003cp>\u003cu>8、老实说，要让像我这样的人感恩，那需要是一件非常重大的事情。\u003c/u>\u003c/p>\u003cp>A、强烈不同意 B、不同意 C、有点不同意 D、中立\u003c/p>\u003cp>E、有点同意 F、同意 G、强烈同意\u003c/p>\u003cp>9、我对生命本身有种非常美好的感恩的感觉。\u003c/p>\u003cp>A、强烈不同意 B、不同意 C、有点不同意 D、中立\u003c/p>\u003cp>E、有点同意 F、同意 G、强烈同意\u003c/p>\u003cp>10、我经常回想我的生命是如何因为别人的努力而变得更轻松自在的。\u003c/p>\u003cp>A、强烈不同意 B、不同意 C、有点不同意 D、中立\u003c/p>\u003cp>E、有点同意 F、同意 G、强烈同意\u003c/p>\u003cp>如何计算你的分数\u003c/p>\u003cp>1、把你在1，2，4，5，7，9和10项的分数加起来。\u003c/p>\u003cp>2、把你在3，6，8三项的得分反过来相加。也就是说，如果你得分是7分，那么把它变成1，如果你得分是6分，那么把它变成2，以此类推。\u003c/p>\u003cp>3、把你刚刚在3，6，8三项的反向得分相加之后，再加上第一步你的总分数，就是你最后的感恩水平的分数。这个分数应该在10到70之间。\u003c/p>\u003cp>如何解读你的分数\u003c/p>\u003cp>65-70分：极高的感恩水平在这个分数值的人有能力把生命看成是一份礼物。对你来说，感恩是一种生活方 式。\u003c/p>\u003cp>59-64分：很高的感恩水平\u003c/p>\u003cp>你在生活里经常表达自己的感恩，你有能力很容易的认识到别人是怎么的帮助了你。未来的21天练习将帮助你认识到并且提高你在各个领域的感恩水平。\u003c/p>\u003cp>53-58分：较高的感恩水平\u003c/p>\u003cp>你的感恩水平在平均值以上，而且你发现花时间去想值得你感激的事情是比较容易的。你会在未来的21天非常享受我们的感恩挑战旅程。\u003c/p>\u003cp>46-52分：平均感恩水平\u003c/p>\u003cp>你可能发现当事情进展顺利时，你很容易去感恩。但是也许在困难时期就比较难保持这种感恩的心态。\u003c/p>\u003cp>40-45:分：平均值以下感恩水平\u003c/p>\u003cp>在你生命中去寻找感恩的理由对你来说还是一件有些困难的事情。\u003c/p>\u003cp>生命与其说是\u003c/p>\u003cp>礼物，不如说是一种负担。也许你在经历一个低谷期。但是即使你没有经历低谷，经过今天也很可能改变你看世界的眼光和你的生活。\u003c/p>\u003cp>二 、【I】解释自测题（1分钟）\u003c/p>\u003cp>好，我看到大家都已经做完了，请大家对照自己的分数，如何计算你的分数\u003c/p>\u003cp>1、把你在1，2，4，5，7，9和10项的分数加起来。\u003c/p>\u003cp>2、把你在3，6，8三项的得分反过来相加。也就是说，如果你得分是7分，那么把它变成1，如果你得分是6分，那么把它变成2，以此类推。\u003c/p>\u003cp>3、把你刚刚在3，6，8三项的反向得分相加之后，再加上第一步你的总分数。\u003c/p>\u003cp>65-70分：极高的感恩水平\u003c/p>\u003cp>对你来说，感恩是一种生活方式。\u003c/p>\u003cp>59-64分：很高的感恩水平。\u003c/p>\u003cp>经常表达自己的感恩，能认识到别人怎么帮助了你。\u003c/p>\u003cp>53-58分：较高的感恩水平。\u003c/p>\u003cp>平均值以上，你会花时间去想值得你感激的事情。\u003c/p>\u003cp>46-52分：平均感恩水平。\u003c/p>\u003cp>在困难时期难保持感恩的心态。\u003c/p>\u003cp>40-45:分：平均值以下感恩水平。\u003c/p>\u003cp>寻找感恩对你来说有些困难的事情。\u003c/p>\u003cp>65分到70分我们这里有4位，你们是极高的感恩水平，掌声送给你。59到64分你们是很高的感恩水平，这个分数也是非常棒的。如果你身边有些人分数是40分以下，这些人分数很低，感恩水平很低，人际关系也是非常紧张的。\u003c/p>\u003cp>下面这个拆页里的情况，你看看有没有同感，也有一样的经历，也可以共同学习一下，给大家2分钟的时间阅读下面的拆页，阅读完的小伙伴可以给我眼神来表示，你已经阅读完毕。\u003c/p>\u003cp>三、【R】阅读原书拆页\u003c/p>\u003cp>3-3原文片段2当你不愿表达感激时\u003c/p>\u003cp> 约翰·鲍威尔(John Powell)在他的《爱的秘密》一书中有一段文字深深打动了我。他描述了父亲在世时，自己从来没有向他表达过感激，为此他深感悲伤。我想如果错失了机会向那些对我们很重要的人表达谢意，实在是令人遗憾的。\u003c/p>\u003cp> 这使我想到了我的舅舅尤利思·福克斯。当我还小的时候，他每天会到我们家照顾我那位已经全身瘫痪的祖母。我记得当他在照顾祖母时，脸上总是挂着温暖又充满爱的笑容。无论那些活儿在年少的我眼中是多么不堪，他却好像视照顾祖母为莫大的恩惠。他的亲身示范教会了我何为男性的力量，所有这些，我在往后的岁月里时常都会忆起。\u003c/p>\u003cp> 直至舅舅病危，我才发现自己从未向他表达过感激。每当我想要这么做时，总感到自己有些抗拒：“我相信他已经知道他对我有多重要，所以没必要说出来吧。如果我真的说出来了，可能反而会让他觉得尴尬吧。”当脑海中浮现出这些想法时，我马上知道这并不是真的。我经常以为别人知道我有多么感激他们，后来却发现事实并非如此。而即使人们听见感激的话时会感到尴尬，却依然希望能从别人那里听到对自己的感激。\u003c/p>\u003cp> 可我还是有些犹豫，我对自己说：语言并不足以表达我对他的感激之情。好在，很快我就醒悟了：是的，尽管语言不足以充分传递我们的心意，但我已经知道“一件值得做的事情，即使我们做得不怎么样也值得去做！”\u003c/p>\u003cp> 在不久后的一次家庭聚会中，当我坐在尤利思舅舅身旁时，感激的话便从我心里涌了出来。舅舅听了非常高兴，没有丝毫尴尬。当晚，激动不已的我回到家后写下了一首诗寄给他。3个星期后，他便过世了。我后来得知，舅舅在去世前，每天都请人把那首诗念给他听。\u003c/p>","explains":"\u003cp>四、【I】拆书家讲解引导\u003c/p>\u003cp>【和学习者互动】\u003c/p>\u003cp> 你觉得他舅舅做了哪些，让他觉得需要感激？\u003c/p>\u003cp>代表学习者；舅舅在过程中照顾祖母，让他找到榜样的力量，可以更好的为自己未来成长打下基础。\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>（互动）；\u003c/p>\u003cp>拆书家；在这个片段里，你有感触吗？哪个地方有感触？\u003c/p>\u003cp>A；舅舅去世前，每天都请人把那首诗念给他听，我听了戳心窝了。这个点是有故事，我们等会再挖。\u003c/p>\u003cp>在心里。\u003c/p>\u003cp>（互动）；\u003c/p>\u003cp>拆书家；还有谁，看到哪里有感触的。\u003c/p>\u003cp>B；内心深处感谢舅舅，但是没有表达过，舅舅去世前三周告诉了舅舅，而且这事对舅舅是滋养，感激非常重要，很多时候会埋\u003c/p>\u003cp>回想一下，你自己是否有一种关系，你不愿意或者不敢去感激，请举手。\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>在这个原文里，整体的布局是这样的线路，反思-故事-顿悟-行动-升华\u003c/p>\u003cp>反思-他描述了父亲在世时，自己从来没有向他表达过感激，为此他深感悲伤。\u003c/p>\u003cp>故事-照顾祖母，无论那些活儿在年少的我眼中是多么不堪，他却好像视照顾祖母为莫大的恩惠。\u003c/p>\u003cp>顿悟-一件值得做的事情，即使我们做得不怎么样也值得去做！\u003c/p>\u003cp>行动-做了一首诗\u003c/p>\u003cp>升华-舅舅读给别人听\u003c/p>\u003cp> 这件事情，给作者哪些收获，一步一步分享。舅舅也慢慢的接纳这件事，对照我们学习感激三要素。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>感激的重要性主要体现在以下几个方面：\u003c/p>\u003cp>1、心理健康：感激能够提升个人的幸福感和满足感，减少抑郁和焦虑的情绪。研究表明，常怀感激之心的人更容易体验到愉悦、满足和自豪等积极情绪。\u003c/p>\u003cp>2、人际关系：感激有助于建立和维护良好的人际关系。它鼓励人们珍惜和回报他人的好意和帮助，从而增进信任与亲密感，使关系更加和谐、顺畅。\u003c/p>\u003cp>3、个人成长：感激能够促进个人的成长和发展，因为它使人们更加开放和愿意学习。感激还可以激发他人的积极性，当人们知道自己的行为受到感激时，更有可能继续提供帮助和支持。\u003c/p>\u003cp>【WHERE】\u003c/p>\u003cp>适用于我们有内心需求的场景，可能是你，也可能是别人的需求，在人与人之间产生链接。\u003c/p>\u003cp>【举例子】\u003c/p>\u003cp> 给大家讲我和妈妈真实的故事，我成长的过程中，奶奶和爸爸对我帮助最大，在我上学过程中，一直觉得爸爸为我上学做出了很大贡献，特别是初中升高中，考上大学后，想留在外面，妈妈不希望我留在外面，希望回到家乡，能够去帮助弟弟。两件非常重大的问题上，都是爸爸支持我，一辈子不发火的男人，在这两个问题上，为了我撑起了腰。一直对爸爸有非常强感激，觉得妈妈不配享受我现在的成果。\u003c/p>\u003cp>2011年爸爸过世以后，妈妈精神上有了很大重创。2018年的时候，妈妈跟我们一起生活，那个时候我对妈妈有不好感受。似乎觉得她不应该享受我的劳动成果，为了完成赡养的义务，我接纳她住在我家。\u003c/p>\u003cp>我跟她之间发生一次比较大冲突，有一天妈妈很伤心，还说，你把你爸爸挖出来好了，我不应该享受这一切。你把我埋进去，妈妈特别伤心跟我说，在我上学过程中，其实也做了很多的事情。为了防止老母猪把小猪仔压死，妈妈坐到猪圈里，陪着老母猪把猪生下来，一些具体事情。那个时候，我内心的怨恨少了很多，还有一些悔意，当时跟妈妈表达了感激，感激她默默支持我上学，我们之间，有了很大缓和，现在我不会觉得她不配享受。\u003c/p>","interaction":"\u003cp>五、【A3】促动参与\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>【一、提出解决问题】\u003c/p>\u003cp>通过上面片段的学习，大家了解到感激重要性，不感激会有后悔，我想问大家，能否将感激的方法，运用到工作和生活中，在感激这件事情上，还有哪些实施的困难？需要共同来解决？刚才给大家分享的拆页，还有我和妈妈的故事，大家按照反思-故事-顿悟-行动-升华五个环节来探讨，是什么影响他选择了感激，或者是什么阻碍了他。\u003c/p>\u003cp>大家说。。。\u003c/p>\u003cp>代表1：我们组确定故事和顿悟这个问题，这是影响不能表达的主要因素。\u003c/p>\u003cp>代表2：通过商议，我们组确定把行动作为探究的点。\u003c/p>\u003cp>【二、讨论问题本质】\u003c/p>\u003cp>接下来大家谈论的时候，我们用微行动学习的方法，具体的讨论过程，共同来分析和解决这个问题。在微行动之前，我也给大家做一个讨论的规则约定：\u003c/p>\u003cp>1、要尊发言的每个人，不要打断别人的讲话。\u003c/p>\u003cp>2、认真倾听别人的发言，不评价别人的观点。\u003c/p>\u003cp>3、每组有人记录在白纸上，便于综合关注。\u003c/p>\u003cp>下面以小组为单位，结合自己曾经的经历，探讨我们刚才提出的问题，大家根据自己实例，可以多问几个为什么？多问几个为什么，可以找到问题的精髓。给大家5分钟时间，共同讨论我们这个核心问题。（大家在分组讨论中……）\u003c/p>\u003cp>【三、确定问题本质】\u003c/p>\u003cp>拆书家：好了，请各小组说说讨论的成果，下面请两位来分享讨论的结果。\u003c/p>\u003cp>代表学习者1：问题的本质是三个因素动力动机，紧迫感，缺少动机和认知差异。\u003c/p>\u003cp>代表学习者2：我们讨论后确定了是心理障碍的影响，还可以用别的方法替补，还有心理被拒绝，怕被讨厌的勇气，不要过分的追求完美主义，当下觉得做和不做无所谓。\u003c/p>\u003cp>拆书家：大家讨论问题的本质不一致，请大家再一次确认问题的本质。同时根据你们讨论\u003c/p>\u003cp>【四、问题解决方案】\u003c/p>\u003cp>拆书家：刚才又一次明确问题本质，各个小组内展开讨论，看着大家讨论的很激烈，你们都有什么方法可以解决。时间为3分钟，我们来一个头脑风暴，看看大家能给出多少思路来，都写在便签纸上。一起把看看便签纸上写了哪些解决方案。\u003c/p>\u003cp>代表1：我们组讨论的结果，那些阻碍我们的因素是找到动机，分析认知误解，解释事实。\u003c/p>\u003cp>代表2：提高认识，多练习，借助工具，给心灵滋养。\u003c/p>\u003cp>【五、汇报解决方案】\u003c/p>\u003cp>拆书家：经过刚才大家已经头脑风暴了很多方法，也呈现出了方案，下面我们一起归纳一下：\u003c/p>\u003cp>经过大家的共同思考，我们把这个问题的具体解决方案清晰呈现出来了，相信通过这样的讨论方式，这个方法将在我们大脑里存在，再好的知识也需要运用在生活中，促进你的学习，才能更好的助力你的生活和工作。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>代表A:当我们不愿意感激的时候，我们组选的是故事和顿悟来突破，我的一个堂弟不愿意感激父母，哥哥小时候身体不好，没有钱又想抽烟，最后死掉了，最后我的这堂弟就一直埋怨他父母，觉得父母没有就哥哥，当时把卖田地的钱拿去盖房子，只有他爸爸把钱随便花了，生活的居住也不好，妈妈比较溺爱堂弟，不太喜欢他哥哥，都是先给弟弟吃，不给哥哥吃，很多细节的东西，后来他哥哥死了以后，我堂弟就恨他父母，这个问题如何解决？我们组讨论的解决方案是，找一个契机来打开心结，一个中间堂弟信任的中间人，来化解心结，通过中间人把更多的信息给堂弟来解决这个事情。\u003c/p>\u003cp>拆书家：刚才他们组的方案是一个契机和一个中间人，来解决堂弟的问题。\u003c/p>\u003cp>代表B:我们这组谈论的点是行动，知道是一回事，做到又是一回事，我自己的一个故事，我们经常工作没有时间，还有心里的阻力，可以用别的方法替补感激和道歉。还有其他原因就是还有很多时间来得及，或者我们没有时间来做这件事，没有去行动的原因，还有一些我们的危机感，比如子欲养而亲不待，共同的原因就是抓紧时间去做，不论什么方式。\u003c/p>\u003cp> 在我初三那一年，关键那一年爷爷奶奶对我关心很多，但是，妈妈和他们关系不好，那个时候的我总是站在母亲这边，很多年里，我都是觉得奶奶对我不好，相处的一年里，奶奶不论刮风下雨，她都会拖着她弱小的身躯来陪我，下雨了，她都是穿着靴子来回走，后来上班后，我慢慢顿悟，我去我外婆家的时候，外婆对我与奶奶相比，相差很大，后来我想感激她的时候，总觉得没有时机，后来一直到奶奶过世都没有做，慢慢感悟需要去借假修真，慢慢去做一些事情。\u003c/p>\u003cp>拆书家：有些事情可以通过别的方式来做，我14岁爷爷奶奶走了，没有机会回报他们，只能给他们把坟修好，也算是一种感激的方法。\u003c/p>\u003cp>六、【A2】催化应用\u003c/p>\u003cp>拆书家布置任务：\u003c/p>\u003cp>今天非常感激大家分享故事，如果说我们还能做点啥，那就抓紧时间去做吧！每个人对学习的理解不同，未来生活到底如何，还在继续，所以，这里我也给大家布置作业，一个星期的时间，从身边人开始，如果我以前不太喜欢感激别人，我们从身边人开始，去做一件事情，一个星期的时间，大家如果做了的话，可以qq或者微信发给我，我们把感激流动起来，当你学会感激身边，让感激流动起来。\u003c/p>\u003cp>我是老师，喜欢给大家布置作业，我们感激别人的时候，我们自身也会被滋养，未来的生活孩子继续，多点感激你会越来越好。今天回去以后，找身边的伙伴分享一下感激的三步法和感激的重要性，你分享的要点越多，你掌握的技巧的能力就越强。完成作业的小伙伴可以在下周六前私发给我。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>A:周一的时候，我和孩子又有冲突了，我的同事小李给了讲了她的经历，还分享了一本书，当时我感谢她给我分享她的经历，也许幸福是相比而言，听了她的经历，我心里更加踏实，心里还有一些欣慰，我没有和孩子关系恶化。\u003c/p>\u003cp>B:学习感激三点后，我回家也试着和妈妈说了不太好意思说的话，感谢她为我们烧了一桌好菜，大家都吃的很开心，我也感受到家庭的幸福感。\u003c/p>\u003cp>结语（1分钟）\u003c/p>\u003cp>平生多感激、忠义非外奖。我们感激了别人，感激的过程本身就是滋养，无需给太多的物质，也是会被滋养成长，期望这两个片段能给大家实际帮助，助力大家未来的生活和工作，也希望未来的读书，我们彼此成长，彼此滋养，感谢每一位的付出，谢谢各位的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1744967645000,"updated_at":1764117187000,"ria":true},{"id":18746,"topic":"从“怒火中烧”到“心平气和”，解锁高情商沟通的终极密码  ","learn_goal":"","remark":"你有没有这样的经历？  \n\n- 工作中，同事的一句无心之言让你瞬间“炸毛”，结果一场争吵让关系陷入僵局；  \n- 家庭里，伴侣的一个小习惯让你忍无可忍，最终演变成一场“世界大战”；  \n- 甚至在路上，陌生人的一个眼神都可能让你怒火中烧，事后又后悔不已…… \n \n \n《非暴力沟通》为我们提供了一种全新的解决方案。这本书不仅是一本沟通指南，更是一本情绪管理的“秘籍”。它告诉我们，愤怒并不是敌人，而是内心需求的“信号灯”。通过一种独特的沟通框架，我们可以将愤怒转化为理解与连接，从而化解冲突、改善关系。  \n\n无论你是职场中的“沟通达人”，还是家庭中的“情绪管理者”，或者只是想更好地与自己和解，这次拆书活动都将为你带来全新的启发。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"澄心","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，我是澄心，然后我的那个三个标签再跟大家介绍一下我自己。\u003c/p>\u003cp>第一个标签是新晋的一级拆书家，然后第二个标签是疗愈沙龙的策划师，同时我的主业的第三个标签就是传媒的工作者。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>跟随我完成本次RIA现场学习后，学习者可以在遇到沟通不畅有愤怒情绪的时候，可以用四个步骤让自己快速冷静，直达需求，有效解决沟通。\u003c/p>\u003cp>【FAB图书介绍】\u003c/p>\u003cp>F（Feature，特征）\u003c/p>\u003cp>我今天带来的这本图书是非暴力沟通。\u003c/p>\u003cp>我先来介绍一下这本书，非暴力沟通的话是著名的心理学家马歇尔卢森堡博士创作的一本书，它不仅仅是一本沟通的指南，同时它是一本解决语言暴力的一个工具书。然后这本书，卢森堡博士通过 50 多年的这种经验实践和案例的一个积累，然后把它打磨成为简单的四步法。\u003c/p>\u003cp>A（Advantage，优势）\u003c/p>\u003cp>这四步法的话非常的好记，容易上手，应用到我们生活当中的这个，沟通场景之中。它的特点就是结构化的这四步法。嗯，然后可以帮助我们快速的去解决生活当中的一个沟通难题，贴近于生活的案例，然后非常容易的就是操作。\u003c/p>\u003cp>B1（Benefit，利益）\u003c/p>\u003cp>然后他这本书对于我们生活的这个好处就是你用四步法来去进行我们生活中的这种冲突的解决，是非常的一个高效。可以帮我们把这个不好的一个沟通的氛围可以转化成更好的一个理解的这样的一个氛围。然后双方的需求能达成，同时也能达成一个共赢的模式。\u003c/p>\u003cp>B2（Benefit，利益）\u003c/p>\u003cp>然后我今天来选的这个拆页，就是其中的一个表达愤怒的这样的一个四步骤的拆页。这个选段的话，其实它是从这个情绪的层面沟通场景当中，情绪的这个，愤怒情绪的层面来去帮我们实际的解决。你在沟通的场景当中，如果你产生了这个愤怒情绪，然后你如何的去更温和地表达自己的需求感受，然后从而达到双方彼此的一个共赢的目标。我把这个选段给大家发一下，大家接下来可以一分钟的时间看一下这个选段，然后看完的朋友可以抬头示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":23069,"quote":"\u003cp>表达愤怒的四个步骤\u003c/p>\u003cp>1.停下来，深呼吸。\u003c/p>\u003cp>2. 看看我们有哪些评判性的想法。\u003c/p>\u003cp>3. 与我们的需要连结。\u003c/p>\u003cp>4. 表达我们的感受和未被满足的需要。\u003c/p>\u003cp>来看看充分表达愤怒的具体步骤。首先，停下来，除了深呼吸，什么都别做；不去指责或惩罚他人，只是保持安静。接着，看一看是什么想法让我们生气。例如，无意中听到某人说了一些话，使我们相信自己由于种族的缘故遭到了排斥。感知到自己的怒气时，如果停下来，便会看到头脑中盘旋的想法：“这太不公平了！她这是种族歧视！”我们知道，所有的评判都在用可悲的方式表达未满足的需要。于是，接下来的第3步是：与这些想法背后的需要连结。如果指责某人是种族主义者，我们的需要也许是融合、平等、尊重或者与人连结。\u003c/p>\u003cp>为了充分表达自己，我们要采取的第4步是开口表达愤怒——怒火此时已被转化为感受和需要。然而，表达此时的感受也许要很大的勇气。对我来说，生气并冲着人们嚷“你这样做是种族歧视”是很容易的，甚至还会感到很畅快。然而，要说出内心深处的感受和需要，却可能令人却步。为了充分表达愤怒，我们也许可以试着和对方说：“你走进房间后，开始与其他人聊天，却没有和我说话。接着，你开始议论有关白人的种种。当注意到这些时，我的胃非常不舒服，我也很害怕。这使我意识到，我非常希望受到平等的对待。我想请你告诉我，听到这些话，你的感受是怎么样的？”\u003c/p>","explains":"\u003cp>好的，我看到大部分的朋友都看完了这个选段。\u003c/p>\u003cp>\u003cu>\u003cstrong>What\u003c/strong>\u003c/u>\u003c/p>\u003cp>然后这个选段的话它是表达愤怒的这四个步骤，这四步的话可以帮助我们去有效高效的转化我们愤怒的情绪。然后可以让我们在沟通当中避免情绪的这样的一个失控，可以更温和的去表达我们的需求和感受，然后从而有效的去解决矛盾啊。\u003c/p>\u003cp>\u003cstrong>\u003cu>Why\u003c/u>\u003c/strong>\u003c/p>\u003cp>一般如果让我们就是遇到愤怒的事情，通常的这种传统做法，然后互相可能会去指责对方，然后有情绪的这种发泄往往会让我们的矛盾去升级，但是这里边这四个步骤的话，可以让我们去冷静下来，可以直达自己的需求，有效的去解决和促进我们的这个关系。\u003c/p>\u003cp>\u003cu>\u003cstrong>How\u003c/strong>\u003c/u>\u003c/p>\u003cp>具体怎么去做这四步骤：\u003c/p>\u003cp>第一个步骤就是\u003cstrong>按下我们情绪的一个暂停键\u003c/strong>啊。当我们感觉我们情绪有巨大的一个波动和愤怒的时候，先冷静下来，先不要用情绪去沟通，让自己可以就是冷静下来，避免行动上的这种冲突啊。\u003c/p>\u003cp>第二个步骤就是\u003cstrong>挖掘我们这个情绪背后的源头\u003c/strong>，就是到底是什么引发了我们生气、愤怒，然后是背后是什么样的这个事件和想法推动的我们的这个情绪的一个发展啊？\u003c/p>\u003cp>第三步就是\u003cstrong>挖掘我们内在的一个需求\u003c/strong>，就是我们愤怒的这个背后，我们有什么样未被满足的一个需求？是觉得没有被他人尊重，还是说没有被他人理解和认可啊？要去挖掘自己背后的这个更深层次的一个需求。\u003c/p>\u003cp>第四步的话就是\u003cstrong>用温和的方式去表达自己的这个感受和想法\u003c/strong>。我们可以用这样的这种那个句式，就是我认为你的这个行为让我现在感觉到很受伤，然后我需要的是看你能不能在我们情绪冷静下来之后，然后大家可以坐到一起好好的去商讨一下这个问题，我们各自的想法，然后我们接下来的一些解决方案可以尝试这样更温和而清晰的，去表达自己的需求跟感受。\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>如果说我们没有按照上面这个四个步骤这么去做的时候，往往可能双方会情绪如果起来了，然后你可能就会指责对方，你为什么要这样？你怎么这么的自私？然后你为什么没有考虑我的感受？然后对方会感觉到是被攻击，很委屈，也会激起对方的一个情绪的反弹和防御，这样非常不利于这个关系，甚至于说会破坏关系。也没办法解决眼前的一个这个沟通的这么一个困境。\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>对，然后我最近的话其实就是有这样的一个真实的案例，在我的生活中就是一个失败的沟通案例发生就是因为我最近跟我妈有一个巨大的一个矛盾，他就是用家庭的积蓄，然后买了很多很多的保险，就是这个量可能已经超过了就是家庭正常的这种需求的一个配备的量啊。然后我再帮他去协助他去梳理我们家庭的这个保单的时候，发生了就是很大的分歧，我觉得他太不考虑，他在购买的时候他不会问他人的需求，然后不考虑他人的想法，特别的自我，然后他就觉得他一片好心，就被我那个不理解，明明是可能给家庭保障，然后想建构这种安全感，但是却觉得好像没有被理解，被辜负的这种心理，他又觉得很受伤。然后于是我们就爆发了一次争吵，对，这个就是一个失败案例。\u003c/p>\u003cp>【反例变正例】\u003c/p>\u003cp>然后我复盘回顾一下，如果说我用今天就是这个选段里边的这 4 个步骤，我应该怎么样去跟我妈妈可能就这个问题更好的一次进行一次深入的交流跟沟通呢？\u003c/p>\u003cp>就是\u003cstrong>首先我要先给情绪按下暂停键\u003c/strong>，我先不要去指责他，然后我要冷静下来，然后冷静下来。之后第二步，然后我去\u003cstrong>挖掘引发我情绪背后的想法\u003c/strong>啊。我可以跟他说，就是你买过多的这个保险的这个行为让我觉得就是挺担心的，然后家里边这个就是整个的财务方面的这个配置的一个不合理的情况啊。\u003c/p>\u003cp>然后\u003cstrong>第三步去跟他表达我内在的需求\u003c/strong>，我的需求就是我希望就是这件事情，家庭涉及到家庭其他成员的这种重大的一个事情的话，你可以和我们能有一个商量的一个过程，然后大家可以共同的去提出自己的意见，大家都可以畅所欲言啊。\u003c/p>\u003cp>然后第四步就是，\u003cstrong>温和的去表达自己接下来的一个想法\u003c/strong>，就是看是不是可以，比如说在本周三的晚上 8 点的时候，大家可以坐在一起，然后具体的去梳理一下现有的这个情况，然后去想接下来的一些解决方案，甚至于借助于比如说就是一些很科学的这种家庭的标准普尔象限图这样的这种工具，然后去分析，然后这样的问题大家应该怎么样去处理，都能有一个就是，嗯，表达自己和被尊重到的机会。\u003c/p>\u003cp>对，然后这个就是我生活当中的一个案例，这样沟通之后，我相信就是他可能也会感受到我并不是在全盘的去否定他的一个行为，我只是希望大家都能去更好地表达自己，以及说更合理的去规划，这个就是比较家庭当中财务上比较大的这么一个事情的这么一个解决方案。\u003c/p>\u003cp>其实任何的这个沟通方法，包括今天这个表达愤怒的一个四步骤，它都有相应的一个适用边界。\u003c/p>\u003cp>\u003cstrong>\u003cu>Where\u003c/u>\u003c/strong>\u003c/p>\u003cp>就是在我们生活中，我们跟家人、同事、朋友沟通的时候，你有情绪的时候，你可以用这四个步骤去解决，但是它不适用于就可能相对疏远和陌生人的这种关系啊。因为对方对你可能没有信任和情感上的这个基础的话，他不会有耐心去听你表达这些东西，所以可能并不适用于四个步骤的整个过程。\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003cu>A1：\u003c/u>\u003c/strong>\u003c/p>\u003cp>然后就是大家可以来去回想一下，就是你最近的一次有没有在沟通当中，你或者引发对方有一个很生气、很愤怒的这样一个沟通场景。\u003c/p>\u003cp>【显像提问】\u003c/p>\u003cp>比如说在家庭当中两个人因为就是家务分配的这种不合理产生了摩擦，觉得你应该扫地刷碗，但是你一直在偷懒等等。\u003c/p>\u003cp>然后比如说在那个同事的这种沟通当中，可能就会误会，他没有在认真的工作，在摸鱼等等，或者说朋友迟到了，你觉得他没有尊重到你的时间，然后引起你的一些这个不满的这些情绪。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>然后在你最近一次有没有这样的场景出现，然后就按照刚才一开始分好的那个小组，大家可以在小组内去讨论一下这个场景。\u003c/p>\u003cp>然后一分钟的时间，因为拆书的时间也比较有限，然后我这边会计时在临近的时候会提醒大家。\u003c/p>\u003cp>倒计时7654321，谢谢大家讨论，怎么样？感觉停不下来？好，谢谢现在能邀请那个一位停不下来的朋友分享一下吗？Teller你来分享一下吧。\u003c/p>\u003cp>【学习者案例分享】\u003c/p>\u003cp>也只有一分钟的时间，那我就快速分享一下。今天晚上发生一些事情，我爱人经常要出去玩骑自行车，你知道吗？然后他那次就说没有气了，我儿子说他去打气，这是他正好是要理下户这个事情，然后等两分钟一起打，我就跟他说，我说儿子你去给那个你妈自行车打气，他来就怼我一句，你知道吗？就跟他那个态度特别不好，我说当时特特愤怒，你知道吗？就是首先我感觉我没有被尊重到，另外一句话就是说，因为我还没有跟他说这个事情，我这心想就是你承诺的事情你没有做到，然后反而怼了我一句，你知道我就特难受。后来我说话人出来之后，哪怕人说，而且这件事真参加两个竞赛平台方，然后他准备参加六一考试，感觉事情比较多，有可能有压力，你知道吗？嗯，然后来完事给我结束了之后，我感觉我还倒是能心里头稍微舒服一点了，但是幸好当初我没有直接去指责他，比如说你口气不好，或者说你承诺事情去跟他掰扯这个事情。嗯，幸好是我按下了那个暂停键。\u003c/p>\u003cp>谢谢，谢谢Teller的分享。\u003c/p>\u003cp>\u003cu>\u003cstrong>A1+：\u003c/strong>\u003c/u>\u003c/p>\u003cp>【反思加工】\u003c/p>\u003cp>嗯，然后那个大家刚才可能也都回想到了自己生活当中跟别人有这种愤怒情绪的这个场景哈。\u003c/p>\u003cp>然后稍后这个便签的话，每个人可以拿一张便签，然后可以回想这个场景，按照这咱们今天的这四步骤，然后可以尝试的去写一下，如果说穿越时光机，你再回到那个场景当中，你应该可以怎么样做得更好一些？\u003c/p>\u003cp>大家一分半钟的时间。 \u003c/p>\u003cp>最后 20 秒倒计时。\u003c/p>\u003cp> 好的，时间到了。然后我看Teller写得非常认真，然后正好因为刚才你有分享你的这个案例，然后刚才大家也都比较清楚，然后所以现在可以邀请你来分享一下。嗯，穿越时光机回去，然后你要怎么去做？\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>我大概想一下子，就是针对这事情的话，就是如果让我去做的话，我有可能去冷静下来跟他说一下，就是说。\u003c/p>\u003cp>第一个话就是说这件事情的话，是你想去做的事情，给你自行车去打气，然后我。也是对你母亲一个关心。\u003c/p>\u003cp>然后第二我下一步我会出来就是说，嗯，我对你刚才说话的语气表示那个不是很舒服，我会跟他去说这个情况，就是表达我的情绪。因为他说的确实很愤怒，或者说我因为很不尊重我，所以我会把我的情绪告诉他，就是希望他下次的话在说的过程。\u003c/p>\u003cp>然后其实我也会告诉他，比如说这件事情，假如说你现在没有事情做事情，那你可以这样申诉我说爸爸我现在比较忙，要不你能不能去帮我？帮这个我妈把这个车打气。\u003c/p>\u003cp>那我觉得这也是一句话，他不能说拿这话直接怼我，我因为就是让我感觉心里很不舒服，这是我大概的一个处理的策略。\u003c/p>\u003cp>那希望你能在今天下来的时候回家，可以跟儿子这样去那个沟通一下。\u003c/p>\u003cp>可以，那我去尝试一下。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>然后那以上，也特别感谢那个今天大家的这个讨论跟分享，以上就是我今天的这个分享。\u003c/p>\u003cp>再来帮大家总结一下，今天我们一起共同学习的就是这个非暴力沟通这本经典的书，其中的一个表达愤怒四步骤，这样的一个小小的一个拆页啊。然后这个拆页也是非常实用的，然后它简单的这四个步骤，就是\u003cstrong>第一步先给我们的情绪按下暂停键\u003c/strong>，然后找到\u003cstrong>第二步按照找到情绪背后的这个感受，然后这个源头在哪里？\u003c/strong>然后\u003cstrong>第三步就是挖掘我们内心的一个需求\u003c/strong>，然后\u003cstrong>第四步就是温和的可以去表达出自己的需求跟感受\u003c/strong>啊。然后这四个步骤也希望大家可以应用到自己的生活当中，解决自己实际沟通场景当中的这些情绪性的问题。\u003c/p>\u003cp>希望可以今天这个拆页能帮助到大家，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1743154729000,"updated_at":1743389608000,"ria":true},{"id":18606,"topic":"非暴力沟通四要素，探索和谐沟通的艺术","learn_goal":"","remark":"在这个高压力和快节奏的社会里，人与人的交往离不开沟通，著名的沟通漏斗理论揭示了信息传递过程中的递减效应：你心里想的是100%，你嘴里讲的是80%，别人听到的是60%，别人听懂的是40%，别人执行的是20%。这一数据直观地展示了沟通不畅可能导致的误解程度。\n\n所以，我们如何能在工作中有效沟通，以寻求领导的支持和团队的协作呢？如何能在和家人相处中柔和的表达需求，以获得家人的理解和关爱呢？这些都需要我们不断的学习和提升沟通表达能力。\n\n沟通的经典名著《非暴力沟通》其中的四要素就是一种理想与感性并重的递进式沟通方法，能让沟通双方感同身受，从而促进人与人之间的理解与连接，达成共赢的沟通局面。欢迎大家来和我们一起学习和演练非暴力沟通四要素，做个沟通高手。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"澄心","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"\u003cp>大家好，我是澄心，又和大家见面了，然后非常感谢大家今天来参加这次那个拆书活动。\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>然后还是用三个标签来介绍一下我自己，第一个标签就是金融传媒行业的这个工作者，然后做金融方面的品牌的工作。然后第二个标签的话就是，嗯，商业疗愈沙龙的策划师，然后在北京市落地了 20 多场商业疗愈的这个沙龙。然后第三个标签的话，我自己是一个瑜伽冥想的爱好者，然后每天都会那个有瑜伽冥想啊。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>然后今天我要给大家带来的这个拆页的话，是来自于米歇尔卢森堡博士的这本书《非暴力沟通》，然后这卢森堡博士的话，他是全球的非暴力沟通的专家，然后他发现了这个平和的而神奇的这个非暴力沟通的方法帮助了世界上的很多人，然后去找到关系上的这种嗯谐和爱啊。\u003c/p>\u003cp>【阅读拆页】\u003c/p>\u003cp>然后下面就是这个拆页，然后给到大家，大家可以花一分钟的时间来看一下这个拆。\u003c/p>\u003cp>然后大家看好了的话可以抬头示意我。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>好的，我看到那个大部分大家看好了，然后为了更好的咱们来学习和演练今天的这个拆页，然后来进行一下现场的这个分组，然后现场分成两组。\u003c/p>\u003cp>好，那你们三个。好的。\u003c/p>","ratings_count":1,"texts":[{"id":22911,"quote":"\u003cp>要达到让双方都能发自内心地相互给予，我们需将注意力聚焦在四个方面——它们是非暴力沟通模式的四个要素。\u003c/p>\u003cp>首先，我们观察实际上发生了什么。不论他人的言行是否有益于我们，我们只是去观察。要做到清晰表达所观察到的，我们的挑战在于不夹杂任何评判。不论喜欢与否，我们只是说出人们做了什么。第二步，表达出我们看到这些行为时的感受：是感到伤心、害怕、喜悦、有趣，还是心烦呢？第三步，表达出我们的感受与什么需要相关联。通过对这三个要素的觉察，我们清晰和诚实地表达出自己的状态。\u003c/p>\u003cp>例如，一位母亲想和正值青春期的儿子用非暴力沟通的方式来说话，她可以这样来表达以上三个要素：“菲利克斯，看到咖啡桌下的两团脏袜子和电视机旁边的三团脏袜子，我很生气，因为我希望在我们共用的空间里能多些整洁。”\u003c/p>\u003cp>紧接着，她可以表达非暴力沟通的第四个要素——一个具体的请求：“你愿意把你的袜子放在你房间或放进洗衣机里吗？”我们借助这个要素提出对他人的期许，希望他（她）怎么做来满足我们的需要，让我们的生命更加美好。\u003c/p>","explains":"\u003cp>好，嗯，我来跟大家先来分享一下我对这个拆页的一个那个理解。\u003c/p>\u003cp>【What】\u003c/p>\u003cp>嗯，就是这个拆页的话，讲述的就是非暴力沟通的四要素。嗯，观察、感受、需求和请求，嗯，然后运用这四要素的话，在我们的这个，嗯发生沟通问题的时候，然后可以去解决我们的沟通问题，然后促进我们人际关系的这个提升和谐。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>嗯，然后为什么要运用这四要素呢？就是嗯，当我们在发生矛盾的时候，嗯，这四要素的话可以帮助我们在沟通之初的时候就建立到一个很平和的这样的一个沟通的场景和氛围，然后大家可以去发现问题的事实，寻求到共同的一个理解，然后达到一个沟通的一个共赢的效果啊。\u003c/p>\u003cp>【How】\u003c/p>\u003cp>然后具体是哪四要素？分为以下的这四个步骤，\u003c/p>\u003cul>\u003cli>第一个步骤就是陈述客观事实，就是不带我们个人的评判和喜好的去表达客观的事实，比如说这是我第二次在拆书帮嗯去做 1- 2 的这个拆书过级的分享。\u003c/li>\u003cli>然后第二个就是，嗯，反馈情绪感受，嗯，就是对这个事件，然后对于我们整个自己内在的这个情绪和感受去客观的去反馈和表达，嗯，就是比如说今天的话，嗯，如果说我 1-2 还没有过级的话，我会很伤心、很难过。\u003c/li>\u003cli>然后第三，嗯就是表达关联的需求，嗯，就是可以去表达我们内在对于这个事件有更深层次的一个内在的一个动力跟需求啊。比如说今天希望大家可以，嗯，给到我更多客观和嗯有建设性的意见，可以帮助我以后可以更好的去拆书过级，成为一级拆书家啊。\u003c/li>\u003cli>第四步的话就是请求行动建议。比如说希望今天的话可以大家在结束的时候给我写一个便签，给到我具体的一个这个行动的，嗯，接下来的一个行动建议。\u003c/li>\u003c/ul>\u003cp>【where】\u003c/p>\u003cp>然后就是这个非暴力沟通的四要素的话，它是适用于当我们和他人发生嗯，沟通的分歧的时候，然后可以用这个四个步骤，然后去解决我们沟通的一个嗯冲突。嗯，当双方的这个意见僵持不下的时候，然后这个四个步骤可以很好的去破冰，打破这个僵局，让我们大家一起去发现事实，然后不带情绪的去。嗯，表达自己内在的这个需求，然后以及说接下来的一个行动建议促进这个事情更好的一个解决啊。\u003c/p>\u003cp>【自己的案例】\u003c/p>\u003cp>然后按照下面就按照刚才的这个分组，然后大家可以嗯，根据于自己的这个，嗯非暴力沟通的这个事件的话进行一个讨论。\u003c/p>\u003cp>然后在这里我也来分享一个我自己的这个，嗯，近期的一个非暴力沟通的这么一个案例。\u003c/p>\u003cp>就是在工作当中，最近一个工作当中就是要小红书帮助客户去做一个这个博主的一个合作的事情啊。然后但是有一个博主他在中途其实是爽约掉了我们这个合作，已经在签好协议的情况下爽约掉了我们的这个合作，然后导致这个项目的一个终止啊。在以往如果发生这样的事情的时候，我可能就会很冲动的就去找这个博主去理论了，就觉得你为什么不去履约怎么样？然后但是因为现在学习了这个非暴力沟通，然后所以我用这四个步骤，然后尝试跟这个博主进行了这个沟通，然后有了以下的一些对话啊。\u003c/p>\u003cul>\u003cli>就是第一步先去陈述客观的事实，嗯，先去跟博主沟通，就是博主你好，就是我们原定于叫未来的一周内去完成这次素材的一个制作和合作的推进啊。\u003c/li>\u003cli>然后第二步反馈我的一个情绪感受，跟博主说，就是你因为你的个人原因导致了这个项目的终止，给我带来了很大的一个压力。嗯，然后我也会觉得就是对于这个行为本身会觉得会比较失望啊。\u003c/li>\u003cli>然后第三步的话就是关联内在的一个需求，就是希望我跟博主去表达，希望我们双方可以想到共同的一个办法可以解决掉。我这边，然后客户这边和博主这边的这个合作的一个事宜。\u003c/li>\u003cli>然后第四步的话请求具体的一个行动建议。嗯，跟博主去沟通他在就是当天的下班时间前，然后去给到我一个解决的方案。然后这样的话可以把这个合作能继续的往前去推进，然后做一个补救性的这么一个措施，因为我整个的这个比较客观性的表达，然后也确实因为博主他也有一些那个理亏，通过这四个步骤表达下来之后，然后博主也是积极的去响应了就是我的建议，然后给到的一个解决方案，让这次合作的一个，嗯损失的话也是降到了最低，嗯，虽然可能就是中间还是有一些亡羊补牢的这个作用，但最后还是圆满的解决了这件事情啊。\u003c/li>\u003c/ul>\u003cp>所以刚才这个是我自己的一个，嗯，对于非暴力沟通四个步骤的这么一个案例的一个解读，然后给大家一个借鉴。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>【分组讨论】\u003c/p>\u003cp>然后待会可以在两个小组内，然后大家可以就这四个步骤去做一下练习，然后要求就是可以去思考一下，过去自己一个月内有没有跟。嗯，就是身边的人，比如说上级，然后同事、朋友或者说亲密关系有发生过这种沟通的矛盾跟冲突，然后大家可以去，嗯，回忆整个这个事件的本身，然后不去那个过多的延伸到这个事件具体的一些原因，然后嗯，一共是一分钟的时间，可以在小组里讨论一下。\u003c/p>\u003cp>这个时间还有最后 10 秒的时间。\u003c/p>\u003cp>大家分享好了吗？那个现在刚才有听到那个小柔这边那个分享的特别的带劲，哈哈哈，邀请那个小柔来分享一下她的那个事件。\u003c/p>\u003cp>【分享环节】\u003c/p>\u003cp>我们家事件是发生在我和孩子之间，其实最开始是发生在我和我老公之间，我们家因为两个宝宝，然后家里通常都会弄得很乱嘛。然后所以就是我又不太经常打扫房间，嗯，因为我会觉得我很累，然后我需要有时间休息。然后有一次在我和老公吵架的时候，我们俩就爆发了一个冲突，就因为打好房间这个事情，我老公说，你看我每次下班回来家里就会猪圈一样，你又不去打扫，然后我跟孩子就会也会爆发这样的冲突。就是基本上，比如说面临到这种问题的时候，我就会跟孩子说，我说你看妈妈每天又要送你们上学，要做饭、要收拾物资，然后又要洗衣服，要干嘛？我说你们看把玩具扔了，可地。我说妈妈都要累死了，每天给你们当奴隶，哈哈，然后爸爸还说家里像猪圈，然后每次就很生气噢，有的时候还咣就把玩具让踢走一样，就刚才他其实他在分享他那个和博主那个案例的时候，我就一直在想，我自己就经常会有这种情况发生，就我们家孩子的玩具可能这一堆那一堆的，我就duang一脚，就自己也反思，但是也并没有做得很好。\u003c/p>\u003cp>【过渡语】\u003c/p>\u003cp>陈述事实就可以了，谢谢。哈哈哈，非常感谢小柔的那个分享。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>然后下面的话,我们其实就我们具体的这个生活当中的一些事件，然后去规划一下我们未来两周内，去应用这个非暴力沟通的这个四步骤，在我们的这个生活和行动之中，然后会给到大家一分钟的时间，在那个便签上写一下我们的行动规划，\u003c/p>\u003cp>然后主要是下面的几个步骤，有时间、空间、行动和目标时间，\u003c/p>\u003cul>\u003cli>就是具体未来在多长时间之内，建议是1 ~ 2周内。\u003c/li>\u003cli>空间的话就是我们要在什么样的沟通场景下去沟通，\u003c/li>\u003cli>然后第三步就是行动。嗯，四步骤的话具体的沟通方法做了哪些事情？\u003c/li>\u003cli>然后目标的话就是通过非暴力沟通的四步骤去达预期达到一个什么样的一个沟通目标。\u003c/li>\u003c/ul>\u003cp>嗯，大家写的时候的话不是决心，然后主要是自己具体的一些做法，然后有明确的时间节点，然后可以衡量的步骤和嗯目标，然后请大家就是结束的时候可以把这个便签给到我。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>然后以上的话就是我今天的这个分享，然后最后总结一下，今天的拆页是来自于非暴力沟通的片段，然后这个片段的话就是让我们如何通过非暴力沟通的四个步骤来去沟沟通解决生活当中沟通的矛盾，然后帮助我们去达成一个共赢的一个沟通的结果。\u003c/p>\u003cp>然后感谢大家今天的分享就到这里。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1737546443000,"updated_at":1737603400000,"ria":true},{"id":18487,"topic":"非暴力沟通的四要素","learn_goal":"","remark":"《非暴力沟通》心理学领域经典之作，更被成为沟通领域的圣经。阅读这本书，不仅能帮助我们提升沟通能力，更能帮助我们建立起和谐的生命体验。非暴力沟通不仅是一座找寻爱的桥梁，更重要的是，它让我们拥有爱的能力来支持生命中的各种关系。","level":"TF2-1","duration":20,"status":19,"type":0,"chaishujia":{"username":"吴超","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>线下拆书时长：15-20分钟\u003cbr>学习目标：能够现场使用四要素表达方式进行举例表达\u003cbr>\u003cbr>\u003cbr>\u003cstrong>1分钟\u003c/strong>\u003cbr>\u003cstrong>【自我介绍】\u003c/strong>\u003cbr>\u003cbr>\u003cbr>各位好，我是吴超。我的三个标签是：跑步爱好者、阅读爱好者、非暴力沟通践行者\u003cbr>1、第一个标签是：跑步爱好者。累计跑量一万多公里。\u003cbr>2、第二个标签是：阅读爱好者。最近在读心理学方面的书籍。\u003cbr>3、第三个标签是：非暴力沟通的践行者。因为非暴力沟通的方法对我的生活影响深远，非暴力沟通让我收获了更为融洽的人际关系，帮助我减少了很多不必要的烦恼。\u003cbr>\u003cbr>\u003cbr>\u003cbr>\u003cbr>\u003cstrong>1分钟\u003c/strong>\u003cbr>\u003cstrong>【图书介绍】\u003c/strong>\u003cbr>今天和大家分享的拆页内容选自《非暴力沟通》，刚刚提到了非暴力沟通对我影响很大，所以想要把它分享给大家。\u003cbr>\u003cstrong>F：\u003c/strong>\u003cbr>《非暴力沟通》这本书的作者是马歇尔.卢森堡博士，是一位著名的心理学家，书中阐述了非暴力沟通的“四项基本原则”。\u003c/p>\u003cp>\u003cbr>\u003cstrong>A：\u003c/strong>\u003cbr>这本书豆瓣上的评分高达8.7分，被称为心理学的经典之作；相比起市面上大部分沟通类的书籍，这本书算是经典中的经典，也被称为沟通领域的圣经，这是一本非常值得我们阅读和学习的书籍。众多高校的年度推荐书单里面都会推荐这本书。\u003cbr>\u003cbr>\u003cbr>\u003cstrong>B1：\u003c/strong>\u003cbr>阅读非暴力沟通这本书，不仅能帮助我们提升沟通能力，更能帮助我们建立起和谐的生命体验。\u003cbr>\u003cbr>\u003cbr>\u003cstrong>B2：\u003c/strong>\u003cbr>如果你也想避免因为不恰当的沟通产生冲突，今天的内容，相信能带给你一些启发。\u003cbr>\u003cbr>\u003c/p>","ratings_count":2,"texts":[{"id":22788,"quote":"\u003cp>\u003cstrong>3分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【R:原文拆页】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>《非暴力沟通》P00\u003c/strong>\u003c/p>\u003cp>\u003cstrong>7-008\u003c/strong> \u003c/p>\u003cp>非暴力沟通过程。 要达到让双方都能发自内心地相互给予，我们需将注意力聚焦在四个方面——它们是\u003cstrong>非暴力沟通模式的四个要素。\u003c/strong> \u003c/p>\u003cp>首先，我们\u003cstrong>观察\u003c/strong>实际上发生了什么。不论他人的言行是否有益于我们，我们只是去观察。要做到清晰表达所观察到的，我们的挑战在于不夹杂任何评判。不论喜欢与否，我们只是说出人们做了什么。 \u003c/p>\u003cp>第二步，表达出我们看到这些行为时的\u003cstrong>感受\u003c/strong>：是感到伤心、害怕、喜悦、有趣，还是心烦呢？ 第三步，表达出我们的感受与什么\u003cstrong>需要\u003c/strong>相关联。通过对这三个要素的觉察，我们清晰和诚实地表达出自己的状态。\u003c/p>\u003cp> 例如，一位母亲想和正值青春期的儿子用非暴力沟通的方式来说话，她可以这样来表达以上三个要素：“菲利克斯，看到咖啡桌下的两团脏袜子和电视机旁边的三团脏袜子，我很生气，因为我希望在我们共用的空间里能多些整洁。” 紧接着，她可以表达非暴力沟通的第四个要素——一个具体的\u003cstrong>请求\u003c/strong>：“你愿意把你的袜子放在你房间或放进洗衣机里吗？”我们借助这个要素提出对他人的期许，希望他（她）怎么做来满足我们的需要，让我们的生命更加美好。 \u003c/p>\u003cp>非暴力沟通的一部分是对这四个要素的清晰表达，表达的形式也不拘泥于语言。而另一部分则是从对方的表达中了解这四个要素。我们通过感知对方此刻的观察、感受和需要，与他们建立连结，进而聆听他们的请求，来找到通过什么方式让他们的生命变得更丰富。 \u003c/p>","explains":"\u003cp>【I拆书家讲解指导】\u003c/p>\u003cp>\u003cstrong>WHAT：\u003c/strong> 非暴力沟通是马歇尔·卢森堡博士发现的一种沟通方式，依照它来谈话和聆听，能使人们情谊相通，和谐相处，非暴力沟通有非常重要的四个要素：“观察、感受、需要、请求”。 \u003c/p>\u003cp>\u003cstrong>WHY：【不这么做的坏处】\u003c/strong> 暴力语言不仅会影响到我们的沟通，还会伤害感情。比如，“你总是不讲道理。你从来都这么自以为是。你这个人太自私了。你听不懂人话吗？”……这些都属于暴力语言，这些都非常容易引发对方的抵触情绪，或者说把对方激怒了，最终导致两败俱伤。正如《增广贤文》里的一句话：良言一句三冬暖，恶语伤人六月寒。“恶语”也就是暴力的语言对人们造成的伤害是非常大的，通常情况下我们每一个人都要尽量避免暴力语言，减少暴力语言的使用避免不必要的伤害是我们每一个人的通常做法。学习“非暴力沟通”对我们非常重要！\u003c/p>\u003cp>\u003cstrong>HOW：【正确做法】\u003c/strong> 怎么做到非暴力沟通，需要做好以下四步： \u003c/p>\u003cp>\u003cstrong>第一步：描述事实\u003c/strong> 不带评论的观察是人类智力的最高形式。留意发生的事情。就是你此刻观察到了什么?不管你是否喜欢，只是说出人们所做的事情。要点是，清楚的表达你观察到的结果，而不去判断或者评估。 表达事实的好处是不会引起反驳，因为事实是客观存在的，是无法让人辩驳的。 \u003c/p>\u003cp>\u003cstrong>第二步：表达感受\u003c/strong> 表达你的感受，比如这件事情是让你感到，受伤，害怕，还是说让你感到喜悦或者开心呢。 \u003c/p>\u003cp>\u003cstrong>第三步：体会需要\u003c/strong> 说出是哪些需要导致了你那样的感受。\u003c/p>\u003cp> \u003cstrong>第四步：提出请求\u003c/strong> 使用正向具体的语言提出请求。即明确告诉对方你希望他采取何种行动来满足我们。 \u003c/p>\u003cp> \u003cstrong>反例：\u003c/strong> \u003c/p>\u003cp>和大家分享一个发生在去年的案例，在一个阳光明媚的周六，弟弟一直在玩手机，刷视频，家里有很多家务活要在周六做完，比如每周六的扫除，房间的收拾整理，垃圾的清理以及碗筷的清洁等，但是弟弟一直只顾着玩手机，一点也不帮忙，这时候我感到有一些情绪反应，感到有一些生气，就过去直接质问他：“你怎么这么懒？整天只会玩手机，无所事事？怎么那么懒呢？”这时候弟弟也生气反驳到：“我哪里懒了？我哪里无所事事了？你倒是说说？我做家务的时候你怎么没看到？”场面一度不可收拾！\u003c/p>\u003cp>\u003cstrong>反思+正例：\u003c/strong>\u003c/p>\u003cp>刚刚案例的场景中导致了一种冲突，这是一种暴力沟通的一种场景。但是我们学了这个非暴力沟通的方法，我们会看到里面会有很多的暴力语言，比如“你怎么这么懒？”“你一整天无所事事？”等，它其实就是一个暴力的语言。\u003c/p>\u003cp>我们来回顾一下刚刚的表达中是如何运用非暴力沟通的四个过程的： \u003c/p>\u003cp>\u003cstrong>描述事实：\u003c/strong>我看到你坐沙发上刷视频已经两个小时了\u003c/p>\u003cp>\u003cstrong>表达感受：\u003c/strong>这让我有一点不开心 \u003c/p>\u003cp>\u003cstrong>体会需要：\u003c/strong>还有很多家务要做，需要帮忙 \u003c/p>\u003cp>\u003cstrong>提出请求：\u003c/strong>你能帮忙把卫生打扫一下吗？ \u003c/p>\u003cp>而当我们用非暴力来表达：\u003cstrong>我看到你在沙发上刷视频已经两个多小时了（描述事实），这让我有一点不开心（表达感受），因为还有很多家务要做（体会需要），你能帮忙把卫生打扫一下吗？（提出请求）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>WHERE：\u003c/strong> 这种沟通方法运用相对比较广泛，在我们需要对方做出改变的时候，就可以用这种沟通方法来提出我们的请求。但是如果当对方情绪非常激动，场面混乱的时候，或者不愿意沟通的时候，我们可以另择时机再沟通。 \u003c/p>\u003cp>【预防异议】 有人可能会问，每次都要运用非暴力沟通四要素表达吗？这样说话太麻烦了！ \u003c/p>\u003cp>【异议讲解】 初学者建议先认真应用四要素表达法。随着应用能力的增强，你对非暴力沟通表达的掌控会更加灵活，你可以根据不同时间和场景下进行调整。 \u003c/p>","interaction":"\u003cp> 5分钟 【A1:激活学习者经验】 请小伙伴们想一想，在我们的日常生活中，或者在我们身边遇到的，有没有哪次对话让你或者让对方感到不开心，或者激怒了对方的情况出现，或者有没有那种给别人贴标签，进行道德评判，或者进行比较的情况出现，比如说你想要同事哪个方面作出改变，但是你却用要求的语言去表达，结果闹得很不开心等等。接下来会给大家1-2分钟的时间去讨论，然后每组会请一位小伙伴来分享。 \u003c/p>\u003cp>丙大哥：和父亲沟通起小时候的事情，母亲的教育导致自己不够勇敢，这也怕，那也是怕，可是母亲回复：这与她有何关系？这样让他感受到愤怒。\u003c/p>\u003cp> 5分钟 【A1+ 请学习者反思加工经验】   感谢小伙伴们的分享。假如再给你一次机会，回到当初的情景，用上今天学习到的非暴力沟通的四个要素，也就是描述事实、表达感受、体会需要、提出请求。你会如何去回应呢？再给大家3分钟，按照我们刚才的分组的情况，在小组内进行交流，然后请一位小伙伴进行分享。 \u003c/p>\u003cp>丙大哥：\u003c/p>\u003cp>我的观察：在我说了小时候的一些教育让自己不够勇敢的时候，母亲嗓门很大的说了一句：这与她有何关系？我的感受：这让我感到有一些不开心，难过；我的需要：需要母亲能够理解自己，倾听自己；我的请求：希望母亲能够听自己把话讲完，能够自己的角度去考虑问题。\u003c/p>\u003cp>非暴力沟通的表达：（观察）妈妈你刚刚说话的声音很大，（感受）让我感到有一些难受，（需要）其实我希望你能理解我，（请求）能够先听我把话说完。\u003cbr>\u003c/p>\u003cp>【结语】 我们今天的分享就到这里，感谢聆听，希望今天的分享对大家会有收获。最后送大家一句话：用生活所感来阅读，用阅读所得去生活，希望非暴力沟通方法小伙伴们能在生活中实践起来！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1734944578000,"updated_at":1737128560000,"ria":true},{"id":18249,"topic":"非暴力沟通","learn_goal":"","remark":"非暴力沟通","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"兴宝","city":""},"club":{"name":"烟台八仙过海分舵","city":"烟台"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp> 大家好，我是兴宝，兴旺发达的兴，招财进宝的宝。三个标签介绍自己，第一航空安全管理者，曾经担任过6年飞机维修工程师，目前从事航空安全管理已经7年了；第二个标签是运动爱好者，平时喜欢打羽毛球、跑步、爬山、滑雪等；第三个标签，终身学习践行者，喜欢读书和演讲，是烟台八仙过海分舵的创始舵主，也是现在的会员长老，今天重新从1-1开始拆，是希望系统回顾下拆书技能。\u003c/p>\u003cp>【拆书和拆书帮介绍】\u003c/p>\u003cp> “拆书”不是把书拆开了读，是把书拆为己用，是一种学习方法，强调以学习者为中心而不是以知识为中心，学完了要考试，它是适用于提升能力、解决问题为目标的成人学习，要把知识关联过往经验、规划具体的应用。\u003c/p>\u003cp>“拆书”分为个人学习和组织学习的拆书法：个人学习的应用就是RIA便签法，R便签指的是阅读原文片段，I便签指用自己的语言转述R原文片段的知识，A便签分为A1和A2，A1对应的是过去的经验和反思，A2对应的是未来规划，通过便签读书让人读一本书达到参加同主题培训的效果；组织学习是拆书家拿出一本书加工出一堂课，引导学习者把知识拆为己用。\u003c/p>\u003cp>“拆书帮”就是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵，拆书帮分舵是非营利性青年自组织，使命是帮助更多学习爱好者成长为拆书家。我们的烟台八仙过海拆书分舵成立于2022年12月12日。\u003c/p>","ratings_count":1,"texts":[{"id":22527,"quote":"\u003cp>大家花2分钟左右时间看一下这个片段，看完片段的伙伴到时候请给我个示意，谢谢！\u003c/p>\u003cp>P140-141\u003c/p>\u003cp>表达愤怒的四个步骤\u003c/p>\u003cp>现在让我们看看非暴力沟通表达愤怒的具体步骤。首先，停下来，除了呼吸，什么都别做。我们避免采取行动去指责或惩罚对方。我们只是静静地体会自己。接着，想一想是什么想法是我们生气了。例如，无意中听到某个人的谈话后，我们认为由于种族原的原因自己遭到了排斥。这时，我们体会着愤怒，并留意脑海中盘旋的想法：“这太不公平了！她这是种族歧视！”我们知道，像这样的想法是尚未满足的需要的可悲表达。于是，接下来，就去了解自己想要满足的需求。如果我把某个人当作种族主义者，我的需要也许是接纳、平等、尊重或联系。\u003c/p>\u003cp>为了充分表达自己，我们现在需要张开嘴，说出我们的愤怒---怒火此时已被转化为需要以及需要相联系的情感。然而，表达此时的感受也许需要很大的勇气。对我来说，生气并冲着人们嚷“你忙这是种族歧视”是很容易的。事实上，我甚至还会觉得高兴。但是，倾听心底深处的感受和需要却很可能引发不安。为了充分表达愤怒，我们也许会对那个人说：“你走进房间后，和其他人都打了招呼，却没有和我说话，现在你又在议论白种人，注意到这些，我的胃有些不舒适，而且很害怕，因为我很看重平等。我想请你告诉我，听到我说这些，你的感觉怎么样？\u003c/p>","explains":"\u003cp>【WHAT】这个片段告诉了我们表达愤怒的四个具体步骤。\u003c/p>\u003cp>【WHY】【不这样做的坏处】当我们用着四个步骤表达愤怒时候可以充分表达我们的需求，而如果我们不这么做，要么忍气吞声最后不利于事情解决对自己身体还不好，要么把批评指责攻击对方，大家都跟着痛苦。\u003c/p>\u003cp>【where】这个方法使用于我们向可以沟通的人表达愤怒的时候。\u003c/p>\u003cp>【how】四个步骤表达自己的愤怒。\u003c/p>\u003cp>第一步，停下来，深呼吸，先不说话，先想一想\u003c/p>\u003cp>第二步，想想什么想法使我生气。\u003c/p>\u003cp>第三步，体会自己的需求。\u003c/p>\u003cp>第四步，表达感受和需求，\u003c/p>","interaction":"\u003cp>【A1】上个月需要向公司总部反馈全国质量审核发现问题的整改情况，一个单元反馈的工作内容不合格，整改材料在发现问题之前，我非常生气，我当时指着电脑对那个反馈的人说，你们反馈的内容经理不审核吗？审核怎么可能这么低级的问题都发现不了，你们稍微动动脑，最后同事很不开心的走了。\u003c/p>\u003cp>【A2】年底分公司要审核了， 由我牵头，各单元审核员可能会有一些基本常识不懂，或者审核发现不了问题，可能会让我很恼火，需要我表达愤怒，我会按照这四个步骤表达自己的愤怒\u003c/p>\u003cp>第一步，停下来，深呼吸，先不说话。\u003c/p>\u003cp>第二步，想想什么想法使我生气，作为审核专员连最基本的审核常识和技能都不掌握。\u003c/p>\u003cp>第三步，体会自己的需求。年底比较忙，内审这项工作需要大家的支持，每个审核员需要掌握基本的审核常识和技能，这样才能高质量的完成分公司内审。\u003c/p>\u003cp> 第四步，表达感受和需求，你们审核没发现问题，我很失望，我希望可以通过我们的审核更好的提升分公司的质量管理，我需要大家的支持，每个人都能按照质量审核的要求更新完善自己的检查单并按照条款逐项审核做到文文相符文实相符。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1730252138000,"updated_at":1730252642000,"ria":true},{"id":18125,"topic":"和谐沟通的艺术：非暴力沟通四步法","learn_goal":"","remark":"你想成为一个会沟通的人吗？来了解一下非暴力沟通吧，它让我们对情绪和感受更加觉察，既知道如何更清晰准确的表达自己，也知道如何同理倾听他人，运用非暴力沟通让我们的人际关系更加和谐。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"冰冰Bella","city":"深圳市"},"club":{"name":"深圳桃李分舵","city":"深圳"},"prologue":"\u003cp>大家好，我是今天的拆书家，冰冰。\u003c/p>\u003cp>\u003cstrong>F：（PPT 介绍图书）\u003c/strong>今天我给大家带拆的图书是《非暴力沟通》，作者是美国著名的心理学家马歇尔•卢森堡博士。这本书豆瓣评分高达8.7分，是非常经典的沟通类书籍。非暴力沟通是一种提倡友好、和平的沟通方式，它强调人与人之间善意的连结。非暴力沟通可以解决大部分的沟通难题。\u003c/p>\u003cp>\u003cstrong>A：\u003c/strong>与同类书籍相比,它简单易懂,对话式的案例形式,让我们身临其境感受到非暴力沟通语言的魅力。书中对于难懂的概念也有非常清晰的案例解析,让我们知其然,也知其所以然。\u003c/p>\u003cp>\u003cstrong>B1：\u003c/strong>语言暴力其实在我们身边很常见，特别是发生在亲近的人之间，有时候我们都没有意识到，但是当我们听到别人说这样的话的时候，我们会感觉不舒服或者产生不好的情绪，有时候我们自己也会对别人说出这样的暴力语言。这本书正是教我们需要有这种觉察，并且通过合理的方式正确的表达自己和倾听他人。\u003c/p>\u003cp>\u003cstrong>B2：（PPT 和谐沟通的艺术）\u003c/strong>今天我分享的主题是《和谐沟通的艺术：非暴力沟通四步法》，让我们在面对沟通障碍的时候，能够应用非暴力沟通的四个要素（无评判的观察，表达自己的感受，识别和表达自己的需求，提出具体的请求）来清晰的表达自己，和同理倾听他人，让我们的人际关系更加和谐美好。\u003c/p>","ratings_count":1,"texts":[{"id":22379,"quote":"\u003cp>（PPT 请大家阅读拆页）接下来，请大家花2分钟时间来阅读一下我挑选的这个片段。阅读完的伙伴可以在聊天窗口扣1，示意我。（ppt 原文拆页）\u003c/p>\u003cp>\u003cstrong>选自\u003c/strong>：\u003cstrong>《非暴力沟通》马歇尔·卢森堡 刘轶/译 p7-8 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>和谐沟通的艺术：非暴力沟通四步法\u003c/strong>\u003c/p>\u003cp>要达到让双方都能发自内心地相互给予，我们需将注意力聚焦在四个方面——它们是非暴力沟通模式的四个要素。\u003c/p>\u003cp>\u003cstrong>首先，我们观察实际上发生了什么\u003c/strong>。不论他人的言行是否有益于我们，我们只是去观察。要做到清晰表达所观察到的，我们的挑战在于\u003cstrong>不夹杂任何评判\u003c/strong>。不论喜欢与否，我们只是说出人们做了什么。\u003cstrong>第二步，表达出我们看到这些行为时的感受\u003c/strong>：是感到伤心、害怕、喜悦、有趣，还是心烦呢？\u003cstrong>第三步，表达出我们的感受与什么需要相关联。\u003c/strong>通过对这三个要素的觉察，我们清晰和诚实地表达出自己的状态。\u003c/p>\u003cp>例如，一位母亲想和正值青春期的儿子用非暴力沟通的方式来说话，她可以这样来表达以上三个要素：“菲利克斯，看到咖啡桌下的两团脏袜子和电视机旁边的三团脏袜子，我很生气，因为我希望在我们共用的空间里能多些整洁。”\u003c/p>\u003cp>紧接着，她可以表达非暴力沟通的\u003cstrong>第四个要素——一个具体的请求\u003c/strong>：“你愿意把你的袜子放在你房间或放进洗衣机里吗？”我们借助这个要素提出对他人的期许，希望他（她）怎么做来满足我们的需要，让我们的生命更加美好。\u003c/p>","explains":"\u003cp>好的，我看到大部分小伙伴已经阅读完了。\u003c/p>\u003cp>非暴力沟通能让我们在沟通的过程中心怀善意，它是一种沟通方法，也是一种思维方式。当沟通发生阻碍的时候，你还希望继续和对方沟通下去。那这个时候，你需要的不是摆事实讲道理、也不是证明谁对谁错，而是先用善意的方式表达自己,让对方感受到你的善意而不是评判,会让他感到安全,从而更愿意与你继续沟通。\u003c/p>\u003cp>如果不这样做的话？沟通可能会继续不下去，或者发展成更激烈的冲突或者争吵，会严重影响我们的人际关系。\u003c/p>\u003cp>片段中给出了非暴力沟通四步法，让我们学会善意的表达自己和聆听他人，与自己和他人建立连结。具体如下（ppt 方法回顾）：\u003c/p>\u003cp>\u003cstrong>第一步，描述事实：\u003c/strong>\u003c/p>\u003cp>我们需要清晰、客观的描述我们看到或听到的事实，而不是对其进行评判或解读。例如,与其说“你总是迟到”，不如说“我注意到你过去一周迟到了三次”。\u003c/p>\u003cp>\u003cstrong>第二步，表达感受：\u003c/strong>\u003c/p>\u003cp>说出你当时的感受，是伤心、害怕，还是心烦呢？\u003c/p>\u003cp>\u003cstrong>第三步，识别需要：\u003c/strong>\u003c/p>\u003cp>问一问自己，我有这种感受，是因为我有什么需求没有得到满足呢？比如，“我感到失望，因为我希望被肯定”。\u003c/p>\u003cp>\u003cstrong>第四步，提出请求：\u003c/strong>\u003c/p>\u003cp>最后，我们需要提出一个明确的、具体的请求，让对方知道他如何做能够满足我们的需要。\u003c/p>\u003cp>当我们将注意力持续聚焦在以上几个方面，\u003cstrong>并协助对方也这样做\u003c/strong>，我们便在彼此的沟通中创造了一种流动，如此你来我往，最终双方都能自然而然的展现善意。\u003c/p>\u003cp>通过非暴力沟通四步法，我们不仅能够看见自己：我此刻的观察、感受和需要是什么？为了让我的生命更美好，我的请求是什么？\u003c/p>\u003cp>还能看见对方：你此刻的观察、感受和需要是什么？为了让你的生命更美好，你的请求是什么？\u003c/p>\u003cp>\u003cstrong>&lt;举例&gt;\u003c/strong>\u003c/p>\u003cp> （PPT 案例分享）给大家说一个我自己的例子吧，（ppt 沟通发生冲突）最近一个月 我发现我爸开始用蓝牙耳机了，不管是在家里，还是外出，在他的耳朵上始终都挂着一个白色无线耳机。有时候，在家里跟他说话，话说完也不应，我以为他上年纪听力下降了，结果是因为戴了耳机，我就很生气。有时候，我也会忍不住说他几句，语气也不是很好。我爸呢，虽然不会怼我，但每次我说他，他就会臭着脸，仍然还是喜欢戴耳机，带孩子出门也挂个耳机。\u003c/p>\u003cp> 我觉得长期戴耳机对听力不好，在外面戴耳机也不安全。我反思了一下，我在跟我爸说耳机这件事的时候，总是在表达不满的情绪，并没有很友善的去和他沟通，也没有去关照他的需求。\u003c/p>\u003cp> 学习了非暴力沟通四步法之后，我换了一种更平和的方式来表达我的需求，并同理对方的感受，我是这样做的（ppt 方法应用）：\u003c/p>\u003cp> \u003cstrong>第一步，描述事实：\u003c/strong>\u003c/p>\u003cp> 我说：“爸，我看到您最近在家里经常戴着耳机，有时候跟您说话您会听不到；有时候带着米粒出门（米粒是我儿子小名），您也戴着耳机。”\u003c/p>\u003cp> \u003cstrong>第二步，表达感受：\u003c/strong>\u003c/p>\u003cp> 我有些担心，因为长时间佩戴耳机可能让您的听力受损；我有些害怕，因为您戴着耳机在外面听不到声音，过马路的时候会很危险，如果您和米粒在外面，孩子有什么事情，叫您您也不能及时回应他。\u003c/p>\u003cp> \u003cstrong>第三步，识别需要：\u003c/strong>\u003c/p>\u003cp>我感到担心和害怕，因为我希望您身体健康，不会因为年纪大了听不见，而影响您的生活质量；我也很担心您和米粒的安全，戴耳机出去听不到周围的声音是很危险的。\u003c/p>\u003cp>\u003cstrong>第四步，提出请求：\u003c/strong>\u003c/p>\u003cp>我希望您外出的时候，尽量不要戴耳机；在家里，您休息的时候戴耳机总时长也不要超过2个小时，孩子上学的时候，您在家放外音就好了。\u003c/p>\u003cp>我看见我爸爸有听书、听歌和看视频的需求，所以我说孩子不在家，他一个人可以在家里外放声音。我爸是看到我老公用了蓝牙耳机，自己买了一个差不多的，后来我老公送了一个质量更好的给我爸，把我爸开心坏了。\u003c/p>\u003cp> 这是我实际运用非暴力沟通的例子。\u003c/p>\u003cp>那这种沟通方式呢，让我们能够感受到彼此的善意，不委屈自己，也不伤害别人，让沟通双方都能满意，也增加了我们的幸福感。\u003c/p>\u003cp>\u003cstrong>&lt;预防异议&gt;\u003c/strong>\u003c/p>\u003cp>有的小伙伴可能会说，我就是急性子、暴脾气，像这样一步一步的处理问题太难了，还不如一通劈里啪啦，发泄完了再说。\u003c/p>\u003cp>但是这样做，不仅伤害了别人，自己的问题也没能得到解决，人际关系也变得不和谐。\u003c/p>\u003cp>在这本书里面讲到一个爸爸，把非暴力沟通的基本要素写在了一张卡片上，每次当他和同事或者家人发生争执时，他就会拿出卡片，认真考虑应该如何做出回应。以至于有一次，这个爸爸为了看电视的事情和他4岁的儿子发生了争执，眼看着争吵就要升级了，那个孩子连忙说：“爸爸，快拿卡片！”\u003c/p>\u003cp>这个例子说明，任何新技巧，都需要不断练习；所谓熟能生巧，用的多了，它就会成为我们的思维习惯和沟通习惯，不仅如此，善意回流，我们也会影响到我们身边的人。\u003c/p>\u003cp>非暴力沟通是一种以理解为基础的沟通方式，它强调在交流中避免任何形式的暴力，无论是言语上的、情绪上的还是行为上的。不过，有些情况下非暴力沟通可能不是最有效或者最合适的方法，比如：危险或紧急情况、对方完全不愿意参与沟通或处于无法理性沟通的状态（如酗酒、精神不稳定等）。\u003c/p>","interaction":"\u003cp>\u003cstrong>&lt;分步催化&gt;\u003c/strong>\u003c/p>\u003cp>（ppt 想一想最近..场景..）接下来，请大家想一想，在未来一周或者一个月，你与家人、朋友、同事或者领导之间交流的时候，会不会有可能发生一些争执的情况？可以用上非暴力沟通这个方法呢？\u003c/p>\u003cp>比如，十一假期快到了，家人们有的希望回老家，有的希望出去旅游，或者对于旅游地点的选择争执不下。\u003c/p>\u003cp>比如，夫妻之间，或者和父辈之间因为孩子的教养问题，发生矛盾，甚至引发争吵。\u003c/p>\u003cp>又或者是工作当中，两个合作的部门，因为没有及时沟通，或者是沟通不畅，导致落地实操的时候，工作不能顺利进行。\u003c/p>\u003cp>大家可以把想到的场景内容记下来，这个场景要包括时间、人物、起因这些要素，稍后我会邀请小伙伴现场分享。\u003c/p>\u003cp>(ppt 分组)这里需要提醒大家注意的是：现在只列出你设想的那个场景就好，不需要具体说如何去做。\u003c/p>\u003cp>\u003cstrong>&lt;分组安排&gt;\u003c/strong>\u003c/p>\u003cp>现在请主持人帮忙设置一下分组，分成2个组，时间3分钟，互相分享一下你在未来一周或者一个月，可能需要由你去处理的一个冲突场景。\u003c/p>\u003cp>....（ppt 请小伙伴分享）好，时间到了，请大家回到我们的主会场。现在，我们请一位小伙伴来分享你想到的这个场景，哪位小伙伴愿意分享，可以打开麦克风。（没有就随机点名啦）\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;请2位学习者分享，每人1分钟左右\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者彭大哥：\u003c/strong>\u003c/p>\u003cp>国庆节，回老家之后，和妹妹、父亲团聚，想到父母可能会和妹妹有沟通冲突的场景，因为妹妹一直希望老人可以过去帮她带孩子。\u003c/p>\u003cp>\u003cstrong>分享者鲲坤：\u003c/strong>\u003c/p>\u003cp>老婆在家喜欢刷手机视频，外放声音很多大，会影响在旁边工作的我，会让我感到烦躁，我感觉也会对小孩有不好的影响，我希望给孩子一个好的环境，做他的榜样。\u003c/p>\u003cp>好，谢谢分享。要沟通的情景已经有了，请各位小伙伴再思考一下，如果你要用“非暴力沟通四步法”来化解你上面想到的冲突场景，你会如何去做，如何去说。\u003c/p>\u003cp>(PPT 思考)给大家两分钟时间思考一下，稍后，我们请小伙伴来分享（ppt 方法回顾）。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;请2位学习者分享，每人1分钟\u003c/strong>\u003c/p>\u003cp> \u003cstrong>......\u003c/strong>（ppt 请小伙伴分享）好，时间到了，现在，我们请一位小伙伴来分享，哪位小伙伴愿意分享，可以打开麦克风（ppt 方法回顾）。（没有可以点名上面分享过的伙伴）\u003c/p>\u003cp>\u003cstrong>分享者1：鲲坤\u003c/strong>\u003c/p>\u003cp>假设发生上面的场景，运用非暴力沟通，我会这样和我老婆沟通：\u003c/p>\u003cp> \u003cstrong>首先，我不能发脾气，要心平气和描述事实：\u003c/strong>\u003c/p>\u003cp> 我会说：“老婆，我看到你抱着孩子，手里拿着手机，孩子眼睛也在盯着手机屏幕看。”\u003c/p>\u003cp> \u003cstrong>第二步，表达感受：\u003c/strong>\u003c/p>\u003cp> “我有些担心，手机屏幕对孩子的眼睛不好。也可能让孩子对手机产生兴趣。”\u003c/p>\u003cp> \u003cstrong>第三步，识别需要：\u003c/strong>\u003c/p>\u003cp>“我们都希望给孩子一个良好的成长环境。”\u003c/p>\u003cp>\u003cstrong>第四步，提出请求：\u003c/strong>\u003c/p>\u003cp>“我希望你陪孩子的时候，尽量不要玩手机。”\u003c/p>\u003cp>好，非常感谢鲲坤的分享。\u003c/p>\u003cp>\u003cstrong>分享者彭大哥：\u003c/strong>\u003c/p>\u003cp>场景是妹妹希望父母帮忙带孩子，但是父母不太愿意，他们之间沟通发生了一些冲突，我作为调解人，运用非暴力沟通四步法，缓解家人关系，我可能会这样跟我妹妹沟通：\u003c/p>\u003cp>\u003cstrong>首先，描述事实：\u003c/strong>\u003c/p>\u003cp>我可能会说：“妹妹，刚刚我听到你在跟爸妈商量，想让他们过去同住，帮你照顾孩子。”\u003c/p>\u003cp>\u003cstrong>第二步，表达感受：\u003c/strong>\u003c/p>\u003cp> “我有些担心，因为老爸前几天做身体检查，腰有些不适，去你那里要坐长途车，我担心他的腰受不了，会变严重。这次回家，我看到两个老人头上的白发又变多了，我有点心疼他们。”\u003c/p>\u003cp> \u003cstrong>第三步，识别需要：\u003c/strong>\u003c/p>\u003cp>“我感到担心，因为父母年纪大了，我希望他们少一些颠簸和折腾，他们在老家也习惯了，去到新环境可能会不适应。他们应该也挺害怕不适应的，做什么都没老家方便。”\u003c/p>\u003cp>\u003cstrong>第四步，提出请求：\u003c/strong>\u003c/p>\u003cp>“我希望你能再好好考虑这个决定，照顾孩子这块我们一起想想还有没有别的方案，你现在也去给爸妈道个歉，还是要多尊重他们自己的想法。”\u003c/p>\u003cp>好，非常感谢彭大哥的分享。\u003c/p>\u003cp>非暴力沟通帮助我们既清晰的表达自己，又同样关心他人，从而实现我们的情绪自由并与他人建立连结。希望我今天的分享能给大家一些启发，我的分享到这里就结束了，谢谢大家（ppt 最后一页）。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1727409206000,"updated_at":1728224335000,"ria":true},{"id":18005,"topic":"非暴力沟通的四个要","learn_goal":"","remark":"学习用非暴力沟通的四个要（观察、感受、需求、请求），解决人际冲突，使沟通更加顺畅。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"天天学习","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>大家好！我叫李洁，很荣幸和大家一起参加拆书帮的学习，我今天过的级别是TF1-1。\u003c/p>\u003cp>我的三个标签是：\u003c/p>\u003cp>我的第一个标签是：终身学习者。目前的主要学习方式是阅读，再有通过日记记录生活，自我反思，还有就是像参加咱们拆书帮的学习。\u003c/p>\u003cp>我的第二个标签是：银行从业者。二十年来主要从事公司银行业务，如果有任何企业融资方面的问题可以随时交流，可以给大家提供咨询。\u003c/p>\u003cp>我的第三个标签是：准拆书家。加入拆书帮，我的目标就是要成为三级拆书家，做一名学习促进者，帮助更多的人学习进步。\u003c/p>\u003cp>下面介绍一下拆书法和拆书帮\u003c/p>\u003cp>和拆书帮的缘分还是因为赵周老师的这本书。我参加拆书帮，也是非常偶然的一次机会，因为读书总记不住，我就在京东上搜关于读书方法的书，就看到了赵周老师的这本《这样读书就够了》书里的内容非常实用，重要的是让学习找到了方向，所以我坚定的要加入拆书帮成为拆书家。\u003c/p>\u003cp>先说一下什么是拆书法，“拆书”是成人学习的方法论，是解决问题、提升能力的成人学习，它以学习者为中心，把知识关联到学习者，做到学以致用。\u003c/p>\u003cp>“拆书法”分为个人便签法和组织学习的应用。先说个人便签法RIA,拿读书为例，R就是阅读原文，选择对自己有价值的内容I，用自己的话重述内容，做到真正理解；A分为A1和A2，A1就是联系自身实际经验，进行总结反思；A2就是在实际生活工作中的规划应用，以达到学以致用的效果。组织学习是通过现场学习，引导和促进学习者，把书中知识拆为己用，特别优秀的拆书家可以把学习变成一场培训。\u003c/p>\u003cp>什么是拆书帮？拆书帮是基于拆书法成立的学习社群，在全国乃至海外部分地区都有分舵，是非营利的青年自组织。拆书帮的使命是释放更多的学习促进者的能量，帮助更多的学习爱好者成为拆书家，相互陪伴，助人达己。\u003c/p>\u003cp>过渡语：\u003c/p>\u003cp>那现在就由我来带领大家拆解一下今天的片段，今天的片段来自《非暴力沟通》这本书，这本书解决的是沟通问题，作者是马歇尔·卢森堡博士(1934—2015)。国际非暴力沟通中心创始人，全球首位非暴力沟通专家。他有着50多年的实践经验，不仅指导人们在工作和生活中运用非暴力沟通，消除分歧和争议，实现高效沟通，还帮助解决了许多世界范围内的争端和冲突。我们可以用书中的方式，就是非暴力沟通的四个要素（观察、感受、需求、请求），解决人际冲突，使沟通更加顺畅。\u003c/p>","ratings_count":1,"texts":[{"id":22252,"quote":"\u003cp>\u003cstrong>那好，下面请大家花两分钟的时间阅读以下原文，请阅读完成的小伙伴示意我一下。\u003c/strong>\u003c/p>\u003cp>原文选自《非暴力沟通》P6-7页\u003c/p>\u003cp>非暴力沟通的要素\u003c/p>\u003cp>为了彼此能乐于互助，我们专注于四个方面﹣﹣非暴力沟通模式的四个要素。\u003c/p>\u003cp>首先，留意发生的事情。我们此刻观察到什么？不管是否喜欢，只是说出人们所做的事情。要点是，清楚地表达观察结果，而不判断或评估。接着，表达感受，例如受伤、害怕、喜悦、开心、气愤等等。然后，说出哪些需要导致那样的感受。一旦用非暴力沟通诚实地表达自己，前三个要素就会得到体现。\u003c/p>\u003cp>举例来说，一位母亲可能对她处于青春期的儿子说：&quot;费利克斯，看到咖啡桌下的两只脏袜子和电视机旁的三只，我不太高兴，因为我看重整洁。&quot;\u003c/p>\u003cp>接着，她立即提出非暴力沟通的第四个要素﹣﹣具体的请求：&quot;你是否愿意将袜子拿到房间或放进洗衣机？&quot;这一要素明确告知他人，我们期待他采取何种行动，来满足我们。\u003c/p>\u003cp>这样，这位母亲就清楚地说出非暴力沟通的四个要素。借助这四个要素诚实地表达自己，是非暴力沟通的一个方面。非暴力沟通的另一方面是借助它们关切地倾听。我们首先通过体会他人此刻的观察、感受和需要，与他们建立联系，然后聆听他们的请求，来发现做什么可以帮助他们。\u003c/p>\u003cp>保持对这两方面的关注，并帮助他人也这么做，双方便可持续互 动，直至情意相通：我此刻的观察、感受和需要是什么；为了改善生活，我的请求是什么；你此刻的观察、感受和需要是什么；为了改善生活，你的请求是什么……\u003c/p>\u003cp>使用非暴力沟通时，表达自己或倾听他人，都是好的开端。但需要牢记的是，非暴力沟通不是固定的公式，它可以适应不同的情况，并根据个人风格及文化环境做出调整。为了叙述的方便，我将非暴力沟通称为&quot;沟通方式&quot;，但有时语言是多余的。非暴力沟通的精髓在于对其四个要素的觉察，而不在于使用什么字眼进行交流。\u003c/p>","explains":"\u003cp>\u003cstrong>I：what\u003c/strong>看完这个片段，大家可以想象一下，如果你回到家看到袜子乱扔，满屋乱糟糟，你又是个好干净的妈妈，会怎么样？估计会直接暴怒，臭骂一顿，最起码也得指责一番，但最后的结果是往往是鸡飞狗跳，。而片段中母亲和儿子的对话场景，给大家呈现了一种标准的非暴力沟通模式，告诉我们非暴力沟通模式的四个要素，非常值得学习。\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>当我们清楚的说出非暴力沟通的四个要素（观察、感受、需要、请求），通过诚实的表达自己并关切的倾听他人，与对方建立链接，有了良好的互动，才能解决人际冲突，顺畅的沟通。大家是不是也很想学一下这个方法？\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>\u003c/p>\u003cp>非暴力沟通具体怎么操作呢?有以下几个步骤：\u003c/p>\u003cp>第1步:陈述事实\u003c/p>\u003cp>讲出自己观察到的事情，这里的观察中不能带有评论。比如:孩子把脱下来的衣服扔在地上，这是事实。我说这是没有规矩，这是评判。 \u003c/p>\u003cp>第2步:表达感受\u003c/p>\u003cp>表达出我们看到这些行为时内心的感受，注意这里是表达感受。比如开心、害怕、喜悦、生气等等这是感受。\u003c/p>\u003cp>第3步:表达需求\u003c/p>\u003cp>表达出感受背后的需要，比如生气是因为什么，因为我希望能保持家里的整洁。\u003c/p>\u003cp>第4步:提出请求\u003c/p>\u003cp>向对方说出你具体的请求。比如:你可以把房间的东西都放回原位吗? \u003c/p>\u003cp>以上四步简单吧，为了让大家方便使用，我总结了一句话，大家可以直接填空马上试一下：我看到/听到了\u003cu>什么\u003c/u>（观察）、我内心的感受\u003cu>是什么\u003c/u>（感受），我希望的\u003cu>是什么\u003c/u>（需求），你可以\u003cu>怎么做\u003c/u>（请求）。好，大家可以把它抄在纸上，都在自己在心里用一下哈。\u003c/p>\u003cp>\u003cstrong>Where\u003c/strong>这个方法很多场合都能用上，对话交谈、会议讨论都可以，也适用于不同对象，对家人、客户、同事、领导都行。只要使用非暴力沟通表达自己或倾听他人，就是好的开端。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>\u003c/p>\u003cp>我的A1便签：记得我家老大上高一的时候，暑假的一个周六，下午我去买菜，回来刚到门口，还没进门就听见争吵声。赶紧开门进去，看到儿子大声和他妈妈争吵，我也没问原因，就是两声呵斥，“养你这么大不是让你就这么对家长说话吗，一点儿规矩都没有！”后面我还加了一句脏话。儿子当时怒目而视，摔门就出去了，气氛很尴尬。其实就是因为假期生活不规律，在家里晚上不睡，白天不起的小事，我爱人说了几句就烦了。\u003c/p>\u003cp>现在回想，我当时的处理也特别不妥，上来就是给孩子下了一个没规矩的定义，还用了脏话，尽管是个本能反应，但这是激化矛盾而不是解决问题。应该按照非暴力沟通的要素进行沟通，告诉孩子：“你现在和妈妈说话的声音很大，我觉得这样不好，我希望你尊重你妈，你能心平气和的沟通吗？”\u003c/p>\u003cp>我的方式直接把对话停止了，双方没有了互动，最后不可能解决问题，更何况对青春期的孩子策略也不对。\u003c/p>\u003cp>\u003cstrong>A2：\u003c/strong>\u003c/p>\u003cp>目标：本周日针对我家二宝经常晚睡的问题，进行一次非暴力沟通，要涵盖四个要素。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>1、 时间定在周日的晚上八点左右，这个时间段没有课，有一段不受打扰的时间。\u003c/p>\u003cp>2、具体谈话步骤：\u003c/p>\u003cp>1)、闺女，爸爸和你说个事啊，最近发现你一周以来都在12：00之后才睡觉（观察）。\u003c/p>\u003cp>2）、爸爸很担心你的身体（感受）。\u003c/p>\u003cp>3）、你现在还小正在长身体，经常这么晚睡对身体很不好，爸爸希望你能有养成好的生活习惯，是个身心健康的孩子（需求）。\u003c/p>\u003cp>4）、这对你未来有很大好处，咱们以后每天11：00前就睡觉怎么样？（请求）\u003c/p>\u003cp>然后用以上四个要素，做好倾听，互动分析孩子晚睡的原因，找到适合的解决方案。\u003c/p>\u003cp> 那好我们总结一下，今天我们学习到了非暴力沟通的四个步骤，大家要特别注意以上沟通不是固定格式，要根据具体情况，当时的气氛，做出调整，重点在于对四个要素的觉察，不在于使用什么样的字眼。最后再复习一下，我看到/听到了\u003cu>什么\u003c/u>（观察到的事实）、我内心的感受\u003cu>是什么\u003c/u>（表达感受），我希望的\u003cu>是什么\u003c/u>（表达需求），你可以\u003cu>怎么做\u003c/u>（提出请求）。用我们学到的四步，表达自己并倾听他人，人与人之间的沟通一定会更加顺畅，人际关系也会更加和谐，最后感谢大家的聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1724757398000,"updated_at":1724770387000,"ria":true},{"id":17501,"topic":"区分观察与评价，做有效沟通者","learn_goal":"","remark":"观察是“我看见”，评论是“我认为”，区分两者的差异，如何做一个只说事实、不带情绪和偏见的沟通者？","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"汤小敏","city":"镇江市"},"club":{"name":"镇江西津分舵","city":"镇江"},"prologue":"\u003cp>大家好，我是汤敏，是今天TF3-1拆书家。用三个标签介绍我自已，第一我是地产公司的从业者，第二我植物美肌护肤英树护肤品牌的官方经销者，第三我是二级拆书家拆书法追随者。今天我的拆页选自《非暴力沟通》这本书。\u003c/p>\u003cp>为了方便稍后的讨论和演练，我们先分个组，从我的左手边起，两两一组\u003c/p>\u003cp> \u003cstrong>（场景）\u003c/strong>\u003c/p>\u003cp>上周末上午，儿子上完篮球课10:00到家回来就抱着手机在玩游戏，我到家准备睡个回笼觉，告诉他玩半小时游戏后写一页《课时练习》，然后刚好吃饭。他玩着手机爽快答应，让我快快去睡觉。到了饭点，我起来吃饭，看他还在沉浸式玩游戏，说好写的作业安静的躺在书桌上一动未动。\u003c/p>\u003cp>\u003cstrong> （提问）\u003c/strong>\u003c/p>\u003cp>我想问问大家，如果这是你的孩子，你会怎么处理？是批一顿还是骂一顿？是听之任之，随他去，还是好言相劝，晓之以理，动之以情？ \u003c/p>\u003cp>\u003cstrong> （影响）\u003c/strong> \u003c/p>\u003cp>其实，在遇到孩子无节制的玩手机不愿意写作业这样的情况，很多时候我们都会心情很糟糕，对应的坏情绪就会上来，那也就很难做到跟孩子好好沟通，长此以往带着坏情绪跟孩子沟通，会让亲子关系很不和谐，而且严重点说，会造成孩子一直跟你对着干很叛逆。\u003c/p>\u003cp>\u003cstrong> （解决）\u003c/strong>\u003c/p>\u003cp>《非暴力沟通》这本书作者主张用爱的语言来表达感受和倾听，通过非暴力沟通三步法“观察行为--表达事实--友善提醒”以达到彼此之间的真诚交流，这种不带情绪和偏见的表达，更有助于解决人与人之间因为沟通不畅而带来的矛盾与冲突。\u003c/p>\u003cp>\u003cstrong>（学习目标）\u003c/strong>\u003c/p>\u003cp> 通过今天的学习，让我们可以学会如何区分(行为)“观察”与“评论”，并运用有效沟通三步法“观察行为--表达事实--友善提醒”（澄清），来让沟通双方都能愉快地接受对方（界定）。\u003c/p>\u003cp>现在请大家用2分钟的时间，阅读一下刚刚给到大家的拆页，读完小伙伴举手示意我一下。\u003c/p>","ratings_count":2,"texts":[{"id":21687,"quote":"\u003cp>《非暴力沟通》P40-41 作者:马歇尔.卢森堡博士\u003c/p>\u003cp>对于大多数人来说，观察他人及其行为，而不评判、指责或以其它方式进行分析，是难以做到的。\u003c/p>\u003cp>在为一个小学提供咨询服务时，我对此有了深刻的体会。这个学校的教师和校长经常反映彼此很难沟通。于是，学区负责人请我协调双方的矛盾。我先和全体教师交谈，然后请校长来参加讨论。\u003c/p>\u003cp>会谈一开始，我就问：“校长的哪些行为不符合你们的需要？”“他是个大嘴巴。”有人马上回答。我的问题是想了解他们的观察——校长说了什么或做了什么，而“大嘴巴”只是这位教师对校长的评价。\u003c/p>\u003cp>在我指出这一点后，第二位教师补充说：“我知道他是什么意思。校长的话太多了！”这仍是一个评论——评论校长话多还是话少。随后，第三位教师说：“他认为只有他的话有价值。”我解释说，推测别人想什么与观察他的行为幷不是一回事。最后，第四位教师也表明了看法：”他希望所有的人都一直听他讲话。“当我说这也是猜测时，有两位教师脱口而出：”你的问题真难回答啊！“\u003c/p>\u003cp>接着，我们注意区分观察和评论，一起列出了校长的具体行为。例如，在全体教员会议中，校长会讲他的童年和战时经历，有时会导致会议超时20分钟。我问他们是否已向校长反映问题，他们说，他们试过，但从没有提及具体行为——例如校长在会议中回忆往事。最后，他们同意，在校长参加讨论时，指出这些行为。\u003c/p>\u003cp>与校长的会谈开始后，我很快就发现教师们一直在说的事情。不论讨论的主题是什么，校长总是插话：”这让我想到。。。。。。“然后，他就开始讲他的童年和战时经历。我等着教师们说出他们的不快。然而，他们运用的不是非暴力沟通，而是无声的抗议。一些人滴溜溜转着眼睛；另一些人故意打着哈欠；还有个人直盯着手表。\u003c/p>\u003cp>我忍耐着这痛苦的场面，过了 一会儿，我问道：”没有人有话要说吗？“接着是有些别扭的沉默。后来，在之前会谈中率先发言的那位教师鼓起勇气，冲着校长说：”你是个大嘴巴！”\u003c/p>\u003cp>可见，不受旧习惯束缚，学会区分观察和评论，幷不容易。最后，教师们终于告诉校长，他在做哪些事时，他们会感到不安。校长听后抱怨说：”为什么从没有人提醒我呢？“他承认他有讲故事的习惯。然而，他接着就开始说与这个习惯有关的故事！这时，我提醒了他。会谈结束后时，我们总结了几个办法。一旦教师们不想听校长回忆往事，就温和的提醒他。\u003c/p>","explains":"\u003cp>好，时间到。如果还有伙伴没有读完也不要紧，我将在下面的分享中继续为你讲解。\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>这个片段通过作者给小学老师提供咨询服务，化解老师与校长之间的沟通矛盾的经历，提出了在沟通中要善于观察客观现象，提出善意建议，而不是用主观观点评论对方行为。\u003c/p>\u003cp>\u003cstrong>概念辨析\u003c/strong>\u003c/p>\u003cp>观察是非暴力沟通的第一要素，也是实现非暴力沟通的第一步，但是这非常不容易做到，因为它特别容易和表达评论相互混淆。那什么是观察？什么是评论呢？它们两者该如何辨析？\u003c/p>\u003cp>观察是列出自己看到、听到或用其他感官感受到的客观存在的具体事件或行为，用语言表述出来。\u003c/p>\u003cp>评论则是我们对人、事、物的主观判断或者评判。下面，我们来简单举个例子。\u003c/p>\u003cp>例子一：他经常迟到。这是观察还是评论？\u003c/p>\u003cp> 拆书家：好，答对了，这是评论。迟到是他观察后的结果，但是经常怎么去界定呢？一周迟到三天是经常？还是一个月迟到五天算经常？\u003c/p>\u003cp> 例子二：今天周一，他上班迟到了5分钟。这是观察还是评论？\u003c/p>\u003cp> 拆书家：好，很对，这是观察。这是表达观察，因为他只是通过观察之后，不带任何意见的表达目前看到的场景。\u003c/p>\u003cp> 例子三：他真是个大嘴巴。 \u003c/p>\u003cp>拆书家：对了，这显然是个评论。这句话里“大嘴巴”是一个非常主观的判断，换一个人来可能就不会这样形容他了。\u003c/p>\u003cp> 例子四：领导给我们开周例会，比原计划结束时间延迟了20分钟。\u003c/p>\u003cp>拆书家：对，这是个观察，我们感受到的客观存在的具体事件，会议延迟了20分钟。\u003c/p>\u003cp>【两者区别】通过上面四个例子，相信大家能够比较清晰的辨别了“观察”与“评论”两者之间的区别。观察是给人呈现当下的事实，是客观描述，而评论是由事实让你所产生的感受和想法，带有主观性，这就是二者最大的差异。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>那我们在日常生活与工作中，怎么能做到客观描述的表达呢，结合原文的案例，我总结出以下三个步骤：\u003c/p>\u003cp>1、观察行为：通过眼看、耳听等方式观察对方正在发生的具体行为、动作。\u003c/p>\u003cp>2、表达事实：将正在发生的客观事实如实地表达出来。\u003c/p>\u003cp>3、友善提醒：用对方能接受的语气做出善意的提醒与劝告。\u003c/p>\u003cp>（回到案例）\u003c/p>\u003cp>回到上周我儿子玩手机没做作业的案例，我想我会这么做：\u003c/p>\u003cp>1、观察行为：\u003c/p>\u003cp>看儿子玩游戏的神情，专注、投入，而且嘴里念念有词：一定行、一定行，拿手机的手指，有节奏地、欢快地、快速地动着、突然，非常开心地，一握拳，嘴里喊着：Ye，我赢了、终于过关了。\u003c/p>\u003cp>2、表达事实：\u003c/p>\u003cp>我走到孩子身边，摸着孩子的头说：儿子，你玩手机的时候，太专注了，即使叭着玩，眼睛也没离开过手机。\u003c/p>\u003cp>3、友善提醒：\u003c/p>\u003cp>妈妈担心你， 小小的年纪，眼睛怎么吃得消？你就一点也不担心，小小年纪会近视？妈妈可是非常担心你。\u003c/p>\u003cp>你看，儿子，玩游戏的时候，你会发现，时间过得特别快，不知不觉一个半小时，很快就过去了，但是作业却没有完成，你说该怎么办呢？儿子看了我一眼，诧异的说：妈妈大气啊，竟然没骂我。我吃完饭就把作业做完。\u003c/p>\u003cp>相信这样温柔且友好的表达客观事实，孩子一定不会反抗，而是与你达成共识，今后认真履行自己定下来的规则。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp> 通过有效沟通三步法“观察行为--表达事实--友善提醒”以达到彼此之间的真诚交流，这种不带情绪和偏见的表达，更有助于解决人与人之间因为沟通不畅而带来的矛盾与冲突。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>有效沟通三步法适用于亲密关系（比如亲子、夫妻、好朋友等）的沟通。\u003c/p>\u003cp>（预防异议）\u003c/p>\u003cp>可能有人会问这么沟通不是太麻烦了嘛，说个话还要想半天这究竟是观察？还是评论？其实非暴力沟通，强调的是使用爱的语言，客观的表达我们的想法。其重点在于，发生矛盾和冲突时，如果没有把观察和评论区分开来，别人只会倾向于听到批评，不容易认同你的言语表达。所以发生矛盾和冲突时，使用有效沟通三步法”比较容易让对方接受你的言语表达。\u003c/p>","interaction":"\u003cp>现在请大家设想一下，未来的一个月内时间内会不会出现这样的场景：\u003c/p>\u003cp>孩子做作业拖拖拉拉还发脾气不愿写。\u003c/p>\u003cp>跟孩子玩电子产品的约定，孩子不能自觉遵守。\u003c/p>\u003cp>老公天天出去应酬晚归不顾家。\u003c/p>\u003cp>跟同事一起协作完成的事情，停滞在同事负责的那个部分得不到有效推进。\u003c/p>\u003cp>请每位小伙伴各自独立编写一个小故事剧本，具体场景内容要包含时间、人物、地点、事件背景、经过（需要有人物对话、动作，部分对话使用“有效沟通三步法”的技巧）、结果。时间是4分钟。\u003c/p>\u003cp>4分钟后，我们请一个小伙伴来跟我们分享她的故事。\u003c/p>\u003cp>凌老师案例分享：\u003c/p>\u003cp> 我分享的事情是在下周五会发生。是我们班有个小朋友，上课讲话，上课下位置不遵守课堂纪律。为了不影响其他同学，老师之前会大声提醒这位小朋友。今天学了有效沟通三步法后，会这样做：\u003c/p>\u003cp>第一步：观察行为：给这个小朋友一些时间，尽力去观察他，看他究竟做什么。\u003c/p>\u003cp>第二步：表达事实：不在全班同学面前提醒他讲话等这样的行为，会私下里跟他清楚表达上课动了几下，做了哪些小动作，讲话了几次不要以为老师不知道。而且是不带情绪的去提醒他。\u003c/p>\u003cp>第三步：友善提醒：用委婉的方式提醒他，周五时我会这么跟他说：想做什么事情，想玩什么玩具，下课了老师带你去玩，你想跟哪位小朋友讲话，下课了老师会帮你与他沟通好，但是上课我们就好好上课。\u003c/p>\u003cp>好，非常感谢凌老师的反馈，我如果是你班上的这位小朋友，会感觉特别的温暖。\u003c/p>\u003cp>今天我们学习了如何区分“观察”与“评论”，同事运用“非暴力沟通三步法”来表达观察结果，从而远离令人反感的评论，希望大家在生活和工作中多运用多实践，取得预期的沟通效果。，今天的我的分享就到这里啦~感谢大家的聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1713337740000,"updated_at":1713572262000,"ria":true},{"id":17228,"topic":"非暴力沟通化解冲突五步法","learn_goal":"","remark":"你有没有这样的情况，本来是想化解冲突，缓和关系；一场谈话后，冲突爆发了，关系破裂了。\n\n本次拆书能教会你如何应用非暴力沟通五步法来化解冲突，收获幸福的人际关系。\n\n 内容简介：\n用非暴力沟通五步法来化解冲突，收获幸福的人际关系","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"魏立","city":""},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>今天的学习目标是：跟随我完成本次RIA现场学习后，学习者能够用非暴力沟通化解冲突的这五个步骤来反思加工过去的冲突，也就是完成A1+便签。\u003c/p>\u003cp>今天我们就自行分为一组。\u003c/p>\u003cp>自我介绍：\u003c/p>\u003cp>大家好，我是今天的拆书家魏立，用三个标签简单介绍一下自己；\u003c/p>\u003cp>第一个标签是曾经的一名工程师。有需要的话，可以教你们用电脑画图，做三维设计，做分析等工作。\u003c/p>\u003cp>第二个标签是一名阅读者，看心理，传记类，致用类，文学类书籍较多。最近和人在共读《高效能人士的七个习惯》这本书。如果你也喜欢相同类型的书籍，那就来，一起读一本书，相互分享和探讨。\u003c/p>\u003cp>我还是一名开启了拆书家之旅的终生学习者。\u003c/p>\u003cp>图书介绍：\u003c/p>\u003cp>今天选取的拆书片段来自于《非暴力沟通（修订版）》，作者是马歇尔-卢森堡博士。\u003c/p>\u003cp>Feature：\u003c/p>\u003cp>《非暴力沟通（修订版）》这本书在沟通界有着神圣的地位，有着沟通界的圣经之称；在香港大学等很多大学，樊登读书，古典读书会都被列入必读书籍。\u003c/p>\u003cp>Advantage：\u003c/p>\u003cp>这是一本非常畅销的沟通类书籍，又和一般的沟通类书籍不同，他不是某个成功人士的经验总结，不是几个万能金句，更不是一些心灵鸡汤。\u003c/p>\u003cp>它涵盖了沟通领域的方方面面，从理论到实践，从个人到人与人之间，为读者呈现了一幅完整的沟通地图。\u003c/p>\u003cp>Benefit：\u003c/p>\u003cp>B1：\u003c/p>\u003cp>通过阅读本书，您将学会先看见自己的需要和情绪，再看见别人的需要和情绪。做到“先悦己，后悦人”，每一天都可以更加的幸福。 \u003c/p>\u003cp>B2：\u003c/p>\u003cp>今天的拆书主题为“非暴力沟通化解冲突五步法”，能教会你在面对冲突时，如何让对方感受到被理解，被看见。\u003c/p>\u003cp>这样你就能，平复对方的情绪；然后就可以化解冲突，增强彼此的关系。\u003c/p>","ratings_count":1,"texts":[{"id":21400,"quote":"\u003cp>\u003cstrong>R原文阅读《非暴力沟通（修订版）》P177\u003c/strong>\u003c/p>\u003cp>非暴力沟通化解冲突的步骤\u003c/p>\u003cp>在详细讨论化解冲突的核心要素之前，我先大致介绍一下在化解自己和他人的冲突过程中所涉及的5个步骤。任何一方都可以先表达自己的需要，简便起见，假设先由我方表达。\u003c/p>\u003cp>·首先，我们要表达自己的需要。\u003c/p>\u003cp>·其次，不论对方说什么，设法找出他们真正的需要。如果发现他们表达的是想法、评判或分析，而不是需要，我们可以继续寻找话语背后的需要。\u003c/p>\u003cp>·第三，确认我们都准确理解了彼此的需要，否则，继续寻找话语背后所隐含的需要。\u003c/p>\u003cp>·第四，尽可能地同理对方，以便让双方都能确切地了解彼此的需要。\u003c/p>\u003cp>·第五，当双方都澄清了事件中的需要后，我们就可以用正向的描述行动的语言提出化解冲突的策略。\u003c/p>\u003cp>在整个过程中，我们要仔细聆听彼此的心声，避免在言语中影射对方有错。\u003c/p>","explains":"\u003cp>What，这个片段介绍了使用非暴力沟通化解冲突的的五个步骤。\u003c/p>\u003cp>Why，冲突，与我们息息相关，无论你在生活中，还是在工作中，就不可能逃离冲突，甚至每天都要应对各式各样的冲突。\u003c/p>\u003cp>冲突来了，我们是怎么应对的呢？通常有这两种模式：\u003c/p>\u003cp>第一种模式是赢输模式，一方赢，一方输； \u003c/p>\u003cp>一方以力量、地位、权势、财力等为手段使另一方屈服，但是屈服一方的需要没有得到满足，被压抑的情绪也会不断地积累，最终会以某种形式爆发出来。\u003c/p>\u003cp>第二种模式是输输模式，双方都是输家，双方都固执己见，都不服输，采取对抗的行为，坚持自己的要求，达成不了共识，最后却落了个两败俱伤。\u003c/p>\u003cp>这两种模式都会伤害这段关系，严重的甚至会失去这段关系，就连赢输模式中赢家曾经获得的，也会一并失去。\u003c/p>\u003cp>举反例说明：\u003c/p>\u003cp>之前和朋友约好了一起去浏阳看烟花，当天中午，有一个在群里说不去了，不想错过五月天线下活动的彩蛋。当时我是挺愤怒的，要出发了才说，故意没有回她。在群里和其他几位确定了集合地点后去看了烟花。\u003c/p>\u003cp>这件事之后，我们联系的就少了。\u003c/p>\u003cp>事实上这就是一种输输模式，两败俱伤，损伤了我们的关系。\u003c/p>\u003cp>How，那怎么样才能化解冲突，增强双方的关系呢？我们可以通过这五个步骤来完成：\u003c/p>\u003cp>第一个步骤：讲出自己的需求。\u003c/p>\u003cp>第二个步骤：觉察对方的需求。\u003c/p>\u003cp>第三个步骤：互相确认都清晰准确了解了对方的需求，否则，重复前面步骤，继续寻找需求。\u003c/p>\u003cp>第四个步骤：同理对方，安抚情绪。\u003c/p>\u003cp>第五个步骤：从当下出发，用正向行动的语言提出自己的策略，化解冲突。\u003c/p>\u003cp>反例变正例。\u003c/p>\u003cp>第一步：这次借着一起看烟花，也是想朋友之间，能够一起小聚一下。（讲出自己的需求）\u003c/p>\u003cp>第二步：不过我也感到你真的好喜欢五月天，很想现场参与，看看彩蛋是什么。（觉察对方的需求）\u003c/p>\u003cp>第三步：彼此确认都清晰准确了解了对方的需求，包括她知道了我的需求，不仅仅是看烟花，也是想一起聚一下。也知道我明白了她对五月天线下活动的重视，尤其是彩蛋。（确认彼此知道了对方的需求）\u003c/p>\u003cp>第四步：你这么喜欢五月天，我也感受到了你的激动，兴奋，很想现场见证这个彩蛋是什么。（同理她，安抚情绪）\u003c/p>\u003cp>第五步：那你玩的开心点。我们就去浏阳看烟花去了，下次我们找时间再聚。（当下的一个正向行动建议）\u003c/p>\u003cp>Where，自己重视的人际关系或者重要事情有了冲突时，比如亲子关系，伴侣之间，重要的朋友，重视的同事之间，推荐使用这种沟通方式来化解冲突。\u003c/p>\u003cp>如果是已经决定不再来往的人或者陌生人插队这样子的事情，就大可不必使用这种方法。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>拆书家激活学习者经验：（激活经验+显像提问法）\u003c/p>\u003cp>刚刚我们学习了这个片段，那么请我们想一想，在生活与工作中，最近有没有冲突发生，伤害了彼此间的关系呢？\u003c/p>\u003cp>比如：\u003c/p>\u003cp>你回到家，看到桌子上都是瓜子壳，橘子皮，老公却躺在沙发上玩手机。\u003c/p>\u003cp>晚上10点钟了，孩子还在玩游戏，作业却没有写完。\u003c/p>\u003cp>给下属安排了一个任务，超过截至日期了，还没有完成。\u003c/p>\u003cp>当时你是怎么说的，怎么做的？可以回想一下具体的场景，请在便签上写一下时间、地点以及你当时的一些关键词。\u003c/p>\u003cp>时间3min。\u003c/p>\u003cp>燕子学员分享的案例：\u003c/p>\u003cp>就是前一前几天学了一个那个演讲的体验课嘛，跟我老公在那边聊天时候经常发生这个情况。\u003c/p>\u003cp>就是说比如我跟他说一件什么事情，那他的说话模式就是no＋and，什么意思呢？\u003c/p>\u003cp>比如说你跟他讲说，哎这个杯子好好看，他说这有什么好看的，你看他觉得怎么样啊，就是后面证明一下这个东西不好看，就类似这样子一个说话模式啊，但之前我是没意识到的，然后前两天是有个那个体验演讲课，那老师就说，就是人在说话的时候，最好用的是yes＋and模式，就是不论别人说什么，你先肯定他；然后再说，哎；为什么肯定他，冲突就来源于这个啊。\u003c/p>\u003cp>因为我学了之后，我知道啊，我就跟我老公说，你看我知道为什么我天天跟你吵架，就是你的说话模式有问题，你的说话模式，你看人家老师说了正常的那的用yes+and，最后是他不承认。\u003c/p>\u003cp>就这样子会发生争吵，一次冲突就来了。\u003c/p>\u003cp>A1+\u003c/p>\u003cp>拆书家提问设计：（反思加工经验）\u003c/p>\u003cp>嗯，刚才我们听到燕子学员的一个分享，嗯，从这个分享也能看出其实学习这个步骤也是挺有必要的。\u003c/p>\u003cp>因为这又是一个很明显的冲突案例。他们当中这个沟通其实是是无效的，这种是非常的伤害这段关系的，对吧？\u003c/p>\u003cp>嗯，那么也感谢他，感谢他的分享。那曾经的她，不知道这种方法就会留下遗憾。\u003c/p>\u003cp>假设有个时光机回到过去的话，用非暴力沟通这五个步骤来化解当时那场冲突。\u003c/p>\u003cp>那每个步骤我们要怎么做呢？我们还是一样，在纸上把它写出来。\u003c/p>\u003cp>燕子的A1+\u003c/p>\u003cp>第一个步骤：老公，我不想听到你对我有负面的评价，我只想听到正面的评价。所以你不要评价我，你可以夸我，但你不要评价我。（说出自己的需求）\u003c/p>\u003cp>第二个步骤：老公想要多说话，有表现欲，想要有存在感。 (觉察老公的需求） \u003c/p>\u003cp>第三个步骤:和老公确认，互相对需求理解是否正确。（确认需求）\u003c/p>\u003cp>第四个步骤：老公，你说那么多话，其实我特别能理解你，因为你想多说话，其实的目的是要多说话，并不要惹我生气，对不对？（同理他，安抚情绪）\u003c/p>\u003cp>第五个步骤：你可以讲一点，不会让我生气的话，就你只要不评价，我，让你爱说啥说啥充分表示让发挥你的这个那个沟通的欲望。（一个正向的方案）\u003c/p>\u003cp>好的，感谢小伙伴的踊跃参与，积极分享和互动。\u003c/p>\u003cp>现在，拆书是结束了，学习可还没有。\u003c/p>\u003cp>学以致用，用以促学，以学促行，知行合一。只有用起来才真正的学有所成，学有所获。\u003c/p>\u003cp>谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1705660002000,"updated_at":1705803110000,"ria":true},{"id":17217,"topic":"表达感激三要素","learn_goal":"","remark":"生活中，我们经常对别人提供的帮助习以为常，忽略了表达感激的重要性，也失去了表达感激的能力。重新认识表达感激三要素，让你重获美好人际关系","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"qixiyueya","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>【自我介绍】188字，1分钟\u003cbr>大家好，我叫七七。因为我的生日是7月7号，很好记。\u003cbr>3个标签先介绍自己：\u003cbr>第一个标签：职业规划师，有15年互联网大厂的工作经验，可以一起探讨怎么赚钱的问题\u003cbr>第二个标签：理财规划师，探讨少花钱和钱生钱的问题\u003cbr>第三个标签，就是重启人生沙盘主持。重启人生类似于财富流，但更能激发玩家对幸福人生的思考，很有意思，感兴趣的可以随时来找我玩。\u003cbr>\u003cbr>\u003cbr>请大家记住我：职业规划师、理财规划师，也是未来的拆书家，七七\u003cbr>\u003cbr>\u003cbr>【拆书介绍】373字，2分钟\u003cbr>接下来是对于拆书法和拆书帮的介绍。\u003cbr>拆书是一种以学习者为中心的成人学习法，核心是拆为己用。不是说我们背诵了多少个知识点，就算学习了，而是这些知识变成了我们日常工作生活中在熟练使用的技能，那才是真正的习得。\u003cbr>拆书法呢，有两种方式。\u003cbr>第一种是个人便签学习法。比如你看一本致用类的书，发现一个很有感触的知识点，可以写3张专属便签，来督促自己学习。这种自己练习的方式，也能达到参加主题培训的效果。\u003cbr>第二种是RIA现场组织学习法：R是Reading阅读拆页，I是Interpretation拆书家讲解技能点，A是Appropriation学习者练习拆为己用。就像我们今天这样，拆书家把一本书加工成一场现场培训，引导和促进学习者练习一项技能。\u003cbr>那么拆书帮呢，首先它是一个非营利性的青年自组织，不为了赚钱，而是致力于创造一个广大的学习爱好者在这里都能学以致用的社群，同时也帮助更多学习爱好者成长为拆书家。\u003cbr>全国自上而下，有总舵，也有各地的分舵，感兴趣的可以来加入，希望大家都能在拆书帮的大家庭里，有所收获。\u003c/p>","ratings_count":1,"texts":[{"id":21388,"quote":"\u003cp>【阅读拆页的过渡语】70字，0.5分钟\u003cbr>接下来开始我们今天的拆书：\u003cbr>我选择的是《非暴力沟通》，做为沟通类书籍的扛鼎之作，相信大家都不陌生。\u003cbr>下面给大家2-3分钟的时间阅读下拆页，看完可以抬头示意我一下。\u003c/p>\u003cp>\u003cbr>\u003cbr>在使用非暴力沟通表达感激时，我们会清楚地包含以下三个要素：\u003cbr>·他人做了什么增进了我们的福祉。\u003cbr>·我们有哪些需要因此得到了满足。\u003cbr>·因为这些需要得到了满足，引起了我们什么样的愉悦感受。\u003cbr>\u003cbr>\u003cbr>在下文的对话中，大家可以看到如何用这三个要素来表达“赞赏”。\u003cbr>学员：（在工作坊结束后来找我）马歇尔，你太棒了！\u003cbr>马歇尔：我好像不太理解你为什么要这么称赞我。\u003cbr>学员：为什么？你的意思是？\u003cbr>马歇尔：人们给过我无数的头衔，但我却完全无法从这些表述中学到什么。我想从你对我的赞赏中有所学习，并且因此感到喜悦，但我需要你再多说一些。\u003cbr>学员：比如说？\u003cbr>马歇尔：首先，我想知道我说了什么或者做了什么让你的生命变得更加美好。\u003cbr>学员：嗯，你很有智慧。\u003cbr>马歇尔：恐怕你刚刚又给了我另一个评判。我依然想知道我做了什么让你的生命更美好。\u003cbr>学员：（思索了一会儿后，她指着自己在工作坊上写下的笔记）看这两处，就是你说的这两点。\u003cbr>马歇尔：噢，所以你赞赏的是我说的这两点？\u003cbr>学员：是的。\u003cbr>马歇尔：接下来，我想要知道这些话带给你的感受。\u003cbr>学员：感到充满希望，并且释然。\u003cbr>马歇尔：那么现在我想知道，我说了这两点满足了你哪些需要。\u003cbr>学员：我一直无法和我18岁的儿子沟通，一直在努力寻找一种更加情意相通的方式和他相处，你说的这两点让我找到了方向。\u003cbr>听到这三个要素的内容（我做了什么，她有何感受以及满足了她哪些需要）后，我就能真正和她一起享受这份赞赏。如果一开始就用非暴力沟通的方式来表达，她可以说：“马歇尔，当你说这两点时（向我展示她的笔记），我感到充满了希望并且释然，因为我一直在寻找方法和儿子连结，你的这些话给了我方向。”\u003c/p>","explains":"\u003cp>【I便签】760字，5分钟\u003cbr>【Why】\u003cbr>不管是生活还是工作，如果别人为我们提供了帮助，我们是不是得表示感谢，那大家平时怎么表达感谢呢？\u003cbr>有些朋友觉得，咳，都是一家人，说感谢的话多见外，我们心里都懂；\u003cbr>有些朋友觉得，那就说谢谢呀，如果光说感谢还不够，那就再送些礼物；\u003cbr>有些朋友觉得，如果说的太多了，会不会让人觉得我们还有其他所求呀。\u003cbr>\u003cbr>\u003cbr>没有人不喜欢听感谢的话，那是对自己做的事情的肯定，所以千万不要去吝啬说感谢的话。\u003cbr>而且，表达感谢也很简单，只要是真诚就够了，也不一定需要昂贵的礼物。\u003cbr>\u003cbr>\u003cbr>【What】\u003cbr>《非暴力沟通》中的这段话，就讲述了表达感激的三个要素，也是将表达感激拆分成了3句话，通过表达对方做了哪些行为、满足了自己什么诉求、当前的心情如何，来体现，对方确确实实帮助了你，而你，非常真诚的感谢他。\u003cbr>\u003cbr>\u003cbr>【How】\u003cbr>这3句式如何做呢？我们来练习一下。\u003cbr>首先，要描述对方做了什么事情，要具体。比如：谢谢你指导我修改了我的简历\u003cbr>其次，要描述满足了你哪些需求，解决了你的哪些问题。比如，我之前的简历写的不好，投简历之后就石沉大海了，我自己也不知道该怎么改，还好有你帮我，现在我每天都能接到面试邀请。\u003cbr>最后，说下这些问题解决后，你的心情如何。比如：简历终于通过了，我可真是太开心了，非常有信心我一定能找到工作。\u003cbr>这样的3句式下来，对方一定能感受到你的感谢，以及你感谢里的真诚。\u003cbr>\u003cbr>\u003cbr>【Where】\u003cbr>这样简单的3句式，可以应用在很多你想要表达感谢之情的场景。\u003cbr>比如，我们跟父母之间，可能对现在的你，没法提供工作上实质性的建议了。但是回家后，他们准备了一桌你爱吃的菜，我们可不可以就这个场景，对父母表达感谢之情呀？可以吧。\u003cbr>比如，下属跟老板之间，虽然你是靠自己的业绩升职加薪的，但老板给你做晋级答辩之前的辅导，为你争取晋级的名额，把能出成绩的业务交给你，我们可不可以表达下感谢呀？可以的。\u003cbr>再比如，父母跟孩子之间。孩子帮你画了一幅画，帮你倒了一杯水，或者就只是在你下班回家后，她冲过来抱着你说爸爸妈妈，我好想你呀，你怎么才回来~是不是立刻满血复活？那我们可不可以对孩子表达下感谢呢？非常可以！\u003cbr>\u003cbr>\u003cbr>\u003c/p>","interaction":"\u003cp>【A1】300字，2分钟 \u003c/p>\u003cp>比如我自己，还是一个挺愿意表达感谢的，举个我和我前老板的例子。 那还是我刚参加工作没多久。有一次，我被其他同事甩锅了，他找我老板投诉我，虽然我老板平时非常强势，爱批评我们，但在这件事情，她还是很公平公正的站在了我这边。 虽然，我本来就做的没错，但并不是所有老板都公平公正的，对吧。 所以我当时就很直接对她表示了感谢： 感谢你在收到这个投诉的时候，第一时间不是找我问责，而是先调查清楚了事实，然后做出了公平的抉择，最后还来安慰我，不要因为这个生气、不要委屈。（这是她做的事实）。如果换成别的老板，这个锅最后肯定是我来接了，这个项目我以后也没法负责了，对我的打击会很大（这是解决了我什么问题）。你这么做，我真的很感动，也觉得自己很幸运（我的心情）。 是不是很简单，也很真诚，不用担心被讲，我只是在拍马屁吧，哈哈\u003c/p>\u003cp>【A2】218字，1.5分钟\u003cbr>\u003cbr>\u003cbr>当然，也有做的不好的时候。\u003cbr>比如，我要搬家，我的朋友非常积极的帮我看房子，还砍价格。\u003cbr>但是因为是非常好的朋友，习惯了互相帮忙了，就容易忽略。\u003cbr>\u003cbr>\u003cbr>所以我给自己定了一个计划：\u003cbr>【时间】明天，约她一起吃饭，然后向她表达我的感谢。\u003cbr>【行动】感谢你牺牲了带娃的时间，出来帮我看房子，还帮我砍下了不少价格，直接帮我省了1万多块钱。我这么爱拖延，如果不是你帮我，肯定不会这么快就找到这么好的房子，而且我超级不会砍价的，还好有你。找到新房子，能搬到跟你一个小区，我很开心，有你这样的朋友，我可真幸福，爱你哟~\u003cbr>\u003cbr>\u003cbr>我相信她也会很开心的。\u003c/p>\u003cp>【结束语】101字，0.5分钟\u003cbr>最后，说一句，在生活和工作中，多觉察别人对你的好，多说说感谢地话，我们的美好人生，先从积极的表达感谢之情开始。\u003cbr>\u003cbr>\u003cbr>最后的最后，感谢大家今天花15分钟来听我这次的拆书，帮助我完成第一次拆书家的锻炼和成长，非常开心在这里遇到大家~谢谢~~\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1705552508000,"updated_at":1705649186000,"ria":true},{"id":17181,"topic":"表达愤怒的方法","learn_goal":"","remark":"拆页中的非暴力沟通会帮助我们解决生活中和别人的沟通问题","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"刘雪","city":"邢台市"},"club":{"name":"邢台第二筹备分舵","city":"邢台"},"prologue":"\u003cp>\u003cstrong>自我介绍：\u003c/strong>\u003c/p>\u003cp>大家好！我是刘雪，刘就是刘邦刘备刘禹锡的刘，雪就是“梅须逊雪三分白”的雪。首先我用三个标签来介绍一下我自己，一是小学语文教师，今年刚入职，在这之前做了四年的初中老师，带了两届毕业班，还带出来了一个中考语文状元。二是万能手工小师傅，我会刺绣、钩针、做簪子、做耳饰头饰等等。三是家庭教育的小学徒，半年时间内学了PET和游戏力，并成为了游戏力和PET的践行者。相信在今后我的自我介绍中会多一项拆书家的标签。\u003c/p>\u003cp>\u003cstrong>拆书帮介绍：\u003c/strong>\u003c/p>\u003cp> 说到拆书家，就得先跟大家讲一讲什么是拆书。拆书是什么呢？拆书就是\u003cstrong>将书中的知识转化为学习者能力的方法论\u003c/strong>，拆书法\u003cstrong>强调将知识关联学习者的经验并规划具体的运用\u003c/strong>。它适合以自我为导向、以解决实际问题为目的的成人学习。与它相对的就是以知识为导向，以考试过级为目的的学院式学习。拆书分为个人学习的拆书法——RIA便签法，帮助个人在没时间没精力的情况下快速地将书中的知识拆为己用，解决实际问题，读一本书相当于参加一场同主题的培训；供组织学习的拆书法——RIA现场学习。现场学习就是拆书家拿一本书加工出一场现场学习，帮助他人把知识拆为己用。\u003cbr> \u003c/p>\u003cp>而拆书帮就是聚集拆书学习爱好者的社群，它是非营利性的青年自组织，目前全球58个正式分舵，17个筹备分舵，在册同学有1720位。\u003cstrong>拆书帮是致力于培养拆书家的学习乐园。\u003c/strong>在这里大家可以提升自己的学习力，把知识拆为己用、反求诸己。这里也有一群志同道合的小伙伴陪伴赋能，一起持续精进自己的学习能力，共同成长。同时我们还可以在这里释放自己的能量，帮助更多的人提升自己，让世界变得更加美好。\u003c/p>","ratings_count":2,"texts":[{"id":21358,"quote":"\u003cp>接下来就由我来带领大家拆解一下大家手中的片段。拆页内容选自《非暴力沟通》，作者是\u003ca href=\"https://baike.baidu.com/item/%E9%A9%AC%E6%AD%87%E5%B0%94%C2%B7%E5%8D%A2%E6%A3%AE%E5%A0%A1/16435374?fromModule=lemma_inlink\">马歇尔·卢森堡 ，\u003cstrong>这是一本经典的沟通类书籍\u003c/strong>，接下来请大家用1分钟的时间阅读拆页内容，阅读结束后，请抬头示意。\u003c/p>\u003cp>\u003cstrong>原文阅读《非暴力沟通》P159\u003c/strong>\u003c/p>\u003cp>表达愤怒的四个步骤\u003c/p>\u003cp> 1.停下来，深呼吸。\u003cbr> 2.看看我们有哪些评判性的想法。\u003cbr> 3.与我们的需要连结。\u003cbr> 4.表达我们的感受和未被满足的需要。\u003c/p>\u003cp>来看看充分表达愤怒的具体步骤。首先，停下来，除了深呼吸，什么都别做；不去指责或惩罚他人，只是保持安静。接着，看一看是什么想法让我们生气。例如，无意中听到某人说了一些话，使我们相信自己由于种族的缘故遭到了排斥。感知到自己的怒气时，如果停下来，便会看到头脑中盘旋的想法：&quot;这太不公平了！她这是种族歧视！&quot;我们知道，所有的评判都在用可悲的方式表达未满足的需要。于是，接下来的第3步是：与这些想法背后的需要连结。如果指责某人是种族主义者，我们的需要也许是融合、平等、尊重或者与人连结。\u003c/p>\u003cp>为了充分表达自己，我要采取的第4步是开口表达愤怒——怒火此时已被转化为感受和需要。然而，表达此时的感受也许要很大的勇气。对我来说，生气并冲着人们嚷&quot;你这样做是种族歧视&quot;是很容易的，甚至还会感到很畅快。然而，要说出内心深处的感受和需要，却可能令人却步。为了充分表达愤怒，我们也许可以试着和对方说：“你走进房间后，开始与其他人聊天，却没有和我说话。接着，你开始议论有关白人的种种。当注意到这些时，我的胃非常不舒服，我也很害怕。这使我意识到，我非常希望受到平等的对待。我想请你告诉我，听到这些话，你的感受是怎么样的？”\u003c/p>","explains":"\u003cp>大家都已经看完了手中的拆页内容了，不知道大家在生活中是否会被愤怒的情绪困扰，我猜大家应该都有控制不住自己的时候哈。\u003c/p>\u003cp>\u003cstrong>Why:\u003c/strong>就像我之前在网上看到一句话“我经常因为我的易怒而生气”。听起来很好笑，又有点真实。我们都知道莫生气莫生气，气出病来无人替，可轮到我们自己碰到一些事情时却难以控制自己的愤怒，结果就是口出冲动之语，让事情变得更加糟糕。有愤怒乱发泄不好，有愤怒不发泄更不好，那么我们如何表达愤怒呢？\u003c/p>\u003cp> \u003cstrong>What：\u003c/strong>本拆页就讲了表达愤怒的方法，可以帮助我们合理表达愤怒，提高我们面对愤怒时解决问题、缓解情绪的能力。\u003cbr> \u003cstrong>How：\u003c/strong>表达愤怒的四个步骤大家也都知道了，我在拆页的基础上带大家再深入理解一下。\u003cbr> 1.\u003cstrong>停下来，深呼吸\u003c/strong>。发觉自己有了愤怒的情绪，停下来，不说话、不做事，通过深呼吸将理智脑拉回来。\u003cbr> 2.\u003cstrong>看看我们有哪些评判性的想法\u003c/strong>。对于这件让我们生气的人或事我们是怎么想的。例如：学生上课说话，想法：他们不遵守班规，不把我的话放在心上，太不尊重我了。\u003cbr> 3.\u003cstrong>与我们的需要连结\u003c/strong>。这件让我生气的事情导致了我的什么需求未被满足。例如：我需要安静的环境保证我能顺利讲课。\u003c/p>\u003cp>4.\u003cstrong>表达我们的感受和未被满足的需要\u003c/strong>。将我们生气愤怒的感受和自己的需求表达出来。例如：我需要安静的环境让我能够顺利讲课，但是你上课大声说话，让我很生气。\u003c/p>\u003cp>\u003cstrong>Where：\u003c/strong>此方法适用于我们有愤怒情绪的时候向别人表达情绪。但需要特别注意的是，不要忽略第一步，如果我们不能让自己停下来深呼吸给自己情绪降温的话，是无法成功进行下面的步骤的。所以当自己情绪过于激动无法控制时，也不适用。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1便签\u003c/strong>\u003c/p>\u003cp>我在看拆页内容的时候，就想到了我自己亲身经历的事情。上周上课时，有一个男同学不好好在座位上听课，用凳子和地板碰撞出声音，多次说坐端正，不要发出声音，但并不管用。我就无法压抑自己的愤怒了，于是奔向那个同学，揪起他的领子，跟他说：“再发出声音就滚出去。”虽然他暂时被我吓到了，但是下一节课还是没有明显改变。我自己也因为发了脾气，影响了自己讲课的效果。这件事情为什么变得更加糟糕了呢？我认为有以下几个原因：\u003c/p>\u003cp> 1.自己没有给自己深呼吸平复情绪的时间，而是由情绪控制自己，做一些冲动的事。\u003cbr> 2.情绪脑占据主要地位，丧失理性思考的能力了，所以没有思考自己有哪些评判性的想法，也没有连接自己的需求。\u003cbr> \u003c/p>\u003cp>3.自己在表达愤怒时，没有说出自己的感受和需求，对方并不知道他的行为，对我造成的影响。\u003c/p>\u003cp>\u003cstrong>A2便签\u003c/strong>\u003c/p>\u003cp>针对我对拆页内容的理解和反思，我给我自己定了以下目标：\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong>从今天到本周天，再遇到同学做出让我生气的事的时候，运用此方法表达出自己的愤怒。\u003c/p>\u003cp>为了达到此目标我将采取以下\u003cstrong>行动\u003c/strong>：\u003c/p>\u003cp>1.遇到学生让自己生气的情况时，先停下讲课，让自己深呼吸三下。\u003c/p>\u003cp>2.用1分钟的时间思考自己对学生这一行为评判性的想法。并找出自己产生这一想法背后的需求。\u003c/p>\u003cp>3.将自己的需求和当下的感受表达给对方。\u003c/p>\u003cp>\u003cstrong>结语：\u003c/strong>最后我再对今天所拆解的内容进行一个总结，本次拆页主要讲了如何表达愤怒，分为：停下来深呼吸、思考想法、连接需求、表达感受和需求四个步骤。希望可以帮助大家在日常工作学习中察觉自己的愤怒情绪，表达自己的感受，让自己被自己看到。\u003c/p>\u003cp>我今天的分享到这里就结束了，感谢大家的聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1705312724000,"updated_at":1706189040000,"ria":true},{"id":16889,"topic":"真诚感谢三步骤 夸到对方心坎里","learn_goal":"","remark":"非暴力沟通表达感谢的方式。通过摆事实、说需求、表感受，将我们的感谢具象化，传递对方做这件事情的价值，还能够让对方感受到你的真诚。","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"长缨","city":"天津市"},"club":{"name":"天津北洋分舵","city":"天津市"},"prologue":"\u003cp>不破不能立，不拆不成器。\u003c/p>\u003cp>大家好，我是长缨，用三个标签介绍一下我自己。\u003c/p>\u003cp>1.拆书帮一级拆书家\u003c/p>\u003cp>2.AACTP天津培训师Pro俱乐部创会主席\u003c/p>\u003cp>3.医药营销培训师\u003c/p>\u003cp>今天我挑战的2-3会有讨论、演练环节，所以在正式开始之前我们先分一下组（以我为中心左边为第1组，右边为第2组）。\u003c/p>\u003cp>今天我拆解的书籍是《非暴力沟通》：\u003c/p>\u003cp>F 特征：这本书在豆瓣有着8.4的高评分，是非常经典的沟通类书籍，在拆书帮目前拆书实录中位居榜首，足见它的受欢迎程度。\u003c/p>\u003cp>A 优点：本书作者马歇尔·卢森堡是美国威斯康星大学临床心理学博士，也是一名临床心理学专家。相较于其他同主题的书，这本书不仅给出了非暴力沟通的万能公式，对于典型沟通场景还提供了许多实用的建议和案例分析，便于理解应用。\u003c/p>\u003cp>B 利益：\u003c/p>\u003cp>（B1）通过阅读这本书，我们可以运用非暴力的沟通方式，降低冲突矛盾发生的频率，使人际关系更加和谐，个人内心更加平和。\u003c/p>\u003cp>（B2）今天片段的学习能让我们学会有效的表达感激，对方提供了什么具体的帮助，满足了我们的什么需求，以及带给我们的感受，让对方感到被重视和被尊重、增强彼此的关系。\u003c/p>\u003cp>大家跟随我完成RIA现场学习后，学习者能够在需要正式表达感激之情的场合，清晰的运用“感谢三步法”向对方表达谢意。\u003c/p>\u003cp>现在请大家先阅读原文片段，时间是 2 分钟。看完之后抬头示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":21012,"quote":"\u003cp>在使用非暴力沟通表达感激时，我们会清楚地包含以下三个要素：\u003c/p>\u003cp>・他人做了什么增进了我们的福祉。\u003c/p>\u003cp>・我们有哪些需要因此得到了满足。\u003c/p>\u003cp>・因为这些需要得到了满足，引起了我们什么样的愉悦感受。\u003c/p>\u003cp>表达这三个要素时，并不一定要遵照以上的顺序。有时哪怕是一个微笑或一句简单的“谢谢你”就足以传递这一切。不过，如果我们想要确保对方能够充分收到我们的心意，用语言完整地表达这三个要素是有意义的。在下文的对话中，大家可以看到如何用这三个要素来表达“赞赏”。\u003c/p>\u003cp>学员：（在工作坊结束后来找我）马歇尔，你太棒了！\u003c/p>\u003cp>马歇尔：我好像不太理解你为什么要这么称赞我。\u003c/p>\u003cp>学员：为什么？你的意思是？\u003c/p>\u003cp>马歇尔：人们给过我无数的头衔，但我却完全无法从这些表述中学到什么。我想从你对我的赞赏中有所学习，并且因此感到喜悦，但我需要你再多说一些。\u003c/p>\u003cp>学员：比如说？\u003c/p>\u003cp>马歇尔：首先，我想知道我说了什么或者做了什么让你的生命变得更加美好。\u003c/p>\u003cp>学员：嗯，你很有智慧。\u003c/p>\u003cp>马歇尔：恐怕你刚刚又给了我另一个评判。我依然想知道我做了什么让你的生命更美好。\u003c/p>\u003cp>学员：（思索了一会儿后，她指着自己在工作坊上写下的笔记）看这两处，就是你说的这两点。\u003c/p>\u003cp>马歇尔：噢，所以你赞赏的是我说的这两点？\u003c/p>\u003cp>学员：是的。\u003c/p>\u003cp>马歇尔：接下来，我想要知道这些话带给你的感受。\u003c/p>\u003cp>学员：感到充满希望，并且释然。\u003c/p>\u003cp>马歇尔：那么现在我想知道，我说了这两点满足了你哪些需要。\u003c/p>\u003cp>学员：我一直无法和我18岁的儿子沟通，一直在努力寻找一种更加情意相通的方式和他相处，你说的这两点让我找到了方向。\u003c/p>\u003cp>听到这三个要素的内容（我做了什么，她有何感受以及满足了她哪些需要）后，我就能真正和她一起享受这份赞赏。如果一开始就用非暴力沟通的方式来表达，她可以说：“马歇尔，当你说这两点时（向我展示她的笔记），我感到充满了希望并且释然，因为我一直在寻找方法和儿子连结，你的这些话给了我方向。”\u003c/p>","explains":"\u003cp>看到大家抬头示意我，看来原文已经阅读好了。接下来，咱们一起来拆解这个片段。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>当我们得到他人非常重要的帮助时，如果只是简单地说声“谢谢”，往往显得不够有诚意。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>这个片段为我们提供的非暴力沟通表达真诚感谢的方式。感谢不是浮于表面的谢谢，而是通过说明行为、说明价值、说明感受这三个要素，将我们的感谢具象化，传递对方做这件事情的价值，还能够让对方感受到你的真诚。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>如何向对方表达真诚的感激呢？（细化的行动步骤）\u003c/p>\u003cp>第一、说明行为\u003c/p>\u003cp>先说对方帮你做了什么，在描述过程中，不能一带而过，而是要多说细节。我们来对比一下这两句，“靓靓老师帮我看了逐字稿”和“靓靓老师熬夜帮我审阅了50页逐字稿”，后一句对于细节行为的描述传递的能量更强烈。\u003c/p>\u003cp>第二、说明价值\u003c/p>\u003cp>对方做的事情对你而言，有什么重大的影响。比如“这个逐字稿反复修改了7次，还是不能过关，这次多亏了你反复帮我研磨，汇报顺利通过了！”\u003c/p>\u003cp>第三、说明感受\u003c/p>\u003cp>传递给对方有哪些真实的感受，让对方也体会到你的心情。比如“为了这个逐字稿你帮我反复斟酌，有你在，我总是特别安心。”\u003c/p>\u003cp>三个要素介绍完了，这里需要注意的是，以上没有先后顺序，从任何一个要素开始都是可以的。\u003c/p>\u003cp>【常见的异议】\u003c/p>\u003cp>也许你会质疑，需要这么隆重吗？向对方表达感激说一句“谢谢”不就可以啦，是不是有些啰嗦。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>事实上，我们都体会过在餐厅对端菜给你的服务生说“谢谢”，和对在危难时刻借给你十万块钱的人说“谢谢”，轻重是不一样的。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>当“谢谢”不足以表达对他人的感激或者尊重的时候，可以使用今天学到的感谢三步骤。而在一些公共场合，例如餐厅中服务员上菜、倒水，地铁、公交车上别人起身让座，只要一个点头微笑或者说声‘谢谢’就可以。\u003c/p>\u003cp>【反面例子】\u003c/p>\u003cp>为了方便大家理解，我来分享一个真实的例子。上个月我参加一场工作坊，讲师马晓龙老师水平很高，对我提升培训水平很有帮助。于是我课后找到了她。我们之间是这样对话的。\u003c/p>\u003cp>我：马老师，你讲得太好了！\u003c/p>\u003cp>马晓龙：我好像不太理解你为什么要这么称赞我啊？\u003c/p>\u003cp>我：老师的意思是？\u003c/p>\u003cp>马晓龙：其实我更想知道哪些地方给你带来收获？你可以说的具体说说么？\u003c/p>\u003cp>我：老师我一下子说不上来。。。您能举个例子么。\u003c/p>\u003cp>马晓龙：好，首先，我想知道我在课上讲了什么或者做了什么让你认为这个工作坊很棒？\u003c/p>\u003cp>我：嗯，马老师很有方法。\u003c/p>\u003cp>马晓龙：有方法，比‘讲的棒’有进步了，回忆一下，有哪些让你印象深刻的方法么 ？\u003c/p>\u003cp>我：（思索了一会儿后，她指着自己在工作坊上写下的笔记）我记下两个特别难忘的，您看看。\u003c/p>\u003cp>马晓龙：嗯，看到你的笔记画红圈圈的两个了。\u003c/p>\u003cp>我：是的老师。一个是提问引导方法、一个是案例分析方法。\u003c/p>\u003cp>马晓龙：接下来，我想要知道这两个方法带给你的感受。\u003c/p>\u003cp>我：豁然开朗！\u003c/p>\u003cp>马晓龙：嗯，很好，这两个方法满足了你哪些需要？\u003c/p>\u003cp>我：这种学习方式不仅增加了我们学员的交流和沟通能力，还让我们更好地理解了所学内容。\u003c/p>\u003cp>例子讲完了，有些羞愧的是，我是在马老师的引导下才讲出了内心深处的谢意。\u003c/p>\u003cp>【正面例子】\u003c/p>\u003cp>在学完了《非暴力沟通》关于真诚感谢的片段后，我重新梳理了感谢三要素，在培训结束前，我再次表达了对马老师的感谢，我是这样说的。\u003c/p>\u003cp>马老师，您课程中讲到了提问引导和案例分析法，（说明行为）\u003c/p>\u003cp>这两个方法是我特别期待学习的，增加了我们与学员交流与沟通能力，（说明价值）\u003c/p>\u003cp>收获满满，特别感谢您！（说明感受）。\u003c/p>","interaction":"\u003cp>我们刚刚学习了如何使用非暴力沟通的三个要素来表达感激，为了让大家更好地理解和掌握新知识，现在我们来做一个演练。\u003c/p>\u003cp>请大家认真倾听演练的场景：\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>任女士的女儿特别喜欢看女子体操，其中有两位体操选手是孩子的偶像，比赛结束后孩子守在体育馆门口期待能得到两位偶像的签名。等了一段时间才发现，这里不是运动员的出入口，估计白等了，不免心里有些失落。这时候一位体操迷小哥哥看到任女士母女两个站在那里干等，就主动跑过来告诉他们母女两个，他也是来要签名的，看到母女俩个等的地方不对，一会儿运动员出来就要不到签名了。于是，母女跟随两个来到正确的运动员出口后，这位体操迷小哥哥还主动找到了工作人员，特别拜托如果两位选手出来，专门提醒一下远道而来的母女两人，别让他们白等。就这样，在他的帮助下，孩子顺利的等到了自己的偶像，不但签了名，体操迷小哥哥帮着用孩子的手机和偶像合影。\u003c/p>\u003cp>任女士和孩子都非常感动，孩子主动走向体操迷小哥哥，想向对方表达内心的感激之情，但又觉得一句“谢谢小哥哥”之类的语言，太单薄了。现在请你帮助孩子或这位母亲运用刚才学到的非暴力沟通的“感谢三步骤”，真诚的感谢小哥哥提供帮助，该怎么说呢？\u003c/p>\u003cp>【指令】\u003c/p>\u003cp>各位小伙伴，场景听清楚了吗？\u003c/p>\u003cp>（1）接下来，现场的两组小伙伴讨论，请你选择以孩子或者母亲的口吻，运用非暴力沟通“感谢三个要素”表达对这位小哥哥的感谢之情吧。\u003c/p>\u003cp>（2）讨论时间是5分钟，时间到了之后，再来请 2 位伙伴分享。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>学习者 1：带领我们来到了正确的出口，还细心的叮嘱工作人员照顾我们，然后让我和妈妈等到了自己的偶像签了名合了影，实现了自己的愿望，让我既开心又感动，感谢真心感谢小哥哥。\u003c/p>\u003cp>学习者 2：感谢你带我们到正确的位置，然后让我们见到了偶像，并且还帮我们拍照留念，你就满足了孩子追星的愿望，然后也能让他继续保持对体操的这份热爱。那么你这个行为让我们感到特别的开心，这一趟旅行也没有遗憾，特别谢谢你！\u003c/p>\u003cp>感谢两位的精彩演练！把今天所学到的三步骤用到位了！\u003c/p>\u003cp>最后我们再回顾一下非暴力沟通的“感谢三个要素”吧。\u003c/p>\u003cp>一、说明行为，说出你观察到对方为了帮助我们，做了哪些具体的事情。\u003c/p>\u003cp>二、说明价值，说出对方提供的帮助，让你的哪些需求得到了满足。\u003c/p>\u003cp>三、说明感受，表达我们的需求获得满足或者问题得到解决时，给对方正向积极的评价。\u003c/p>\u003cp>本次拆书到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1699795531000,"updated_at":1700032457000,"ria":true},{"id":16846,"topic":"非暴力沟通表达愤怒","learn_goal":"","remark":"用非暴力沟通表达愤怒，和平地解决问题。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"彭丽","city":"南宁市"},"club":{"name":"南宁清澄分舵","city":"南宁"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是彭丽，彭德怀的彭，美丽的丽，是拆书帮的准拆书家，今天我通关的级别是TF1-2。首先我先简单介绍下我自己。\u003c/p>\u003cp>我是一名职业整理师，有5年整理研习和从业经验，为自己打造了两个井井有条的家，有30多户入户整理和咨询经验。有家居环境困扰的伙伴可以链接我。同时我希望通过整理的推广，让更多人的人能够发现生活的美，热爱生活，用心生活。\u003c/p>\u003cp>\u003cstrong>【分组+图书介绍】\u003c/strong>\u003c/p>\u003cp>在正式拆书之前，我先给大家分一下组，方便等会儿讨论。从我右手边开始，三位伙伴一个小组。\u003c/p>\u003cp>我今天要拆解的片段来自于《非暴力沟通》这本书，作者是马歇尔·卢森堡博士，他喜欢全世界到处给人做调停，为促进人类和谐共处做出了突出贡献。这本书解释了我们在和别人说话或者沟通的时候为什么容易出现暴力的情况，并给出了一个非暴力沟通的解决方案，用8个字来概括就是非暴力沟通的四要素：观察-感受-需要-请求。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>今天跟大家分享的这个片段是如何运用非暴力沟通的原则来表达愤怒，下面请各位花1分钟的时间看一下原文片段，看完后请示意我一下。\u003c/p>","ratings_count":2,"texts":[{"id":20962,"quote":"\u003cp>片段来源：《非暴力沟通》[美]马歇尔·卢森堡 著（P159-160）——表达愤怒的四个步骤\u003c/p>\u003cp>表达愤怒的四个步骤 \u003c/p>\u003cp>1. 停下来，深呼吸。 \u003c/p>\u003cp>2. 看看我们有哪些评判性的想法。 \u003c/p>\u003cp>3. 与我们的需要连结。 \u003c/p>\u003cp>4. 表达我们的感受和未被满足的需要。 \u003c/p>\u003cp>来看看充分表达愤怒的具体步骤。首先，停下来，除了深呼吸，什么都别做；不去指责或惩罚他人，只是保持安静。接着，看一看是什么想法让我们生气。例如，无意中听到某人说了一些话，使我们相信自己由于种族的缘故遭到了排斥。感知到自己的怒气时，如果停下来，便会看到头脑中盘旋的想法：“这太不公平了！她这是种族歧视！”我们知道，所有的评判都在用可悲的方式表达未满足的需要。于是，接下来的第3步是：与这些想法背后的需要连结。如果指责某人是种族主义者，我们的需要也许是融合、平等、尊重或者与人连结。 \u003c/p>\u003cp>为了充分表达自己，我们要采取的第4步是开口表达愤怒——怒火此时已被转化为感受和需要。然而，表达此时的感受也许要很大的勇气。对我来说，生气并冲着人们嚷“你这样做是种族歧视”是很容易的，甚至还会感到很畅快。然而，要说出内心深处的感受和需要，却可能令人却步。为了充分表达愤怒，我们也许可以试着和对方说：“你走进房间后，开始与其他人聊天，却没有和我说话。接着，你开始议论有关白人的种种。当注意到这些时，我的胃非常不舒服，我也很害怕。这使我意识到，我非常希望受到平等的对待。我想请你告诉我，听到这些话，你的感受是怎么样的？”\u003c/p>","explains":"\u003cp>好的，我看到大家都已经看完了。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>这个片段是教我们如何正确、有效地表达愤怒，既不压抑自己的情绪，又不会造成激烈的冲突。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>大家想下，我们吵架的时候，是不是因为我们觉得别人做错了，而我们骂了对方或者责怪了对方，然后对方觉得不服或者委屈，才吵起来的。在讨论怎么做之前，我们想跟大家探讨两个问题：\u003c/p>\u003cp>第一个问题：生气的时候能不能不爆出来？请注意，我不是让大家不生气，而是生气的时候我们能不能不骂出来？看到孩子无聊玩手机，约定时间到了，不仅不停还玩得越来越嗨，怒气一下就上来了，张口就要开骂。但是如果这个时候手机响了，一看是领导的电话，这个时候我们会带着怒气接电话？不会吧，一定会是“喂，领导”，而不是“什么事？”这说明情绪来的时候我们是可以不爆出来的，认可吗？\u003c/p>\u003cp>好，第二个问题：我们生气的点在哪里？还是孩子不按约定玩手机的例子，如果我们任由情绪爆发出来，我们会说什么？会不会说“你怎么说话不算数，说好了半小时，一点自控力都没有！就知道玩手机玩手机，也不学习！”我们生气的点就在于这些想法。我们担心玩手机就不想学习，考不上好大学，找不到好工作，那他人生就完了。那我们希望孩子怎么做呢？有节制的玩手机，该学习的时候学习，该运动的时候运动，该找朋友找朋友，有自控力，但是孩子没有做到。\u003c/p>\u003cp>基于这两个共识，第一，生气的时候是可以不爆出来的；第二，我们生气的点在于我们的想法，我们有一些期待没有得到满足。那生气的时候我们应该怎么有效处理呢？\u003c/p>\u003cp>【how】\u003c/p>\u003cp>这个片段就给了一个好用的工具，表达愤怒的四个步骤，我总结了几个关键词在拆页的原文片段下方，帮助大家理解和记忆。\u003c/p>\u003cp>第一， \u003cstrong>积极暂停。\u003c/strong>当我们感觉到自己情绪上来的时候，停一停，想想领导来电话了，做几次深呼吸。\u003c/p>\u003cp>第二， \u003cstrong>辨别想法。\u003c/strong>想一想自己脑海里有哪些想法。\u003c/p>\u003cp>第三， \u003cstrong>了解需要。\u003c/strong>问一问自己有什么需要和期待没有得到满足。\u003c/p>\u003cp>第四， \u003cstrong>表达愤怒。\u003c/strong>说出自己的感受和需求，而不是发泄情绪和指责他人。\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>分享我自己最近一次发怒的经历。上周五晚饭后，我正在收拾厨房，我大儿子自己倒金桔柠檬水喝，一整壶都倒到了桌上，木地板上，我一下就火了，这头还没收拾完，那头又出状况了，我就吼了我大儿子，“你干嘛！搞什么！”。当时我儿子立马就僵住了。用表达愤怒的四个步骤反思一下我的当时的处理过程：\u003c/p>\u003cp>第一， \u003cstrong>积极暂停。\u003c/strong>我可以停一停，先深呼吸三次。\u003c/p>\u003cp>第二， \u003cstrong>辨别想法。\u003c/strong>当时我脑海里有什么想法。“怎么总是这么不小心，这种事情发生不是一次两次了” “一点都不省心，天天干不完的活”“这果汁是甜的，还是木地板，清理很麻烦”。\u003c/p>\u003cp>第三， \u003cstrong>了解需要。\u003c/strong>我是什么需要没有得到满足？我想好好爱自己，不干这么多活。我希望孩子学会小心做事，不要给别人带来麻烦，自己承担后果。我希望好好维护木地板，能多用几年。\u003c/p>\u003cp>第四， \u003cstrong>表达愤怒。\u003c/strong>儿子，妈妈今天已经忙了一天，有点累，不想干这么多活。你这一个不小心，我又要清理了，而且我们家是木地板，被果汁弄到，不好清理还容易把地板弄坏。妈妈现在很生气，因为我希望能够好好爱自己，少干点活，也希望我们的家得到更多的爱护。听到妈妈这么说，你有什么感受？\u003c/p>\u003cp>用这种方式来表达愤怒的好处，首先我的情绪很快得到了平复，同时能让孩子体会别人的感受，不会引起孩子的反抗或者是让孩子感到委屈，还能让孩子学会自己承担后果。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验-拆书家提问设计】\u003c/strong>\u003c/p>\u003cp>现在我想请大家也回忆一下，自己最近一次生气的情景，发生了什么事情，你是什么感受？你是怎么处理的？先在组内分享一下，然后我们找一位小伙伴给大家分享一下。给大家5分钟时间。\u003c/p>\u003cp>\u003cstrong>【A1激活经验-学习者案例】\u003c/strong>\u003c/p>\u003cp>时间到，大家分享完了吧？我们请1位小伙伴来分享一下。有积极主动地伙伴吗？ \u003c/p>\u003cp>学习者案例分享：\u003c/p>\u003cp>\u003cstrong>巧克力：\u003c/strong>可能是性格原因，加上我是东北人，然后在广东待了有五年的时间，我这半个月刚刚来到我们广西，在前期自己的工作当中会有一些压力，就突然来了一个小小的假期呢，可能就会一下子放松了。那这这一个分享呢，就主要是就针对我跟家人的一个小小的案例吧，就是前阵子的时候，因为刚来到广西这边，自己要筹备做一个小小的艺术工作室，因为我之前是一个小学美术老师，可能因为环境的过渡，加上来这的话会有一种无形的压力，就是我希望我尽快进入状态，然后妈妈这边呢，有一些生活方面的琐事，她也会找到我，当然她不知道我白天去干了什么，但是当我晚上回家的时候，如果我没有第一时间去执行她给我的命令和任务的话，因为都是东北妈妈，有点急躁，然后加上我的状态可能也不是很好，大家脸上挂满情绪。就像刚刚我们那个老师说到啊，说表达情绪的时候，先是要表达需求，而不是说先把我们的情绪挂到脸上，这样的是无效的沟通。通过这个小事，加上今天的学习，整体来说我感触颇多，有些时候真的是要先内化自己，冷静下来，不要把情绪先挂到脸上。\u003c/p>\u003cp>\u003cstrong>【A2催化应用-拆书家提问设计】\u003c/strong>\u003c/p>\u003cp>好，感谢我们巧克力的支持和分享。我们说学习学习，怎么样能把知识内化为自己的能力呢？就是要规划应用了，我们拆书学习有一个很重要的环节就是要规划应用。我想请在座的各位把今天学习的这四个表达愤怒的步骤在自己的拆书原文片段的下面，写上未来当你遇到什么情景的时候可以用上这四步表达愤怒的工具去解决，可以设想一下怎么去用。我们在规划应用的时候注意要符合smart原则，也就是要有明确的时限、可观测可衡量的行动目标、具体的步骤和做法，给大家两分钟的时间。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>好，由于时间关系我们今天规划应用的阶段就到这里。最后让我们一起回顾一下今天拆页的内容，表达愤怒的四个步骤，是哪四个步骤啊？积极暂停、辨别想法、了解需要、表达愤怒。希望这个工具能够帮助大家在日常生活当中能够正确处理自己激动的情绪，生气愤怒的情绪，通过和平，非暴力的方式处理我们日常的生活，能够让我们更加从容，人际关系更加和谐！好的，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1698993446000,"updated_at":1700055493000,"ria":true},{"id":16718,"topic":"真诚感谢三步骤 夸到对方心坎里","learn_goal":"","remark":"非暴力沟通表达感谢的方式。通过摆事实、说需求、表感受，将我们的感谢具象化，传递对方做这件事情的价值，还能够让对方感受到你的真诚。","level":"TF2-3","duration":25,"status":19,"type":0,"chaishujia":{"username":"长缨","city":"天津市"},"club":{"name":"天津北洋分舵","city":"天津市"},"prologue":"\u003cp>不破不能立，不拆不成器。大家好，我是长缨，用三个标签介绍一下我自己。\u003c/p>\u003cp>1.一级拆书家\u003c/p>\u003cp>2.AACTP天津培训师Pro俱乐部创会主席\u003c/p>\u003cp>3.医药营销培训师\u003c/p>\u003cp>今天我挑战的2-3会有讨论、演练环节，所以在正式开始之前我们先分一下组（以我为中心前面为第1组，后面为第2组）。\u003c/p>\u003cp>首先我先介绍一下这本书：\u003c/p>\u003cp>F 特征：今天给大家介绍的这本书叫做《非暴力沟通》修订版，这本书在豆瓣有着8.4的高评分，是非常经典的沟通类书籍，在拆书帮目前拆书实录中位居榜首，足见它的受欢迎程度。\u003c/p>\u003cp>A 优点：作者马歇尔·卢森堡是美国威斯康星大学临床心理学博士，也是一名临床心理学专家。相较于其他同主题的书，这本书不仅给出了非暴力沟通的万能公式，对于典型沟通场景还提供了许多实用的建议和案例分析，便于理解应用。\u003c/p>\u003cp>B 利益：（B1）通过阅读这本书，我们可以运用非暴力的沟通方式，降低冲突矛盾发生的频率，使人际关系更加和谐，个人内心更加平和。（B2）今天片段的学习能让我们学会有效的表达感激，对方提供了什么具体的帮助，满足了我们的什么需求，以及带给我们的感受，让对方感到被重视和被尊重、增强彼此的关系。\u003c/p>\u003cp>大家跟随我完成RIA现场学习后，学习者能够在需要正式表达感激之情的场合，清晰的运用“感谢三步法”向对方表达谢意。\u003c/p>","ratings_count":1,"texts":[{"id":20838,"quote":"\u003cp>现在请大家先阅读原文片段，时间是 2 分钟。看完之后抬头示意我一下。\u003c/p>\u003cp>\u003cstrong>原文：\u003c/strong>\u003c/p>\u003cp>在使用非暴力沟通表达感激时，我们会清楚地包含以下三个要素：\u003c/p>\u003cp>・他人做了什么增进了我们的福祉。\u003c/p>\u003cp>・我们有哪些需要因此得到了满足。\u003c/p>\u003cp>・因为这些需要得到了满足，引起了我们什么样的愉悦感受。\u003c/p>\u003cp>表达这三个要素时，并不一定要遵照以上的顺序。有时哪怕是一个微笑或一句简单的“谢谢你”就足以传递这一切。不过，如果我们想要确保对方能够充分收到我们的心意，用语言完整地表达这三个要素是有意义的。在下文的对话中，大家可以看到如何用这三个要素来表达“赞赏”。\u003c/p>\u003cp>学员：（在工作坊结束后来找我）马歇尔，你太棒了！\u003c/p>\u003cp>马歇尔：我好像不太理解你为什么要这么称赞我。\u003c/p>\u003cp>学员：为什么？你的意思是？\u003c/p>\u003cp>马歇尔：人们给过我无数的头衔，但我却完全无法从这些表述中学到什么。我想从你对我的赞赏中有所学习，并且因此感到喜悦，但我需要你再多说一些。\u003c/p>\u003cp>学员：比如说？\u003c/p>\u003cp>马歇尔：首先，我想知道我说了什么或者做了什么让你的生命变得更加美好。\u003c/p>\u003cp>学员：嗯，你很有智慧。\u003c/p>\u003cp>马歇尔：恐怕你刚刚又给了我另一个评判。我依然想知道我做了什么让你的生命更美好。\u003c/p>\u003cp>学员：（思索了一会儿后，她指着自己在工作坊上写下的笔记）看这两处，就是你说的这两点。\u003c/p>\u003cp>马歇尔：噢，所以你赞赏的是我说的这两点？\u003c/p>\u003cp>学员：是的。\u003c/p>\u003cp>马歇尔：接下来，我想要知道这些话带给你的感受。\u003c/p>\u003cp>学员：感到充满希望，并且释然。\u003c/p>\u003cp>马歇尔：那么现在我想知道，我说了这两点满足了你哪些需要。\u003c/p>\u003cp>学员：我一直无法和我18岁的儿子沟通，一直在努力寻找一种更加情意相通的方式和他相处，你说的这两点让我找到了方向。\u003c/p>\u003cp>听到这三个要素的内容（我做了什么，她有何感受以及满足了她哪些需要）后，我就能真正和她一起享受这份赞赏。如果一开始就用非暴力沟通的方式来表达，她可以说：“马歇尔，当你说这两点时（向我展示她的笔记），我感到充满了希望并且释然，因为我一直在寻找方法和儿子连结，你的这些话给了我方向。”\u003c/p>","explains":"\u003cp>看到大家抬头示意我，看来原文已经阅读好了。接下来，咱们一起来拆解这个片段。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>这个片段为我们提供的非暴力沟通表达真诚感谢的方式。通过摆事实、说需求、表感受，将我们的感谢具象化，传递对方做这件事情的价值，还能够让对方感受到你的真诚。\u003c/p>\u003cp>・他人做了什么增进了我们的福祉。\u003c/p>\u003cp>・我们有哪些需要因此得到了满足。\u003c/p>\u003cp>・因为这些需要得到了满足，引起了我们什么样的愉悦感受。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>当我们得到他人非常重要的帮助时，如果只是简单地说声“谢谢”，往往显得不够有诚意。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>如何向对方表达真诚的感激呢？（细化的行动步骤）\u003c/p>\u003cp>第一、说明行为\u003c/p>\u003cp>先说对方帮你做了什么，在描述过程中，不能一带而过，而是要多说细节。我们来对比一下这两句，“靓靓老师帮我看了逐字稿”和“靓靓老师熬夜帮我审阅了50页逐字稿”，后一句对于细节行为的描述传递的能量更强烈。\u003c/p>\u003cp>第二、说明价值\u003c/p>\u003cp>对方做的事情对你而言，有什么重大的影响。比如“这个逐字稿反复修改了7次，还是不能过关，这次多亏了你反复帮我研磨，汇报顺利通过了！”\u003c/p>\u003cp>第三、说明感受\u003c/p>\u003cp>传递给对方有哪些真实的感受，让对方也体会到你的心情。比如“有你在，我总是特别安心。”\u003c/p>\u003cp>三个步骤介绍完了，这里需要注意的是，以上没有先后顺序，从任何一个步骤开始都是可以的。\u003c/p>\u003cp>【常见的异议】\u003c/p>\u003cp>需要这么隆重吗？向对方表达感激说一句“谢谢”不就可以啦，是不是有些啰嗦。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>事实上，我们都体会过在餐厅对端菜给你的服务生说“谢谢”，和对在危难时刻借给你十万块钱的人说“谢谢”，轻重是不一样的。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>当“谢谢”不足以表达对他人的感激或者尊重的时候，可以使用今天学到的感谢三步骤。而在一些公共场合，例如餐厅中服务员上菜、倒水，地铁、公交车上别人起身让座，只要一个点头微笑或者说声‘谢谢’就可以。\u003c/p>\u003cp>【反面例子】\u003c/p>\u003cp>为了方便大家理解，我来分享一个真实的例子。\u003c/p>\u003cp>上个星期我去北京参加培训，中午外出和同学们吃饭的时候，突降倾盆大雨，眼看上课时间就要到了我们都没有带伞，如果此时跑回街对面的教室，一定被浇成落汤鸡，正当我们十分焦急无助的时候，一辆汽车按着喇叭停在了餐厅门口，原来是刘同学，他中午没有外出吃饭，看到时间快到同学们还没有回来，就主动跑去地库开车来接我们，来回接送了 3 趟。事后，我们只说了一句‘谢谢谢谢，现在想起来觉得这样的感谢实在太单薄了！学了感谢三步骤之后，我完全可以这样来表达。\u003c/p>\u003cp>【正面例子】\u003c/p>\u003cp>刘同学，你冒着倾盆大雨，专程跑去地库来回三趟开车接我们（说明行为）。\u003c/p>\u003cp>我们没有挨浇，还提前到达了教室，也没有耽误下午的课程（说明价值）。\u003c/p>\u003cp>真是太感动了，太感谢你了（说明感受）。\u003c/p>","interaction":"\u003cp>我们刚刚学习了如何使用非暴力沟通的三步骤来表达感激，为了让大家更好地理解和掌握新知识，现在我们来做一个演练。\u003c/p>\u003cp>请大家认真倾听演练的场景：\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>任女士的女儿特别喜欢看女子体操，其中有两位体操选手是孩子的偶像，比赛结束后孩子守在体育馆门口期待能得到两位偶像的签名。等了一段时间才发现，这里不是运动员的出入口，估计白等了，不免心里有些失落。这时候一位体操迷小哥哥看到任女士母女两个站在那里干等，就主动跑过来告诉他们母女两个，他也是来要签名的，看到母女俩个等的地方不对，一会儿运动员出来就要不到签名了。于是，母女跟随两个来到正确的运动员出口后，这位体操迷小哥哥还主动找到了工作人员，特别拜托如果两位选手出来，专门提醒一下远道而来的母女两人，别让他们白等。就这样，在他的帮助下，孩子顺利的等到了自己的偶像，不但签了名，体操迷小哥哥帮着用孩子的手机和偶像合影。\u003c/p>\u003cp>任女士和孩子都非常感动，孩子主动走向体操迷小哥哥，想向对方表达内心的感激之情，但又觉得一句“谢谢小哥哥”之类的语言，太单薄了。现在请你帮助孩子运用刚才学到的非暴力沟通的“感谢三步骤”，真诚的感谢小哥哥提供帮助，该怎么说呢？\u003c/p>\u003cp>【指令】\u003c/p>\u003cp>各位小伙伴，场景听清楚了吗？\u003c/p>\u003cp>（1）接下来，现场的两组小伙伴讨论，如果你是这个孩子，运用非暴力沟通“感谢三步骤”表达对这位小哥哥的感谢之情吧。\u003c/p>\u003cp>（2）讨论时间是5分钟，时间一到，我们就停下来请两位伙伴分享。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>\u003cstrong>学习者 1果果：\u003c/strong>\u003c/p>\u003cp>你发现我们走错地方，带我们找到正确的门口，还帮我们拿到了签名并且合影，达成了孩子的心愿，不虚此行，让我们感受到了特别开心幸福。（说明行为）\u003c/p>\u003cp>（拆书家提示）刚才说到了，我们要用什么样的口吻，是以孩子口吻对小哥哥要表达感谢。可以再重新调整一下。\u003c/p>\u003cp>\u003cstrong>学习者 1果果：\u003c/strong>\u003c/p>\u003cp>小哥哥你发现我们站错地方，不但带我们找到正确的门口，还帮我们拿到签名并且合影（说明行动），达成了我的心愿（说明价值）。这一次不虚不虚此行，让我和妈妈感受到特别开心和幸福（说明感受）。\u003c/p>\u003cp>\u003cstrong>学习者 2丁老师：\u003c/strong>\u003c/p>\u003cp>“小哥哥你看刚才我们站错位置，你帮我们指出了我们的位置，同时领着我们找到了正确的地方，而且又嘱托我们的工作人员给我们做了一个提醒，同时也拿这个相机给我们去照相。（说明行为）这一次不光我们要到了签名，而且还留下了合影，这一次真的让我们不光不虚此行，还得到一个额外的收获（说明价值）。这个过程让我们感觉特别的开心幸福，而且还有兴奋（说明感受）。”\u003c/p>\u003cp>\u003cstrong>学习者 3小于老师：\u003c/strong>\u003c/p>\u003cp>小哥哥，本来我跟妈妈两个人在这个地方都等了这么长时间的，然后多亏了有你带着我们，发现我们等的地方不对，然后带着我们走到了正确的地方，然后你还特别贴心的跟负责人说，告诉他去帮助我们去给我们及时的提醒，多亏了你的这句提醒，我们才没有错过运动员出场的重要的时刻，才能够一下子找到他们，而且你还用自己的时间牺牲自己的时间来帮我跟明星合影。（说明行为）\u003c/p>\u003cp>然后我不光是要到了签名，同时我没想到最后还能够跟我最喜欢的两个体操选手，有了这样一张合影，我回家以后还可以跟小伙伴们去吹牛炫耀，我简直就觉得这次出行可以说是除了得到自己想要的这个东西之外，还有一些意外的收获（说明价值），真是不虚此行。我特别的开心，就觉得自己幸福的都要飞起来了。这次经历对我来说特别的难忘，让我觉得非常的满足，非常感谢。（说明感受）\u003c/p>\u003cp>好的，谢谢小于老师，大家觉得说的怎么样？非常棒，其实在整个我们三位小伙伴表达的过程当中，大家都运用了这三个步骤。\u003c/p>\u003cp>\u003cstrong>说明行为\u003c/strong>的时候，每个人都把这个行为描述得非常的清楚，比如说他们找不到出口是吧？立刻带到正确的出口，而且不仅仅帮他们找到正确出口之外，还找到工作人员说帮着看一下，如果运动员出来，马上能够找到。这些都是描述了具体的行为。\u003c/p>\u003cp>还有在\u003cstrong>说明价值这\u003c/strong>一块，大家也表达非常清晰。\u003c/p>\u003cp>对于孩子来说，如果这次合影拿到了，签名拿到了，其实可以在同学面前炫耀，满足了他这个需求，还有他就是好不容易那么大老远来的，冲着签名，这个能够达到他可能心里已经是非常的开心了，非常的欢喜了，所以在这个过程当中价值也说得非常清楚，满足了孩子的需求。\u003c/p>\u003cp>最后也\u003cstrong>表达了自己的感受\u003c/strong>，开心雀跃都要飞起来了，描述得非常的形象。\u003c/p>\u003cp>好的，刚才三位伙伴的分享非常的精彩，今天学到的三个步骤都用到位了，再次感谢各位小伙伴今天的全部内容就分享到这里，最后我们再来回顾一下非暴力沟通的感谢三步骤。\u003c/p>\u003cp>第一个说明行为，说出你观察到对方为了帮助我们做了哪些具体的事情。\u003c/p>\u003cp>第二个是说明价值，我们可以说明一下对方提供给我们的帮助，让我们的哪些需求得到了满足。\u003c/p>\u003cp>第三个是说明感受，来表达一下我们的需求获得满足的时候你的心情。这个时候我们可以通过说明感受表达出来。\u003c/p>\u003cp>好的，本次拆书就到这里，非常感谢大家的参与，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1696693001000,"updated_at":1700032477000,"ria":true},{"id":16693,"topic":"用非暴力沟通表达感激，让生活更美好","learn_goal":"","remark":"用非暴力沟通的方式表达感激","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"向阳花","city":""},"club":{"name":"南宁清澄分舵","city":"南宁"},"prologue":"\u003cp>大家好，我是向阳花，我的性格与我的名字很相似，向阳而生，不畏艰难。\u003c/p>\u003cp>我的工作是一名产品经理，是一位每天跟程序员打交道的女孩子，所以呢我练就了一身怎么程序员沟通的本领。为什么我要加入拆书帮呢？因为我平时也喜欢读书，俗话说，一个人走的快，但是一群人走的更远，我希望跟大家拆书一百年，我养了一只70斤的拉布拉多，有喜欢养狗狗的可以会后多交流。 \u003c/p>","ratings_count":2,"texts":[{"id":20811,"quote":"\u003cp>接下来请大家看一些原文拆页，大概用1分半的时间，看完了示意我一下。\u003c/p>\u003cp>非暴力沟通表达感激的方式包含三个部分：\u003c/p>\u003cp>1.对方做了什么事情使我们的生活/工作得到了改善？\u003c/p>\u003cp>2.我们有哪些需要得到了满足？\u003c/p>\u003cp>3.我们的心情怎么样？\u003c/p>\u003cp>在表达感激时，这三个部分的先后次序并不重要；有时我们甚至可以通过微笑或说声“谢谢”来表达这三个部分。然而，如果我们要确保对方能够明白我们的意思，那么，用语言具体地描述这三个部分是值得的。\u003c/p>\u003cp>参加者：（在研讨班结束以后走近我）马歇尔，你真了不起！\u003c/p>\u003cp>马歇尔：我想知道为什么你这么说？\u003c/p>\u003cp>参加者：为什么呢？\u003c/p>\u003cp>马歇尔：在我的一生中，人们用各种各样的话来评价我，这对我并没有多大帮助，我需要更多的信息来理解你的评价。\u003c/p>\u003cp>参加者：什么样的信息？\u003c/p>\u003cp>马歇尔：首先，我想知道，我做了什么，你认为对你的生活有多大帮助？\u003c/p>\u003cp>参加者：哦，你聪明过人。\u003c/p>\u003cp>马歇尔：也许这又是一个评价，但我还是不清楚我做了什么对你有益的事？\u003c/p>\u003cp>他想了想，然后拿出笔记本，指着其中的两段话说：就这2点， 你今天在研讨班中提到了他们。\u003c/p>\u003cp>马歇尔：哦，你很欣赏这两点\u003c/p>\u003cp>参加者：是的。\u003c/p>\u003cp>马歇尔：听到这2 个观点时，你的心情怎么样？\u003c/p>\u003cp>参加者：我感到一阵轻松，对将来更有信心了。\u003c/p>\u003cp>马歇尔：现在，我想知道，这两个观点使你的什么样的需要得到了满足？\u003c/p>\u003cp>参加者：我没法和儿子沟通，他今年18岁了，我一直盼着能有办法和他沟通，你今天的这2个观点给了我很大启发。\u003c/p>\u003cp>这样，我就知道了我所做的事情，她的感受以及她的需要，我很高兴自己帮到了她。如果她一开始就能以非暴力沟通的方式表达感激，她也许会说，马歇尔，当你提到这2个观点时，我很欣喜，感到将来有盼头了，我一直在寻找和儿子沟通的办法，这2个观点给我很大启发\u003c/p>","explains":"\u003cp>what：\u003c/p>\u003cp>用非暴力沟通的方式表达感激时，应该从具体事件、收获，心情入手\u003c/p>\u003cp>why：作者最后举的例子，更加的说明了我们在感激他人的时候，如果使用用非暴力沟通的方式表达感激，可以让对方更加好的理解我们的感受。\u003c/p>\u003cp>how：\u003c/p>\u003cp>第一步：\u003c/p>\u003cp>1.对方做了什么事情使我们的生活/工作得到了改善？\u003c/p>\u003cp>对方做了什么事情，在什么背景下发生的事情？\u003c/p>\u003cp>比如：在生活中，妈妈会将我换洗的衣服整理熨平。\u003c/p>\u003cp>第二步：\u003c/p>\u003cp>2.我们有哪些需要得到了满足；\u003c/p>\u003cp>比如：为我第二天重要的会议做准备。\u003c/p>\u003cp>第三步：\u003c/p>\u003cp>3.我们的心情是怎样的？\u003c/p>\u003cp>表达我们的感受，比如：很开心，很幸福，有个体贴细心的妈妈\u003c/p>\u003cp>Were\u003c/p>\u003cp>可以使用在哪些方面呢？比如：亲子关系、夫妻关系、朋友关系、职场关系\u003c/p>","interaction":"\u003cp>【A1联系具体经验】\u003c/p>\u003cp>接下来我讲述一个发上在我身上的故事\u003c/p>\u003cp>1）时间：一次训练营上\u003c/p>\u003cp>2）人物：我和我的同学\u003c/p>\u003cp>3）地点：无\u003c/p>\u003cp>4）起因：自己缺了一次课程，录播课很粗糙的听了一次，做练习的时候不知道怎么下笔。\u003c/p>\u003cp>5）经过：听完了录播课，按照自己的理解去做了作业，但是做到中途发现了自己遇到了卡点，又不好意思问老师，于是寻求了A同学的帮助，A同学认真的看了我的作业，并且重新给我总结了那节课的重点，还把她的笔记分享给我。\u003c/p>\u003cp>6）结果：作业完成了，该次课程也没有留下什么疑惑点，事后我也向该同学说了，谢谢\u003c/p>\u003cp>反思：\u003c/p>\u003cp>1.我心里其实是很感激A同学的帮助，但是我只是轻描淡写的说了句“谢谢”，没有陈述出具体的事情\u003c/p>\u003cp>2.也没有告诉因为她对我该作业帮助给我带来的帮助\u003c/p>\u003cp>3.虽然他解决了对课程的理解程度，作业的准确度需求\u003c/p>\u003cp>4.也没有告诉她我因为这个事情很开心。\u003cbr>\u003c/p>\u003cp>【A2具体应用】\u003cbr>A2根据今天学习的表达感激三部曲进行感谢，接下来我的目标是：本周内，找到帮助我的同事再次认真感谢她。\u003c/p>\u003cp>1 ：描述事件：这里表述要具体，对方都干了啥事，这件事情使你的生活得到了感受，在感谢时，清晰地表达你的这一观察结果。\u003c/p>\u003cp>2：强调结果：说出这样的行为发生之后，让你的哪些需求得到了满足。\u003c/p>\u003cp>3：表达情绪：描述下你的心情和感受来表达感谢\u003cbr>\u003cbr>最后总结一下今天的拆书，我们学习了表达感谢三部曲，通过改变我们的沟通方式让我们有效沟通从而建立和谐的关系。我今天的分享就到此结束了，希望这个片段会对各位小伙伴有帮助。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1695693553000,"updated_at":1697426690000,"ria":true},{"id":16508,"topic":"充分发达愤怒四步法","learn_goal":"","remark":"生气时，指责和惩罚他人都无法真正传达我们的心声；想要充分表达愤怒，先要把注意力放在自己的感受和需求上，这样更有可能让自己的需求得到满足。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"谢娜洁","city":"镇江市"},"club":{"name":"镇江西津分舵","city":"镇江"},"prologue":"\u003cp>\u003cstrong>一、自我介绍1分钟\u003c/strong>\u003c/p>\u003cp>大家好，我是绿雪，是一名教师。我的三个标签：第1个标签是学习爱好者。我是一个好奇宝宝，喜欢一切新鲜事物，不停的学习是为了探索自己，成长自己，并跟上时代的步伐。第2个标签是运动践行者。运动让我有健康的身体，有蓬勃的朝气，有强壮的体魄。我现在每天晚上几乎都会进行运动。目前喜欢的运动是跳操和瑜伽。跳操能燃烧我的卡路里，瑜伽能使我的身心合一。第3个标签是新晋拆书家。\u003c/p>\u003cp>点评：\u003c/p>\u003cp>逐字稿：\u003c/p>\u003cp>\u003cstrong>二、拆书和拆书帮介绍2分钟\u003c/strong>\u003c/p>\u003cp>拆书是一种学习方法论。它的中心是学习者而不是知识，它的目标是提升能力、解决问题，它的方法是把知识关联经验，转化成具体行动。拆书分为个人学习和组织学习。个人学习通常用RIA便签法进行，让人读一本书就能达到参加同主题培训的效果。组织学习的应用就是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。拆书帮是一群学习爱好者的社群，他们目标就是通过学习能解决自身存在问题，突破自我。它的价值观是陪伴赋能、拆为己用，持续精进，反求诸己，共同成长，它的愿景是帮助学习者升级学习力及促进他人学习的能力，能影响身边的人，让世界变得更好。\u003c/p>\u003cp>\u003cstrong>三、阅读原书拆页\u003c/strong>\u003c/p>\u003cp>大家在日常生活中应该会有极度生气或者发怒的时候，不知道你们怎么处理？是一个人生闷气还是直接爆发出来对对方大吼大叫？你觉得这两种方法能很好的处理事情吗？不能，那怎样才能够较好的表达此刻的情绪？今天《非暴力沟通》这本书中的表达愤怒的四个步骤可以告诉我们方法。阅读原文P159-P160。\u003c/p>\u003cp>主题《表达愤怒的四个步骤》\u003c/p>","ratings_count":1,"texts":[{"id":20620,"quote":"\u003cp>停下来，深呼吸。\u003c/p>\u003cp>看看我们有哪些评判性的想法。\u003c/p>\u003cp>与我们的需要连结。\u003c/p>\u003cp>表达我们的感受和未被满足的需要。\u003c/p>\u003cp>来看看充分表达愤怒的具体步骤。首先，停下来，除了深呼吸，什么都别做:不去指责或惩罚他人，只是保持安静。接着，看一看是什么想法让我们生气。例如，无意中听到某人说了一些话， 使我们相信自己由于种族的缘故遭到了排斥。感知到自己的怒气时，如果停下来，便会看到头脑中盘旋的想法:“这太不公平了!她这是种族歧视!”我们知道，所有的评判都在用可悲的方式表达未满足的需要。于是，接下来的第3步是:与这些想法背后的需要连结。如果指责某人是种族主义者，我们的需要也许是融合、平等、尊重或者与人连结。\u003c/p>\u003cp> 为了充分表达自己，我们要采取的第4步是开口表达愤怒——怒火此时已被转化为感受和需要。然而，表达此时的感受也许要很大的勇气。对我来说，生气并冲着人们嚷“你这样做是种族歧视”是很容易的，甚至还会感到很畅快。然而，要说出内心深处的感受和需要，却可能令人却步。为了充分表达愤怒，我们也许可以试着和对方说:“你走进房间后，开始与其他人聊天，却没有和我说话。接着，你开始议论有关白人的种种。当注意到这些时，我的胃非常不舒服，我也很害怕。这使我意识到，我非常希望受到平等的对待。我想请你告诉我，听到这些话，你的感受是怎么样的?\u003c/p>","explains":"\u003cp>\u003cstrong>四、分享I便签\u003c/strong>\u003c/p>\u003cp>（What） 这个拆页讲述了表达愤怒的方法，它有四个步骤，使用这个步骤可以最大限度的避免当事人情绪冲动，用自己的内心需求代替指责对方，从而回归问题本身去思考问题，去处理问题。\u003c/p>\u003cp>（Why） 为什么要学习这个方法呢？因为当别人的言行引发我们愤怒时，我们的习惯思维是，“我很生气，是因为他人做了什么”的想法，我们便会指责或惩罚他人。其实，别人的言行会引发这种感受，但不是根本原因。如果我们转化思维，从自己出发，分析自己为什么会愤怒，自己的内心需求是什么，这时怒火就转变成需求的说明了，也就是把前面那句话换成“我很生气，是因为我需要......”，在沟通的时候对方就会愿意听我们的诉求，我们的需求得到实现，怒火也因此被表达出来了。\u003c/p>\u003cp>（How） 如何表达愤怒呢？它给了四个详细步骤：一停下来，深呼吸。二看想法，就是看看自己是不是想对对方进行评判了，三连需求。就是连接到自己的内心需求，自己内心有哪些需求对方没有满足，四去表达是指从自己出发，去表达自己的需求。可以简单的概括为“一停二看三连四表”。\u003c/p>\u003cp>（Where ） 愤怒指自己的需求不能实现或不能达到目的的一种情绪反应，现在还表现在对他人的遭遇，甚至与自己无关事项的极度反感，都可能引发这种情绪；所以每个人都会生气，所以对象是社会群体的人，应用在各种场合。学会了这个方法，在协调工作，在家庭沟通，在社会性活动当中都会变得顺畅。\u003c/p>","interaction":"\u003cp>\u003cstrong>五、分享A1便签\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享一个故事《我让孩子做试卷》\u003c/strong>\u003c/p>\u003cp>我记得是快期末考试了的一个周末，，我从我校拿一套数学复习试卷回家想让他做，在码好了他做完自己的作业之后还有时间的，于是告诉他吃饭之前做好，我便兴高采烈地去买菜做饭了。喊他吃饭时，我问他试卷做好了没有，他回答我没做。我当时火一下子窜上来了，甩出几句话：是不是不想考好，是不是想偷懒？我儿子嗖的一下子站起来，啪的一声拍着桌子说：就是不想考好！就是懒！我抬头看着他愤怒的眼神，觉得不能再说下去了，于是强压自己的怒火。火是压下去了，但自己内心特别不舒服，自己的问题似乎没有解决。现在学到表达愤怒的方法和步骤，我就可以这样做了：当听到他说没做时，一停，先停下来，深呼一口气，二看，看自己是不是在评判他不求上进，懒，如果有，赶紧停止。三连，连接我的内心需求就是想让他多做一套试卷，多巩固知识，这样期末考试考得好点，四表，最后开口表达的时候，用平缓的语气对他说：“今天周末，你做完了学校作业，我以为你会有多余的时间，在你有时间的情况下多做一套试卷，是想让你多复习巩固知识，这样期末考试就更从容些，说不定考得更好些。”孩子就会接受我这个建议，多做一套试卷。\u003c/p>\u003cp>点评：\u003c/p>\u003cp>\u003cstrong>六、分享A2 便签\u003c/strong>\u003c/p>\u003cp>生活当中，上述类似的场景很多，不尽人意的地方很多，想发火的时刻也很多，那么你用这种“一停二看三连四表”的方法可以去处理这些事情，如果不能直接达到你想要的效果，降低愤怒的频次，也是一种效果。比如一周发火5、6次降低到2、3次。接下来就运用今天学到的表达愤怒的方法，设定目标是：降低愤怒的频次。行动计划是在一个月刻意练习表达愤怒。具体行动是1、每天起床说出表达愤怒的四个步骤。2、每天用这种方法刻意练习表达愤怒1次。\u003c/p>\u003cp>\u003cstrong>七、总结\u003c/strong>\u003c/p>\u003cp>最后总结一下今天的拆书，表达愤怒的四步法，一停(停下来深呼吸)二看(看看有没有评判性的想法)三连(连接愤怒背后的需求)四表(开口去表达未被满足的需求或感受)。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1693184922000,"updated_at":1693703501000,"ria":true},{"id":16428,"topic":"真诚感谢三步骤 夸到对方心坎里","learn_goal":"","remark":"非暴力沟通表达感谢的方式。通过摆事实、说需求、表感受，将我们的感谢具象化，传递对方做这件事情的价值，还能够让对方感受到你的真诚。","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"长缨","city":"天津市"},"club":{"name":"天津北洋分舵","city":"天津市"},"prologue":"\u003cp>开场：\u003cbr>不破不能立，不拆不成器。大家好，我是长缨，用三个标签介绍一下我自己。\u003cbr>1.一级拆书家\u003cbr>2.AACTP天津培训师Pro俱乐部创会主席\u003cbr>3.商业培训师\u003cbr>今天我挑战的2-3会有讨论、演练环节，所以在正式开始之前我们先分一下组（以我为中心左边为第1组，右边为第2组）。\u003cbr>\u003cbr>首先我先介绍一下这本书：\u003cbr>\u003cbr>【F 特征】\u003cbr>今天给大家介绍的这本书叫做《非暴力沟通》修订版，这本书在豆瓣有着8.4的高评分，是非常经典的沟通类书籍，在拆书帮目前拆书实录中位居榜首，足见它的受欢迎程度。\u003cbr>\u003cbr>【A 优点】\u003cbr>作者马歇尔·卢森堡是美国威斯康星大学临床心理学博士，也是一名临床心理学专家。相较于其他同主题的书，这本书不仅给出了非暴力沟通的万能公式，对于典型沟通场景还提供了许多实用的建议和案例分析，便于理解应用。\u003cbr>\u003cbr>【B 利益】\u003cbr>（B1）通过阅读这本书，我们可以运用非暴力的沟通方式，降低冲突矛盾发生的频率，使人际关系更加和谐，个人内心更加平和。（B2）今天片段的学习能让我们学会有效的表达感激，对方提供了什么具体的帮助，满足了我们的什么需求，以及带给我们的感受，让对方感到被重视和被尊重、增强彼此的关系。\u003cbr>\u003cbr>【学习目标】\u003cbr>大家跟随我完成RIA现场学习后，学习者能够在需要正式表达感激之情的场合，清晰的运用“感谢三步法”向对方表达谢意。\u003c/p>","ratings_count":0,"texts":[{"id":20554,"quote":"\u003cp>在使用非暴力沟通表达感激时，我们会清楚地包含以下三个要素：\u003c/p>\u003cp>・他人做了什么增进了我们的福祉。\u003c/p>\u003cp>・我们有哪些需要因此得到了满足。\u003c/p>\u003cp>・因为这些需要得到了满足，引起了我们什么样的愉悦感受。\u003c/p>\u003cp>表达这三个要素时，并不一定要遵照以上的顺序。有时哪怕是一个微笑或一句简单的“谢谢你”就足以传递这一切。不过，如果我们想要确保对方能够充分收到我们的心意，用语言完整地表达这三个要素是有意义的。在下文的对话中，大家可以看到如何用这三个要素来表达“赞赏”。\u003c/p>\u003cp>学员：（在工作坊结束后来找我）马歇尔，你太棒了！\u003c/p>\u003cp>马歇尔：我好像不太理解你为什么要这么称赞我。\u003c/p>\u003cp>学员：为什么？你的意思是？\u003c/p>\u003cp>马歇尔：人们给过我无数的头衔，但我却完全无法从这些表述中学到什么。我想从你对我的赞赏中有所学习，并且因此感到喜悦，但我需要你再多说一些。\u003c/p>\u003cp>学员：比如说？\u003c/p>\u003cp>马歇尔：首先，我想知道我说了什么或者做了什么让你的生命变得更加美好。\u003c/p>\u003cp>学员：嗯，你很有智慧。\u003c/p>\u003cp>马歇尔：恐怕你刚刚又给了我另一个评判。我依然想知道我做了什么让你的生命更美好。\u003c/p>\u003cp>学员：（思索了一会儿后，她指着自己在工作坊上写下的笔记）看这两处，就是你说的这两点。\u003c/p>\u003cp>马歇尔：噢，所以你赞赏的是我说的这两点？\u003c/p>\u003cp>学员：是的。\u003c/p>\u003cp>马歇尔：接下来，我想要知道这些话带给你的感受。\u003c/p>\u003cp>学员：感到充满希望，并且释然。\u003c/p>\u003cp>马歇尔：那么现在我想知道，我说了这两点满足了你哪些需要。\u003c/p>\u003cp>学员：我一直无法和我18岁的儿子沟通，一直在努力寻找一种更加情意相通的方式和他相处，你说的这两点让我找到了方向。\u003c/p>\u003cp>听到这三个要素的内容（我做了什么，她有何感受以及满足了她哪些需要）后，我就能真正和她一起享受这份赞赏。如果一开始就用非暴力沟通的方式来表达，她可以说：“马歇尔，当你说这两点时（向我展示她的笔记），我感到充满了希望并且释然，因为我一直在寻找方法和儿子连结，你的这些话给了我方向。”\u003c/p>","explains":"\u003cp>看到大家抬头示意我，代表原文已经阅读好了。我们来拆解这个片段。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>当我们得到他人的帮助时，我们通常只是简单地说声“谢谢”，往往显得不够有诚意。\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>这个片段为我们提供的非暴力沟通表达感谢的方式。通过摆事实、说需求、表感受，将我们的感谢具象化，传递对方做这件事情的价值，还能够让对方感受到你的真诚。\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003c/p>\u003cp>如何向对方表达真诚的感激呢？（细化的行动步骤）\u003c/p>\u003cp>\u003cstrong>一、摆事实\u003c/strong>\u003c/p>\u003cp>说出你观察到对方为了帮助我们，做了哪些具体的事情。\u003c/p>\u003cp>比如：对方的哪一个观点、行为、或者表情给与了我们帮助。\u003c/p>\u003cp>在原文中，学员在刚开始与米歇尔教授的反馈中说到，“你真了不起”，给出的是‘评价’不是‘事实’。\u003c/p>\u003cp>如何区分评价和事实？事实是指我们看到的、听到的真实发生的情况。原文中，学员提到马歇尔讲课是说到的‘两个观点’，这就是事实。\u003c/p>\u003cp>评价是加工过的事实，代入了个人的主观评判，比如原文中“你真了不起”“你聪明过人”就是学员对马歇尔的主观评论。\u003c/p>\u003cp>\u003cstrong>二、说需求\u003c/strong>\u003c/p>\u003cp>说出对方提供的帮助让你的哪些需求得到了满足？比如：\u003c/p>\u003cp>1 生理需求，就像吃喝拉撒睡，这些生存最基本的需求。像我们前段时间大家看到，因为下暴雨被困在路上的一列火车，本来他应该一个小时之后到达北京，但实际上被困了30个小时，那时候车厢当中好多莫素不相识的人把自己的吃的给了其他的人和孩子，所以那个时候就是让对方能够先吃饱，至少满足了对方生存的基本需求，这是一个需求。\u003c/p>\u003cp>2 安全需求，也就是对安全稳定、免受惊吓等外部环境的需求。就是给对方一个相对稳定免受惊吓的这种外部环境，比如说在外面找不到住的地方了，然后有个人愿意提供住宿让你住到他们家里面，我觉得让你至少不会露宿街头，给你一个安全的需求。\u003c/p>\u003cp>3 爱和归属需求，渴望得到友情、爱情、亲情等情感需求。\u003c/p>\u003cp>4 尊重需求，自尊心被满足，希望别人认可的需求。\u003c/p>\u003cp>5 自我实现需求，成为自己能够成为的那个人。\u003c/p>\u003cp>比如原文对话中，儿子认同母亲并主动与母亲沟通，这位学员获得了被孩子尊重认可的需求。\u003c/p>\u003cp>\u003cstrong>三、表感受\u003c/strong>\u003c/p>\u003cp>表达我们的需求获得满足或者问题得到解决时，给到对方正向、积极的评价。\u003c/p>\u003cp>比如原文中说“我很欣喜，感到将来有盼头”，这就是正向的感受。\u003c/p>\u003cp>三个步骤介绍完了，这里需要注意的是，以上没有先后顺序，从任何一个步骤开始都是可以的。\u003c/p>\u003cp>\u003cstrong>【常见的异议】\u003c/strong>\u003c/p>\u003cp>你也许会说，比起‘谢谢’这个是不是有些啰嗦了。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>当‘谢谢’不足以表达对对方的感激之情时，可以通过留心观察细节，表达哪些需求获得了满足，以及内心的真实感受，这样，也让对方也能看到价值，获得喜悦之情。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp>当“谢谢”不足以表达对他人的感激或者尊重的时候，可以使用今天学到的感谢三步骤。而在一些公共场合，例如餐厅中服务员上菜、倒水，地铁、公交车上别人起身让座，只要一个点头微笑或者说声‘谢谢’就可以。\u003c/p>\u003cp>\u003cstrong>【反面例子】\u003c/strong>\u003c/p>\u003cp>为了方便大家理解，我来分享一个真实的例子。\u003c/p>\u003cp>上个星期我去北京参加培训，中午外出和同学们吃饭的时候，突降倾盆大雨，眼看上课时间就要到了，如果此时跑回街对面的教室，一定被浇得浑身湿透，正当我们十分焦急无助的时候，一辆汽车按着喇叭停在了餐厅门口，原来是刘同学，他中午没有外出吃饭，看到时间快到同学们还没有回来，就主动跑去地库开车来接我们，来回接送了 3 趟，就这样我们不但没有被淋湿，还在开始上课之前赶到了教室。事后，我们只说了一句‘谢谢，现在想起来觉得这样的感谢实在太单薄了！学了感谢三步骤之后，我完全可以这样来表达。\u003c/p>\u003cp>\u003cstrong>【正面例子】\u003c/strong>\u003c/p>\u003cp>刘同学，中午你冒着倾盆大雨开车来接我们大家（摆事实）。\u003c/p>\u003cp>我们特别惊喜又感动（表感受）。\u003c/p>\u003cp>有你的帮忙，我们没有挨浇，而且还提前到达了教室，没有耽误下午的课程，太感谢你了！（说需求）。\u003c/p>","interaction":"\u003cp>我们刚刚学习了如何使用非暴力沟通的三步骤来表达感激，为了让大家更好地理解和掌握新知识，现在我们来做一个演练。\u003c/p>\u003cp>请大家认真倾听演练的场景：\u003c/p>\u003cp>\u003cstrong>【场景设计】\u003c/strong>\u003c/p>\u003cp>任女士的女儿特别喜欢看女子体操，其中有两位体操选手是孩子的偶像，比赛结束后孩子守在体育馆门口期待能得到两位偶像的签名。等了一段时间才发现，这里不是运动员的出入口，估计白等了，不免心里有些失落。这时候一位体操迷小哥哥看到任女士母女两个站在那里干等，就主动跑过来告诉他们母女两个，他也是来要签名的，看到母女俩个等的地方不对，一会儿运动员出来就要不到签名了。于是，母女跟随两个来到正确的运动员出口后，这位体操迷小哥哥还主动找到了工作人员，特别拜托如果两位选手出来，专门提醒一下远道而来的母女两人，别让他们白等。就这样，在他的帮助下，孩子顺利的等到了自己的偶像，不但签了名，体操迷小哥哥帮着用孩子的手机和偶像合影。\u003c/p>\u003cp>任女士和孩子都非常感动，孩子主动走向体操迷小哥哥，想向对方表达内心的感激之情，但又觉得一句“谢谢小哥哥”之类的语言，太单薄了。现在请你帮助孩子运用刚才学到的非暴力沟通的“感谢三步骤”，真诚的感谢小哥哥提供帮助，该怎么说呢？\u003c/p>\u003cp>\u003cstrong>【指令】\u003c/strong>\u003c/p>\u003cp>各位小伙伴，场景听清楚了吗？\u003c/p>\u003cp>（1）接下来，现场的两组小伙伴讨论，如果你是这个孩子，运用非暴力沟通“感谢三步骤”表达对这位小哥哥的感谢之情吧。\u003c/p>\u003cp>（2）讨论时间是5分钟，时间一到，我们就停下来请 2 位伙伴分享。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>\u003cstrong>学习者 1思思：\u003c/strong>\u003c/p>\u003cp>我会感谢他，我会这么说，我跑大老远过来就是想得到就是喜欢的这两位体操选手的签名，然后先说的需求（说需求），然后感谢你刚才站错位置，感谢你引导我到正确的正确的位置出口，然后拿到了签名还帮我去合照（摆事实），简直太高兴太感动了，完成了我的一大心愿，我现在太激动了（表感受）。\u003c/p>\u003cp>\u003cstrong>学习者 2刘钰：\u003c/strong>\u003c/p>\u003cp>我可能会去先跟他去陈述一下：非常感谢你能够把我从错误的出口然后带到了正确的出口（摆事实），然后我从不太抱希望到你给了我一个新的希望（说需求），不但获得了偶像的签名，并且还能够跟他进行了合影（摆事实），我真的非常激动非常感谢（表感受）。\u003c/p>\u003cp>\u003cstrong>学习者 3Gary：\u003c/strong>\u003c/p>\u003cp>我说：大哥你帮我找到了一个正确的出口，又拜托工作人员照顾我，又帮我拍照。（摆事实）这细节满满的。要不是你我们大老远的就白来一趟，会非常的失落，正是因为你我才可以和偶像合影，满足了多年的夙愿（说需求），我真是太激动太感谢了（表感受）。\u003c/p>\u003cp>感谢我们三位非常精彩的表达，让我都感觉这小哥哥做的实在是太到位了，是不是？而且大家把今天所学到三个步骤都用到位了。最后我们再一块回顾一下今天咱们学的非暴力沟通“感谢的这三个步骤”：\u003c/p>\u003cp>第一个摆事实，说出你观察到对方为了帮助我们做了哪些具体的事情，要说细节。\u003c/p>\u003cp>第二个就是说需求就对方提供的帮助，让我们的哪些需求获得了满足，无论是心理上的或者是身体上的都可以。\u003c/p>\u003cp>第三个就是表达一下我们的感受，我们在获得帮助的时候或者问题得到解决的时候，我们要表达自己的感激之情，而且是正向的那种。\u003c/p>\u003cp>好的，再次感谢各位伙伴今天在拆书过程当中的精彩表现，这次拆书也到此结束了，感谢大家的积极参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1692322529000,"updated_at":1692322544000,"ria":true},{"id":16217,"topic":"非暴力沟通四要素","learn_goal":"","remark":"通过观察、感受、需要以及请求这四个要素帮助我们更加清晰的表达自己，使彼此之间的关系更加融洽。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"汤小敏","city":"镇江市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>Hello,大家好，我是汤敏，是今天TF2-2拆书家。用三个标签介绍我自已，第一我是地产公司的从业者，第二我植物美肌护肤英树护肤品牌的官方经销者，第三我是一级拆书家拆书法追随者。\u003c/p>\u003cp>因为今天会有讨论的环节，为了方便讨论，现在我们先进行分组,以3人为1组，其中某某老师、某某老师、某某老师3人为1组，某某老师、某某老师与某某老师3人，为1组，主要分成2组。\u003c/p>\u003cp>今晚学习的主题是通过非暴力沟通四要素：观察、感受、需要和请求帮助我们更加清晰的表达自己，让彼此之间的关系更融洽，从而达到让彼此双方都能发自内心的相互给予。\u003c/p>\u003cp>【F 】\u003c/p>\u003cp>今天的拆页来源于《非暴力沟通》这本书，作者是美国心理学家马歇尔·卢森堡博士，由华夏出版社于2021年5月在北京发行第2版，全书分为14章节，约19万字，从日常沟通语言、不带评论的观察、描述自已的心情、感受，甚至是愤怒，化解冲突，解放自我，协助他人、表达感激与赞赏等多方面阐述非暴力沟通的意义、方法与价值。\u003c/p>\u003cp>【A】\u003c/p>\u003cp>该书豆瓣评分8.4分，跟同类沟通的书籍不同，不是教你各种场景下的话术，而是从专业的心理学角度告诉你，如何去体会对方和表达自己真实的情感和需求，于2006年荣获地球村基金会颁发的和平之桥奖，非暴力沟通也被理解为“一种生命的语言”，“非暴力沟通”方式也被称为“爱的语言“，深受广大读者喜爱与追捧。\u003c/p>\u003cp>【B1】\u003c/p>\u003cp>通过阅读《非暴力沟通》这本书，会有什么好处呢？\u003c/p>\u003cp>一可改变“惯有的、自动化的”思维模式； \u003c/p>\u003cp>二可改变看待、回应周遭人、事、物的方式； \u003c/p>\u003cp>三可改变我们与己、与人的关系，使我们的生活、生命体验更美好。\u003c/p>\u003cp>【B2】\u003c/p>\u003cp>今天我们学习的拆页是非暴力沟通四要素，通过观察、感受、需要、请求清晰完整的表达自己，从而达到让双方都能发自内心的相互给予。\u003c/p>\u003cp>现在请大家跟我一起来践行拆书法，请阅读我刚才分发给大家的拆页，给大家1分钟，读完的伙伴请举手示意一下。  \u003c/p>","ratings_count":2,"texts":[{"id":20305,"quote":"\u003cp>《非暴力沟通》（修订版）P007-008\u003c/p>\u003cp>要达到让双方都能发自内心地相互给予，我们需将注意力聚焦在四个方面——它们是非暴力沟通模式的四个要素。\u003c/p>\u003cp>首先，我们观察实际上发生了什么。不论他人的言行是否有益于我们，我们只是去观察。要做到清晰表达所观察到的，我们的挑战在于不夹杂任何评判。不论喜欢与否，我们只是说出人们做了什么。第二步，表达出我们看到这些行为时的感受：是感到伤心、害怕、喜悦、有趣，还是心烦呢？第三步，表达出我们的感受与什么需要相关联。通过对这三个要素的觉察，我们清晰和诚实地表达出自己的状态。\u003c/p>\u003cp>例如，一位母亲想和正值青春期的儿子用非暴力沟通的方式来说话，她可以这样来表达以上三个要素：“菲利克斯，看到咖啡桌下的两团脏袜子和电视机旁边的三团脏袜子，我很生气，因为我希望在我们共用的空间里能多些整洁。”\u003c/p>\u003cp>紧接着，她可以表达非暴力沟通的第四个要素——一个具体的请求：“你愿意把你的袜子放在你房间或放进洗衣机里吗？”我们借助这个要素提出对他人的期许，希望他（她）怎么做来满足我们的需要，让我们的生命更加美好。\u003c/p>\u003cp>非暴力沟通的一部分是对这四个要素的清晰表达，表达的形式也不拘泥于语言。而另一部分则是从对方的表达中了解这四个要素。我们通过感知对方此刻的观察、感受和需要，与他们建立连结，进而聆听他们的请求，来找到通过什么方式让他们的生命变得更丰富。\u003c/p>","explains":"\u003cp>WHAT\u003c/p>\u003cp>好，我看到大家都读完了，这段拆页讲了什么呢？\u003c/p>\u003cp>这段拆页片段告诉我们如何通过非暴力沟通模式四要素观察、感受、需要、请求来清晰明确的表达自己，从而实现良性互动，避免互相伤害，使得彼此之间的关系更为融洽。\u003c/p>\u003cp>WHY\u003c/p>\u003cp>这样表达有什么好处呢？\u003c/p>\u003cp>一来可以使自己的需求得到满足，同时也会让对方心甘情愿的来满足你提的需求。\u003c/p>\u003cp>二来，可以增进彼此的感情，让彼此之间相处起来更和谐融洽。\u003c/p>\u003cp>否则，不但导致自己的需求没有被满足，反而使彼此之间的关系变得更为紧张，长此以往这样的沟通方式，会让自己的心情变的糟糕，毫无幸福感可言。\u003c/p>\u003cp>\u003cstrong>反例：\u003c/strong>\u003c/p>\u003cp>日常，我们家吃完晚餐后，我与先生一起会把家里的卫生搞一遍，默认的都是我洗碗刷锅擦油烟机，他扫地拖地，可是，昨天，我搞好厨房了，出来发现先生把地扫完已经躺在沙发刷手机了，我便会气不打一出来，一个白眼翻过去，指责道“地都还没拖好，你怎么躺那玩手机了啊？别玩了，起来把地拖了”先生爱答不理，阴阳怪气的来一句：“你就是看不得我闲着！”我便更生气了，朝他吼道“我也上了一天班啊？难道我不累吗？你宁可躺着玩也要留给我做？我也不想拖，都别弄了吧！”。地没人拖，我还一晚上不开心。\u003c/p>\u003cp>通过今晚非暴力沟通四要素的学习，我总结出以下四个步骤来做：\u003c/p>\u003cp>HOW\u003c/p>\u003cp>第一、摆事实（观察）。不进行主观评判、客观描述具体的行为动作。\u003c/p>\u003cp>第二、谈感受（感受）。基于自己的观察，用情绪类词汇描述自己的感受。\u003c/p>\u003cp>第三、讲需要（需要）。明确自己与人交谈的目标。\u003c/p>\u003cp>第四、提请求（请求）。指令清晰，要用肯定的句式说出对方具体要怎样做。\u003c/p>\u003cp>\u003cstrong>反例变正例：\u003c/strong>\u003c/p>\u003cp>在意识到我跟先生的沟通带有指责以及攻击性表达的时候，我尝试着做如下的调整：\u003c/p>\u003cp>1、摆事实。先生已经把地扫完了，但地还没有拖，而且躺那玩手机！！\u003c/p>\u003cp>2、谈感受。我看到地没拖，你躺那玩着玩手机，我挺生气的。\u003c/p>\u003cp>3、讲需要。今天我工作不开心，我也不想拖地，而且我想等搞完卫生全家一起下楼散个步。\u003c/p>\u003cp>4、提请求。所以，老公，你这么疼我，那把地拖完，然后我们带孩子们下楼溜达一圈散个步吧。\u003c/p>\u003cp>WHERE：\u003c/p>\u003cp>\u003cstrong>这个方法适用于\u003c/strong>各种关系的沟通，包括家人、朋友、同事等等\u003c/p>\u003cp>\u003cstrong>不适用\u003c/strong>于恶意发泄情绪时候。比如我8岁儿子蛮不讲理发脾气时的哭闹，说啥都听不进去的时候，这时候让他一个人待一会儿等他情绪缓解或者揍一顿什么都强。\u003c/p>\u003cp>\u003cstrong>异议\u003c/strong>\u003c/p>\u003cp>大看到这里，有的小伙伴小伙伴可能还会问，我必须完整的按照顺序将这四个要素一个不落的都表达出来吗？\u003c/p>\u003cp>还有的小伙伴可能会说这样表达是不是太麻烦了，遇到情绪上来的时候一顿输出猛如虎，哪里还能想到那么多一二三四？\u003c/p>\u003cp>\u003cstrong>预防性的讲解：\u003c/strong>\u003c/p>\u003cp>我们刚开始学习，为了更好的掌握应用它，会按照它的步骤一步一步来，等使用时间长了，我们就可以灵活的应用，因为非暴力沟通不是固定的公式，掌握它以后，也不用每次四个要素都必须用全，它的精髓在于对这四个要素的觉察，而不在于使用什么字眼进行交流。这就更需要我们联系自己的真实经验，放到自己的生活中去学以致用。\u003c/p>\u003cp> 当我自己被情绪控制的时候，我也是会霹雳吧啦一大堆，发泄完了当时是爽了，但事后想想还是挺后悔的，当时怎么就不能好好说话呢。所以为了避免我们事后后悔，通过刻意练习非暴力沟通四要素这个方法，我们把情绪改变在事情发生的那一刻，让我们都好好说话，简单直白的表达自己。\u003c/p>","interaction":"\u003cp>分享到这里，在座的各位伙伴，对非暴力沟通四要素：观察、感受、需要、请求已经有了很深入的理解。比如你白天在公司被老板吊了一顿，回家看到满水池的碗筷扔那没洗，孩子的作业没做好，却跟小伙伴玩的不着家，而老公确葛优躺刷着手机嘻嘻哈哈。\u003c/p>\u003cp>在此给大家2分钟时间，大家可以把想到的场景内容写在便签纸上,要求场景内容包含时间、地点、人物、事件等各要素，稍后我会邀请一位小伙伴现场分享，这里需要提醒大家注意的是：只讲你设想的那个场景就好，不需要具体说会怎样去做。\u003c/p>\u003cp>赵老师分享如下：\u003c/p>\u003cp> 我去开会不在班级里时，班上就会乱成一锅粥，有吵闹的，有下座位的，我表示很生气。\u003c/p>\u003cp>通过今天的学习我会怎么处理呢？首先让自己安静来下来，然后跟同学说我事先跟你们说了，我去开会希望你们安静，但我人还没到，就听到你们吵闹的声音（摆事实），对此我感到失望并且很生气（谈感受），我需要有个安静的环境让我静下来可以思考一些问题同时，也能让们能够静下心来学习。（讲需要）我希望你们下次讲话之前自己想一想：我答应过赵老师她不在的时候不讲话的。（提请求）\u003c/p>\u003cp>再次感谢赵老师的精彩分享，让我们进一步学习非暴力沟通模式四要素，观察、感受，需要，请求。通过1、不进行主观评判、客观描述具体的行为动作（摆事实），2、基于自己的观察，用情绪类词汇描述自己的感受，比如说我生气、不开心（讲感受），3、明确自己与人交谈的目标（说需要\u003c/p>\u003cp>），4、指令清晰，要用肯定的句式说出对方具体要怎样做。（提请求），来充分沟通，最大程度向对方释放善意，也能让沟通彼此都愿意真诚的为彼此付出。\u003c/p>\u003cp>我的分享到此结束，感谢大家的聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1689059172000,"updated_at":1692665463000,"ria":true},{"id":16215,"topic":"充分表达感激 ","learn_goal":"","remark":"当你向他人说“谢谢”感到无法表达内心感激之情时，就可以用表达感激三要素来表达你的感激之情。 ","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"汤小敏","city":"镇江市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>Hello,大家好，我是汤敏，是今天TF2-1拆书家。用三个标签介绍我自已，第一我是地产公司的从业者，第二我植物美肌护肤英树护肤品牌的官方经销者，第三我是一级拆书家拆书法追随者。\u003c/p>\u003cp>因为今天会有讨论的环节，为了方便讨论，现在我们先进行分组,以3人为1组，其中某某老师、某某老师、某某老师3人为1组，某某老师、某某老师与某某老师3人，为1组，主要分成2组。\u003c/p>\u003cp>\u003cstrong>今晚学习的主题是表达感激三要素，通过今晚的学习，大家将会掌握一个方法，当你向他人说“谢谢”感到无法表达内心感激之情时，就可以用表达感激三要素来表达你的感激之情。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【F 】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>今天的拆页来源于《非暴力沟通》这本书，作者是美国心理学家马歇尔·卢森堡博士，由华夏出版社于2021年5月在北京发行第2版，全书分为14章节，约19万字，从日常沟通语言、不带评论的观察、描述自已的心情、感受，甚至是愤怒，化解冲突，解放自我，协助他人、表达感激与赞赏等多方面阐述非暴力沟通的意义、方法与价值。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>该书豆瓣评分8.4分，跟同类沟通的书籍不同，不是教你各种场景下的话术，而是从专业的心理学角度告诉你，如何去体会对方和表达自己真实的情感和需求，于2006年荣获地球村基金会颁发的和平之桥奖，非暴力沟通也被理解为“一种生命的语言”，“非暴力沟通”方式也被称为“爱的语言“，深受广大读者喜爱与追捧。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【B1】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>通过阅读《非暴力沟通》这本书，会有什么好处呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一可改变“惯有的、自动化的”思维模式；\u003c/strong> \u003c/p>\u003cp>\u003cstrong>二可改变看待、回应周遭人、事、物的方式；\u003c/strong> \u003c/p>\u003cp>\u003cstrong>三可改变我们与己、与人的关系，使我们的生活、生命体验更美好。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【B2】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>今天我们学习的拆页表达感激三要素不仅让对方感受到你真诚的谢意，同时也能让对方能够更全面更深入感受到你的感激之情以及你发自内心的对对方的认可与尊重，让彼此的关系更加和谐、紧密与融洽。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>现在请大家跟我一起来践行拆书法，请阅读我刚才分发给大家的拆页，给大家1分钟，读完的伙伴请举手示意一下。\u003c/strong>\u003c/p>","ratings_count":2,"texts":[{"id":20303,"quote":"\u003cp>在使用非暴力沟通表达感激时，我们会清楚地包含以下三个因素：\u003c/p>\u003cp> .他人做了什么增进了我们的福祉。\u003c/p>\u003cp> .我们有哪些需要因此得到了满足。\u003c/p>\u003cp> .因为这些需要得到了满足，引起了我们什么样的愉悦感受。\u003c/p>\u003cp> 表达这三个要素时，并不一定要遵照以上的顺序。有时哪怕是一个微笑或者一句简单的“谢谢你”就足以传递这一切。不过，我们想要确保对方能够充分收到我们的心意，用语言完整地表达这三个要素是有意义的。在下文的对话中，大家可以看到如何用这三要素来表达“赞赏”。\u003c/p>","explains":"\u003cp>\u003cstrong>{what}\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我看大家都已经阅读完了，这个拆页讲了什么呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这个拆页告诉我们，当向一个人表达谢意之时，如果道一声“谢谢”不足以表达自已内心的激动，就可以用表达感激三要素，细致而又全面地向对方说出自己内心的认可之事与感动之情。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>{why}\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这样的表达有什么好处呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一是丰富，言之有物，我们感激的并不是一句口头上的表达，而是具体的某件事情；\u003c/strong> \u003c/p>\u003cp>\u003cstrong>二是真挚，通过对事情的讲述，表明这件事情对你的重要性，让对方感受到确实帮助了你，这是一种精神上的认可与褒奖。\u003c/strong>\u003cbr> \u003cstrong>否则，\u003c/strong> \u003cstrong>一声“谢谢”，一句“你辛苦了”，虽然也表达了我们的谢意，但是并没有诠释我们的感激之情，一声“谢谢”，“你辛苦了”，会显得力度不够，苍白与寡淡，长此以往，人际关系将趋于平淡、疏远，甚至产生隔阂与仇视。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>{how}\u003c/strong>\u003c/p>\u003cp>\u003cstrong>那么，我们究竟如何做，才能让帮助我们的人感受到我们的感激之情呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在此，我归纳为三点：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、讲事实：讲对方究竟做了什么事情让你感动。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、讲需求：讲述你原本的需求是什么，让对方清楚地明白你的想法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3、讲心情：对方的支持或者帮助满足了你的需求，解决了你的问题，让对方充分了解你此刻的心情。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>以上3点，没有先后顺序，可以根据情况，灵活运用。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>{where}\u003c/strong>\u003c/p>\u003cp> \u003cstrong>有的小伙伴可能会想，对自己有任何帮助的人，不论事情大小，都要这样表达感激吗？\u003c/strong>\u003c/p>\u003cp> \u003cstrong>当然不是了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>该方法适用于帮你解决难题或者给你启发，让你的生活、工作、学习得到改善的感激表达。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不适用于日常小事，比如帮忙拿个快递、帮忙打个文件、帮忙倒杯水等\u003c/strong>\u003c/p>\u003cp>\u003cstrong>举例：\u003c/strong>\u003c/p>\u003cp> \u003cstrong>前段时间，我有笔抵押贷款被银行查出来，银行通知我必须在10天内全部足额还清，逾期将会影响我的征信。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我可吓坏了，东拼西凑，钱仍是不够。眼看期限就要到了，我与爱人如热锅上的蚂蚁，愁的团团转，这时我公司同事了解了这个事情,他一听我的处境，立马说，我用我的信用贷款20万帮你一把，你就不用再担心了，到时候抵押贷款下来还我就可以。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>哎，当时我是非常感动的，但是我也只是向对方说了声：太谢谢了，就结束了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>通过今天的学习，如果下次再碰到这样的情况，我想我可以这样对同事说：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、讲事实：老吴，面对这笔突然要还的贷款，我一直在想解决办法，可一时半会，没有想到很好的办法，你主动拆借的20万，真是帮了我一个大忙。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、讲需求:我原来是想卖掉股票，割肉离场，将贷款先还上，再重新办理抵押贷款，可我很纠结，不甘心认亏离场。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3、讲心情：正在我左右为难，不知道如何是好的时候，是你出手，拉了我一把，让我很快解决了这个问题，此时的我，压力全消，再不也用愁了，真的谢谢你，中午我请你吃大餐，走起。\u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>分享到这里，我想请大家回想一下，过去的1个月内有没有遇到过这样的情况：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>别人帮助了你，而你却没有正式的表达感谢，只是随意地说了一声谢谢，现在想起来是不是有些不好意思或者懊悔？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>比如说，同事心甘情愿地加班，配合你完成你的工作与计划而你却认为理所当然，没有好好感谢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>再比如说，父母或者爱人给你做了一些事情，而你却认为是家人，也从来没有想过要好好感谢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>现在给大家1分钟时间，一起来回想一下。可以把你们想到的场景内容写在便签纸上，然后小组内分享。稍后我会邀请一位小伙伴现场分享。这里需要提醒大家注意的是：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>只讲当时发生了什么就可以，不需要说应该怎样做。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>经过1分钟的小组讨论，现在我想邀请一位伙伴，用一分钟时间来简单分享一下你的故事。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>凌老师分享：\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 我一直跟着父母生活了很多年，父母承担了家里所有的家务活儿，让我有很多时间可以去做别的事情，对此从未好好的表达感谢。通过今天的学习，我的分享如下：\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 讲事实。爸爸妈妈你们跟着我们一起生活，承揽了家里的家务活，也很辛苦。\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 讲需求。原本这些家务活都是我的分内事，因为你们对我的爱，让我有了更多的时间去做我喜欢的事情。\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 讲心情。有你们陪在我身边，我觉得很幸福。今天是父亲节，我们给你们准备了礼物，希望你们喜欢。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>真诚的感谢是需要方法的，我们很多时候想表达自己内心的感谢，但是组织不好内容，欠缺恰当的表达方法，没有充分、具体的表达自己的感激。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>通过今天的分享，我们回去之后大家可以积极的运用起来，通过讲事实、讲需求、讲心情这个三个要素充分来表达我们的感激之情吧。我今天的分享就到这里啦，感谢大家的聆听。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1689057161000,"updated_at":1692665371000,"ria":true},{"id":15963,"topic":"如何运用感激三要素，表达感激之情","learn_goal":"","remark":"通过非暴力沟通感激三要素。来正向肯定别人的举动，并向他表达我们内心的感受。","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"ELIAUK","city":"镇江市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>各位老师，大家晚上好，我是今天本场的拆书家赵丽英，用三张标签介绍一下我自己第一张标签，我是一名认真的基督徒。第二张标签是我是一个用心生活的家庭主妇，第三张标签我是刚刚晋级的一级拆书家。\u003c/p>\u003cp>今晚学习的主题是如何用非暴力沟通表达感激与赞赏，学习的目标是：\u003c/p>\u003cp>大家通过今晚现场的学习，能够在以后适用的场景中运用感激三要素，准确的识别别人的行动满足我们怎样的需要，又产生怎样的感受，从而给到别人正向的反馈。\u003c/p>\u003cp>因为我们下面有讨论的环节，所以进行一下分组。每位老师可以跟坐在自己身边的小伙伴儿二人成为一组。我们参加的人若有单数的话，最后一组也可以，三人为一组。我向大家介绍一下今天晚上学习的这本书。\u003c/p>\u003cp>【F】【Feature 特征》（以书为核心来满足好奇心)本书作者是著名心理学家马歇尔·卢森堡博工，这本书的核心是如何采用非暴力沟通的方式与别人相处。这个方式是，沟通=事实+感受+需要+请求。这种调节方式既能为一个安全而又和谐的社会做出贡献。又能够培养出生命力和创造力。最终让世界充满爱。&quot;\u003c/p>\u003cp>【AI【Advantage 优势》（用方法解决情绪）相比其他沟通类书籍，内容简单，易懂，方法可操作性很强。没太多理论性的东西，而是从我们内心 需要与感受的角度。去看待问题，解决问题。\u003c/p>\u003cp>【B1】(学完本书可得利益）我们可以通过学习这本书去识别情绪背后双方的需要，与别人建立连接。而且可以做自己情绪的主人 ，进而做生活的主人。\u003c/p>\u003cp>【B2】（学完此片段可得利益）可以让自己在各样的冲突当中去梳理自己。更加的明白自己里边的感受和需要。也能够更好的同理到别人。还可以去帮助到别人，做使人和睦的工作。更有效的使双方进入正向积极的模式，达到一个双赢的局面。 现在请大家跟我一起来践行拆书法，请阅读我刚才分发给大家的拆页，给大家2分钟，读完的伙伴请举手示意一下。\u003c/p>","ratings_count":2,"texts":[{"id":20069,"quote":"\u003cp> 表达感激的三个要素 \u003c/p>\u003cp>在使用非暴力沟通表达感激时，我们会清楚地包含以下三个要素，\u003c/p>\u003cp>他人做了什么增进了我们的福祉。\u003c/p>\u003cp>我们有哪些需要因此得到了满足。\u003c/p>\u003cp>因为这些需要得到了满足，引起了我们什么样的愉悦感受。\u003c/p>\u003cp>表达这三个要素时，并不一定要遵照以上的顺序。有时哪怕是一个微笑或一句简单的“谢谢你”就足以传递这一切。不过，如果我们想要确保对方能够充分收到我们的心意，用语言完整地表达这三个要素是有意义的。在下文的对话中，大家可以看到如何用这三个要素来表达“赞赏”。\u003c/p>\u003cp>学员：（在工作坊结束后来找我）马歇尔，你太棒了！\u003c/p>\u003cp>马歇尔：我好像不太理解你为什么要这么称赞我。\u003c/p>\u003cp>学员：为什么？你的意思是？\u003c/p>\u003cp>马歇尔：人们给过我无数的头衔，但我却完全无法从这些表述中学到什么。我想从你对我的赞赏中有所\u003c/p>\u003cp>马歇尔：人们给过我无数的头衔，但我却完全无法从这些表述中学到什么。我想从你对我的赞赏中有所学习，并且因此感到喜悦，但我需要你再多说一些。\u003c/p>\u003cp>学员：比如说？\u003c/p>\u003cp>马歇尔：首先，我想知道我说了什么或者做了什么让你的生命变得更加美好。\u003c/p>\u003cp>学员：嗯，你很有智慧。\u003c/p>\u003cp>马歇尔：恐怕你刚刚又给了我另一个评判。我依然想知道我做了什么让 你的生命更美好。\u003c/p>\u003cp>学员：（思索了一会儿后，她指着自己在工作坊上写下的笔记）看这两处，就是你说的这两点。\u003c/p>\u003cp>马歇尔：噢，所以你赞赏的是我说的这两点？\u003c/p>\u003cp>学员：是的。\u003c/p>\u003cp>马歇尔：接下来，我想要知道这些话带给你的感受。\u003c/p>\u003cp>学员：感到充满希望，并且释然。\u003c/p>\u003cp>马歇尔：那么现在我想知道，我说了这两点满足了你哪些需要。\u003c/p>\u003cp>学员：我一直无法和我18岁的儿子沟通，一直在努力寻找一种更加情意相通的方式和他相处，你说的\u003c/p>\u003cp>学员：我一直无法和我18岁的儿子沟通，一直在努力寻找一种更加情意相通的方式和他相处，你说的这两点让我找到了方角。\u003c/p>\u003cp>听到这三个要素的内容（我做了什么，她有何感受以及满足了她#些需要）后，我就能真正和她一起享受这份赞赏。如果一开始就用非暴力沟通的方式来表达，她可以说：“马歇尔，当你说这两点时（向我展示她的笔记），我感到充满了希望并且释然，因为我一直在寻找方法和儿子连结，你的这些话给了我方向。\u003c/p>","explains":"\u003cp>逐字稿：\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>好，我看到大家都读完了，这段拆页讲述子什么？这段拆页作者向我们分享了一种正向表达赞赏和感谢的三个要素。\u003c/p>\u003cp>【WHY】为什么这么做？这么做的好处，不这么做的坏处。\u003c/p>\u003cp>在我们的日常生活中，当遇到被别人帮助的时候，我们通常只向对方讲一声“谢谢”。这是我们从尘家长和学校给卵的教导。要做一个有礼貌的人。把它视为一种有礼貌的行动。很多时候我们说的一声哥谢并没有走心。对于接受感谢的人也不痛不痒。没有多大的意义。若是运用非暴力沟通，表达感激的兰个要素。却让对方能够充分明白我们当时的内心壮况，正向强化他所做事情的意义，能够满足他内心的成就感。甚至会激励他在以后的生活当中更加的活出一个正向，积极的生命状态。如果没有应用三要素的话，那彼此之间的关系没有得到很好的连接。长此以往，就是生命上的梳离。\u003c/p>\u003cp>那下面我们看一下这个感激的三要素是如何运用的呢\u003c/p>\u003cp>1看见行为 看见并描述对方所做的事情。\u003c/p>\u003cp>2需要满足 我们里边什么需要通过对方的行为得到满足？\u003c/p>\u003cp>3引发感受 因着需要的满足，会带给我们怎样一个愉悦的感受。\u003c/p>\u003cp>【意译原书案例】\u003c/p>\u003cp>参照原文案例，让我联想到我与队友发生的一个案例:\u003c/p>\u003cp>每一个礼拜六我们都要去教会练诗歌。每我从家里出发的时候，他们晚饭都还没有吃完。所以只能等我练完诗歌回到家才能洗激碗筷清理厨房。但上一个礼拜六却出现了不一样的版本。当天晚上我练完回到家中。看见餐桌和厨房整理的清清爽爽，整整齐齐。心中的爱箱瞬间被填满非常开心。询问之后才知道是爸爸做的。我就进到卧室他说\u003c/p>\u003cp>我：“老公，你真的太好了！”\u003c/p>\u003cp>队友：“为什么会这样说呢？”\u003c/p>\u003cp>我：“你不明白吗？”\u003c/p>\u003cp>队友：“真的不知道自己做了什么，会让你觉得我很好。”\u003c/p>\u003cp>我：“比方说?\u003c/p>\u003cp>队友：“首先，我想知道我做了什么或说了什么让你有这样的感受呢。”\u003c/p>\u003cp>我：“奥！你很爱我。”\u003c/p>\u003cp>队友：“我的意思是让你说具体的事情，不是评价。”\u003c/p>\u003cp>我：你整理厨房了。”\u003c/p>\u003cp>队友：“原来你说的是这件事呀！”\u003c/p>\u003cp>我：“是的。”\u003c/p>\u003cp>队友：“接下来，我想知道这件事带给你的感觉。”\u003c/p>\u003cp>我：“如释重负，很开心。”\u003c/p>\u003cp>队友：“那现在我想知道，我这样做满足了你那些需求。”\u003c/p>\u003cp>我：“每次练歌回来我的身体很疲惫，就不想再做事情，但又不想拖延。你的举动刚好满足我。”\u003c/p>\u003cp>【WHERE】\u003c/p>\u003cp>非暴力沟通的表达感激三步法可以应用在我们生活，工作中当我们接受到别人帮助时，有一些时候是不太适用的，比如说随手一个帮助的举动。这是我们应用这个表达方法的话，会给别人觉得我们太迂腐。\u003c/p>","interaction":"\u003cp>我们刚刚学习了如何运用非暴力沟通表达感激的方法。现在一起做一个演练，请大家认真听一下演练的场景:\u003c/p>\u003cp>礼拜天的下午，突然遇到一个紧急情况要出去处理，忙完已经到了晚上七八点钟。这时的你身心俱疲，想到孩子们还在家等你一起做晚饭。就火急火燎的往家赶。你推开家门的那一刻，看到餐桌上摆满了孩子们做的食物。你当时的感受是怎样的呢？\u003c/p>\u003cp>现在我们按照开始时候的分组，在组内进行讨论和角色扮演，一个人扮演家长，另一个人来扮演孩子，组内演练的时间为5分钟，稍后我会邀请一组伙伴来表演一下，大家在讨论的时候可以参考我刚刚发给大家的这个表格。现在开始我们的讨论环节。\u003c/p>\u003cp>好，5分钟到，哪组伙伴愿意用5分钟时间来扮演一下如何运用“非暴力沟通表达感激三步法”？\u003c/p>\u003cp>其中丁舵主和宋老师积极举手示意，小组分享如下：丁舵扮演爸爸，宋老师扮演孩子。\u003c/p>\u003cp>爸:今天傍晚不错嘛，是谁把晚饭已经做好了呀？\u003c/p>\u003cp>孩:爸爸是我。\u003c/p>\u003cp>爸:是吗？是你自己完成的还是有帮手？\u003c/p>\u003cp>孩:爸爸是我自己做的，我看你平时上班太辛苦了，今天回来的又晚，所以就学着妈妈的样子烧了这顿饭。\u003c/p>\u003cp>爸:看到你平时的表现，其实爸爸对你还挺担心的，觉得你不能把自己照顾好。这个举动完全改变爸爸对你的看法。心里的焦虑瞬间没有了。你知道吗？其实到了傍晚，爸爸的身体非常的疲惫。看见你所做的饭菜，给了我很大的安慰。你真的长大了。谢谢你儿子。这一组的分享就到此结束。\u003c/p>\u003cp>谢谢宋老师和丁舵的精彩分享。\u003c/p>\u003cp>由于当时时间还很宽泛，所以又去了做了第二组的分享\u003c/p>\u003cp>下面有请张老师和王老师来给我们分享一下。 张老师扮演爸爸，王老师扮演孩子。\u003c/p>\u003cp>孩子:爸爸你快来，我给你做晚饭了。\u003c/p>\u003cp>爸爸:儿子今天为什么会想到给我做饭呀？\u003c/p>\u003cp>孩子:因为你回来太晚了，我都饿坏了。我老早不是跟你讲过，要让你尝尝我的手艺吗？\u003c/p>\u003cp>爸爸:你是怎么做到的呀？\u003c/p>\u003cp>孩子:我平时都有偷偷学。\u003c/p>\u003cp>爸爸:其实爸爸今天很辛苦，再回来的路上还在纠结是给你们点外卖，还是回来给你们做饭，最后决定回来给你们做。但是回家看到你所做的饭菜，立刻就打消了我的担忧。瞬间觉得很轻松，心情也很愉悦。\u003c/p>\u003cp>孩子:是吗？爸爸，我就这么一个小小的举动，就给你带来这么大的感受。那我答应你，以后我会常常给你做的。我们的分享也到此结束。\u003c/p>\u003cp>结束语\u003c/p>\u003cp>感谢四位老师的精彩分享，大家学到这？回顾一下今天学习的内容，我们来总结一下，我们今天学习了一些什么？\u003c/p>\u003cp>我们今晚学习的目标是学会正确使用非暴力沟通表达感激三要素。它的具体操作步骤是\u003c/p>\u003cp>1描述行动，\u003c/p>\u003cp>2 满足需要。\u003c/p>\u003cp>3带出感受。\u003c/p>\u003cp>相信大家在今后的生活中，通过运用此方法，让我们的行为被看见。内心的需要得满足。以喜乐的心面对生活。我的分享到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1686115925000,"updated_at":1686638952000,"ria":true},{"id":15801,"topic":"消极变积极，与自己握手言和的法宝","learn_goal":"","remark":"一本解决沟通的圣经","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"于枫","city":""},"club":{"name":"天津北洋分舵","city":"天津市"},"prologue":"\u003cp>三个标签自我介绍\u003c/p>\u003cp>大家好！我是小鱼。一个喜欢阅读、热爱美食、钻研神秘学的中年少女。如果你对这些方面感兴趣，我们可以有更多的交流。今天是我2-4的晋级现场，很高兴在这里和大家一起学习。今天会有讨论和角色演练，我们先在现场进行一下分组。以为我为中轴，左边为一组，右边为一组。\u003c/p>\u003cp>FAB图书介绍\u003c/p>\u003cp>\u003cstrong>【F特征】\u003c/strong>\u003c/p>\u003cp>今天和大家一起学习的这本书是马歇尔 卢森堡博士畅销数十年的一本沟通圣经《非暴力沟通》，他的豆瓣评分高达8.4分，常年位居沟通类书籍的榜首。而作者本人更是师从心理学大师卡尔·罗杰斯，其著作的科学性和严谨性都不容置疑。\u003c/p>\u003cp>\u003cstrong>【A优势】\u003c/strong>\u003c/p>\u003cp>自1963年非暴力沟通这个观点被提出，长达60年，数以万计的人不断实践、验证，能够留存至今，足以说明它是行之有效的一套方法。能被冠以“圣经”之名，其地位已不言而喻。如果要研究沟通类的主题，这本书必然是首选。与其他同类书相比，它不仅仅停留在沟通时的语言表达，而是更深一步挖掘了语言背后的情感和潜在需求。\u003c/p>\u003cp>\u003cstrong>【B利益】\u003c/strong>\u003c/p>\u003cp>阅读这本书能让我们更好的发现自己的真实需求，同时也能在关键时刻化解与他人之间的矛盾，用温和和地损害的方式化解冲突，拥有更和谐稳定的人际关系。\u003c/p>\u003cp>\u003cstrong>【B1】：\u003c/strong>\u003c/p>\u003cp>我们无法给予别人自己没有的东西，想要在日常生活中和他人进行有效且良好的沟通，首先自己要有一个稳定乐观向上的态度，书中专门有一个章节就是教会我们如何来爱自己，与自己和解的。今天我们的两个片段都出自此章。我们先从自身做起，让自己的内心安定和强大起来。\u003c/p>\u003cp>学习目标：\u003c/p>\u003cp>今天我们一共会读到书中两个片段，在跟随我完成第一个片段的RIA现场学习后，相信大家如果遇到自己不想做，但又不得不做的事情时，就能够第一时间想到运用替换大法，让自己开开心心的投入到所做的事情当中。\u003c/p>","ratings_count":4,"texts":[{"id":19887,"quote":"\u003cp>\u003cstrong>现在请大家先阅读原文片段。看完之后抬头示意我一下。\u003c/strong>\u003c/p>\u003cp>【片段来源】： 《非暴力沟通》P145-146\u003c/p>\u003cp>【主题】：积极主动的选择代替消极被动的接受\u003c/p>\u003cp>R原文片段：\u003c/p>\u003cp> \u003cstrong>“不得不”转化为”我选择“\u003c/strong>\u003c/p>\u003cp> 第一步：\u003c/p>\u003cp> 在你的生活中，哪些事情让你觉得无趣，却又不得不去做？你不想做它们，但还是去做了，因为你认为自己没有选择。请将这些事情列在一张纸上。\u003c/p>\u003cp> 当我第一次审视我的清单时，发现上面的事情可真不少，我恍然大悟自己为何常常无法享受生活。有许多事情，我之所以日复一日地去做，是因为我糊弄自己去相信那是不得不做的。 \u003c/p>\u003cp> 清单上的第一项是：写临床报告。我痛恨撰写这些报告，但却每天至少要花一个小时在上面，这让我苦不堪言。清单的第二项是：开车送孩子们上学。\u003c/p>\u003cp> 第二步： 写完清单后，清楚地告诉自己：你之所以做这些事情，是因为你选择了它们，而非你不得不做。在你所列出的每一件事情前加上“我选择做……”。 \u003c/p>\u003cp>我记得当时我对这一步有些抗拒。我一直信誓旦旦地认为：“写临床报告不是我选择要做的事情，而是我不得不做的事。我是一名临床心理医生，当然必须要写这些报告。”\u003c/p>\u003cp> 第三步： 一旦你认同了之所以做某件事是出于自己的选择，请试着体会选择背后的意图是什么，然后以“我选择做……因为我想要……”来表述。 \u003c/p>\u003cp> 起初，我怎么也想不清楚到底为什么要写临床报告。几个月前，我已经认定这些报告对我的咨询病人来说用处不大，不值得花那么多时间。既然如此，为什么我还投入那么多精力在这上面呢？最终我发现，我选择写这些报告，仅仅是因为想要获得这份工作带来的收入。意识到这点，我再也没有写过任何临床报告了。想到这35年来，自己少写了无数的报告，我就开心得不得了！当意识到金钱是我的首要驱动力时，我立刻就想到可以用别的方式来获得收入。事实上，我宁愿在垃圾桶里觅食，也不愿再多写一份临床报告！ \u003c/p>\u003cp> 我列出的第二项不情愿做的事：开车送孩子们上学。当我仔细思索为什么要这么做时，我发现，对于孩子们从学校收获的好处，我心怀感恩。虽然他们可以步行到附近的学校上学，但现在的这所学校更符合我的教育理念。于是，我还是继续开车送孩子们上学，不过心态已经不一样了。我不再对自己说：“讨厌，今天我又必须做车夫了。”因为我已经清楚地知道，这是为了让孩子们受到良好的教育，因为我很重视教育的品质。当然，有时候我需要在开车时提醒自己好多次，重新关注这样做的目的。\u003c/p>","explains":"\u003cp>\u003cstrong>What:\u003c/strong>生活中我们难免会遇到一些不得不做的事情，可以转换思考角度，用“选择做”代替“不得不”，让心态从消极转化为积极。\u003c/p>\u003cp>\u003cstrong>Why及不那么做的坏处\u003c/strong>\u003c/p>\u003cp>[通常的做法]\u003c/p>\u003cp>遇到自己抗拒的事情时，我们通常会抱怨、逃避、推脱或者敷衍了事。\u003c/p>\u003cp>[通常做法的结果]\u003c/p>\u003cp>试想一下，我们如果用上述的方式处理事情，是不是会身心俱疲，心情一团糟不说，事情也不会做的有多好。\u003c/p>\u003cp>[不这么做的坏处] \u003c/p>\u003cp>如果不能用正确的方式化解情绪，坏情绪有可能牵扯到其他人，影响我们的人际关系。办事态度不端正也会让你在朋友、同事眼里变成一个不靠谱的人，严重的话，升职加薪也和消极怠工的你擦肩而过了。\u003c/p>\u003ch2>\u003c/h2>\u003ch2>\u003cstrong>【反例】\u003c/strong>\u003c/h2>\u003cp>和大家分享最近发生的一件事情：\u003c/p>\u003cp>两周前，我身体状态不好，各种杂事缠身，早上刚到公司，领导就让我改8个教案，还要求在3天内完成。我当时第一反应就是：这是要累死我吗？太烦躁了，辞职两字差点脱口而出。当时下意识的就把脸拉下来了。带着负面情绪改教案，工作效率低，还把领导得罪了。\u003c/p>\u003cp>\u003cstrong>how:如何做呢？（细化步骤） 第三个步骤细化为3和4\u003c/strong>\u003c/p>\u003cp>这个片段给出了处理情绪的方法，我叫它替换大法。\u003c/p>\u003cp>1、\u003cstrong>列清单，\u003c/strong>把自己近期有抗拒心里去做的事情先列出来。\u003c/p>\u003cp>2、\u003cstrong>强暗示\u003c/strong>，把每件事前面加上“我选择”三个字，暗示自己，这是自己做的决定。\u003c/p>\u003cp>3、\u003cstrong>找益处\u003c/strong>，找到做这件事情给自己带来的好处？不限于身体、心情、人际关系。维度越多越好。\u003c/p>\u003cp>4、\u003cstrong>再强调\u003c/strong>，用“\u003cstrong>我选择做XXX，是因为我想要XXX\u003c/strong>”的句式，在脑海中强化自己获得的好处。\u003c/p>\u003ch2>\u003c/h2>\u003ch2>\u003cstrong>【反例加工】\u003c/strong>\u003c/h2>\u003cp>如果用“选择做”代替“不得不”，来复盘一下我的失败案例。我会这样处理：\u003c/p>\u003cp>1、先列出最近1周周，让我特别抗拒的不想做的事情都有哪些（列清单）\u003c/p>\u003cp>2、给写教案这件事情加上“我选择做”的前缀，来暗示自己。（强暗示）\u003c/p>\u003cp>3、发现做教案可以让我有1000元的收入，且让我的早教课程做了完结。（找益处）\u003c/p>\u003cp>4、对自己说，我选择做教案，是因为我可以赚到1000元且能完善我的早教课体系。（再强调）\u003c/p>\u003cp>\u003cstrong>where:\u003c/strong>\u003c/p>\u003cp>这个方法不仅适用于工作环境、家庭关系中，同样也适用我们学习新的知识等多个场景中。只要是突破舒适区，干一些不情愿却必须做的事情时，都可以试试这个方法。\u003c/p>","interaction":"\u003cp>\u003cstrong>【显像提问】\u003c/strong>\u003c/p>\u003cp>【A1】请大家现在也回忆一下，有没有让你不得不面对，但是却心里不痛快的场景出现？比如\u003c/p>\u003cp>（场景一）你累了一天，晚上回家孩子非要让你陪着一起看书玩游戏，你不得不拖着疲惫的身体陪她到睡觉时间。\u003c/p>\u003cp>（场景二）眼看下班时间快到了，领导又在你桌子上放了几个文件夹，告诉你，务必在走前完成，你不得不拖延了下班时间，继续埋头苦干。\u003c/p>\u003cp>（场景三）你的好哥们（闺蜜）每次和你出去都要和你吐槽她的老板、家人等等负能量的事情，你听完心情很不好，但又不得不当他的垃圾桶。\u003c/p>\u003cp>或者除了以上，过去一周内，你还遇到哪些不得不做的场景？请大家按刚才的分组进行讨论，2分钟后请一位小伙伴给大家分享下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>莎莎：我每天喂我家的小狗，每天必须把儿童肠拧断，一点点捋出来，手很疼，不捋狗就不吃了。\u003c/p>\u003cp>拆书家回应：这可能是一只尊贵的狗狗，然我们的莎莎不得不做这件事情。\u003c/p>\u003cp>【A1+】接下来我们要把刚才自己分享的例子进行加工，结合刚才学的替换大法，反思自己面对特别抗拒的事情时，运用刚才所学4个步骤，列清单、强暗示、找益处、再强调。\u003c/p>\u003cp>最后用我选择做，是因为……的句式，看看如何转换自己的消极心态。\u003c/p>\u003cp>请与同组的小伙伴分享一下你的经历，时间到了我会提示大家，然后请小伙伴上来分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1、列清单，找到自己最不愿意做的就是给狗拧香肠，很麻烦。\u003c/p>\u003cp>2、和自己说，加上一个我选择，我选择每天带它玩，每天给它吃好吃的、每天溜它。是我选择给它拧香肠的。\u003c/p>\u003cp>3、狗狗开心，我也会开心。\u003c/p>\u003cp>4、我选择做这些，是因为我想让狗狗来帮助活跃家庭气氛。\u003c/p>\u003cp>过渡语：我们今天的目的就是要拥有积极快乐的心态在生活中处理事务，第一个片段的学习教会我们，如何用选择做的心态，积极面对不得不做的事情。有人也许会说，光有积极心态就可以吗？开开信心的做事，结果搞砸了，马上就开心变伤心了，很可能还陷入“我很糟糕”的自我否定里。那该如何避免陷自责的情绪漩涡中呢？为了解决这个问题，我们就需要进入第二个片段的学习。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":19888,"quote":"\u003cp>【片段来源】： 《非暴力沟通》 P124-125\u003c/p>\u003cp>【主题】：自我宽恕\u003c/p>\u003cp>外衣染上墨水带来的启发\u003c/p>\u003cp> 我想通过个人经历来说明非暴力沟通的忧伤及自我宽恕。在一个研讨班开始前的一天，我买了一套浅灰色的夏季外衣。这个研讨班很重要，出席的人很多。在结束时，许多人围着我询问地址及其他信息，并请我签名。为了赶下一场会面，我匆忙地回答问题，并紧张地签字和留言。当我飞快地冲出门时，我将笔放入了新外套的口袋。我居然忘了戴笔帽！等到了外面，我吓了一跳——那件雅致的浅灰色外套已染上了墨水！\u003c/p>\u003cp> 有二十分钟的时间，我不停地训斥自己：“你怎么可以这么粗心？这么愚蠢的错误！”我刚损失了一套崭新的外衣，如果我在生活中需要得到体谅，那么，此刻正是时候。可是，我却是在训斥自己，这简直糟透了。\u003c/p>\u003cp> 幸运的是，二十分钟后，我意识到自己正在做什么。我静了下来，开始想外衣染上墨水使我什么样的需要得不到满足。我问自己：“我责备自己“粗心”和“愚蠢”，是想要满足什么需要呢？\u003c/p>\u003cp> 我马上就明白了，其实我是想照顾好自己：在匆忙地回应他人的请求时，要多留意自己的需要。此时，我的心情也随即发生了变化。我不再感到恼怒、羞愧和内疚，身体也一阵轻松。我体会着损失一件新外衣及忘记戴笔帽的悲哀，以及照顾好自己的强烈愿望。\u003c/p>\u003cp> 接着，我开始考虑，我为了满足什么样的需要而随手把笔放入口袋中。这使我意识到，回应他人的请求对我是多么地重要。遗憾的是，为了尽量满足他人的需要，我忽视了自己的一些需要。想到这些，我并没有责备自己，而是感到对自己深深的爱——即使在我心不在焉地把笔放入口袋的时候，我也是在满足自己服务他人的渴望。\u003c/p>\u003cp> 这样，我做到了同时包容上述的两种需要：一方面，服务他人；另一方面，照顾好自己。我相信，在类似的情形中，只要能意识到这两方面的需要，我就能灵活地克服困难。反之，如果陷入内心的冲突，只会使情况更糟。\u003c/p>","explains":"\u003cp>\u003cstrong>what:\u003c/strong>\u003c/p>\u003cp>这个故事让我们体会到作者在关注他人需求时，因为一个小疏忽导致自己陷入自责和懊恼中，又是如何运用与自我和解4步法，让自己逃离情绪漩涡。\u003c/p>\u003cp>\u003cstrong>how:如何做呢？四字口诀\u003c/strong> \u003cstrong>“停-挖-找-抱”（配合动作示意）（现场带着学习者一起做四个动作代表暂停、挖掘、寻找和拥抱）\u003c/strong>\u003c/p>\u003cp>既然知道了诸多的坏处和影响，那我们该如何摆脱这样的情形呢？\u003c/p>\u003cp>1、\u003cstrong>暂停自责\u003c/strong>，先把责备的语言封在嘴巴里，别让它有机会跑出来。\u003c/p>\u003cp>2、\u003cstrong>深挖需求\u003c/strong>，找到自我否定的真实需求哪里未得到满足。\u003c/p>\u003cp>3、\u003cstrong>寻找出口\u003c/strong>，想想是否有可以让自己获得心理安慰的理由。\u003c/p>\u003cp>4、\u003cstrong>拥抱自我\u003c/strong>，告诉自己，我是值得被爱的，这是可以被原谅的，并没什么大不了。给自己一个温暖的抱抱。\u003c/p>\u003cp>\u003cstrong>【不那么做的坏处】\u003c/strong>我们很容易因为自己的无心过失造成麻烦和损失时，感到沮丧。用现在很流行的一句网络用语叫做”怀疑人生“，给自己贴上“我很蠢笨”“我很无能”之类的负面标签。\u003c/p>\u003cp>\u003cstrong>[通常做法的结果]\u003c/strong>\u003c/p>\u003cp>经常给自己否定的暗示，很容易让自己变得不自信，心情变糟糕。\u003c/p>\u003cp>\u003cstrong>[不这么做的坏处]\u003c/strong>\u003c/p>\u003cp>然而自责和否定，并不能改变发生的结果，如果我们不能用积极的方式处理，长期以往，将限入糟糕的恶性情绪里，对自己擅长的领域也会丧失信心，时间久了甚至可能给健康带来隐患，比如焦虑症等等疾病，那可就得不偿失了。\u003c/p>\u003cp>\u003cstrong>【意译案例】\u003c/strong>\u003c/p>\u003cp> 五一假期，3年没有机会见面的导师要来天津开讲座。我特别激动，头天晚上特意准备了一套定制裙装，想要隆重出席这场活动。这个讲座很重要，我提前去酒店接导师，外面下起瓢泼大雨，我一直为导师撑着伞，完全忘记自己自己也是穿着一身新衣在雨里！等到了会场，有人悄悄提醒我，我才惊觉——我的新裙装全是泥点！\u003c/p>\u003cp>有半小时的时间，我不停地训斥自己：“你怎么可以这么马虎？犯这么愚蠢的错误！”我刚损失了一套崭新的裙装，我此时此刻需要一些安慰。不久之后，我意识到自己正在做什么。我静了下来，开始想裙装弄上泥点子使我什么样的需要得不到满足。我问自己：“我责备自己“马虎”和“愚蠢”，是想要满足什么需要呢？\u003c/p>\u003cp>我想明白了，我是希望可以打理好自己，让自己在在乎的场合和在乎的人面前，有完美的表现。再进一步去想，因为导师就是我在乎的人啊，我是为了让一直很敬重的导师能够在今天的活动中有完美的呈现，才忽略了关照自己，我顿时就释然了。遗憾的是，为了照顾导师，我忽视了自己的一些需要。想到这些，我并没有责备自己，而是感到对自己深深的爱——即使在我好无察觉在淋雨的时候，我也是在满足自己服务他人的渴望。\u003c/p>\u003cp>照顾他人对我也同样重要，我因此弄脏了自己的新衣服，我完全没必要去责备自己。我应该原谅自己，我是那么的善良且懂得关爱他人，我和自己和解了。坏情绪也一扫而空，衣服脏了可以拿去洗一洗，这和我的好状态比起来，太微不足道了。\u003c/p>\u003cp>\u003cstrong>where:\u003c/strong>\u003c/p>\u003cp> 这个方法不仅适用于自我的宽恕；也适用于，帮助他人从自责到自我宽恕的转变。\u003c/p>\u003cp>但这个方法不适用于，故意犯错之后给自己找开脱的理由，比如我们有蓄意搞破坏的行为动机时，并不能用这个方法为我自己开脱，寻求原谅。事情的出发点好与坏，是关键判断因素。\u003c/p>\u003ch2>\u003c/h2>\u003ch2>【预防异议】\u003c/h2>\u003cp>有人也许要问，那每次都用这个方式来宽慰自己，会不会就让自己太放纵了？不懂得自我反思？\u003c/p>\u003cp>我想说的是，我们只是在特定场合下，不让自己陷入情绪中，而不是逃避解决问题，或者故意犯错。和自己的和解，是希望不要因为一件已经不可逆转结果的事情，让自己陷进情绪的泥沼无法自拔。\u003c/p>","interaction":"\u003cp>\u003cstrong>【场景描述】\u003c/strong>\u003c/p>\u003cp>接下来，结合今天学到的自我和解四步法\u003cstrong>，\u003c/strong>我们一起做个演练，模拟一个小情景剧\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A3【场景设计】\u003c/strong>\u003c/p>\u003cp>小白是公司技术骨干，全国总部举办技能比武，小白主动报名参加了比赛，势在必得，想要拔得头筹。在总决赛的赛场上，有一名选手突然晕倒在侯场区，小白因为有护理背景且有急救证，第一时间冲过去给晕倒的人做急救处理，等医务人员赶到后，他才匆匆赶往赛场，这时已经开赛快5分钟了，按规定开赛5分钟就会取消比赛资格，他踩着点参加比赛，时间紧迫加上心情还未平复，状态不是特别好，技能操作也没有发挥到最佳水平，比赛结束后，他有一点失落，本来志在必得的第一名就这样失之交臂了。\u003c/p>\u003cp>给大家一些时间，我们先在小组内讨论，请小伙伴来给大家呈现一下小白参加比赛时遇到这样的遗憾该怎样避免对自己的自责。\u003c/p>\u003cp>\u003cstrong>请大家按照分组，两两组合（一个扮演小白，一个扮演旁观者）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>扮演小白的小伙伴要运用今天所学的“自我和解四步法”与自己的内心对话，并让另一位伙伴看到你是如何一步步与自我达成和解的。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>然后你们需要一起讨论，写个小剧本，让小把与自我和解的关键词写下来。写完之后先在小组内演练一下。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>注意在编写剧本的时候一定要运用自我和解四步法，我们演练的目的就是练习运用这个方法。\u003c/strong>\u003c/p>\u003cp>现在开始组内讨论演练，时间5分钟，稍后我会请小伙伴分享。\u003c/p>\u003cp>\u003cstrong>【现场展示】\u003c/strong>\u003c/p>\u003cp>下面我们请一位伙伴现场呈现一下，如果你是小白，讲如何运用“自我宽恕四步法”来缓解糟糕的情绪。\u003c/p>\u003cp>\u003cstrong>学习者案例记录\u003c/strong>\u003c/p>\u003cp>思思：我看到比赛之后没有得第一，看到别人在台上拿奖，我在心里斥责自己，没有发挥最高水平，可以发挥得更好，我要先停止（停）对自己得责备，我深挖（挖）自己想得第一得真实需求是什么？我是公司得技术骨干，我想拿第一，是因为我想拔得头筹，有升职加薪得机会，也希望别人高看我一眼，或者可以帮助更多得人，（找）我刚才救了一个人，如果我没有去管，是错失了一个生命，刚才我救了人，我是有爱心的，救人一命胜造七级浮屠，给自己寻找了自我安慰以后，（抱）告诉自己是值得被爱得，我不应该这么责备自己，我需要给自己一个拥抱。\u003c/p>\u003cp>拆书家回应：特别棒，感谢思思的精彩演绎。如果你是小白，经过这样的环节之后，你心里有没有感受好一点呢？\u003c/p>\u003cp>思思：感觉好多了。\u003c/p>\u003cp>\u003cstrong>【分步催化】\u003c/strong>\u003c/p>\u003cp>感谢大家的精彩分享。\u003c/p>\u003cp>在，我想请你们思考一下，今后会在什么情况下需要用到我们的四步法呢？\u003c/p>\u003cp>就比如：你的孩子和你发生了争执，领导误会了你，你的朋友和你争论不休……\u003c/p>\u003cp> 我们只需要在脑海中构建想出那个场景即可。（提示学习者，只构建场景，不说出解决方法，下一步再解决）\u003c/p>\u003cp> \u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>莎莎：擅长做饭，偶尔一不留神把西红柿鸡蛋做的特别苦，就很自责，怎么这么简单的菜都做不好？\u003c/p>\u003cp>接下来，请大家把刚才你想到的那个情景加工成具体的例子，在该情景下，如何运用自我和解四步骤，（停、挖、找、抱），让自己逃离情绪漩涡。\u003c/p>\u003cp>请大家与同组小伙伴先分享，一会我们找一位发言官分享；\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>长樱：我每次出门都会随身带一个铅笔盒，很有可能会把墨水洒出来了，下周就要去参加培训，就可能发生这样的情况，如果弄得书包里，铅笔盒里都是。就觉得很沮丧，会忍不住责怪自己：这么点事都做不好。\u003c/p>\u003cp>1、停：先停止责备自己，不去抱怨自己什么都做不好。\u003c/p>\u003cp>2、挖：我是一个培训师，我不希望自己的形象看起来那么狼狈。\u003c/p>\u003cp>3、找：别人看见也没有关系，至少证明我是一个做事严谨的人，出门准备的东西都很齐全。\u003c/p>\u003cp>4、抱：抱抱自己，我是值得被爱的。这件事情是可以被原谅的。\u003c/p>\u003cp>拆书家回应：感谢长缨的分享，看到你用四个步骤能昂自己让自己从沮丧的情绪中走出来，非常的棒。我们要学会好好的爱自己，我们都是值得被爱的。\u003c/p>\u003cp>感谢今天在场所有小伙伴的分享，今天我们一起学习用替代大法让自己心态更阳光，同时学会自我宽恕四个步骤与自己握手言和，走出情绪低谷。愿我们都能做自己的宇宙，阳光、快乐、积极，让每一个日子都闪闪发光。（强有力的结语，金句）\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1684119409000,"updated_at":1690920689000,"ria":true},{"id":15795,"topic":"如何运用非暴力沟通化解冲突","learn_goal":"","remark":"建立连接，\n化干戈为玉帛，\n让世界充满爱。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"ELIAUK","city":"镇江市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>大家好，我叫赵丽英，用三张便签来介绍一下我自己。第一张便签。我是一名虔诚的基督徒。第二张便签，我是一名幸福的家庭主妇。第三张便签，我是刚刚晋级的一级拆书家。\u003c/p>\u003cp>通过今天晚上的学习，可以让我们使用非暴力沟通解决冲突的这五个步骤。化解冲突使双方建立良好的关系。\u003c/p>\u003cp>因为今天会有讨论的环节，为了方便讨论，现在我们先进行分组，可以跟自己的邻居两个人为组。\u003c/p>\u003cp>【F】【Feature 特征》（以书为核心来满足好奇心)\u003c/p>\u003cp>本书作者是著名心理学家马歇尔·卢森堡博士，这本书的核心是如何采用非暴力沟通的方式与别人相处。这个方式是，沟通=事实+感受+需要+请求。这种调节方式既能为一个安全而又和谐的社会做出贡献。又能够培养出生命力和创造力。最终让世界充满爱。\u003c/p>\u003cp>【A】【Advantage 优势》（用方法解决情绪)\u003c/p>\u003cp>相比其他沟通类书籍，内容简单，易懂，方法可操作性很强。没太多理论性的东西，而是从我们内心需要与感受的角度。去看待问题，解决问题。\u003c/p>\u003cp>【B1】（学完本书可得利益)\u003c/p>\u003cp>我们可以通过学习这本书去识别情绪背后双方的需要，与别人建立连接。而且可以做自己情绪的主人，进而做生活的主人。\u003c/p>\u003cp>【B2】（学完此片段可得利益)\u003c/p>\u003cp>可以让自己在各样的冲突当中去梳理自己。更加的明白自己里边的感受和需要。也能够更好的同理到别人。还可以去帮助到别人，做使人和睦的工作。更有效的使双方进入正向积极的模式，达到一个双赢的局面。\u003c/p>","ratings_count":1,"texts":[{"id":19881,"quote":"\u003cp> 非暴力沟通化解冲突的步骤。\u003c/p>\u003cp>在详细讨论化解冲突的核心要素之前，我先大致介绍一下在化解自和他人的冲突过程中所涉及的5个步骤。任何一方都可以先表达自己结腾要，简便起见，假设先由我方表达。\u003c/p>\u003cp>肯先，我们要表达自己的需要。\u003c/p>\u003cp>其次，不论对方说什么，设法找出他们真正的需要。如果发现他们表达的是想法、评判或分析，而不是需要，我们可以继续寻找话语背后的需要\u003c/p>\u003cp>第三，确认我们都准确理解了彼此的需要，否则，继续寻找话语意后所隐含的需要。\u003c/p>\u003cp>第四，尽可能地同理对方，以便让双方都能确切地了解彼此的需要\u003c/p>\u003cp>第五，当双方都澄清了事件中的需要后，我们就可以用正向的描述这行动的语言提出化解冲突的策略\u003c/p>\u003cp>在整个过程中，我们要仔细聆听彼此的心声，避免在言语中影射对方有错。\u003c/p>","explains":"\u003cp>WHAT\u003c/p>\u003cp>好，我看到大家都读完了，这段拆页讲了什么呢?\u003c/p>\u003cp>这段拆页告诉我们一种化解冲突的方法。可以通过此方法不仅可以解决自己生活，工作上的冲突。还可以作为中间人帮助别人去调解。\u003c/p>\u003cp>WHY\u003c/p>\u003cp>学习这个，对我们有什么好处呢?\u003c/p>\u003cp>无论是在我们的日常生活，工作职场，只要与人打交道，都难免会出现冲突。冲突当中我们一般都非常的情绪化。会在情绪脑的作用底下说一些不该说的，做一些不该做的。就会出现伤别人1000，自损800的状况害人害己。如果运用此方法就可以避免这种两败俱伤的场景。还可以让双方得到双赢的局面。使这个社会少了一些鸡飞狗跳，多了一些和谐融洽，少了一些生命上的疏离，多了一些生命上的连接\u003c/p>\u003cp>讲到这里让我想起了前一段时间发生在我和儿子之间的一个冲突。那是礼拜三的一个早上。7:00 准时叫儿子起床，儿子把起床和洗漱都拆分开。不是一次穿完。每提醒一次，他就穿一件儿。洗漱也是拆分成三趟。看到他早上这样的状况，这我个老母亲就在那里一直提醒他。尽管愤怒的小火苗被点燃。依然还能控制得住。在他吃饭的时间，我就跟他讲事情怎么做才能够更加的高效率呀？自己身上有了坏习惯，别人提醒你要听，听了之后就要改的大道理。没等我讲完孩子的情绪也上来了，说我早上一直在批评他，开始又哭又闹。又讲自己今天不舒服，不想去上学。然后我就又是一通说教引导，愣是不管用。来看软的不行。就来硬的拖过来就揍了一顿。这时孩子他爸也在家，因为这两天孩子也一直有情绪。搞得他心情也\u003c/p>\u003cp>不好，看到我的火气上来了，他也冲过来揍了孩子一顿，来了一场男女混合打。后来儿子直接摔门而出。等冷静下来，拿着孩子的书包在小区里找了一圈，也没有找到孩子。回家后看到孩子坐在楼梯口，过去安慰了两句，然后把他送到了学校。事后其实挺为自己的表现懊悔的。那让我们看一下这个方法的具体操作步骤吧。\u003c/p>\u003cp>How（具体怎么做？)\u003c/p>\u003cp>第一步，表达自己的需要。自己在冲突当中真实的需要。\u003c/p>\u003cp>第二步，寻找对方的需要。是他言语背后真正的需要。并不是他的想法，评判或分析。\u003c/p>\u003cp>第三步，确知彼此的需要。每次确认双方真正的需要。\u003c/p>\u003cp>第四步，尽力的同理对方。转换立场和角度。是为了真正了解他的需要。\u003c/p>\u003cp>第五步，提出解决的办法。提出当下使局面双赢的办法，不是妥协。\u003c/p>\u003cp>当学了这个方法，我就和孩子运用这个方法为上一次的冲突做了一下梳理。\u003c/p>\u003cp>1表达自己的需要，想提醒帮助你改掉做事没有条理性的习惯。\u003c/p>\u003cp>2寻找对方的感受。通过儿子的表述知道他只想安静吃早饭。\u003c/p>\u003cp>3确知彼此的需要。通过询问他再一次的确定他的需要。自己通过梳理，也明白自己真实的需要。\u003c/p>\u003cp>4尽力的同理对方。自己换位思考。在儿子的立场上去感受。\u003c/p>\u003cp>5提出解决的办法。当时就跟孩子达成共识。当出现类似状况的时候，我建议他要给我一个正向的反馈，让我知道他明白。我就要立刻停止我的喋喋不休， 反复唠叨。\u003c/p>\u003cp>预防性的讲解：\u003c/p>\u003cp>也许有些伙伴会问，如果问题升级到冲突的话，就不是一般小小的摩擦，用这个方法真能解决吗?起冲突的原因就是每一个人都站在个人的立场上去考虑问题。就会以自己的利益最大化去解决问题。从而不能想到对方的需要，更谈不上去同理对方。从而使冲突升级。运用此方法则会进入双赢的局面。\u003c/p>\u003cp>也许有的小伙伴儿也会问。非暴力沟通的这个方法是不是属于心理治疗范畴，而非是解决冲突的办法。根据作者的经验告诉我们，连接人非单不是心理治疗还是化解冲突的关键。是唯一能够有效化解冲突的方式，一旦你成功的建立了人与人之间的连接，问题多半会自行解决。 与其冲突矛盾升级之后，请第三人来调解。还不如让每个人清楚明白自己的需要，此刻希望对方做什么。在双方都明白对方的需要后，自然就能够找出方法来满足彼此的需要，也就是双方都能够认同在调解工作结束之后所实施的策略。\u003c/p>\u003cp>Where（适用场景）除涉及主权原则性问题的冲突以外，生活，工作中的冲突都能应用。\u003c/p>","interaction":"\u003cp>分享到这里，相信在座的各位伙伴，对非暴力沟通化解冲突的步骤也有了很清楚的了解。设想一下，假如在我们的生活工作当中出现冲突的场景，^\u003c/p>\u003cp>比如节假日家人们决定去旅游。儿子，女儿想去的地方不统一各自坚持不让步，甚至上升到吵架的局面。\u003c/p>\u003cp>或者是好朋友家的孩子进入了青春期。母子之间的有了很多的冲突。导致亲子关系的张力很大，拜托你去做一下调解的场景\u003c/p>\u003cp>又或者是工作当中，两个合作的部门。因为没有及时的沟通，或者是沟通不畅。导致落地实操的时候，工作不能顺利进行。而且他们还相互的推卸责任。整个工作停滞，场面异常混乱。\u003c/p>\u003cp>在此给大家2分钟时间，大家可以把想到的场景内容写在便签纸上，要求场景内容包含时间、地点、人物、事件等各要素，稍后我会邀请一位小伙伴现场分享，这里需要提醒大家注意的是：只讲你设想的那个场景就好，不需要具体说会怎样去做。\u003c/p>\u003cp>好，2分钟到，我们邀请了陈芳老师。用1分钟时间来分享一下自已想到的场景。分享如下。\u003c/p>\u003cp>我的设想是未来有可能我和丈夫会在小女儿的画画这件事情上有冲突。因为大女儿画画很好，我家的先生就希望小女儿也学画画，因为他觉得画画可以培养拓展性思维。但是小女儿不喜欢画画，反而喜欢唱歌。我的想法是想按着孩子她自己的兴趣来培养她。\u003c/p>\u003cp>【A2】分步催化中指令清晰，有学习者根据指令，规划出了以后可以如何做的具体计划。逐字稿:\u003c/p>\u003cp>感谢陈芳老师的精彩分享，刚才各组伙伴都对自已接下来的生活工作中有可能出现的冲突设想了。下面给大家2分钟的时间。每组挑选一个加工一下，要运用到今天所学的解决冲突五步法。两分钟之后。请一位小伙伴儿来为我们分享。\u003c/p>\u003cp>现在我继续给大家4分钟时间，在小组内分享讨论一下，看看如何运用今天学习的表明自己的需要。寻找对方的需要，确知彼此的需要，尽力同理对方，提出解决方法这五个步骤来化解冲突。4分钟后,我将再次邀请1位伙伴来分享：\u003c/p>\u003cp>好，时间到，陈芳老师您愿意用1分钟时间来分享一下自已是如何将解决冲突五步法运用在刚才的设想场景中。陈芳老师的分享如下。\u003c/p>\u003cp>我运用赵老师给我们分享的解决冲突步伐来解决一下刚才我与我先生的那个冲突。分享如一下\u003c/p>\u003cp>1表达我的需求。小女儿不适合画画。\u003c/p>\u003cp>2丈夫的需求， 画画能够提升拓展思维。\u003c/p>\u003cp>3确认需求。认彼此的需求，就是都希望小孩子好。\u003c/p>\u003cp>4同理对方。能明白对方想为孩子将来设想的心情。\u003c/p>\u003cp>5提出解决方案。因为都是想为孩子好，所以站在孩子的立场上去分析。孩子是最适合画画还是唱歌。按着孩子的优势来培养他。\u003c/p>\u003cp>结尾：\u003c/p>\u003cp>再次感谢陈芳老师的精彩分享，让我们进一步学习了“化解冲突的步骤。”这个工具，让我们再次对这个方法有了更深的了解，现在让我来总结一下，我们今晚所学的主题是如何使用“暴力沟通化解冲突的步骤”这个工具帮助我们解决冲突。，主要是分成五步，第一步讲述自己的需要，第二步寻找他人的需要，第三步确知彼此的需要，第四步，尽力同理对方。第五步提出解决方法。希望今天的分享能给大家带来积极的启发，我的分享到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1684045444000,"updated_at":1684732396000,"ria":true},{"id":15774,"topic":"如何不带任何情绪，不急不躁，恰如其分诚实的表达出我们内心对美好事物真实的感受。","learn_goal":"","remark":"我们常常把夸奖当初杀手锏，批评不好使的时候就一顿夸奖，当时觉得特管用，但是，实际上一些夸奖很空洞也很片面，甚至是加入我们自己的评判标准，我们觉得很好，但是当事人不一定认同，甚至给人一种敷衍的感觉。效果并不好，而欣赏是透过现象看到实物本质，从事物本身看到积极、正能量的一面。所以，欣赏是很具体的，客观的姿态，不带任何情绪，不急不躁，恰如其分诚实的表达出我们内心对美好事物真实的感受。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"晚柠-","city":"鄂尔多斯市"},"club":{"name":"鄂尔多斯天骄分舵","city":"鄂尔多斯"},"prologue":"\u003cp>\u003cstrong>分发拆页、分组、打招呼】时间：30&quot;\u003c/strong>\u003c/p>\u003cp> 不破不能立，不拆不成器，大家好！我是一级拆书家的晚柠，很高兴我能站在这里和大家分享拆页。绘本老师、终生学习爱好者、运动爱好者是我目前的三个标签，因为打算践行终身学习者的理念，所以加入到拆书帮学习，期待和伙伴们一起成长，相互学习。\u003c/p>\u003cp>【分组】咱们今天天气不好就选择线上拆书，线上拆书咱们没有超过六个人就统一分成一组。\u003c/p>\u003cp>\u003cstrong>【图书介绍FAB法】时间：30&quot;-2‘10&quot;\u003c/strong>\u003c/p>\u003cp>F特征（核心是“书”，用于满足好奇心）：我今天的拆页选自《非暴力沟通》，作者是马歇尔•卢森堡。这本书不仅帮助人们在生活和工作中利用非暴力沟通，实现良好的的倾听和表达，还帮助了许多国家之间解决争端和武力冲突。\u003c/p>\u003cp>A优势（重点是比较，用于建立安全感）：这本书豆瓣评分8.4分,全球销售破万。并且获得了各种国际大奖。而且咱们拆书帮的实录里面就有726篇关于非暴力沟通的实录，可见这本书有很大的阅读价值。非暴力沟通和一般沟通类书籍相比，非暴力沟通发现了沟通中的隐蔽暴力危害，它更注重倾听和表达，更深入探讨心灵深处的的感受和和需求，从而达到更高效、和谐的沟通。\u003c/p>\u003cp>B1（强调学习者利益）：俗话说：&quot;你赚的钱12.5%来自于知识，87.5%来自于人际关系，所以不管是想获得成功还是和谐美好的生活，建立良好的人际关系都非常重要，通过学习“非暴力沟通”采用描述事实、感受、需求、请求几点要素，实现和谐美好的人际关系，从而打开通往幸福人生道路的绿色通道。\u003c/p>\u003cp>\u003cstrong>【学习总目标】2‘10&quot;-2’30&quot;\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA拆书活动后，小伙伴们通过欣赏四步法和诚实表达四步法，让旁边的小伙伴在理解和信任我们的前提下，彼此能够更真诚的表达出自己具体需要。(拆页一和拆页成递进关系)\u003c/p>\u003cp>\u003cstrong>【学习目标1】\u003c/strong>在跟随我完成拆页一RIA现场学习后，小伙伴通过学习欣赏四步法，找到一件他人令你欣赏的事儿，并且在A1环节分享给大家。\u003c/p>\u003cp>\u003cstrong>【学习目标2】\u003c/strong> 在跟随我完成拆页二RIA现场学习后，学习者可以运用诚实表达四步法，现场通过角色扮演，向对方提出具体的行动要求。\u003c/p>","ratings_count":2,"texts":[{"id":19861,"quote":"\u003cp>\u003cstrong>拆页一\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【R】阅读原书拆页一2‘32&quot;-3’33&quot;\u003c/strong>\u003c/p>\u003cp>如何表达欣赏?\u003c/p>\u003cp>参与者十六:你能否说一说，为了表达欣赏你所需要的三点是什么?\u003c/p>\u003cp>马歇尔:我们需要三点来表达欣赏--不是夸奖，因为非暴力沟通中没有所谓的夸奖。夸奖是一种典型的评判技巧;管理者喜爱夸奖，因为他们声称研究表明，如果每周至少夸奖下属一次，下属会表现得更好。在员工意识到其中的操控意味之前，夸奖确实会起一阵子作用。在非暴力沟通中，我们给予欣赏，从来都不是为了在别人身上起到什么效果。我们给予欣赏不只是为了赞美，让他们知道，我们对他们做的某些事感觉多棒。这三点是:\u003c/p>\u003cp>V对方做了哪件让我们欣赏的事情，对此我们心中有数\u003c/p>\u003cp>√我们的感受\u003c/p>\u003cp>√我们已得到满足的需要\u003c/p>\u003cp>\u003cstrong>【学习目标1】\u003c/strong>在跟随我完成拆页一RIA现场学习后，小伙伴通过学习欣赏四步法，找到一件他人令你欣赏的事儿，并且在A1环节分享给大家。\u003c/p>","explains":"\u003cp>\u003cstrong>拆页一\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【分享I便签】\u003c/strong> \u003cstrong>3‘52&quot;-9’39&quot;\u003c/strong>\u003c/p>\u003cp>（what）:这个拆页通过三点让我们理解如何欣赏别人，且不做评判的夸奖，从而让我们彼此都感到身心愉悦，收获信任。\u003c/p>\u003cp>  (why)如果我们不用这个方法，而常常采用夸奖这个杀手锏，那你的说辞难免空洞且片面，甚至给别人一种敷衍的感觉，效果并不长久。但是欣赏呢，它是透过现象看到事物本质，从事物本身看到积极、正能量的一面。所以，欣赏是很具体的，客观的姿态，不带任何情绪，不急不躁，恰如其分表达出我们内心对美好事物真实的感受。\u003c/p>\u003cp>（反面例子）在生活中很多人确实是不会表达欣赏的。拿我来举个例子，我和我对象最近开始尝试经营一下自己的生活，之前我们在各自的家里让贯的，基本不怎么做家务，那待在一起也没有别人帮忙，得自己动手丰衣足食。当时我心里想：“他可能也会像我听到的那些新婚的男士们，整日与手机为伍，肯定也不做”。但是，万万没想到，我做完饭，他主动提出我们分担家务----收拾厨房、刷碗。我当时就说：哈呀，你还会干家务呢?他说：“你以为就你会了”当时心理多少有点不舒服，也就各自玩各自的撇开了这个话题。\u003c/p>\u003cp>  (how)听完这个例子你可能会想：这不就是我的日常嘛，那我怎么才能发现身边的人值得欣赏的地方呢？然后还怎么能恰当表达出对对方的欣赏之意呢？那么我就在这里细化出四个步骤来供大家参考：\u003c/p>\u003cp>\u003cstrong>（第一步和第二步由原文的第一点细化而出的步骤）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：列清单\u003c/strong>\u003c/p>\u003cp>观察他们做出的哪些事情值得欣赏。这点判断比较难，是需要你去留心观察和思考。比如，你的同事最近的工作出错率明显下降；最近孩子在能在课堂上认真听讲了，不在和同学交头接耳；你的另一半慢慢的帮着你一起分担家务了。那这些发生改变的的事情，开始向好的方向发展或者正能量的事情就是值得欣赏的事。\u003c/p>\u003cp>\u003cstrong>第二步：找关联\u003c/strong>\u003c/p>\u003cp>找出与我有关值得欣赏的事件。值得欣赏的事儿挺多，但是，不关乎自己的情况下感受也并不会那么深刻。\u003c/p>\u003cp>\u003cstrong>第三步：表感受\u003c/strong>\u003c/p>\u003cp>描述具体值得欣赏的事件+你的感受。你做....让我感觉（开心、难过、伤心...）\u003c/p>\u003cp>\u003cstrong>第四步：提需求\u003c/strong>\u003c/p>\u003cp>需求得到满足，表达你的谢意。谢谢你满足了我……（亲近的人还可以使用肢体语言）等。\u003c/p>\u003cp>\u003cstrong> 【加工成正面例子】\u003c/strong>通过学习表达欣赏的四步骤，我意识到我自己在欣赏对方方面做的不够，如果回到刚才的例子，我怎么表达对对象的欣赏呢？第一步，列清单。他做事细心，情绪稳定，工作中热心帮助同事。第二步，找关联。他帮着我一起收拾厨房、帮我刷碗。第三步，表感受。我会和他说：“哇塞！博伟你把桌子、厨房收拾的好干净，而且你主动承担洗碗这件事让我觉得特别开心。第四步，提需求。你满足了我也是需要被帮助的需要，谢谢你博伟，拥抱一下’’。我想我们彼此会感受到愉快的。\u003c/p>\u003cp>（where）\u003c/p>\u003cp> 那这个拆页的适用范围是，你想进一步促进良好的关系，增加信任时，比如亲子关系，亲密关系，合作关系是非常有帮助的。但是，也不是随便使用，比如随便一个甲乙丙丁，你也不和他们有深层链接，其实也不需要花费这个精力。\u003c/p>\u003cp>\u003cstrong>【预防可能的异议】\u003c/strong>\u003c/p>\u003cp>可能有伙伴心理会想：说话之前还得思考第一步，第二步…那在实际生活中太难做到了吧。难，是我们感觉很难，你可以从微行动开始，哪怕每次你只用一个条也行，慢慢的尝试其他步骤，随着时间的推移，表达欣赏这种沟通技能也就信手捏来啦。不要害怕困难，先从尝试其中一个步骤开始，相信你们一定会做的很好。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆页一\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1】（激活学习者经验） 显像提问\u003c/strong> \u003cstrong>3分钟\u003c/strong> \u003cstrong>9‘40&quot;-13’24&quot;\u003c/strong>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>小伙伴们，你回忆一下，有没有类似的让你想表达欣赏的的场景？\u003c/p>\u003cp>比如：\u003c/p>\u003cp>1.你想和你另一半增进感情，最近观察到他身上值得让你欣赏的事儿。\u003c/p>\u003cp>2.想增进你和同事的信任度，有意观察到他们身上值得欣赏的点。（具体一点的情景）\u003c/p>\u003cp>3.你的下属在你出差的几天里出色的完成了那些你交代的很难的工作。\u003c/p>\u003cp>4.你的孩子完成了平常根本做不到的事儿。\u003c/p>\u003cp>5.你和你的朋友约定一起减肥，你三天打鱼两天晒网，但是，你的朋友非常有韧性，经过一定时间的坚持有很好的效果，你很欣赏她/他的态度。\u003c/p>\u003cp>【接下来请你花费30秒回忆一下自己的相关场景】\u003c/p>\u003cp>小伙伴们用1分钟在组内分享一下让你们很想表达欣赏的的场景。\u003c/p>\u003cp>由于时间关系我们请小伙伴们分享一下？\u003c/p>\u003cp>1. 【冉馨案例记录】：我要买去旅顺的机票，当时是我老公提出帮我买。买的时候他就很细心的考虑一些我没关注到的细节。当时去北京有两趟航班，有一趟比较晚上但是比较便宜，我说要不就订晚上的吧。我老公他就说订早上的，我当时也没有想太多，我说：“你自己看着定。”然后就他订了，结果订完以后，我才发现定的是早上的。我就询问老公晚上那趟价格不是更适合吗？他就跟我说：“你心真大，晚上的飞机到了那儿以后太晚了，可能大兴机场那个时候已经没有地铁了，你又带着孩子，万一有危险，或者是太晚太冷怎么办。”我老公他考虑的事情很周到，能关照到我想不到的问题，我很赏心他对我贴心的一面，让我感觉他对待我们的生活很用心。\u003c/p>\u003cp>【拆书家反馈】姐夫真的是非常暖心 ，举动很值得欣赏。\u003c/p>\u003cp>2. 【龙肖行案例记录】：大家也知道我比较忙，不管是单位工作，还是我的攀岩事业也好，还是包括咱们拆书帮的工作也好，总之我很忙。所以我家两个孩子的生活和教育都是由我老婆一个人在全全负责。我老婆她也是老师，她也很忙。但是我老婆在照顾家庭这一点上，真的让我感到自愧不如。同时她做的很多事情很值得我欣赏，尤其她照顾两个孩子方面，每天五点多就起床为孩子们准备早饭。晚上回来还要陪孩子学习、整理孩子们用过的东西，还要准备第二天的好多需要准备的东西。以前没觉得这些东西有多么多么难，但是我自己做了几次后说实话真的很不容易。妻子的坚持与付出特别值得我欣赏。\u003c/p>\u003cp>【拆书家反馈】嫂子默默的付出很值得你的欣赏。\u003c/p>\u003cp>\u003cstrong>【A1+】 （学习者反思加工经验）13‘25&quot;-17’28&quot;\u003c/strong>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>1.刚才大家有回顾了自己关于欣赏的场景，那么现在再回顾一下今天拆页的内容：\u003c/p>\u003cp>第一：列清单\u003c/p>\u003cp>第二：找关联\u003c/p>\u003cp>第三：表感受\u003c/p>\u003cp>第四：提需求\u003c/p>\u003cp>接下来请小伙伴们回到刚才分享的场景中，再给你一次机会，运用今天学习的方法你会如何向对方表达欣赏之意呢？\u003c/p>\u003cp>【龙肖行分享记录】按照今天拆页学习的步骤的话，首先就是我在空闲的时候腾出一点时间认真的回想一下我和我妻子的生活，尤其这几年当中我家老大上小学了，我们家就更忙碌了。而老婆在这个家里面则付出的更多，比如她每天早上起来给全家人做早点、每天下了班收拾家、洗衣服……拿我来说我开会穿正装，休息穿休闲装，攀岩工作又穿运动装。这样一周下来衣服换的也非常多，我妻子任劳任怨帮我打理，还有在疫情期间又养狗养猫，家里整个是鸡飞狗跳。其实他做了很多值得我欣赏的事情，我要在空闲时间罗列出一个清单。第二步。找关联。我每周出现的场合比较多，需要各类型服装，有时候去开会需要正装，那有时候我运动需要运动装，我有时候我又参加休闲活动需要休闲服。衣服经常换，每次换下的衣服下一次穿的时候都是干干净净的。妻子帮我勤勤恳恳打理衣服我觉得很欣赏她。第三步，就是我应该找一个机会表达出我的感受。告诉我的妻子她默默帮我收拾、洗衣服让我非常非常的感动。然后最后也会明确的告诉她：“你的默默付出满足了我那种被照顾的需求”，因为我的家庭情况你们也清楚，其实小时候还是比较缺乏关爱的，在这个点上我妻子给到了我满足被照顾的需要。\u003c/p>\u003cp>【拆书家反馈】感受到爱就要用心表达出来，掌声送给龙肖行。感谢龙肖行的分享，看来你今天充分学习到了拆页的内容。首先罗列出你爱人值得你欣赏的方方面面，然后又找到和你相关联的部分，其次，又表达了她做这些事情你的感受，之后你又提出了她满足了你被照顾的需求，表达非常完整。谢谢你给我们的分享，同时我也感受到家人之间表达欣赏是多么重要的一件事。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":19908,"quote":"\u003cp>\u003cstrong>【R】阅读原书拆页二\u003c/strong> \u003c/p>\u003cp>\u003cstrong> 1.5分钟\u003c/strong> \u003cstrong>17‘36&quot;-18’57&quot;\u003c/strong>\u003c/p>\u003cp>现在请大家用1.5分钟的时间阅读。读完后请抬头示意我一下。\u003c/p>\u003cp>选自《非暴力沟通》P6\u003c/p>\u003cp>为了彼此能乐于互助，我们专注于四个方面--非暴力沟通模式的四个要素。\u003c/p>\u003cp>首先，留意发生的事情。我们此刻观察到什么?不管是否喜欢，只是说出人们所做的事情。要点是，清楚地表达观察结果，而不判断或评估。接着，表达感受，例如受伤，害怕，喜悦，开心，气愤等等。然后，说出哪些需要导致那样的感受。一旦用非暴力沟通诚实地表达自己，前三个要素就会得到体现。\u003c/p>\u003cp>举例来说，一位母亲可能对她处于青春期的儿子说:“菲利克斯，看到咖啡桌下的两只脏袜子和电视机旁的三只，我不太高兴，因为我看重整洁。”\u003c/p>\u003cp>接着，她立即提出非暴力沟通的第四个要素--具体的请求:“你是否愿意将袜子拿到房间或者放进洗衣机?”这一要素明确告知他人，我们期待他采取何种行动，来满足我们。\u003c/p>\u003cp>这样，这位母亲就清楚地说出非暴力沟通的四个要素。借助这四个要素诚实地表达自己，是非暴力沟通的一个方面。\u003c/p>\u003cp>\u003cstrong>【学习目标2】\u003c/strong> 在跟随我完成拆页二RIA现场学习后，学习者可以运用诚实表达四步法，现场通过角色扮演，向对方提出具体的行动要求。\u003c/p>","explains":"\u003cp>\u003cstrong>【分享I便签】\u003c/strong> \u003cstrong>19‘20&quot;-22’03&quot;\u003c/strong>\u003c/p>\u003cp>【what】这个片段主要通过四个要素来说明如何实现诚实沟通。\u003c/p>\u003cp>【why】不这么做的坏处：\u003c/p>\u003cp> 如果你不塑造诚实沟通的思维模式时，你可能一张嘴就“杀敌一千”还不知道别人为什么要远离你，这样为了趁口舌之快，而伤害彼此的情感。\u003c/p>\u003cp> 你学习了诚实沟通的四要素，你可能有意识的规范自己的语言，既表达出自己内心最深处的真情实感，也让彼此双方感到舒适，真诚。这不就是大家想努力成为的高情商嘛。\u003c/p>\u003cp>【how】我通过阅读原文拆页，总结出实现诚实沟通的四个步骤：\u003c/p>\u003cp>第一：讲具体事。我看到/听到/感受到…\u003c/p>\u003cp>第二：表感受。例如，我感到…（开心、愉快、难过、伤心…）\u003c/p>\u003cp>第三：说需要。我需要你的…关心、爱护、理解…\u003c/p>\u003cp>第四：提具体请求。前面三步是在为最后一步作准备，为了让大家更好理解我就给大家举个例子。\u003c/p>\u003cp>\u003cstrong>【异议案例】\u003c/strong>：今天我在绘本馆给大家讲故事时，有一位小朋友大声唱起了歌，我就对这个正处于自我意识敏感期的2岁宝宝说：在老师讲故事的时候大你声唱歌，老师觉得很生气，因为我需要安静的听众。”接着，我立即提出诚实沟通的第四步--具体请求：“宝宝你是想在旁边休息一下再来听故事呢？还是想现在安静下来认真听故事？明确告诉小朋友，我们期待他采取的行动，来满足我们的需求。\u003c/p>\u003cp>【where】：诚实沟通适用于那些你认为你很重要的，不想因为自己不会表达而破坏的长久关系中，相反一些无关紧要的人也没太大必要花费那么大精力，一板一眼的按流程说话。\u003c/p>\u003cp>【预防异议】可能有小伙伴想我也觉得诚实沟通挺重要，也挺好。但是，我情绪一上来哪还有理智可言，一顿大发雷霆完事。但是，你想想啊，你是痛快了，对方心里可能憋着一口气，或者留下一道深深的伤痕，时间久了坏情绪越积越多，矛盾也会越来越深，那个时候想轻易解开心结可就很难了。所以，能用和平的方式沟通、解决问题，难道不是更好？\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3促动参与】22‘19&quot;-22’41&quot;\u003c/strong>\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>我们刚刚学习了诚实表达的四步法。为了让大家更好的理解学到的知识，现在请大家一起做个现场演练，我会给大家一个场景，请大家针对这个场景，使用诚实表达的四个步骤来进行演练。请大家认真听要演练的场景：\u003c/p>\u003cp>场景1.\u003c/p>\u003cp>（角色一）旺仔爸爸 （角色二）旺仔妈妈\u003c/p>\u003cp>周五上午，旺仔兴趣班老师通知下午2：30上书法课，当时旺仔妈妈有事儿就安顿旺仔爸爸去送娃娃，旺仔爸爸怕忘还写在备忘录上，结果下午把正事抛诸脑后而是带着娃娃去逛了游乐园。晚些时间书法老师就给妈妈打过电话来。问旺仔妈妈孩子怎么没去上课呢？一听这话，旺仔妈妈气不打一处来。平时就她自己带孩子，今天她有事儿，结果就这。想等父子俩回来劈头盖脸骂他们一顿，但是，旺仔妈妈坐在沙发仔细一想，“骂一顿也不是好的解决办法呀，可能骂完爸爸更帮不上忙了”，那妈妈该如何运用诚实沟通的四步法向爸爸提出具体要求呢?\u003c/p>\u003cp>【指令】小伙伴们对角色有没有疑问，或者有没有不理解的地方？我可以给解释。\u003c/p>\u003cp>给小伙伴们2分钟分别在小组内讨论一下，可以分别扮演场景中旺仔爸爸和旺仔妈妈的角色，帮助旺仔妈妈运用诚实沟通四步法向爸爸提出具体要求的同时还避免一场争吵。\u003c/p>\u003cp>【讨论时间到】小伙伴们都回到我这里，现在邀请一组小伙伴进行角色演练。\u003c/p>\u003cp>\u003cstrong>【演练分享】26’46&quot;-31‘25&quot;\u003c/strong>\u003c/p>\u003cp>角色一旺仔爸爸-饰演者冉馨\u003c/p>\u003cp>角色二旺仔妈妈-饰演者尚老师\u003c/p>\u003cp>旺仔爸爸：等等……我们回来啦。\u003c/p>\u003cp>旺仔妈妈：你们回来了。\u003c/p>\u003cp>旺仔爸爸：今天可是玩儿好了，游乐场关门儿了都不回家。\u003c/p>\u003cp>旺仔妈妈：哎呀！你俩可是开心了是哇？\u003c/p>\u003cp>旺仔爸爸：挺开心的。\u003c/p>\u003cp>旺仔妈妈：那你能不能坐在沙发上，让娃娃先进屋玩儿一会儿，我有事情跟你谈一谈。\u003c/p>\u003cp>旺仔爸爸：能呀！\u003c/p>\u003cp>旺仔妈妈：说实话，其实我现在可生气了。\u003c/p>\u003cp>旺仔爸爸：为什么？\u003c/p>\u003cp>旺仔妈妈：这一下午气的我肚子都快要炸了。\u003c/p>\u003cp>旺仔爸爸：为什么生气？\u003c/p>\u003cp>旺仔妈妈：我看你到现在都没反应过来自己干了啥？今天两点半孩子是不是有书法课？我是不是之前嘱咐你一定要记得带孩子去上兴趣课？到现在你还没想起这件事呢？这，你能不让我生气吗？\u003c/p>\u003cp>旺仔爸爸：哎呀！不好意思，你不说我还真给忘了。你看我的备忘录上边儿还记着两点半去上书法课。但是，后来就真的忘了。\u003c/p>\u003cp>旺仔妈妈：对，我能感觉到你开始自责了。就是之前我确实跟你千叮咛万嘱咐让你记得上两点半的书法课，结果你到点儿竟然没去。书法老师给我打电话说孩子没去上课的时候，我当时一下子就气炸了。我想立即跟你打电话去责备你，我真的是要被气死了。但是，我又静下心想了想，生气也不能让你马上送孩子去上课。其实我特别需要你帮我分担一些孩子的教育，还有就是孩子上兴趣班的时候，你可不可以接送一下孩子？如果能辅助我一下我心里面就会特别特别感激你。比如说下个周六咱家孩子还有兴趣班嘛，我希望你能准时准点儿的送到教室，你看可不可以？\u003c/p>\u003cp>旺仔爸爸：行，首先我对我今天这个粗心的行为跟你道歉，因为平时孩子就你带的多，我带的比较少。那这样的话，下周上课的话我就接送他去上课。然后慢慢也就习惯接送孩子这个事儿了。\u003c/p>\u003cp>旺仔妈妈：今天下午刚面对这个事儿的时候就特别想骂街，觉得已经忍无可忍一定要爆发一次，然后坐在家想了一想，觉得咱们俩之间应该好好沟通一下，然后你今天晚上这样跟我讲话的我心里觉得舒服多啦。\u003c/p>\u003cp>旺仔爸爸：我也很感谢你没有一进门就骂我，而是和我好好沟通。\u003c/p>\u003cp>旺仔妈妈：哈哈，我上午听了非暴力沟通的课，学习怎么进行诚实沟通，这不就在实践中练习到啦，如何提出自己的需要。我也反思了一下自己在过去总是指责你，也没提出自己的需求，今天能清晰的把自己的需求说出来也挺不容易的。\u003c/p>\u003cp>旺仔爸爸：我也感觉欣慰哪。\u003c/p>\u003cp>【拆书家反馈】感谢俩位小伙伴，我想给你们鼓掌。两位小伙伴清晰运用到今天学习的四个步骤，首先提到没有带孩子上兴趣班这个具体事情，然后表达出爸爸没带孩子上课这件事让妈妈气炸了，但是妈妈顺利的提出自己内心深处的需求，没有一味指责爸爸，明确告知爸爸需要得到爸爸的帮助。感觉大家已经很好的吸收了本篇拆页内容。谢谢俩位小伙伴的分享。\u003c/p>\u003cp>\u003cstrong>【A2催化反应】32‘02&quot;-31‘25&quot;\u003c/strong>\u003c/p>\u003cp>分步催化1（2分钟）拆书家提问设计\u003c/p>\u003cp>【拆书家描述使用场景的案例】\u003c/p>\u003cp>三天后的一个傍晚，你想要计划下周的生活和工作，你就想起今天学的拆页内容，你内心一阵热血沸腾，决定好好留意一下生活中需要调整的沟通的情况。比如你日常和你的另一伴因为孩子教育问题有分歧；你的孩子每天一放学回到家把衣服扔得到处是；你的合作伙伴总是临时改变你们的既定方案；你朋友们在一起老是揭你的短儿…你采用诚实沟通四步法如何与他们沟通一下，并且顺利提出你的具体要求。接下来请你设想一个你自己的场景并和小组成员分享一下。\u003c/p>\u003cp>由于时间关系我请一位学习者给大家分享一下你设想的情景。\u003cstrong>33‘52&quot;-38‘35&quot;\u003c/strong>\u003c/p>\u003cp>1.【冉馨分享】\u003c/p>\u003cp>你今天过的这个级的拆页，让我立即想起今天发生的事儿。感觉特别好。我们单位今天下午要开一个比较大的一个党委会，然后我徒弟和我在上午要准备一些会议的相关的准备工作。我们首先要做那个喜卡和椅子上贴的名字。我一直觉得我徒弟她是一个执行力非常强、且也善于动脑的人。但是，这一次我却注意到她没有思考，打座签竟然是用白纸打。因为白纸不是很合适嘛，这是我经历的一个场景。\u003c/p>\u003cp>2.【尚老师分享】\u003c/p>\u003cp>我家孩子辅导作业上是需要爸爸经常帮助的。因为我不懂蒙语，我是汉族，爸爸是蒙古族。我们家小朋友如果蒙语作业上遇到不懂的时候，爸爸的第一反应，就是你去查字典，事实上孩子在问问题之前，他也就已经查过字典了，字典查不到，爸爸就说他查的不仔细，每次在这个时候，我容易跟他起冲突。\u003c/p>\u003cp>3.【龙肖行分享】\u003c/p>\u003cp>我和尚老师的挺接近的。因为家里有娃，而且我家老大现在不是刚上一年级嘛，其实玩儿性还比较大，老二还上幼儿园。所以老大写作业，老二在玩儿，这老大心就飘了，他就老想看她妹妹在干啥。在老大没上一年级以前我设想自己一定会正面去对待，也不会把情绪发泄在孩子身上。但是，现实往往都是情绪的表达，我觉得今天学完这个拆页，其实应该可以把自己内心真正的想法表达出来，哪怕她只是个孩子，也需要诚实的沟通啊，这是我想到的一个场景。\u003c/p>\u003cp> \u003cstrong>【A2】分步催化2（12分钟）\u003c/strong>（\u003cstrong>44‘41&quot;-56‘05&quot;\u003c/strong>）\u003c/p>\u003cp>谢谢冉馨、尚老师、龙肖行三位小伙伴的分享，看来在座的都是渴望进步的小伙伴，那么接下来请小伙伴们选定一个最贴近你生活的场景，运用刚学习的诚实沟通四步法，列出在你未来的生活中如何运用诚实是沟通四步法的计划。完成计划表的小伙伴可以在组内先分享一下你的计划。\u003c/p>\u003cp> 时间到，接下来请小伙伴分享下\u003c/p>\u003cp>1. 【冉馨计划分享】：就我们准备喜卡和椅子上贴的名字这件事我打算明天去跟她谈谈。因为今天我看了他这个行为我其实什么也没做。然后明天我就去和她沟通一下。她用白纸打名字的事情让我很意外，首先我对他的期望值是比较高的。觉得我每个月在开会前准备资料她看我们在做的时候，我认为他是应该学到了。但是，没想到她没注意我平常怎么做。然后我要表达的感受就是：“你用白纸打名签我感到很意外，可能是因为我平时教的没有那么全面，然后导致你没意识到不可以用白纸打名签。”表感受。因为我对你的要求是比较高的，认为我不用教，你自己可以从别人那里自学到的，我一直认为认为你是学习力很强的人。当你出现这种不应该犯的错误时我觉得很意外。表达需求。会议上拿白纸打名字是会议禁忌，这算是会议事故。我的需要让会议顺利完成，不能有一点点的差错瑕疵。具体要求就是以后有不管是党委会或者其他会议，只要涉及到行政相关的一些会议呀，我们需要注意不能用白纸打名字。\u003c/p>\u003cp>【拆书家反馈】掌声送给冉冉姐，谢谢你分享，不能用白纸打名签这个禁忌我其实也不知道，今天冉冉姐讲了这个事情，让我也意识到了以后就打名字切记用白色的纸打。算是一个很好的警醒。那接下来有请尚老师。\u003c/p>\u003cp>2. 【尚老师计划分享】我计划明天晚上八点和我老公谈谈，今天正好人不在家。\u003c/p>\u003cp>【反馈】蓄势待发呀！\u003c/p>\u003cp>蓄势待发的事件就是陪孩子写蒙语作业，第一步是孩子有不会的题，我会跟孩子他爸说；“孩子有不会做的题，你就让他查字典，他没有查到，你就觉得他粗心，实际上他不会，蒙语里词中词尾的那些个变化对于新学的人来说很难，它从左边绕弯弯和从右边绕弯弯，它就是一个词尾的变化，就是孩子是没有掌握好，不是他粗心，我觉得孩子其实一直觉得很委屈，而且他被你批评之后仍然不会，还觉得自己很笨，作为母亲我看到这些也挺难过的，我不希望学习带给他的都是挫败的感受。“第三步就是我好希望你可以更好的理解孩子一些，他是真的不懂，也不是他懒，他心里面也特别着急。第四步。我特别希望你可以给他讲一讲蒙语里面词尾词中的变化，如何从字典里能够高效的查到这个词，希望在你的陪伴之下，掌握一些高效的查字查词的方法，让孩子慢慢掌握，我相信咱家孩子会学的很好。\u003c/p>\u003cp>【拆书家反馈】 尚老师的要求非常具体和清晰，教给爸爸要怎么去帮助孩子去学习蒙语，如果我是孩子的，我一定会感谢有这样的妈妈。作为老师首先我能理解，孩子不是不想学，他可能是真的有困难，尚老师清晰的要求对我都很受用，谢谢尚老师的分享。\u003c/p>\u003cp>3. 【龙肖行计划分享】刚才尚老师的分享我听的很认真，我的同事也有很多是蒙古族的，然后也知道这个蒙语不太好学，和我们汉语其实差别特别的大。然后刚才听完，原来是这么个原因---关键是词尾不一样阿，在我看来都长得都一样，今天我也受教了。\u003c/p>\u003cp>那我说一下我的例子啊，还是关于我女儿写作业的事情。大家都知道我计划星期五下午要带着我女儿去长沙，参加咱们拆书帮十周年庆典，机票也都订。我给我女儿周五下午请了一下午假，拿这就涉及到一个提前完成作业的事情，以前别提前完成作业了，就是当天作业完成起来都比较拖沓。所以，这一次就借着这个机会要和他去谈一谈，这周周2、3、4怎么提前能把周末的作业写完。要聊的具体的事情。我说：“女儿我看到你把今天的作业写完了，非常好，但是老爸想和你商量一下咱们星期五下午就要坐飞机去长沙玩儿，期间我们就没有时间去写作业，而且你的作业又要必须在周日完成，因为星期一你要交的。”第二呢，说感受。我会和女儿说：“老爸我非常信任你一定会提前完成周末作业的。”因为我知道他写作业写的挺慢，当然我一直也不是很着急，因为我总觉得就是慢归慢，但是他只是去做就很好。毕竟刚上小学专注力还比较短，还老受妹妹的影响，或者旁边儿有个啥好玩儿的他的注意力就会跑掉，但是如果他要认真去做还是一定能完成的。所以我一定会去表达我对女儿的信任的。第三，提出具体需求。姑娘我们要一起出去玩儿，那这就是我们两个人的事情，我把我的工作交接完，你把你的作业写完。这样我们去了长沙就可以全身心投入不管是玩儿，还是参加活动，我们就心无旁骛的去做，对吧？第四步呢，我就要提出具体的要求。那你从明天开始，你就要周二就要把周三，甚至周四的作业写了，那你周四就要把周五甚至周六的作业写了，最差的结果也是你只留下一点作业，我们周日晚上回来以后可以少补一点作业。我们应该是周日晚上七点回来，这样留下的作业也是简单的作业比如说预习课文这类的，这样的作业也可以顺利完成。\u003c/p>\u003cp>【拆书家反馈】我觉得无论计划还是安排都非常的合理，你给女儿讲清楚这个事情，她可能心里面儿也会抓紧要完成这个事情，我们相信你姑娘一定能按时完成。\u003c/p>\u003cp>三位小伙伴们的分享的故事很贴近生活，相信你们肯定也会达成好的沟通效果，以一种特别高效的方式去解决问题。诚实沟通，它可以很好的帮助我们建立更好的关系。\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>仁者见仁，智者见智。好的沟通能减少80%的困惑，遇到正能量的事情积极表达我们的欣赏，遇到不如意的事情也可以平和的处理。让我们能更好的做到知彼解己。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1683562913000,"updated_at":1684979157000,"ria":true},{"id":15752,"topic":"非暴力沟通之得体表达感激","learn_goal":"","remark":"很多人以为良好的沟通就是好好说话，\n但是职场表达感激最重要的是要“有效”\n——也就是要有实质性的结果，\n跟随我一起来学习“表达感激三步骤”，\n通过学习表达感激的三步骤，\n清晰呈现被帮助后的事实结果及个体感受，促进双方关系。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"皇甫胜男","city":"上饶"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp> 大家好，我是皇甫，今天我们学习的拆页是《非暴力沟通》的如何表达感激。为了方便讨论，我们先来分组，从我的右手边开始，相邻的两位小伙伴为一组，以此类推。\u003c/p>\u003cp>我先介绍下今天要拆的书籍，《非暴力沟通》是美国心理学家马歇尔·卢森伯格所著的一本书，介绍了一种通过有效的沟通方式解决冲突和构建良好关系的方法。这种沟通方式强调表达真实感受和需求，尊重对方的感受和需求，并找到一种合作的解决方案。该方法已被广泛应用于包括婚姻、家庭、教育、医疗和商业等不同领域。\u003c/p>\u003cp> 现在请大家用1分钟的时间阅读刚刚拿到手上的拆页。\u003c/p>","ratings_count":1,"texts":[{"id":19835,"quote":"\u003cp>R：在赞扬他人时，我们很少揭示内心活动，而把自己放在了裁判的位置。赞扬也常常被人用来实现个人目的。非暴力沟通鼓励我们充分表达感激。\u003c/p>\u003cp>在表达感激时，我们说出：\u003c/p>\u003cp>(1）对我们有益的行为；\u003c/p>\u003cp>(2）我们的哪些需要得到了满足；\u003c/p>\u003cp>(3）我们的需要得到满足后，我们是什么样的心情。\u003c/p>\u003cp>当别人以这样的方式表达对我们的感激时，我们可以与对方一起庆祝生命的美﹣既不自大，也不假谦虚。\u003c/p>","explains":"\u003cp>【what】就像我们表扬孩子某些正确行为时通常会用“你真棒，你真聪明，你真能干”这一类的评判词语，而很少表扬孩子的具体行为及行为带来的影响。在表达感谢也一样，我们常常会用“太感谢了，你真是帮了我一个大忙；你是我的贵人”等之类的句式来表达，而很少考虑到描述对方的具体行为带给我们的心理感受和结果上的变化。\u003c/p>\u003cp>【how】作者在拆页中把感激步骤化，简单说来就是：\u003c/p>\u003cp>1：说事实：对方具体做了什么\u003c/p>\u003cp>2：讲作用：对方的行为，满足了我的哪些需求\u003c/p>\u003cp>3：谈感受：我们的心理感受怎么样\u003c/p>\u003cp>我的性格比较内敛，不太擅长表达自己，更很少像这样有流程地感谢别人的帮忙，我更多倾向于放在心里或者用行动去反馈，特别是在家庭关系中。\u003c/p>\u003cp>举个例子，我老公下班比我早半小时，在我到家之前，他都会炒好菜，边收拾厨房边等我，我出于感谢，通常就是饭后刷碗，几乎没有表达过感谢。\u003c/p>\u003cp>在我读了这个拆页之后，我意识到了表达的力量。\u003c/p>\u003cp>比如，在刚结束的年会活动上，我对邀请我报名的上饶光阴分舵的舵主就用这个步骤表达感谢：\u003c/p>\u003cp>晶晶，谢谢你每次有这样的学习活动，都会邀请我一起；这次参加活动，刺激了处于“躺平摆烂”状态的我，促使我重新去思考自己的现状，现在我被激活，感受到了些斗志。特别感谢你邀请我报名，也特别感激有你这样的朋友。\u003c/p>\u003cp>在听到我的表白后，她说她也特别感动于每次我都相信她、支持她，跟她一起。她说她也要感谢我。\u003c/p>\u003cp>【why】大家看看，前后两个不一样的例子，例子1给人感觉就是合作项目，没有情感的交流，而例子2不同，通过表达感谢，情感会再往上升华一个高度。\u003c/p>\u003cp>【where】这两个例子一个是家庭关系，一个是朋友关系，我认为这样的方式可以应用于包括、但不限于朋友，爱人，亲子，同事等各关系中。用我们真诚表达让对方感受到价值感，这对提升人际关系非常有益处。\u003c/p>","interaction":"\u003cp>好，现在请大家回想过去的一周、10天里，经历的帮助他人或被人帮助的情形，当时你们是怎么表达感谢的或者听到对方的感谢，你的感受是怎么样？大家可以跟小组伙伴做个交流，稍后我们请一位小伙伴来分享下。\u003c/p>\u003cp>学习者：前阵同学把他盘了三年多的一对很漂亮的核桃送给我，因为关系非常亲近，就没有特别刻意地表示感谢。现在想想还是觉得确实需要及时表达。下个月等他老婆过生日，我们再聚时再来好好表达感谢。\u003c/p>\u003cp>非常感谢这位小伙伴的分享，现在请大家结合拆页的“说事实，讲作用，谈感受”的表达感谢三步骤，用1分钟时间写出你的表达计划。\u003c/p>\u003cp>最后总结一下今天的内容，我们学习了表达感谢的三个步骤，分别是\u003c/p>\u003cp>1说事实：对方具体做了什么\u003c/p>\u003cp>2讲效用：满足了我的哪些需求\u003c/p>\u003cp>3谈感受：我们的心理感受怎么样\u003c/p>\u003cp>通过这样的表达，能让我们展现被帮助时具体的感受和积极的情绪变化，让对方感受到被尊重的价值感，从而促进关系和情感的双重升华。\u003c/p>\u003cp>好的，我今天的分享到这里就结束了，希望这个片段会对各位小伙伴有帮助，谢谢大家的聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1683279647000,"updated_at":1683507540000,"ria":true},{"id":15751,"topic":"用非暴力沟通，充分表达愤怒","learn_goal":"","remark":"在表达愤怒情绪的时候，\n既不委屈自己，也不伤害他人，\n同时还能表达我们愤怒背后的不满和需求，改善与他人的关系。\n通过学习愤怒四步骤，让我们学会正确表达在冲突时的内在需求","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"皇甫胜男","city":"上饶"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>大家好，我是皇甫胜男。我还有个妹妹，叫超男。哈哈，各位老师可以自行脑补这背后的故事 。皇甫原来不是皇甫，是皇父。是个古老的姓氏，有着2500年历史，是春秋时代宋国公族的后裔，汉朝时皇父鸾改父为甫。所以才有了我这个流落民间千年的贵小姐。\u003c/p>\u003cp>用三个标签介绍下自己\u003c/p>\u003cp>标签1：广告公司销售\u003c/p>\u003cp>标签2：徒步爱好者\u003c/p>\u003cp>标签3：身教践行者\u003c/p>\u003cp>接下来，我先简单介绍下拆书法和拆书帮。\u003c/p>\u003cp>拆书，是一种学习方法论，适用于提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心。\u003c/p>\u003cp>成人的学习，常常出现一本书读不完、记不住、不会用等各种学习困难，拆书法是一剂良药。它强调的是把知识拆为己用，转化成能力。拆书法分两种，一种是个人便签学习法，用来记录原文中与自己相关联的经历体验及未来的具体应用；另一种是组织学习法，也就是RIA三环节的现场学习法，R取自英文 “Reading”的首个字母指阅读原文；I是英文“Interpretation”的首个字母，指对原文进行讲解和引导；A是英文“Appropriation”的首字母。RIA是指通过阅读片段、引导促进理解并激活自身经验的学习法。\u003c/p>\u003cp>我们常说一个人走的快，一群人走的远。拆书帮是由赵周老师创建的非营利性学习组织，在全国有56个正式分舵和18个筹备分舵。在成人学习的路上，拆书帮的使命是致力于培养更多的拆书家，相互陪伴，助人达己。\u003c/p>","ratings_count":1,"texts":[{"id":19834,"quote":"\u003cp>今天我们学习的是马歇尔的著作《非暴力沟通》中的一个片段，请大家用1分钟时间阅读手里的拆页，读完的伙伴请示意我。\u003c/p>\u003cp>1. 停下来，深呼吸。\u003c/p>\u003cp>2. 看看我们有哪些评判性的想法。\u003c/p>\u003cp>3. 与我们的需求连结。\u003c/p>\u003cp>4 表达我们的感受和未被满足的需求。\u003c/p>\u003cp>来看看充分表达愤怒的具体步骤。首先，停下来，除了深呼吸，什么都别做；不去指责或惩罚他人，只是保持安静。接着，看一看，是什么想法让我们很生气。例如，无意中听到某人说了一些话，使我们相信自己由于种族的缘故遭到了排斥。感知到自己的怒气时，如果停下来，便会看到头脑中盘旋的想法：“这太不公平了！她这是种族歧视！”我们知道，所有的评判都在用可悲的方式表达未满足的需要。于是，接下来的第三步是：与这些想法背后的需求连结。如果指责某人是种族主义者，我们的需求也许是融洽、平等、尊重或者与人连结。\u003c/p>\u003cp>为了充分表达自己，我们要采取的第4步是开口表达愤怒——怒火此时已被转化为感受和需求。然而，表达此时的感受也许要很大的勇气。对我来说，生气并冲着人们嚷“你这样做是种族歧视”是很容易的，甚至还会感到很畅快。然而，要说出内心深处的感受和需求，却可能令人却步。为了充分表达愤怒，我们也许可以试着和对方说：“你走进房间后，开始与其他人聊天，却没有和我说话。接着，你开始议论有关白人的种种。当注意到这些时，我的胃非常不舒服，我也很害怕。这使我意思到，我非常希望受到平等的对待。我想请你告诉我，听到这些话，你的感受是怎么样的？”\u003c/p>","explains":"\u003cp>（what）通常情况下，我们愤怒的本质是因为内在的某种需求没得到满足而引起的情绪发泄，我们希望通过愤怒的表象，来抗议对方，希望对方能理解我们的意图并满足我们的需求。事实证明，结果注定是徒劳的，双方反而会因为愤怒情绪之下的口不择言，伤害了彼此的关系。\u003c/p>\u003cp>（why）正确而有效的愤怒，是通过表达感受来获得需求的满足。\u003c/p>\u003cp>（how）拆页中作者给出了4个具体步骤：\u003c/p>\u003cp>1.情绪暂停（我生气了，需要冷静）\u003c/p>\u003cp>2.追问原因，找出评判、争议的观点（是什么导致了冲突）\u003c/p>\u003cp>3.觉察出没被满足需求（我想要什么而？对方想要什么？）\u003c/p>\u003cp>4.表达感受和需求。\u003c/p>\u003cp>当然，由于我们的思维惯性和语言模式，我们会止步在表达需求之前。这种表达方式不是一蹴而就的，需要足够的时间来做刻意的练习才能达到很好的熟练度和效果。\u003c/p>\u003cp>（where）有一个需要注意的点，这个方法适用于非紧急状态下的双方，基于相互尊重且共同期待更好结果的前提才适用，在个体生命财产受到威胁或被他人恶意攻击时是不适用的。\u003c/p>","interaction":"\u003cp>A1:关联过往经验\u003c/p>\u003cp> 我举个我自己的例子。我老家有一幢自建房，因为常年在外省生活，每年就春节回老家待几天，住我妈妈家。所以多年一直没装修。今年春节为这个事我们起了争执，我老公坚持要装，理由是不住自己家，想请朋友吃个饭喝个酒的，很不方便。而我不同意的理由是房子利用率不高，且积蓄不多，要预留足够的钱应对万一。\u003c/p>\u003cp>上个月房子加隔热顶，公公一手操办，顶盖好之后他建议把刷墙、装修的事一起办了。我没同意，让他先放一放，等我们抽时间回家看过后再动工。\u003c/p>\u003cp>老公却认为我又在找理由拖延装修，然后提高音量说：“不是说好了装修的事你不管吗，你又管那么多干嘛？”在一来二往中，我们说了些带情绪的话，最后我恶狠狠地扔给他一句“只要我俩没关系了，那就跟我没关系了”潜台词是要不离婚吧。他没再接话，一直憋着不吭气。结果是两个人不欢而散。\u003c/p>\u003cp>【反思】在这次冲突里，我们都给对方的行为做出了评判，他认为我无视他的感受；我认为他想剥夺我的话语权。我们是在用各自的价值观去要求对方，自然不会有好的结果。\u003c/p>\u003cp>A2：未来的规划应用\u003c/p>\u003cp>结合今天的拆页内容，下次遇到会刺激自己情绪愤怒（比如孩子约定好的玩半小时游戏，结果一个小时也不肯下线）时，我会做以下的调整：\u003c/p>\u003cp>1. 情绪暂停：我在意识到自己情绪强烈时，赶紧暂停，什么都不要做，不要说\u003c/p>\u003cp>2. 找出评判、争议的观点：例如我认为孩子不自律，长时间下去，会玩物丧志毁了自己；\u003c/p>\u003cp>3. 觉察需求：例如我希望孩子能合理安排游戏时间，避免近视；我也渴望孩子能将更多精力放在学习上；\u003c/p>\u003cp>4. 陈述事实，表达需求：比如，我希望你能按计划严格执行游戏时间，注意用眼安全。妈妈认为说到做到的孩子最可爱。如果你能分更多时间用在学习上，那就更完美了。\u003c/p>\u003cp>总结\u003c/p>\u003cp>最后总结一下今天的内容，我们学习了充分有效表达愤怒的步骤，分别是情绪暂停-原因追问-需求觉察—感受及需求的表达，通过这样的梳理，能让我们把关注点放在表达情绪背后的需求上。\u003c/p>\u003cp>我今天的分享到这里就结束了，希望这个片段会对各位小伙伴有帮助 谢谢大家的聆听\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1683278122000,"updated_at":1683507469000,"ria":true},{"id":15727,"topic":"表达愤怒的四个步骤 ","learn_goal":"","remark":"生活中，我们与他人发生情绪失控时，\n我们是如何表达自己愤怒的情绪呢？\n是冷战，还是任由自己的小宇宙爆发，然后不欢而散……\n有一种既不伤害他人，又不委屈自己，\n还能表达出自己愤怒背后不满和需求的沟通方法，让我们一起来学习吧。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"季草集美业","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>\u003cstrong>一、自我介绍、分组\u003c/strong>\u003c/p>\u003cp>【拆书技能】学习目标均包含学习者可被观察到/被测量到的行为或动作，现场学习者设计都清晰体现了各自的学习目标。\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>各位老师大家晚上好！\u003c/p>\u003cp>非常感谢各位老师在百忙之中抽空来参加我的线下过级活动。我叫陈芳，一个很大众普通的名字，我有个姐姐叫陈芬，我妈妈希望我们姐妹俩像花朵一样美丽，所以以“芬芳”给我们俩取名。\u003c/p>\u003cp>三个标签简单地介绍一下我自己：\u003c/p>\u003cp>季草集美业顾问\u003c/p>\u003cp>孩子的提升导师\u003c/p>\u003cp>拆书帮一级拆书家\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>由于今天的过级环节需要分组讨论。我们刚好有10个人，那就两两一组吧。\u003c/p>\u003cp>\u003cstrong>二、图书介绍、学习目标\u003c/strong>\u003c/p>\u003cp>【拆书技能】选择图书是实用类或理论类图书；在 FAB 介绍法中，能够清晰辨别出聚焦于图书和学习主题的F、A、B。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F：\u003c/strong>今天我要给大家介绍的这本书是2021年最新修订版的《非暴力沟通》。作者是美国的马歇尔·卢森堡博士。作者通过非暴力沟通的方式，让人们能更好地表达自己和倾听他人的意见，从而实现有效的沟通。\u003c/p>\u003cp>\u003cstrong>A：\u003c/strong>与其他沟通类书籍相比，这本书不仅曾经被联合国教科文组织列为全球教育和非正式教育领域非暴力解决冲突的最佳实践之一，也是一本在全球范围内比较畅销的沟通类书籍。书里的案例清晰，有具体的步骤，非常通俗易懂，操作起来简便易行。\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>作者通过非暴力沟通的方法，教会我们在表达愤怒情绪的时候，既不委屈自己，也不伤害他人，同时还能表达我们愤怒背后的不满和需求，改善与他人的关系。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在大家跟随我完成今天的RIA现场学习后，学习者能够在情绪即将要失控的时候，运用表达愤怒的四个步骤进行有效、合理地沟通，从而避免与他人发生不愉快的事。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>这份是我今天准备的原文拆页，请大家花1分钟时间阅读一下。阅读完成的伙伴可以举手向我示意一下，谢谢大家。\u003c/p>","ratings_count":1,"texts":[{"id":19805,"quote":"\u003cp>\u003cstrong>三、阅读原书拆页\u003c/strong>\u003c/p>\u003cp>【拆书技能】【R】所选拆页，包括How的内容，且总内容未超过2页图书内页。\u003c/p>\u003cp>\u003cstrong>表达愤怒的四个步骤\u003c/strong>\u003c/p>\u003cp>1. 停下来，深呼吸。\u003c/p>\u003cp>2. 看看我们有哪些评判性的想法。\u003c/p>\u003cp>3. 与我们的需求连结。\u003c/p>\u003cp>4. 表达我们的感受和未被满足的需求。\u003c/p>\u003cp>来看看充分表达愤怒的具体步骤。首先，停下来，除了深呼吸，什么都别做；不去指责或惩罚他人，只是保持安静。接着，看一看，是什么想法让我们很生气。例如，无意中听到某人说了一些话，使我们相信自己由于种族的缘故遭到了排斥。感知到自己的怒气时，如果停下来，便会看到头脑中盘旋的想法：“这太不公平了！她这是种族歧视！”我们知道，所有的评判都在用可悲的方式表达未满足的需要。于是，接下来的第三步是：与这些想法背后的需求连结。如果指责某人是种族主义者，我们的需求也许是融洽、平等、尊重或者与人连结。\u003c/p>\u003cp>为了充分表达自己，我们要采取的第四步是开口表达愤怒——怒火此时已被转化为感受和需求。然而，表达此时的感受也许要很大的勇气。对我来说，生气并冲着人们嚷“你这样做是种族歧视”是很容易的，甚至还会感到很畅快。然而，要说出内心深处的感受和需求，却可能令人却步。为了充分表达愤怒，我们也许可以试着和对方说：“你走进房间后，开始与其他人聊天，却没有和我说话。接着，你开始议论有关白人的种种。当注意到这些时，我的胃非常不舒服，我也很害怕。这使我意思到，我非常希望受到平等的对待。我想请你告诉我，听到这些话，你的感受是怎么样的？”\u003c/p>","explains":"\u003cp>\u003cstrong>四、【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>【拆书技能】【I】的讲解中有举例子说明。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>好的，我看到大部分伙伴已经阅读完成。没有读完的也不要紧，接下来我会详细讲解。\u003c/p>\u003cp>\u003cstrong>What：\u003c/strong>\u003c/p>\u003cp>这个片段主要讲的是通过非暴力沟通的方式，在我们情绪很愤怒时，要先想办法让自己平静下来，再分析原因，找到自己没有被满足的需求，从而说出自己的需求和感受。\u003c/p>\u003cp>\u003cstrong>Why：（不这么做的坏处）\u003c/strong>\u003c/p>\u003cp>在生活中，我们与家人、朋友、同事发生冲突的时候，我们大多数人处理问题的方法可能是冷战，或者大吵一架，然后不欢而散。当然，这还算是最低成本的伤害。\u003c/p>\u003cp>如果我们不运用正确的方式，任由自己的情绪爆发，最后可能会因为很小的问题，引发无法控制的局面。比如说，两个人发生争执的时候，由于言语过激变成了行为上的伤害，最后导致一方受伤，甚至是还有致命的，那还需要负法律责任。所以说，在情绪极度难以控制的情况下，无论我们是言语上的暴力，还是行为上的暴力，都是解决不了问题的。\u003c/p>\u003cp>\u003cstrong>【反例】\u003c/strong>\u003c/p>\u003cp>我举一个我最近比较失败的案例。前两天在书房里，看管我小女儿写作业。作业也不是很多，都给她安排得好好的，然后我告诉她说：妈妈也要写一个很重要的作业，我们现在开始各做各的作业。结果小孩一会儿跑过来说，“妈妈，你看这是我今天在学校画的手工雨伞”，我说“哦，好的。”\u003c/p>\u003cp>过了一会儿，女儿又过来说，“妈妈，我的尺子找不到了”；过了一会儿又来说“我想喝水”。\u003c/p>\u003cp>几个“一会儿”下来，半个小时过去了，作业一点儿没动，而我也因为她一会儿这一会儿那，思路被中断了。当时就一通怒火上来了，直接冲她吼过去：“你要是不想写作业，就去看电视，没有关系，不用写了”。\u003c/p>\u003cp>很明显，我当时的语气是带着愤怒的情绪的。当时小宝木呆呆地看着我，嘴一撇“哇”的就哭起来了。就因为我当时没有控制好自己的情绪，让一个很小的事情，升级到了鸡飞狗跳的场面。\u003c/p>\u003cp>那么，当我们遇到情绪很难以控制的时候，我们该怎么做才能正确地表达愤怒呢？\u003c/p>\u003cp>\u003cstrong>How：（反例变正例）\u003c/strong>\u003c/p>\u003cp>我们今天一起来学习表达愤怒的四个步骤后，我一定会更有效地表达我的愤怒，我会：\u003c/p>\u003cp>\u003cstrong>第一步：停下来\u003c/strong>\u003c/p>\u003cp>（先冷静下来，深呼一口气，或者走开几分钟，到阳台或门外缓一缓。）\u003c/p>\u003cp>\u003cstrong>第二步：思考原因\u003c/strong>\u003c/p>\u003cp>（思考生气的原因。我生气的原因是因为小宝一直没有专注地写作业，而且影响到了我写作业的效率。）\u003c/p>\u003cp>\u003cstrong>第三步：明确需求\u003c/strong>\u003c/p>\u003cp>（我的需求是希望孩子能认真、专注地完成作业，不打扰到我。）\u003c/p>\u003cp>\u003cstrong>第四步：说出感受和需求\u003c/strong>\u003c/p>\u003cp>（说出哪些需求没有得到满足。）\u003c/p>\u003cp>经过前面三个步骤，我先冷静下来，也找到了我生气的原因。我会跟孩子说：“妈妈今天有个很重要的作业要写，我需要宝宝也跟我一起认真地完成作业。如果你一直打扰我，不仅自己的作业写不完，妈妈的作业也没法好好完成。你看这样好不好，从现在起，我们一起写到九点，大家都不说话。九点时，我们结束今天的作业，到时候再来解决你刚才的问题，可以吗？”\u003c/p>\u003cp>我相信，只要我们冷静地，一步步把问题处理好，一定会有一个不一样的结果。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>有些小伙伴可能会说，我们很多时候在愤怒的状态下情绪根本就控制不下来；这个方法看起来很简单，但是做起来太难了。我就是个急性子、暴脾气，让我在处理问题的时候还一步步来，这太难了。我还不如一通霹雳啪啦，发泄完了再说。\u003c/p>\u003cp>但是，这样的结果往往不仅伤害了别人，自己的问题也没有解决，反而营造了一种与他人不和谐的关系。所以我们要通过学习有效的方法来表达愤怒，用新的、更好的方法代替我们过去已经习惯应对问题的模式。任何新的东西，都需要不断学习；所谓熟能生巧，只有熟练了，才能见到效果。\u003c/p>\u003cp>\u003cstrong>Where：\u003c/strong>\u003c/p>\u003cp>非暴力沟通表达愤怒的四个步骤，适用于跟家人、朋友、同事之间，以便在情绪比较难以控制的情况下，需要运用正确的方法表达愤怒，让他人了解我们的需要和感受。\u003c/p>","interaction":"\u003cp>\u003cstrong>五、【A2】分步催化1\u003c/strong>\u003c/p>\u003cp>【拆书技能】【A2】分步催化中，提问中包括情境或场景，有学习者受启发联系到自己的具体应用场景。\u003c/p>\u003cp>接下来，请大家想一想，在未来一周，你与家人、朋友、同事或者领导之间交流的时候，会不会发生一些不愉快的事情，让你情绪很激动，难以控制？\u003c/p>\u003cp>比如，在辅导孩子写作业的时候，孩子一会儿摸摸这，一会儿搞搞那，眼看时间已经不早了，作业还有一堆没有完成，你当时急得抓耳挠腮，但是孩子并没有感觉到。\u003c/p>\u003cp>再比如，领导在没有任何提前通知的情况下，临时让你当天加班。领导突然的安排，打乱了你和一位很久没有见面的朋友的约会，你当时情绪一定要爆炸了吧？\u003c/p>\u003cp>现在请大家花2分钟时间，在小组内讨论一下。我一会儿请一位小伙伴来分享一下。现在开始。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>好的，2分钟时间到。请樊老师跟大家分享一下他会遇到的场景吧。只要介绍一下可能发生的场景就可以了。\u003c/p>\u003cp>樊老师：未来一周，有个关于小孩的场景，发生的可能性太大了。我上了一天班，其实脑子很累了，脑力工作嘛，脑子很累的。下班到家后，有饭吃，本来很好。但是我朝那一坐，孩子可能就要开始了：\u003c/p>\u003cp>“爸爸，这个怎么怎么样”；\u003c/p>\u003cp>“爸爸，那个怎么怎么样”；\u003c/p>\u003cp>“爸爸，这个要你签字”；\u003c/p>\u003cp>“爸爸，我能不能去下卫生间？”\u003c/p>\u003cp>就这样，一次、两次、三次，再有四次、五次，我就得起来了。其实，真的希望头脑能放松一下。\u003c/p>\u003cp>\u003cstrong>【拆书家回应】\u003c/strong>\u003c/p>\u003cp>确实，我们回到家后，孩子会有很多零碎的小事情，可能会导致我们抓耳挠腮的。\u003c/p>\u003cp>\u003cstrong>六、【A2】分步催化2\u003c/strong>\u003c/p>\u003cp>【拆书技能】【A2】分步催化中指令清晰，有学习者根据指令，规划出了以后可以如何做的具体计划。\u003c/p>\u003cp>好的！感谢樊老师给我们分享的场景，也是在家里跟孩子之间的场景。\u003c/p>\u003cp>那今天我们学习了表达愤怒的四个步骤以后，请大家继续在小组内讨论2分钟，讨论一下我们怎样把这四个步骤应用起来，不让我们的小宇宙爆发。现在开始。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>我们还是就刚才的案例，请樊老师再继续分享一下，好不好？就是工作一天回到家后，很想舒服地放松一下，结果孩子一会儿一个这，一会儿一个那，让你的小宇宙要爆发了。请把我们的四个步骤运用一下，怎么样才能不爆发呢？\u003c/p>\u003cp>樊老师：其实第一步最难，要停下来思考。因为那个时候是什么样的感觉呢？其实为什么会发火呢？就是一口血冲头之后，就会产生一种烦闷的感觉。\u003c/p>\u003cp>下次再遇到这种情况，先吸口气，先不再客厅待，先回卧室静一下。（第一步：停下来）\u003c/p>\u003cp>思考一下原因：为什么会这样呢？就是因为上了一天班之后，真的很头疼。（第二步：思考原因）\u003c/p>\u003cp>我想有点不被打扰的个人空间，能够安静地放松一下，安静地吃饭。这是我的需求。（第三步：明确需求）\u003c/p>\u003cp>最后说出感受和需求，我可以说：“果果，爸爸上了一天班，头很疼，很累；想有一点个人的空间，放松一下。在爸爸吃饭的时间，能不能不要跟爸爸说话，让爸爸安安静静地吃饭，好不好？”（第四步：说出感受和需求）。\u003c/p>\u003cp>【拆书家回应】\u003c/p>\u003cp>哇，这个爸爸好温柔啊。我相信爸爸把这个方法运用起来，小宇宙肯定不爆发，这个场面一定是温馨、和谐的，不可能再有愤怒了。\u003c/p>\u003cp>感谢樊老师的精彩分享。\u003c/p>\u003cp>\u003cstrong>七、总结\u003c/strong>\u003c/p>\u003cp>我们偶尔都会有情绪的时候，这很正常。只要我们学会平静地理清楚愤怒背后的原因和未被满足的需求即可。\u003c/p>\u003cp>希望今天的分享能给大家带来一些收获。以后啊，大家再遇到情绪愤怒的时候，能运用今天所学的表达愤怒的四个步骤，充分、合理、有效地表达我们的愤怒。\u003c/p>\u003cp>我的分享就到这里，谢谢大家！\u003c/p>\u003cp>\u003cstrong>【拆书技能】：\u003c/strong>总时长没有少于15分钟，没有超过20分钟。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1682923037000,"updated_at":1683507277000,"ria":true},{"id":15698,"topic":"表达愤怒四步法","learn_goal":"","remark":"面对生活中大小事情带来负面情绪时，\n如何准确的识别自己愤怒背后的原因呢？\n表达愤怒四步法可以帮助我们识别，\n从而控制情绪，让事情正向发展。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"ELIAUK","city":"镇江市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>各位老师，晚上好，我叫赵丽英。若用三个便签介绍一下我自己，第一张便签我是一名虔诚的基督徒，第二张便签我是一名幸福的家庭主妇。第三张便签我是一名一级拆书家。因为今天会有讨论的环节，为了方便讨论，现在我们先进行分组，面对面相邻两排成为一组。我们现在可分为两组。\u003c/p>\u003cp>【F】【Feature 特征》（以书为核心来满足好奇心)\u003c/p>\u003cp>本书作者是著名心理学家马歇尔·卢森堡博士，他是沟通领域的一位大家，他不仅在非暴力沟通理论方面有着深入的研究，更有着50多年的实践经验，他荣获了地球村基金会颁发的和平之桥奖。这本书的核心是如何采用非暴力沟通的方式：就是沟通=事实+感受+需要+请求，在困难场景沟通中，运用这个公式，让沟通者平静下来，用爱去感受对方，和觉察自己的情绪和需要，不道德评判，不比较，不要求，实现沟通的初衷，建立和谐友善的关系。帮助人类解决语言暴力的问题，。\u003c/p>\u003cp>【A】【Advantage优势〗（用方法解决情绪)\u003c/p>\u003cp>相比其他沟通类书籍，内容简单，易懂，方法可操作性很强。没太多理论性的东西，给出了大量的例子让\u003c/p>\u003cp>你更好的理解。\u003c/p>\u003cp>【B1】（学完本书可得利益)\u003c/p>\u003cp>回想一下，我们曾经有没有过对家人某些做法不认可，导致家庭矛盾的经历？我们有没有过和同事有不同意见，导致不欢而散的经历？为什么会这样，原因很简单，就是我们难以管理自己的情绪。这本书会给你一个全新的思维方式。我们可以做自己情绪的主人，进而做生活的主人。非暴力沟通让爱充满全世界。\u003c/p>\u003cp>【B2】（学完此片段可得利益)\u003c/p>\u003cp>今天大家和我一起学习完拆页片段后，今后在面对工作或生活中的愤怒情绪时，我们可以使用表达愤怒\u003c/p>\u003cp>四步法表达自己的感受和需求，同时缓解人际关系。\u003c/p>\u003cp>学完这个片段，想想愤怒带来的坏处，想必大家更愿意看到四步法表达愤怒所带来的好处，也愿意去刻意练习，逐渐遇见更好的自己!\u003c/p>","ratings_count":2,"texts":[{"id":19768,"quote":"\u003cp>表达愤怒的四个步骤\u003c/p>\u003cp>1.停下来，深呼吸。\u003c/p>\u003cp>2.看看我们有哪些评判性的想法。\u003c/p>\u003cp>3.与我们的需要连结。\u003c/p>\u003cp>4、表达我们的感受和未被满足的需要\u003c/p>\u003cp>来看看充分表达愤怒的具体步骤。首先，停下来，除了深呼吸，什么都别做；不去指责或惩罚他人，只是保持安静。接着，看一看是什么想法让我们生气。例如，无意中听到某人说了一些话，使我们相信自己由于种族的缘故遭到了排斥。感知到自己的怒气时，如果停下来，便会看到头脑中盘旋的想法：“这太不公平了！她这是种族歧视！”我们知道，所有的评判都在用可悲的方式表达未满足的需要。于是，接下来的第3步是：与这些想法背后的需要连结。如果指责某人是种族主义者，我们的需要也许是融合、平等、尊重或者与人连结。\u003c/p>\u003cp>为了充分表达自己，我们要采取的第4步是开口表达愤怒——怒火此时已被转化为感受和需要。然而，表达此时的感受也许要很大的勇气。对我来说，生气并冲着人们嚷“你这样做是种族歧视”是很容易的，甚至还会感到很畅快。然而，要说出内心深处的感受和需要，却可能令人却步。为了充分表达愤怒，我们也许可以试着和对方说：“你走进房间后，开始与其他人聊天，却没有和我说话。接着，你开始议论有关白人的种种。当注意到这些时，我的胃非常不舒服，我也很害怕。这使我意识到，我非常希望受到平等的对待。我想请你告诉我，听到这些话，你的感受是怎么样的？”\u003c/p>","explains":"\u003cp>逐字稿\u003c/p>\u003cp> 好，大家目前都已经完成阅读拆页。这个片段在讲什么呢?\u003c/p>\u003cp>【What]（这个片段说了什么)\u003c/p>\u003cp>这个片段用实例告诉我们，如何识别自己的愤怒？并可以找出对应的方法。从而与他人建立正向积极且\u003c/p>\u003cp>亲密的关系。使我们的生活更加美好。\u003c/p>\u003cp>IWhyl（为什么要这么做，这么做有什么好，不这么做有什么坏处）\u003c/p>\u003cp>我们通过这四个方法梳理了愤怒背后自己的感受和需要，就能够正向的向对方表述。这样对方就更清楚知道怎样来回应你。从而使整件事情得到了很好的解决，彼此之间的关系也不会被破坏。甚至可以建立更亲密的连接。如果没有用这四个方法去梳理自己的负面情绪，有可能情绪就成为我们的主人。理智脑停摆，该做的事情没有做，不该做的事情却做了很多，就会伤人伤己。从而关系遭到破坏，人与人之间的生命进入到疏离的状态。\u003c/p>\u003cp>IHowl（具体怎么做呢)\u003c/p>\u003cp>1.停一下，深呼吸，呼吸可以缓解我们愤怒和冲动的情绪，避免我们说出一些不经大脑思考的话。\u003c/p>\u003cp>2.想一下，会感受；想一想别人当时做了什么让自己愤怒？体会一下自己当时的心情是怎样的?\u003c/p>\u003cp>3.问一下，知需求；问一问自己对对方的行为是如何解读的，其中反映了自己怎样的需求？这个过程中,\u003c/p>\u003cp>自己可以去倾听和理解对方，同时让对方静下心来体会自己的感受和需要。\u003c/p>\u003cp>4.说一下，表想法；不带批评和指责地去表达自己的真实感受，并告诉对方自己的什么需求未得到满足。\u003c/p>\u003cp>比如:上个礼拜天的早上从教会回来推开门一看，孩子躺在沙发上看电视。老人坐在那里研究他的中国地图。早饭还在厨房都没有吃。当时心里非常的气愤。\u003c/p>\u003cp>那么，结合今天学习的内容再来回顾这件事。我可以按照这四个步骤去做:\u003c/p>\u003cp>第一步：停下来，深呼吸 3-4 次;\u003c/p>\u003cp>第二步：看到孩子，老人没有自己的提醒，都不知道这个时间段每一个人该做什么。所以我特别生气。第三步：我生气是因为这一天自己要做的事情很多，时间很紧张。感觉他们连这些基本的生活需求都要依靠我，觉得自己好累。\u003c/p>\u003cp>第四步：我要向家里人表达这份特别生气的感受，人首先要为自己负责，而且一个家是需要共建共同分担的，要各司其职，不能老是依靠别人。\u003c/p>\u003cp>[Wherel（适用场景)\u003c/p>\u003cp>这个方法的使用场景比较广，各个层面的交流中均可。比如：亲子关系沟通中，夫妻关系沟通中，家校沟通中，同事沟通中，商业沟通。却不适用于涉及到主权的谈判中。\u003c/p>","interaction":"\u003cp>逐字稿：【显像提问】\u003c/p>\u003cp>那现在回顾一下我们自己的生活，请大家回想一下，最近一次不太愉快的争吵的场景，当时你很不开心甚至很愤怒，这个场景可能发生在你的家里和家人之间；可能发生在职场和领导、同事之间；也有可能和一个多年的好朋友之间。\u003c/p>\u003cp>请你回想一下：（when）当时是什么时间?\u003c/p>\u003cp>(where）在什么地点？\u003c/p>\u003cp>(who)现场有谁?\u003c/p>\u003cp>(why)为什么事情吵？(what)讲了什么话？(what)结果怎么样？\u003c/p>\u003cp>每组为单位讨论一下。等会请人分享。\u003c/p>\u003cp>现场易老师为我们分享了一下他过去的一段经历。\u003c/p>\u003cp>有一次我去亲戚家做客，就帮忙辅导亲戚家的小孩儿写作业。这个小朋友呢是上小学三年级。在写作业的过程当中发现这个孩子有拖延症。一道数学题愣是拖了半个小时都没有写。当时我就被激怒了，甚至说了很多不该说的话。\u003c/p>\u003cp>A+\u003c/p>\u003cp>感谢易老师给我提供的案例，好，现在让我们一起穿越，回到当时的状态，回想一下，今后的生活如果再有类似的场景，我们运用今天表达愤怒的四个步骤，我们应该怎么去做呢？\u003c/p>\u003cp>我们先来回顾一下行动建议：\u003c/p>\u003cp>1、停一下，深呼吸；2、想一下，会感受;\u003c/p>\u003cp>3、问一下，知需求；4、说一下，表想法。\u003c/p>\u003cp>给大家30秒的时间思考，然后请易老师用一分钟分享一下。如何运用今天学到的愤怒情绪梳理四步法？应用于跟孩子的沟通当中。\u003c/p>\u003cp>易老师讲他会从当时的情绪当中抽离出来去。先让自己冷静一下，然后会去梳理一下自己的想法。与想法相关联的需要是什么？然后再向孩子表达一下当时的感受和需要。在梳理的过程当中，也意识到其实孩子不能接纳的是他的情绪。如果跟孩子可以这样好好的沟通的话，就能够达到最终结果。\u003c/p>\u003cp>【结束语〗\u003c/p>\u003cp>感谢各位今晚的陪伴，今天我们学习了四步法表达愤怒，让沟通更走心。希望大家可以回去行动起来，从明天开始，把这个公式存在手机上，只要张口说话，他们就看着手机说，第一步、第二步….再次感谢大家，今天的拆页到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1682390638000,"updated_at":1683507609000,"ria":true},{"id":15656,"topic":"表达内心感受，说出我的需要","learn_goal":"","remark":"线下练级活动","level":"TF3-3","duration":65,"status":30,"type":0,"chaishujia":{"username":"严金英","city":"重庆市"},"club":{"name":"重庆拱辰分舵","city":"重庆市"},"prologue":"\u003cp>\u003cstrong>【开场】\u003c/strong>\u003c/p>\u003cp>不破不能立，不拆不成器！拆书帮把知识拆成你的能力！欢迎大家参加拆书帮重庆筹备分舵线下拆书练级活动，我是今天的领拆人二级拆书家严金英。\u003c/p>\u003cp>我的三个标签是：1. 身心灵学习实践者，2. 拆书帮筹备分舵组织长老，3. 拱辰文化联合创始人\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>为了方便学习过程中充分交流讨论，我们简单分个组。今天有6位书友到场，我们3人一组，3人一组这样分开。谢谢。\u003c/p>\u003cp>【学习总目标】：\u003c/p>\u003cp>我们今天一起进行2个片段的学习，学习总目标是：学会表达感受的4步法，并学会区分出想法和感受，把感受情绪表达出来。表达情绪后，为了让对方更能明白我们的需求和目的，还要能够学会表达需要的四部曲，提出自己感受背后的需要。\u003c/p>\u003cp>【片段①目标】\u003c/p>\u003cp>在跟随我完成片段①的RIA现场学习后，大家能够区分【行为】想法与感受，并在有情绪的状况下，能通过“表达感受4步法” 【澄清】来描述自己当下的感受【界定】，并且在现场能运用“表达感受四步法”写出未来可能出现的场景小剧本。\u003c/p>\u003cp>\u003cstrong>【图书介绍】 1-2分钟\u003c/strong>\u003c/p>\u003cp>在开始之前跟大家先分享个自己的小故事：\u003c/p>\u003cp>因为从小家庭教育的原因，我对自己内心的感知比较少，不会表达自己的感受，只会去要求别人，所以，结婚后的前两年时间里，我和我爱人的日常沟通总是这样的：\u003c/p>\u003cp>看着他把袜子仍在地上，我会随口就说出：“你怎么这么恶心！”\u003c/p>\u003cp>看着他躺在沙发上刷手机，我会说：“你这么这么懒，怎么不知道收拾下屋子！”\u003c/p>\u003cp>他有事忙无法陪我，我会说：“你真是一个冷漠、无情的男人！”\u003c/p>\u003cp>各种评判，指责，PUA，之后呢俩人就免不了一顿大吵。\u003c/p>\u003cp>【事件】\u003c/p>\u003cp>不知道大家有没有遇到过类似这些场景：\u003c/p>\u003cp>让老公带娃出去玩儿，结果不一会儿老公抱着鼻青脸肿的孩子，你冲着他吼：让你看个孩子都看不好，你是瞎吗？\u003c/p>\u003cp>带孩子过马路时，孩子不听话，甩开你的手自己跑到马路对面。你吓得大声斥责：你不要命了，跟你说了有车很危险，你不知道吗？\u003c/p>\u003cp>跟同事一起做一个项目，但是长期她要不请假要不上班摸鱼，只有你自己在苦哈哈的做。你会说落她，你怎么是这样一个又懒又不负责任的人！\u003c/p>\u003cp>【提问】\u003c/p>\u003cp>大家是不是或多或少都遇到过类似的事情？\u003c/p>\u003cp>当时的你是如何表达自己感受的？直接开始就对对方一顿怒吼吗？那表达之后的结果是你想要的吗？\u003c/p>\u003cp>【影响】\u003c/p>\u003cp>这样的状况总是会接连出现在我们的日常生活中。人际交往处处都需要沟通，生活处处有沟通。\u003c/p>\u003cp>如果我们在沟通时不能够正确清晰地表达自己的感受，会令对方无法体会到我们的情绪，导致双方交流困难，长此以往，也会给我们的家庭、事业、人际关系带来诸多麻烦。\u003c/p>\u003cp>如果我们能够正确的表达出自己当下的感受，沟通的对方也能及时体会到我们的情绪，进而能在沟通时互相体谅，最终达成良好的沟通结果。\u003c/p>\u003cp>【解决】\u003c/p>\u003cp>《非暴力沟通》这本书为我们提供了一种生命的语言，帮助我们重新审视自己的沟通方式。让我们可以在沟通中关注彼此的感受与需要，最终通过爱与理解，化解人际交往中的各种冲突。\u003c/p>\u003cp>今天，我为大家分享的两个片段是递进关系。\u003c/p>\u003cp>在跟随我完成片段一的RIA现场学习后，大家能够区分【行为】想法与感受，并在有情绪的状况下，能通过“表达感受4步法” 【澄清】来描述自己当下的感受【界定】，并且在现场能运用“表达感受四步法”写出未来可能出现的场景小剧本。\u003c/p>\u003cp>那表达完自己的感受后，别人理解了我们的情绪与感受，但是我们目的和需求并没有达到，那我们该如何正确提出自己的需求呢？\u003c/p>\u003cp>在跟随我完成片段二的RIA现场学习后，大家能够在沟通的过程中，察觉到【行为】自身的目的和需要没有达到后，能通过“表达需要四步曲” 【澄清】来说明自身的需要【界定】，从而更好地与他人进行沟通与交流，并且在现场能与小伙伴一起讨论，找出自己表达需要时较难实施的步骤，并找到解决方案与细分步骤。\u003c/p>\u003cp>接下来我们来看第一个片段：\u003c/p>","ratings_count":2,"texts":[{"id":19719,"quote":"\u003cp>请大家先用1分钟时间快速阅读原文片段。\u003c/p>\u003cp>【R阅读原文】《非暴力沟通》P39\u003c/p>\u003cp> 在一次研讨班中，一位大学生说，室友将音响的声音放得很大，他怎么也睡不着。我询问他当时的感受，他说：“我觉得在晚上不该这么大声。”我提醒他，虽然他用“觉得”这个词，但他表达的是看法而非感受。我请他再试着表达感受，这一次，他说：“声音太大了就会打扰到别人。”我向他解释，这依然是看法而非感受。他想了想，斩钉截铁地说：“我没什么感受！”\u003c/p>\u003cp> 很明显，他有强烈的感受。不幸的是，他体会不到，更不用说表达它们了。体会和表达感受并不容易。根据我的观察，对于从事律师、工程师、警察、经理等职业的人来说，尤为困难——表达感受与他们的职业形象相冲突。在家庭中，如果家庭成员无法表达情感，那是很悲哀的。西部乡村音乐的代表人物瑞芭﹒麦克英特尔在她父亲去世后写了一首歌《我所不知道的最伟大的人》，这首歌引起许多人的共鸣——他们渴望与父亲沟通情感，却又做不到。\u003c/p>\u003cp>（还有30秒）片段很简单，阅读完的小伙伴请举手示意一下。\u003c/p>","explains":"\u003cp>【what】\u003c/p>\u003cp>从拆页里面我们可以感受到的一个关键词是什么呀？——“感受”（互动）\u003c/p>\u003cp>这个大学生，他没法正确识别出自己的感受，所以也就没办法表达出来，对吧。\u003c/p>\u003cp>我们在生活中往往会把想法当作感受，当我们把两者混为一谈时就很容易忽略自己的真实感受，从而引起冲突或是不满。那到底什么是感受和想法呢？\u003c/p>\u003cp>感受：是接触外界事物得到的影响，体会。是指我们的情感，身体的感觉，心情或者精神状态。也可以说是我们的情绪。比如：兴奋，喜悦，焦虑、难过等。\u003c/p>\u003cp>想法：是我们的感官获得信息后，经过思考，判断，分析，推理总结出的意见、看法。比如：被抛弃，被羞辱，被拒绝，被贬低，被利用等。\u003c/p>\u003cp>【举例对比】\u003c/p>\u003cp>为了让大家能够更好的区分感受和想法，我们接下来看几个例子：\u003c/p>\u003cp>例一：\u003c/p>\u003cp>【提问】\u003c/p>\u003cp>“我觉得作为一个吉他手，我弹得不够好。”这句话是在表达感受吗？？\u003c/p>\u003cp>【现场】\u003c/p>\u003cp>不是\u003c/p>\u003cp>【分析】\u003c/p>\u003cp>这不是在表达感受，只是在评价自己作为一个吉他手的演奏水平，这是一个判断，是在说想法而不是感受。当我认为自己“弹得不够好”的时候，背后的感受可能是失望、着急、或者别的情绪。可以说：“想到我的吉他水平，我感到沮丧”\u003c/p>\u003cp>例二：\u003c/p>\u003cp>【提问】\u003c/p>\u003cp>“我感到被误解了”这句话是在表达感受吗？\u003c/p>\u003cp>【现场】\u003c/p>\u003cp>不是\u003c/p>\u003cp>【分析】\u003c/p>\u003cp>这不是在表达感受，“被误解”是在描述想法，即我认为他人不了解我，我背后的感受可能是焦虑、不快。可以说：“别人这么说我，我感到很不爽”\u003c/p>\u003cp>例三：\u003c/p>\u003cp>【提问】\u003c/p>\u003cp>“大半夜要我自己一个人出去太危险了”这句话是在表达自己的感受吗？\u003c/p>\u003cp>【现场】\u003c/p>\u003cp>不是\u003c/p>\u003cp>【分析】\u003c/p>\u003cp>这也是一个评判而不是一句感受对吧？ 虽然是担心自己的话，但是并没有表达出自己的感受。如果改成“大半夜让我自己一个人出去，我感到害怕，因为那样太危险了。”就是表达感受了。\u003c/p>\u003cp>例四：\u003c/p>\u003cp>【提问】\u003c/p>\u003cp>“听你那么说，我感到很害怕。”这句话是在表达自己的感受吗？\u003c/p>\u003cp>【现场】\u003c/p>\u003cp>是的\u003c/p>\u003cp>【分析】\u003c/p>\u003cp>是的，这句话是感受，表达了自己内心的感觉。\u003c/p>\u003cp>通过以上几个例子不知道大家发现了没有？\u003c/p>\u003cp>想法相对来说比较主观，是在自己的价值观的基础上对某个人、某种行为、某件事情的评价、意见或看法等。\u003c/p>\u003cp>而感受是以自身的情绪、心情为落脚点，是针对客观事实而产生的一种直接情绪的表达。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>如果我们总是将自己的“想法”直接当成“感受”来表达，往往会让沟通的对方产生反感，无法起到很好的沟通效果，还容易产生误会，导致沟通失败。最重要的是我们自己也不能清晰地识别到自己的感受，进而无法做到与自己与他人的链接。（坏处）\u003c/p>\u003cp>如果我们能够很好地识别自己的感受，将我们的“感受”表达出来，一方面能够促进和别人的沟通，改善人际关系，另一方面，这也能链接到自己的内心，与自己达成和解。\u003c/p>\u003cp>这也是我们为什么要学会识别感受的关键所在。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>到底该如何正确的识别自己的感受并表达出来呢？我从书中提炼出来的可以分为4步：\u003c/p>\u003cp>第一步：停下来，深呼吸，什么都不要做\u003c/p>\u003cp>当我们面对突如其来的状况时，能在第一时间停下来，深呼吸，紧接着觉察出自己的情绪和内心的波动。\u003c/p>\u003cp>第二步：找出事实\u003c/p>\u003cp>客观描述出你观察到、看到的已经发生的事实，是事情的结果或者行为。\u003c/p>\u003cp>例如：你可以说：我看到你把垃圾扔到地上……\u003c/p>\u003cp>第三步：匹配感受情绪词\u003c/p>\u003cp>感受看到/听到的内容给自己带来的情绪，不区分对错/好坏，找与情绪相关的词\u003c/p>\u003cp>\u003cstrong>\u003cu>表达感受词语表\u003c/u>\u003c/strong>\u003c/p>\u003cp>\u003cu>(1) 需要得到满足时的感受：\u003c/u>\u003c/p>\u003cp>兴奋 喜悦 欣喜 甜蜜 精力充沛 兴高采烈\u003c/p>\u003cp>感激 感动 乐观 自信 振作 振奋 开心\u003c/p>\u003cp>高兴 快乐 愉快 幸福 陶醉 满足 欣慰 心旷神怡 喜出望外\u003c/p>\u003cp>平静 自在 舒适 放松 踏实 安全 温暖 放心 无忧无虑\u003c/p>\u003cp>\u003cu>(2) 需要没有得到满足时的感受：\u003c/u>\u003c/p>\u003cp>害怕 担心 焦虑 忧虑 着急 紧张 心神不宁 心烦意乱\u003c/p>\u003cp>忧伤 沮丧 灰心 气馁 泄气 绝望 伤感 凄凉 悲伤\u003c/p>\u003cp>恼怒 愤怒 烦恼 苦恼 生气 厌烦 不满 不快 不耐烦 不高兴\u003c/p>\u003cp>震惊 失望 困惑 茫然 寂寞 孤独 郁闷 难过 悲观\u003c/p>\u003cp>沉重 麻木 精疲力尽 委靡不振 疲惫不堪 昏昏欲睡 无精打采\u003c/p>\u003cp>尴尬 惭愧 内疚 妒忌 遗憾 不舒服\u003c/p>\u003cp>第四步：说出来\u003c/p>\u003cp>通过说“我感到……”这样的句式，将自己体察的感受与情绪词表达出来，让对方清楚的接收到。\u003c/p>\u003cp>例如：你听我讲话的同时点头示意我，我感到很开心、很满足。\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>前段时间一天早上，我要去参加一个比较重要的会议，但是要先送孩子上学。\u003c/p>\u003cp>所以我很早就叫孩子起床了，他总是在拖拖拉拉，洗脸玩下水，出来逗逗猫，吃饭慢吞吞，眼看就快迟到了。我就崩溃了，正想向往常一样开始怒吼“你这么这样！”我立马觉察到自己的情绪变化，我想到了表达感受4步法，\u003c/p>\u003cp>第一步：停下来，深呼吸\u003c/p>\u003cp>我让自己停下来，深呼吸，什么都不要说，告诉自己静下来静下来\u003c/p>\u003cp>第二步：找出事实\u003c/p>\u003cp> 现在是7:55了，孩子还没有吃完饭，8:20 我要开会。\u003c/p>\u003cp>第三步：匹配感受情绪词\u003c/p>\u003cp> 眼看就要到我开会的时间了，我怕赶不上，我感到很焦虑并且有点担忧。\u003c/p>\u003cp>第四步：说出来\u003c/p>\u003cp> 把自己的感受真实的说出来，对孩子说，妈妈现在感到有点担忧，很担心赶不上会议，很焦虑！\u003c/p>\u003cp>这样我就成功的向孩子表达了我当下的感受，让他能清楚的知道我的状态。\u003c/p>\u003cp>那表达我的感受之后，我的需求没有被满足，我该怎么向孩子表达我的需求呢？接下来的第二个片段我们一起学习。\u003c/p>\u003cp>那回到我们刚才说的“表达感受四步法”\u003c/p>\u003cp>【where】\u003c/p>\u003cp>在任何沟通的场景下，这个方法可以用于双方的沟通，也可以用于自我的沟通。\u003c/p>\u003cp>当与对方有分歧或者感觉对方不理解我们的时候，可以使用这个方法。\u003c/p>\u003cp>当我们自己面对一件事情，在一种情绪漩涡中无法自拔的时候，可以使用这个方法帮助自己识别感受，进而能从困局中走出来。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>有伙伴可能会说，我自己处在什么样的情绪和感受下，我还不知道吗？何必那么复杂，还一步两步三步四步。当然，如果您觉知度非常高，能很容易识别自己当下的感受，并能把自己从困局中解救出来，那真的恭喜你，你真的很棒。但是我们大多数的伙伴是做不到觉察力这么强的，所以就需要我们前期用这个方法进行刻意的练习，让自己保持在一个觉知的状态。\u003c/p>\u003cp>也有伙伴可能会说，如果真的和别人出现争吵或冲突时，仅仅只是向对方表达感受是不足以解决问题的。是的，确实如此，只是表达自己感受，让对方知道了你的状态，但是你的需求与目的他还不清楚，那该怎么办？就需要用到我们接下来片段二中的“说出需要四步骤”来帮助我们清晰向对方表明我们的需要，进而与对方达成更加高效的沟通。\u003c/p>","interaction":"\u003cp>[A2]催化应用提问设计\u003c/p>\u003cp>【指令】\u003c/p>\u003cp>通过以上的分享，想必大家已经学会如何识别自己的感受，相信也学会了如何区分“想法”和“感受”了。\u003c/p>\u003cp>接下来，请在场的各位现场运用“表达感受四步法”写个小剧本。\u003c/p>\u003cp>在未来的一个月内，在你的生活、工作、学习当中，会在什么样的场景下，可能会因为矛盾或者冲突，你会出现一些情绪变化，可以用到“表达感受四步法”帮助自己清晰识别自己的感受并表达出来呢？\u003c/p>\u003cp>比如：在家里，孩子不肯吃饭，不肯做作业、爱人不愿意配合做家务，或者意见不合，又或者在工作中被同事误解、客户投诉、领导不支持、会议中大家意见无法统一等等，内心会出现一系列感受的变化。\u003c/p>\u003cp>请大家把你可能遇到的场景，根据今天所学的“识别感受四步法”，来设计一组你跟对方沟通剧本，以对话形式呈现。\u003c/p>\u003cp>内容要有发生的时间、地点、人物，以及故事的发展（包括：起因、经过、结果和人物间的对话）。情景不限，自由发挥，大家一定要把四步骤体现在内容中，……\u003c/p>\u003cp>把对话的内容写在我给大家准备的“故事小剧场”便签上。\u003c/p>\u003cp>Ok，现在开始编写，时间5分钟，把你设计的内容，双方的对话记录下来，大家可以按我提供的便签框架填充完整，之后我会邀请小伙伴来分享。\u003c/p>\u003cp>（时间到，哪位来分享一下你们的故事呢，时间大约1分钟哦。）\u003c/p>\u003cp>【学习者案例记录】：\u003c/p>\u003cp>主题：因为太忙，没有时间为老公做午饭的问题\u003cbr>时间：下周一中午\u003cbr>地点：家里\u003cbr>人物：小琼和老公\u003cbr>背景：\u003cbr>因为下周小琼会有些自己的事情比较忙，中午没有为老公做午饭，老公回来后发现没有吃的，产生了一定情绪，正在跟小琼发脾气，小琼也很火大，正要开始大吵。\u003c/p>\u003cp>【对话】\u003c/p>\u003cp>小琼：（先背过去，让自己深呼吸，冷静一下）（step01.停下来）\u003cbr>小琼：老公，因为我没有为你做好午饭，你就对我发脾气。（step02.找事实）\u003c/p>\u003cp>老公：回来了没有饭吃我很生气啊!\u003c/p>\u003cp>小琼：很抱歉，我今天确实很忙的，所以没有时间给你准备午饭。\u003c/p>\u003cp>老公：哼!（发脾气）\u003c/p>\u003cp>小琼：因为我没有为你做好午饭，你就这样大声对我说话，还黑着脸，我感觉有点伤心、难过。\u003c/p>\u003cp>（step03.匹配情绪词，step04.说出来）\u003c/p>\u003cp>老公：额，我只是有点饿的慌，没有饭吃我不舒服。\u003c/p>\u003cp>小琼：那你可以好好说话，对我小声点吗。\u003c/p>\u003cp>老公：我下次注意。\u003c/p>\u003cp>（回应反馈）\u003c/p>\u003cp>谢谢小琼的分享，很棒哦！先是觉察到自己的情绪和感受，先让自己冷静下来，冷静后，向老公说出现在的事实，然后根据事实以及老公的行为，识别出自己的感受，然后通过精炼的语言向老公表达自己的感受。\u003c/p>\u003cp>【表达感受4步骤】很好地运用在其中，再次谢谢小琼。\u003c/p>\u003cp>【过渡语】\u003c/p>\u003cp>好了，因为时间关系，就不再请其他小伙伴分享了。\u003c/p>\u003cp>看来大家通过编写剧本的环节，已经初步掌握了表达感受四步法：1、停下来，2、找事实3、匹配感受情绪词，4、说出来。\u003c/p>\u003cp>我们一起学会了处在某种冲突场景时，暂停下来，识别自己当下的感受，正确的向对方表达出来。\u003c/p>\u003cp>那表达完自己的感受后，别人理解了我们的情绪与感受，但是我们目的和需求并没有达到，那我们该如何正确提出自己的需求呢？下面就来跟大家分享今天的第二个片段——表达需要。\u003c/p>\u003cp>\u003cstrong>【目标2】\u003c/strong>\u003c/p>\u003cp>在跟随我完成片段②的RIA现场学习后，大家能够在沟通的过程中，察觉到【行为】自身的目的和需要没有达到后，能通过“表达需要四步曲” 【澄清】来说明自身的需要【界定】，从而更好地与他人进行沟通与交流，并且在现场能与小伙伴一起讨论，找出自己表达需要时较难实施的步骤，并找到解决方案与细分步骤。\u003c/p>\u003cp>\u003cstrong>【A1自测题】\u003c/strong>1min\u003c/p>\u003cp>下面先来做个小测试：\u003c/p>\u003cp>看看你自己是否看看你是否能认清自己的需要，并通过恰当的语言将其表达出来。\u003c/p>\u003cp>以下5个题目请按照1-6分的标准给自己打分，1代表完全不符合，6代表非常符合。\u003c/p>\u003cp>请大家花1分钟的时间，仔细阅读下面表格中的每句话，根据自己实际情况，凭第一直觉为自己打分，并汇总分数，做好的小伙伴可以示意我一下： \u003c/p>\u003cp>好的，我看大家都做完了，\u003c/p>\u003cp>【解释】\u003c/p>\u003cp>这个自测能让我们清楚自己是否能够准确知道并表达自己内心的需求，总分30分。\u003c/p>\u003cp>请大家对照一下自己的得分：\u003c/p>\u003cp>【结果】\u003c/p>\u003cp>20-30分的小伙伴请举手，非常棒！\u003c/p>\u003cp>说明你很了解自身的需要，并能够准确地表达需要。非常棒，请继续保持。\u003c/p>\u003cp>10-20分的小伙伴请举手，\u003c/p>\u003cp>说明你已经具备了表达需要的能力，但还需通过练习与加强来提升此能力；\u003c/p>\u003cp>1-10分的小伙伴请举手，\u003c/p>\u003cp>说明你在表达需要方面还有很大的提升空间，可以结合我们今天片段二中所分享的方法，来学会如何表达自己的需要。\u003c/p>\u003cp>现在，让我们一起来看手中的这个片段。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":20184,"quote":"\u003cp>请大家先用2分钟时间快速阅读原文片段。\u003c/p>\u003cp>【R阅读原文】《非暴力沟通》P59-60\u003c/p>\u003cp>当我们评判、批评、分析或判断他人的言行时，实际上是在用疏离生命的方式表达自己的需要。如果有人说：“你从不懂我。”他真正的心声是渴望得到理解。如果太太说：“这星期你每天都工作到很晚，相比我，你更爱工作！”那她在诉说的是，亲密的需要未能得到满足。\u003c/p>\u003cp>当我们通过评判、判断和想象等方式间接地表达自己的需要时，他人很容易认为我们在批评他们，并随之启动自我辩护和反抗。我们越能直接说出感受以及相关联的需要，他人也越有可能对我们做出善意的回应。\u003c/p>\u003cp>不幸的是，大多数人从未学习过如何从“需要”的角度来思考。当需要未能得到满足时，我们习惯于认为是他人的错。例如，如果我们希望孩子把衣服收纳在衣橱里，而他们却丢在了沙发上，我们可能就会说他们懒惰；如果我们不喜欢同事工作的方式，也许会指责他们不负责任。\u003c/p>\u003cp>有一次，我受邀到南加州调解一起农场主与外来工人间的冲突，双方的矛盾正愈演愈烈。会谈一开始，我向他们提出两个问题：“你们各自的需要是什么？为了满足这些需要，你们想请求对方做什么？”\u003c/p>\u003cp>这时，一位外来工人喊道：“他们就是一群种族歧视分子！”随即，一位农场主更大声地喊起来：“他们这些人根本无视法律法规！”就像在大部分冲突事件中那样，人们更善于分析对方的错，而非清晰地表达自己的需要。\u003c/p>\u003cp>（最后30秒时）阅读完的小伙伴举手示意一下。片段很简单，接下来跟我一起来看下这个片段：\u003c/p>","explains":"\u003cp>阅读完原文后，有几个问题问一下大家\u003c/p>\u003cp>【提问1】当我们对他人进行批评，实际上是在间接表达什么呢？\u003c/p>\u003cp>【现场】表达自己的需要。\u003c/p>\u003cp>是的，因为自身的需要没有被满足，所以才会去批评指责。\u003c/p>\u003cp>【提问2】如果我们通过批评来表达自己的观点和需要的话，人们通常会有什么反应？\u003c/p>\u003cp>【现场】辩护、反抗，对抗\u003c/p>\u003cp>【提问3】在两个案例中，双方都有冲突、矛盾，彼此都在指责对方，被他们忽略的内容是什么呢？\u003c/p>\u003cp>【现场】没有表达自己的需要。（自己想要什么）\u003c/p>\u003cp>【我】是的，双方都在找对方的问题，挑对方的刺，却没有表达出自己想要什么，所以最终需要没有被满足，内心情绪很崩溃，从而产生了冲突与矛盾。\u003c/p>\u003cp>如果沟通的双方都能够正确清晰地表达出自己的需要，然后双方就能切身的理解对方，当需要被满足时，冲突就会自然化解。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>通过这个片段我们可以看出，情绪、感受都是源自于我们自身的需要。当需要没有被满足时，我们会有强烈的负面情绪，会不耐烦、生气、气馁等。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>当我们能准确地表达出自己没有被满足的需要时，沟通的对方才会清晰地接收到，并能根据我们的需要做出相应的回应，进而双方的沟通就会很顺利，彼此之间的相处也很轻松。（好处）\u003c/p>\u003cp>当我们不能够准确地表达出自己没有被满足的需要时，就可能会通过抱怨、指责、批判等方式来表达我们的情绪，这样对方不光无法精准地接收到我们想要表达的需求，还会因此对我们产生反感对抗的情绪，最终可能造成不必要的矛盾，还会影响彼此的关系。（坏处）\u003c/p>\u003cp>【how】\u003c/p>\u003cp>这样看来表达需要真的很重要，那到底该如何发现并表达自己的需要呢？\u003c/p>\u003cp>我提炼出以下表达需要的四个步骤，我称它为“表达需要四部曲”\u003c/p>\u003cp>1. 体会感受：\u003c/p>\u003cp>当你感受到自己的情绪波动时，用心体会自己当下的感受是什么样的，可通过寻找情绪词来感受情绪。\u003c/p>\u003cp>例如：睡觉前，孩子一直让我陪他玩儿，我感到很烦躁、很愤怒。\u003c/p>\u003cp>情绪词语表\u003c/p>\u003cp>害怕 担心 焦虑 忧虑 着急 紧张 心神不宁 心烦意乱\u003c/p>\u003cp>忧伤 沮丧 灰心 气馁 泄气 绝望 伤感 凄凉 悲伤\u003c/p>\u003cp>恼怒 愤怒 烦恼 苦恼 生气 厌烦 不满 不快 不耐烦 不高兴\u003c/p>\u003cp>震惊 失望 困惑 茫然 寂寞 孤独 郁闷 难过 悲观\u003c/p>\u003cp>沉重 麻木 精疲力尽 委靡不振 疲惫不堪 昏昏欲睡 无精打采\u003c/p>\u003cp>尴尬 惭愧 内疚 妒忌 遗憾 不舒服\u003c/p>\u003cp>2. 自我提问：\u003c/p>\u003cp>询问自己会有这样情绪的原因是什么？能对应到自己的问题是什么？从而发现自己的需要是什么？句式：“我会有这样的感受，是因为什么”\u003c/p>\u003cp>例如：我为什么会因为孩子让我陪玩儿而感到烦躁？可能是我很累，不想说话，可能是连续几天熬夜没休息好。\u003c/p>\u003cp>3. 寻找需要：\u003c/p>\u003cp>通过自我提问发现需要的内容，进一步寻找内心想要被满足的需要。\u003c/p>\u003cp>例如：上面发现的需要是“没休息好，想睡觉”，那内心想要被满足的需要就是“想好好休息，自己美美地睡一觉”。\u003c/p>\u003cp>4. 说出需求：\u003c/p>\u003cp>通过以上三步找到了自己的需要，\u003c/p>\u003cp>那就可以通过“我感到……,是因为……，我想要……”的句式来表达自己的需要。\u003c/p>\u003cp>例如：我感到内心烦躁、疲惫不堪，是因为缺觉没有休息好，我想要睡觉。\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>上周二晚上，我家孩子在关灯睡觉的时候，想让我陪他待一会儿。我当时还有几个稿子没有写完，所以我就立马拒绝他，“不行！我没空，你自己睡。”然后我关完灯就走了。现在现在学习了“表达需要四步曲”，我就可以这样来表达：\u003c/p>\u003cp>1. 体会情绪：我感觉到心烦意乱、内心焦急\u003c/p>\u003cp>2. 自我提问：我为什么会心烦意乱，如此焦急呢？\u003c/p>\u003cp>3. 寻找需要：因为我的稿子还没有写完，周三需要录视频发出来了，我怕我来不及，我需要自己独处的时间来完成自己的工作。\u003c/p>\u003cp>4. 说出需求：然后对孩子说：“宝贝，我知道你很想让我陪你聊聊”，但是，我还有很急的工作没有做完，马上就要开课了，妈妈感到很焦急，担心来不及上课，我想要现在赶紧去把稿子写出来，所以今天我就不陪你聊了，谢谢你理解妈妈。”\u003c/p>\u003cp>如果我换成这样表达，亲子沟通时就会更加和谐，孩子可能会更加理解我。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>“表达需要4步曲”这个方法适用于沟通的场景中，也可以适用于自我察觉和反思。\u003c/p>\u003cp>当我们自己内心有需要，对方也愿意跟我们沟通合作，也有这个能力来满足我们这个需求的场景时，此方法非常适用。\u003c/p>\u003cp>如果当时情况比较紧急，或者对方不愿意跟我们沟通的时候就不太适合。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能有小伙伴会说，在冲突的时候跟对方沟通，可能对方比自己的情绪还要大，根本听不进去我说话，我还怎么让向他表达我的需要呢？\u003c/p>\u003cp>可以先暂停片刻，让彼此冷静一下，之后再表达自己的需要，这样沟通可能会更加顺利且有效。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】微行动学习：\u003c/strong>\u003c/p>\u003cp>【拆书家提问】\u003c/p>\u003cp>我们刚刚学习了“表达需要四步曲”。那么大家在表达需要的时候，觉得1体会情绪，2自我提问，3寻找需要，4说出需求，这4步，联系自己的实际生活或者过往经验，哪一个步骤最难呢？\u003c/p>\u003cp>选一个你认为最难实施的点把它写在便签上！给大家30s的时间。\u003c/p>\u003cp>Ok，现在我们都有了一个问题。\u003c/p>\u003cp>【一、明确问题】3分钟\u003c/p>\u003cp>接下来，请大家把自己想好的问题在小组内分享出来，也可以写在拆页模版上。然后我们每个小组互相讨论，一个小组选定一个问题。给大家3分钟的时间。\u003c/p>\u003cp>【聚焦问题】我们刚才搜集到了两个小组各自推选的问题，大家对哪一个更感兴趣，\u003c/p>\u003cp>①：说出需求，（说出来很难）\u003c/p>\u003cp>②：体会情绪，（无法准确辨别自己的情绪）\u003c/p>\u003cp>③：寻找需要，（有时无法清楚自己的内心需要是什么）\u003c/p>\u003cp>【拆书家引导】：好，谢谢大家的反馈。但是因为今天时间有限，所以我们选一个最想解决，觉得最难的步骤，我们举手表决吧。\u003c/p>\u003cp>（举手表决一下）\u003c/p>\u003cp>①：说出需求，3票\u003c/p>\u003cp>②：体会情绪，1票\u003c/p>\u003cp>③：寻找需要，2票\u003c/p>\u003cp>【拆书家】好，那咱们现在针对【说出需求】这个点来共同解决一下，大家同意吗？\u003c/p>\u003cp>【学习者】同意！\u003c/p>\u003cp>【2、引导分组讨论问题本质】\u003c/p>\u003cp>好，我们就请小伙伴们在组内开展讨论，大家要结合自己的经验来探讨\u003cbr>为什么【说出需求】最难呢？产生这个问题的本质原因是什么？大家结合过往经验，尝试相互追问，进行深入探讨。给大家5分钟的讨论时间，讨论后还是请小伙伴分享你们的讨论结果。\u003c/p>\u003cp>【小伙伴分享】\u003c/p>\u003cp>糖糖：很多时候，我能自我觉醒知道自己的需要是什么，但是，表达不出来，有时是觉得对方根本不想听，不care我的想法，所以我就不说，自己忍着，其实也是很难受的。\u003c/p>\u003cp>山佳：有时跟我老公沟通的时候，他根本就不想听，我就不想跟他说了，就不会向他说出我的感受了。\u003c/p>\u003cp>【拆书家小结】\u003c/p>\u003cp>那我们一起来总结下，为什么【说出需求】最难呢？\u003cbr>1. 在说出需求之前，无法明确自己的真实需要；\u003c/p>\u003cp>2. 情境受限，在某些情形下，就是无法说出自己的需求；\u003c/p>\u003cp>3. 沟通对象不一样，有时也不想说出需求\u003c/p>\u003cp>4. 有时说出的需求被对方误解，有歧义\u003c/p>\u003cp>5. 语言受限，表达能力受限，不知道怎么说出来\u003c/p>\u003cp>\u003cbr>【3、明确问题的本质】\u003cbr>【拆书家引导】\u003c/p>\u003cp>刚刚大家提出来的这5个原因当中，哪一个原因最本质一些呢？或者这5个原因背后隐藏了一个最本质的原因是什么呢？接下来请大家在小组内继续讨论出一个最本质的原因来分享。\u003c/p>\u003cp>【小组分享】\u003cbr>“说出需求”这么难的5个原因中，我们选择了最本质的原因分为内部原因和外部原因。\u003c/p>\u003cp>内部原因 ：自己不明确自己的情绪和需要，自己不够稳定；或者自己的表达能力不够，说出的词汇可能不够精准时，没法说出自己的需要。沟通的方式也会影响沟通效果。\u003c/p>\u003cp>外部原因：情境不对的时候，或者沟通对象不合适、或者对方状态不合适的时候，就没法说出自己的需求。\u003c/p>\u003cp>【拆书家小结】：\u003c/p>\u003cp>根据大家的讨论结果，那我们大家确定找到的最本质的2个原因就是：\u003c/p>\u003cp>对内自己的情绪和表达能力，对外就是沟通情境和对象的状态 ，对么？\u003c/p>\u003cp>【小组回应】：\u003c/p>\u003cp>是的\u003c/p>\u003cp>【4、引导分组讨论解决方案】\u003c/p>\u003cp>那么接下来，我们就一起探讨一下怎么来解决这个问题。结合过往的生活经验，我们可以分步骤讨论 ，可以先讨论要把这个问题解决到什么程度，再讨论如何行动就能达到这个目标。\u003c/p>\u003cp>解决到什么程度：\u003c/p>\u003cp>【分享】\u003c/p>\u003cp>我自己的观点是：能辨别自己和对方的状态，然后结合实际情况表达需求。\u003c/p>\u003cp>小琼的观点是：当双方都比较稳定，当时的场景也是比较安全的时候，是可以表达出自己的需求的。\u003c/p>\u003cp>晶晶的观点是：能找准时机，准确表达自己的需求就行。\u003c/p>\u003cp>所以我们进一步讨论结果就是：当我们能确认自己和对方的状态，在安全的氛围下表达出来。这个问题解决到这个程度就很满意了。\u003c/p>\u003cp>【拆书家小结】根据你们的讨论，你们觉得就是“当我们能确认自己和对方的状态，在安全的氛围下表达出来”，到这个程度就满意了。我理解得对吗\u003c/p>\u003cp>【学习者】：是的\u003c/p>\u003cp>拆书家：那现在进一步在小组内 讨论如何行动能达到这个目标呢，要讨论出具体的行动步骤，时间3分钟。\u003c/p>\u003cp>【5、学习者讲解讨论成果方案】\u003c/p>\u003cp>我们讨论的解决办法\u003cbr>【小组代表晶晶分享】\u003cbr>我们讨论后的解决办法是\u003c/p>\u003cp>1. 确认自身情绪：\u003c/p>\u003cp> 体会自己当下的情绪，确认自己的情绪的平和的。\u003c/p>\u003cp>2. 确认对方状态：\u003c/p>\u003cp> 观察对方的情绪和状态，确认对方也是情绪稳定的。\u003c/p>\u003cp>3. 确认氛围安全：\u003c/p>\u003cp> 确认当下要沟通的环境是比较安全而且利于沟通的，避免在空旷吵杂的环境中。\u003c/p>\u003cp>4. 说出内心需要\u003c/p>\u003cp> 可以结合之前学习的流程说出自己的需要：1.说事实；2表感受；3说需要\u003c/p>\u003cp>【拆书家】：大家觉得这些方法能不能解决“【说出需求】很难”的问题呢？\u003c/p>\u003cp>【学习者】：我们觉得能。\u003c/p>\u003cp>【拆书家引导】：\u003c/p>\u003cp>经过刚刚的讨论，我们得到了“说出自身需求比较难”的解决方案。非常感谢大家的智慧，大家都很棒！\u003c/p>\u003cp>相信经过这次学习，大家对如何使用“表达需要四步曲”表达自己需求有了更深刻的理解，希望大家在工作生活中能积极地使用这个方法。\u003c/p>\u003cp>\u003cstrong>[A2]催化应用提问设计：\u003c/strong>\u003c/p>\u003cp>为了巩固今天的学习成果，让大家更好学以致用。给大家布置一个任务，帮助大家更有意识去使用这个技能。\u003c/p>\u003cp>在未来一周，记录一次使用“表达需要四步曲”来向别人表达一下自己未能被满足的需要，并让对方明白你的需要。\u003c/p>\u003cp>比如：你爱人答应周末陪你却跑去加班了，你不想做饭， 你不太想运动， 闺蜜约你逛街，你不太想去等等。以上是设想的一些场景，大家可以回去以后试着在自己生活的场景中表达自己。\u003c/p>\u003cp>要求：下下周一之前将内容分享在群里。\u003c/p>\u003cp>期待大家的作业哦！\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>我们来总结一下今天的内容。\u003c/p>\u003cp>首先学习了如何区分“想法”与“感受”，并能够通过表达感受四步法来描述自己的感受（1停下来，2找事实、3匹配感受情绪词、4说出感受）；并且在现场运用了“表达感受四步法”写出未来可能出现的场景小剧本。\u003c/p>\u003cp>那表达完自己的感受后，别人理解了我们的情绪与感受，但是我们目的和需求并没有达到，那我们该如何正确提出自己的需求呢？\u003c/p>\u003cp>接着在第二个片段，我们又一起学习到察觉自身未能满足的需要后，通过表达需要四部曲（1体会情绪、2自我提问、3寻找需要、4说出需求）来说明自身的需要，并且在现场与小伙伴们一起讨论，找出自己表达需要时较难实施的步骤【说出需求】，并找到了解决方案与细分步骤。1.确认自身情绪；2.确认对方状态；3.确认氛围安全；4.说出内心需要。\u003c/p>\u003cp>以上是我今天要分享的全部内容， \u003c/p>\u003cp>愿今天的分享，你我都能有所成长。感谢大家的聆听，谢谢。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>【云云】：周六看到孩子起床不马上洗漱吃早餐，直接就开始沉浸式玩玩具，怎么喊都不理，我就很生气。当我觉察到自己情绪上来的时候，我用到了表到需要四部曲。\u003c/p>\u003cp>1. 我刻意让自己冷静了下，觉察了一下，感受自己现在的情绪是生气、愤怒\u003c/p>\u003cp>2. 然后我开始问我自己，我为什么会生气？因为我喊他他不理我，而且现在9点了，他还不洗漱吃东西。\u003c/p>\u003cp>3. 寻找我的需求——为什么他不理我，我就愤怒了，因为我想让他听到我喊他去洗漱东西，不因为饿肚子把胃搞坏了。我想要他健健康康的，不生病。\u003c/p>\u003cp>4. 说出我的需要，当时孩子还是比较好沟通，当时情景也是适合沟通的，所以我打断了孩子，两双眼睛互相对视着，然后告诉他 我的需求：我看到你9点了还不洗漱，不开始吃早餐，我感觉很担心你的胃会因此饿坏，饿坏了这样对你的身体影响很大的，我希望你健健康康的，不生病，所以妈妈建议你去洗漱再吃完饭之后来玩玩具，ok吗？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1682045712000,"updated_at":1688355915000,"ria":true},{"id":15591,"topic":"如何合理地表达愤怒？","learn_goal":"","remark":"如何合理地表达愤怒，对于我们每一个人都至关重要。让我们走进《非暴力沟通》一书，学习合理表达的四要素。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"吴超","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>学习目标：在跟随我完成本次RIA现场学习后，学习者能够在愤怒时不再恶语相向，而是能先停下来深呼吸，能够去表达自己的感受需求。\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>各位好，我是吴超。我的三个标签是：跑步爱好者、阅读爱好者、非暴力沟通学习者\u003c/p>\u003cp>1、第一个标签是跑步爱好者。跑过很多次马拉松，累计跑量一万多公里。\u003c/p>\u003cp>2、第二个标签是一名阅读爱好者。因为我非常喜欢阅读，我平均每年的阅读量在100本左右，同时我也坚持绘制了100多本书籍的思维导图； \u003c/p>\u003cp>3、第三个标签是非暴力沟通的学习者。因为非暴力沟通的方法对我的生活影响深远，非暴力沟通让我收获了更为融洽的人际关系，帮助我减少了很多不必要的烦恼。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>今天和大家分享的拆页内容选自《非暴力沟通》，刚刚提到了非暴力沟通对我影响很大，所以想要把它分享给大家。\u003c/p>\u003cp>F：\u003c/p>\u003cp>《非暴力沟通》这本书的作者是马歇尔.卢森堡博，非暴力沟通 不仅是一种沟通方式，更是一种语言、思维和生活方式，它能促进我们与自己、与他人建立真诚的联系，最终实现顺畅的沟通。非暴力沟通是一种心的语言，其本质是心与心的连接。\u003c/p>\u003cp>A：\u003c/p>\u003cp>这本书豆瓣上的评分高达8.4分，被称为心理学的经典之作，也被称为沟通领域的圣经，这本书不同于一般心理学书籍的枯燥，它提出了大量丰富的案例，可供有沟通需求的人去实践学习。\u003c/p>\u003cp>B1：\u003c/p>\u003cp>阅读非暴力沟通这本书，不仅能帮助我们提升沟通能力，更能帮助我们建立起和谐的生命体验。\u003c/p>\u003cp>B2：\u003c/p>\u003cp>如果你曾因为不恰当的沟通产生冲突，或者不知道如何合理的表达愤怒的情绪，今天要和大家分析的拆页，相信能带给你启发。\u003c/p>","ratings_count":2,"texts":[{"id":19649,"quote":"\u003cp>【R:原文拆页】\u003c/p>\u003cp>《非暴力沟通》P159-160\u003c/p>\u003cp>来看看充分表达愤怒的具体步骤。首先，停下来，除了深呼吸，什么都别做，不去指责或惩罚他人，只是保持安静。接着，看一看是什么想法让我们生气。例如，无意中听到某人说了一些话，使我们相信自己由于种族的缘故遭到了排斥。感知到自己的怒气时，如果停下来，便会看到头脑中盘旋的想法：“这太不公平了！她这是种族歧视！”我们知道，所有的评判都在用可悲的方式表达未满足的需要。\u003c/p>\u003cp>于是，接下来的第三步是：与这些想法背后的需要连结。如果指责某人是种族主义者，我们的需要也许是融合、平等、尊重或者与人连结。\u003c/p>\u003cp>为了充分表达自己，我们需要采取的第4 步是开口表达愤怒——怒火此时已被转化为感受和需要。然而，表达此时的感受也许要很大的勇气。对我来说，生气并冲着人们嚷“你这样做是种族歧视”是很容易的，甚至还会感到很畅快。然而，要说出内心深处的感受和需要，却可能令人却步。为了充分表达愤怒，我们也许可以试着和对方说：“你走进房间后，开始与其他人聊天，却没有和我说话。接着，你开始议论有关白人的种种。当注意到这些时，我的胃非常不舒服，我也很害怕。这使或意识到，我非常希望受到平等的对待。我想请你告诉我，听到这些话，你的感受是怎么样的？”\u003c/p>","explains":"\u003ch2>【I拆书家讲解指导】\u003c/h2>\u003ch2>这个片段介绍了在愤怒时，我们可以通过4个步骤让自己冷静下来，实现有效的沟通。\u003c/h2>\u003ch2>学会正确地表达愤怒对我们每一个人都至关重要，大多数人在遇到让自己愤怒的事时，要么一味隐忍、要么恶言恶语相向、要么直接武力解决。这样容易导致关系破裂、或者引发冲突。\u003c/h2>\u003ch2>\u003c/h2>\u003ch2>【举例子】\u003c/h2>\u003ch2>上个月我和朋友约了一起去跑二环路，我在约定早上7:30准时到达起点，然后一起出发。可是我等到了8点多他才到，我非常生气，我说昨晚不是已经提前提醒过你了吗，不要迟到，可还是迟到了，你怎么这么不靠谱！！结果导致不欢而散。\u003c/h2>\u003ch2>\u003c/h2>\u003ch2>案例反思：【how】：\u003c/h2>\u003ch2>在我们阅读了今天这个片段之后，我对当时的表达有了反思。回到当时的场景我应该怎么去表达愤怒呢？我提炼了四个步骤：&quot;停&quot;&quot;问&quot;&quot;找&quot;&quot;说&quot;！\u003c/h2>\u003ch2>\u003c/h2>\u003ch2>第一步 停：&quot;停&quot;下来深呼吸\u003c/h2>\u003ch2>当时正在气头上，不用那么着急去质问他。当愤怒来时，什么都不要做先静下来，深呼吸。\u003c/h2>\u003ch2>第二步问：&quot;问&quot;自己为什么会生气。\u003c/h2>\u003ch2>找到了自己生气的因为：当时的想法是觉得对方没有重视这一个活动，没有尊重自己。\u003c/h2>\u003ch2>第三步 找：&quot;找&quot;到自己的需求\u003c/h2>\u003ch2>需要对方更加重视一下自己的时间，同时需要对方下次能够准时到达。\u003c/h2>\u003ch2>第四步 说：表达感受和需求\u003c/h2>\u003ch2>咱们之前一起约跑步，你好几次都迟到了很久，让我们感受到你没有重视这一个活动，也没有尊重我的时间。希望你之后能够更加重视一下这个活动，尊重彼此的时间，下次不要再迟到了！\u003c/h2>\u003ch2>\u003c/h2>\u003ch2>表达我们的感受和未被满足的需要。这里重点是表达我们的愤怒，而不是愤怒的表达。可以这样句式表达：陈述事实...我的感受...，自己看中的是...我的请求是...。\u003c/h2>\u003ch2>\u003c/h2>\u003ch2>【预防异议】：\u003c/h2>\u003ch2>有些人可能会说，当愤怒来的时候，我们好像被愤怒操控了一样，根本没法静下来，也就没办法用这四个步骤来表达愤怒。针对这一点我想说，是的，正因为不能有效表达愤怒所带来的后果很可怕。所以我们更应该好好运用表达愤怒四步法。刚开始可能有些困难，但是经过不断的刻意练习和复盘累积经验，一定会用得越来越好。\u003c/h2>","interaction":"\u003cp>【A2:激活学习者经验】\u003c/p>\u003cp>A学习者拆为己用：学习者拆为己用：\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>催化应用\u003c/p>\u003cp>（分步催化1）\u003c/p>\u003cp>接下来大家想象一下未来一周或者两周内，我们日常生活中会遇到哪些让自己愤怒的场景呢？比如说：朋友答应帮你做一件什么事情，然后时间到了但是对方并没有去做！再比如说：跟朋友约好了一起逛街吃饭，你到了约会地点久等不来，给朋友打电话她却说，忘了，有了别的安排去不了了！然后你确实挺生气的。接下给大家三分钟时间，在小组内进行分享，再每组请一个代表公开分享。\u003c/p>\u003cp>张先生：关于亲密关系，我跟爱人结婚六年半的时间，但是自从有了孩子之后，因为孩子的学习问题经常会争吵，所以在未来一两个周还是可能会有这样的引爆点，会引发愤怒！\u003c/p>\u003cp>海先生：就是在日常的工作中，我一个同事经常会催我工作的进度，因为我手里同时有 3 个要交的活，我同事那个并不是那么着急，他们没有截止日期，但是我手里其他的活是有截止日期的，所以在他反复催我的时候我可能就会有一些不耐烦，甚至会感到愤怒！这样的事情其实在之前也有发生过！未来一两周可能还会发生！\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>催化应用\u003c/p>\u003cp>（分步催化2）\u003c/p>\u003cp>通过小伙伴对未来场景的分享，我们了解了哪些场景可能引起愤怒，接下来，请大家设想我们未来一周内或者两个周内发生了上面引发我们愤怒场景，我们如何运用今天学到的充分表达愤怒4步法表达愤怒让沟通产生更好效果呢？这里要注意要有具体的实施时间和具体的行动计划！给大家1分钟时间大家酝酿准备一下、然后请小伙伴们进行分享。\u003c/p>\u003cp>就是我们未来遇到愤怒的场景的时候，我们首先是能够去&quot;停&quot;下来，愤怒来时，什么都不要做先静下来，深呼吸；\u003c/p>\u003cp>第二的话就是能够去&quot;问&quot;自己为什么会生气；\u003c/p>\u003cp>第三就是能够“找”到自己生气背后的一个需求到底是什么。\u003c/p>\u003cp>第四步就是“说”能够去表达，说出你的这种你的需求或者你的感触是什么，进行一个良性的一个沟通。\u003c/p>\u003cp>对，就把这种表达结合到我们这个可能发生的一个场景中去。\u003c/p>\u003cp>海先生：\u003c/p>\u003cp>做一个什么事，就是用这个方法，就是下一次我们同事在催我的时候，进度的时候，因为我手里有 3 个能交的活，然后其中有一就是并不是那么着急，他们没有截止日期，但是我手里其他的活是有截止日期的，他下次再催我的时候你可以用这个方法。在表达一下自己的愤怒，我就会先“停”下来，然后把自己的情绪稳定一下，然后“问”问自己为什么生气？“找”到原因是因为我忙不过来，而且他这个是没有截止日期的，然后也就是说不着急，重要但是不紧急的一个工作。我会用到这个方法解决对那个我跟同事之间愤怒的问题，就是因为他那个手里有一个工作，嗯，然后会催了我好几次。然后但是属于不着急的那种工作，然后我用这个方法表达愤怒的时候，第一步，我就可以先停下来，冷静下来。第二步，然后问自己为什么这么生气的原因是，因为这个活不着急，但是他老催我。第三步我会问我自己的需求是什么？是我需要他理解，然后第四步跟他表达的时候也会去跟他说说，嗯，你看我现在手里有其他的活，这个活也没有截止日期，你能不能先让我把着急的活干完，然后马上接手你的工作？\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>最后希望大家经过今天的学习在日常生活中能够更好的表达愤怒，拥有更和谐的人际关系！感谢大家的聆听，今晚我的分享到此结束！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1681607675000,"updated_at":1699365886000,"ria":true},{"id":15506,"topic":"非暴力沟通","learn_goal":"","remark":"我们常常把夸奖当初杀手锏，批评不好使的时候就一顿夸奖，当时觉得特管用，但是，实际上一些夸奖很空洞也很片面，甚至是加入我们自己的评判标准，我们觉得很好，但是当事人不一定认同，甚至给人一种敷衍的感觉。效果并不好，而欣赏是透过现象看到实物本质，从事物本身看到积极、正能量的一面。所以，欣赏是很具体的，客观的姿态，不带任何情绪，不急不躁，恰如其分诚实的表达出我们内心对美好事物真实的感受。","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"晚柠-","city":"鄂尔多斯市"},"club":{"name":"鄂尔多斯天骄分舵","city":"鄂尔多斯"},"prologue":"\u003cp>\u003cstrong>准备：【分发拆页、分组、打招呼】时间：30&quot;\u003c/strong>\u003c/p>\u003cp> 不破不能立，不拆不成器，大家好！我是一级拆书家的晚柠，很高兴我能站在这里和大家分享拆页。绘本老师、终生学习爱好者、运动爱好者是我目前的三个标签，因为打算践行终身学习者的理念，所以加入到拆书帮学习，期待和伙伴们一起成长，相互学习。\u003c/p>\u003cp>【分组】咱们今天天气不好就选择线上拆书，线上拆书咱们没有超过六个人就统一分成一组.\u003c/p>\u003cp>\u003cstrong>【图书介绍FAB法】时间：30&quot;-2‘10&quot;\u003c/strong>\u003c/p>\u003cp>F特征（核心是“书”，用于满足好奇心）：我今天的拆页选自《非暴力沟通》，作者是马歇尔•卢森堡。这本书不仅帮助人们在生活和工作中利用非暴力沟通，实现良好的的倾听和表达，还帮助了许多国家之间解决争端和武力冲突。\u003c/p>\u003cp>A优势（重点是比较，用于建立安全感）：这本书豆瓣评分8.4分,全球销售破万。并且获得了各种国际大奖。而且咱们拆书帮的实录里面就有726篇关于非暴力沟通的实录，可见这本书有很大的阅读价值。非暴力沟通和一般沟通类书籍相比，非暴力沟通发现了沟通中的隐蔽暴力危害，它更注重倾听和表达，更深入探讨心灵深处的的感受和和需求，从而达到更高效、和谐的沟通。\u003c/p>\u003cp>B1（强调学习者利益）：俗话说：&quot;你赚的钱12.5%来自于知识，87.5%来自于人际关系，所以不管是想获得成功还是和谐美好的生活，建立良好的人际关系都非常重要，通过学习“非暴力沟通”采用描述事实、感受、需求、请求几点要素，实现和谐美好的人际关系，从而打开通往幸福人生道路的绿色通道。\u003c/p>\u003cp>\u003cstrong>【学习总目标】2‘10&quot;-2’30&quot;\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA拆书活动后，小伙伴们通过欣赏四步法和诚实表达四步法，让旁边的小伙伴在理解和信任我们的前提下，彼此能够更真诚的表达出自己具体需要。(拆页一和拆页成递进关系)\u003c/p>\u003cp>\u003cstrong>【学习目标1】\u003c/strong>在跟随我完成拆页一RIA现场学习后，小伙伴通过学习欣赏四步法，找到一件他人令你欣赏的事儿，并且在A1环节分享给大家。\u003c/p>\u003cp>\u003cstrong>【学习目标2】\u003c/strong> 在跟随我完成拆页二RIA现场学习后，学习者可以运用诚实表达四步法，现场通过角色扮演，向对方提出具体的行动要求。\u003c/p>","ratings_count":0,"texts":[{"id":19550,"quote":"\u003cp>\u003cstrong>【R】阅读原书拆页一2‘32&quot;-3’33&quot;\u003c/strong>\u003c/p>\u003cp>如何表达欣赏?\u003c/p>\u003cp>参与者十六:你能否说一说，为了表达欣赏你所需要的三点是什么?\u003c/p>\u003cp>马歇尔:我们需要三点来表达欣赏--不是夸奖，因为非暴力沟通中没有所谓的夸奖。夸奖是一种典型的评判技巧;管理者喜爱夸奖，因为他们声称研究表明，如果每周至少夸奖下属一次，下属会表现得更好。在员工意识到其中的操控意味之前，夸奖确实会起一阵子作用。在非暴力沟通中，我们给予欣赏，从来都不是为了在别人身上起到什么效果。我们给予欣赏不只是为了赞美，让他们知道，我们对他们做的某些事感觉多棒。这三点是:\u003c/p>\u003cp>V对方做了哪件让我们欣赏的事情，对此我们心中有数\u003c/p>\u003cp>√我们的感受\u003c/p>\u003cp>√我们已得到满足的需要\u003c/p>\u003cp>\u003cstrong>【学习目标1】\u003c/strong>在跟随我完成拆页一RIA现场学习后，小伙伴通过学习欣赏四步法，找到一件他人令你欣赏的事儿，并且在A1环节分享给大家。\u003c/p>\u003cp>\u003cstrong>【R】阅读原书拆页二\u003c/strong> \u003cstrong>1.5分钟\u003c/strong> \u003cstrong>17‘36&quot;-18’57&quot;\u003c/strong>\u003c/p>\u003cp>现在请大家用1.5分钟的时间阅读。读完后请抬头示意我一下。\u003c/p>\u003cp>为了彼此能乐于互助，我们专注于四个方面--非暴力沟通模式的四个要素。\u003c/p>\u003cp>首先，留意发生的事情。我们此刻观察到什么?不管是否喜欢，只是说出人们所做的事情。要点是，清楚地表达观察结果，而不判断或评估。接着，表达感受，例如受伤，害怕，喜悦，开心，气愤等等。然后，说出哪些需要导致那样的感受。一旦用非暴力沟通诚实地表达自己，前三个要素就会得到体现。\u003c/p>\u003cp>举例来说，一位母亲可能对她处于青春期的儿子说:“菲利克斯，看到咖啡桌下的两只脏袜子和电视机旁的三只，我不太高兴，因为我看重整洁。”\u003c/p>\u003cp>接着，她立即提出非暴力沟通的第四个要素--具体的请求:“你是否愿意将袜子拿到房间或者放进洗衣机?”这一要素明确告知他人，我们期待他采取何种行动，来满足我们。\u003c/p>\u003cp>这样，这位母亲就清楚地说出非暴力沟通的四个要素。借助这四个要素诚实地表达自己，是非暴力沟通的一个方面。\u003c/p>\u003cp>\u003cstrong>【学习目标2】\u003c/strong> 在跟随我完成拆页二RIA现场学习后，学习者可以运用诚实表达四步法，现场通过角色扮演，向对方提出具体的行动要求。\u003c/p>","explains":"\u003cp>\u003cstrong>拆页一\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 【学习目标1】\u003c/strong>在跟随我完成拆页一RIA现场学习后，小伙伴通过学习欣赏四步法，找到一件他人令你欣赏的事儿，并且在A1环节分享给大家。\u003c/p>\u003cp>\u003cstrong>【分享I便签】\u003c/strong> \u003cstrong>3‘52&quot;-9’39&quot;\u003c/strong>\u003c/p>\u003cp>（what）:这个拆页通过三点让我们理解如何欣赏别人，且不做评判的夸奖，从而让我们彼此都感到身心愉悦，收获信任。\u003c/p>\u003cp>  (why)如果我们不用这个方法，而常常采用夸奖这个杀手锏，那你的说辞难免空洞且片面，甚至给别人一种敷衍的感觉，效果并不长久。但是欣赏呢，它是透过现象看到事物本质，从事物本身看到积极、正能量的一面。所以，欣赏是很具体的，客观的姿态，不带任何情绪，不急不躁，恰如其分表达出我们内心对美好事物真实的感受。\u003c/p>\u003cp>（反面例子）在生活中很多人确实是不会表达欣赏的。拿我来举个例子，我和我对象最近开始尝试经营一下自己的生活，之前我们在各自的家里让贯的，基本不怎么做家务，那待在一起也没有别人帮忙，得自己动手丰衣足食。当时我心里想：“他可能也会像我听到的那些新婚的男士们，整日与手机为伍，肯定也不做”。但是，万万没想到，我做完饭，他主动提出我们分担家务----收拾厨房、刷碗。我当时就说：哈呀，你还会干家务呢?他说：“你以为就你会了”当时心理多少有点不舒服，也就各自玩各自的撇开了这个话题。\u003c/p>\u003cp>  (how)听完这个例子你可能会想：这不就是我的日常嘛，那我怎么才能发现身边的人值得欣赏的地方呢？然后还怎么能恰当表达出对对方的欣赏之意呢？那么我就在这里细化出四个步骤来供大家参考：\u003c/p>\u003cp>\u003cstrong>（第一步和第二步由原文的第一点细化而出的步骤）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：列清单\u003c/strong>\u003c/p>\u003cp>观察他们做出的哪些事情值得欣赏。这点判断比较难，是需要你去留心观察和思考。比如，你的同事最近的工作出错率明显下降；最近孩子在能在课堂上认真听讲了，不在和同学交头接耳；你的另一半慢慢的帮着你一起分担家务了。那这些发生改变的的事情，开始向好的方向发展或者正能量的事情就是值得欣赏的事。\u003c/p>\u003cp>\u003cstrong>第二步：找关联\u003c/strong>\u003c/p>\u003cp>找出与我有关值得欣赏的事件。值得欣赏的事儿挺多，但是，不关乎自己的情况下感受也并不会那么深刻。\u003c/p>\u003cp>\u003cstrong>第三步：表感受\u003c/strong>\u003c/p>\u003cp>描述具体值得欣赏的事件+你的感受。你做....让我感觉（开心、难过、伤心...）\u003c/p>\u003cp>\u003cstrong>第四步：提需求\u003c/strong>\u003c/p>\u003cp>需求得到满足，表达你的谢意。谢谢你满足了我……（亲近的人还可以使用肢体语言）等。\u003c/p>\u003cp> 【加工成正面例子】通过学习表达欣赏的四步骤，我意识到我自己在欣赏对方方面做的不够，如果回到刚才的例子，我怎么表达对对象的欣赏呢？第一步，列清单。他做事细心，情绪稳定，工作中热心帮助同事。第二步，找关联。他帮着我一起收拾厨房、帮我刷碗。第三步，表感受。我会和他说：“哇塞！博伟你把桌子、厨房收拾的好干净，而且你主动承担洗碗这件事让我觉得特别开心。第四步，提需求。你满足了我也是需要被帮助的需要，谢谢你博伟，拥抱一下’’。我想我们彼此会感受到愉快的。\u003c/p>\u003cp>（where）\u003c/p>\u003cp> 那这个拆页的适用范围是，你想进一步促进良好的关系，增加信任时，比如亲子关系，亲密关系，合作关系是非常有帮助的。但是，也不是随便使用，比如随便一个甲乙丙丁，你也不和他们有深层链接，其实也不需要花费这个精力。\u003c/p>\u003cp>\u003cstrong>【预防可能的异议】\u003c/strong>\u003c/p>\u003cp>可能有伙伴心理会想：说话之前还得思考第一步，第二步…那在实际生活中太难做到了吧。难，是我们感觉很难，你可以从微行动开始，哪怕每次你只用一个条也行，慢慢的尝试其他步骤，随着时间的推移，表达欣赏这种沟通技能也就信手捏来啦。不要害怕困难，先从尝试其中一个步骤开始，相信你们一定会做的很好\u003c/p>\u003cp>\u003cstrong>拆页二\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习目标2】\u003c/strong> 在跟随我完成拆页二RIA现场学习后，学习者可以运用诚实表达四步法，现场通过角色扮演，向对方提出具体的行动要求。\u003c/p>\u003cp>\u003cstrong>【分享I便签】\u003c/strong> \u003cstrong>19‘20&quot;-22’03&quot;\u003c/strong>\u003c/p>\u003cp>【what】这个片段主要通过四个要素来说明如何实现诚实沟通。\u003c/p>\u003cp>【why】不这么做的坏处：\u003c/p>\u003cp> 如果你不塑造诚实沟通的思维模式时，你可能一张嘴就“杀敌一千”还不知道别人为什么要远离你，这样为了趁口舌之快，而伤害彼此的情感。\u003c/p>\u003cp> 你学习了诚实沟通的四要素，你可能有意识的规范自己的语言，既表达出自己内心最深处的真情实感，也让彼此双方感到舒适，真诚。这不就是大家想努力成为的高情商嘛。\u003c/p>\u003cp>【how】我通过阅读原文拆页，总结出实现诚实沟通的四个步骤：\u003c/p>\u003cp>第一：讲具体事。我看到/听到/感受到…\u003c/p>\u003cp>第二：表感受。例如，我感到…（开心、愉快、难过、伤心…）\u003c/p>\u003cp>第三：说需要。我需要你的…关心、爱护、理解…\u003c/p>\u003cp>第四：提具体请求。前面三步是在为最后一步作准备，为了让大家更好理解我就给大家举个例子。\u003c/p>\u003cp>\u003cstrong>【异议案例】\u003c/strong>：今天我在绘本馆给大家讲故事时，有一位小朋友大声唱起了歌，我就对这个正处于自我意识敏感期的2岁宝宝说：在老师讲故事的时候大你声唱歌，老师觉得很生气，因为我需要安静的听众。”接着，我立即提出诚实沟通的第四步--具体请求：“宝宝你是想在旁边休息一下再来听故事呢？还是想现在安静下来认真听故事？明确告诉小朋友，我们期待他采取的行动，来满足我们的需求。\u003c/p>\u003cp>【where】：诚实沟通适用于那些你认为你很重要的，不想因为自己不会表达而破坏的长久关系中，相反一些无关紧要的人也没太大必要花费那么大精力，一板一眼的按流程说话。\u003c/p>\u003cp>【预防异议】可能有小伙伴想我也觉得诚实沟通挺重要，也挺好。但是，我情绪一上来哪还有理智可言，一顿大发雷霆完事。但是，你想想啊，你是痛快了，对方心里可能憋着一口气，或者留下一道深深的伤痕，时间久了坏情绪越积越多，矛盾也会越来越深，那个时候想轻易解开心结可就很难了。所以，能用和平的方式沟通、解决问题，难道不是更好？\u003c/p>","interaction":"\u003cp>\u003cstrong>拆页一\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1】（激活学习者经验） 显像提问\u003c/strong> \u003cstrong>3分钟\u003c/strong> \u003cstrong>9‘40&quot;-13’24&quot;\u003c/strong>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>小伙伴们，你回忆一下，有没有类似的让你想表达欣赏的的场景？\u003c/p>\u003cp>比如：\u003c/p>\u003cp>1.你想和你另一半增进感情，最近观察到他身上值得让你欣赏的事儿。\u003c/p>\u003cp>2.想增进你和同事的信任度，有意观察到他们身上值得欣赏的点。（具体一点的情景）\u003c/p>\u003cp>3.你的下属在你出差的几天里出色的完成了那些你交代的很难的工作。\u003c/p>\u003cp>4.你的孩子完成了平常根本做不到的事儿。\u003c/p>\u003cp>5.你和你的朋友约定一起减肥，你三天打鱼两天晒网，但是，你的朋友非常有韧性，经过一定时间的坚持有很好的效果，你很欣赏她/他的态度。\u003c/p>\u003cp>【接下来请你花费30秒回忆一下自己的相关场景】\u003c/p>\u003cp>小伙伴们用1分钟在组内分享一下让你们很想表达欣赏的的场景。\u003c/p>\u003cp>由于时间关系我们请小伙伴们分享一下？\u003c/p>\u003cp>1. 【冉馨案例记录】：我要买去旅顺的机票，当时是我老公提出帮我买。买的时候他就很细心的考虑一些我没关注到的细节。当时去北京有两趟航班，有一趟比较晚上但是比较便宜，我说要不就订晚上的吧。我老公他就说订早上的，我当时也没有想太多，我说：“你自己看着定。”然后就他订了，结果订完以后，我才发现定的是早上的。我就询问老公晚上那趟价格不是更适合吗？他就跟我说：“你心真大，晚上的飞机到了那儿以后太晚了，可能大兴机场那个时候已经没有地铁了，你又带着孩子，万一有危险，或者是太晚太冷怎么办。”我老公他考虑的事情很周到，能关照到我想不到的问题，我很赏心他对我贴心的一面是，让我感觉他对待我们的生活很用心。\u003c/p>\u003cp>【拆书家反馈】姐夫真的是非常暖心 ，举动很值得欣赏。\u003c/p>\u003cp>2. 【龙肖行案例记录】：大家也知道我比较忙，不管是单位工作，还是我的攀岩事业也好，还是包括咱们拆书帮的工作也好，总之我很忙。所以我家两个孩子的生活和教育都是由我老婆一个人在全全负责。我老婆她也是老师，她也很忙。但是我老婆在照顾家庭这一点上，真的让我感到自愧不如。同时她做的很多事情很值得我欣赏，尤其她照顾两个孩子方面，每天五点多就起床为孩子们准备早饭了。晚上回来还要陪孩子学习整理孩子们用过的东西，还要准备第二天的好多需要准备的东西。以前没觉得这些东西有多么多么难，但是我自己做了几次后说实话真的很不容易。妻子的坚持与付出特别值得我欣赏。\u003c/p>\u003cp>【拆书家反馈】嫂子默默的付出很值得你的欣赏。\u003c/p>\u003cp>\u003cstrong>【A1+】 （学习者反思加工经验）13‘25&quot;-17’28&quot;\u003c/strong>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>1.刚才大家有回顾了自己关于欣赏的场景，那么现在再回顾一下今天拆页的内容：\u003c/p>\u003cp>第一：列清单\u003c/p>\u003cp>第二：找关联\u003c/p>\u003cp>第三：表感受\u003c/p>\u003cp>第四：提需求\u003c/p>\u003cp>接下来请小伙伴们回到刚才分享的场景中，再给你一次机会，运用今天学习的方法你会如何向对方表达欣赏之意呢？\u003c/p>\u003cp>【龙肖行分享记录】按照今天拆页学习的步骤的话，首先就是我在空闲的时候腾出一点时间认真的回想一下我和我妻子的生活，尤其这几年当中我家老大孩上小学了，我们家就更忙碌了。而老婆在这个家里面则付出的更多，比如她每天早上起来给全家人做早点、每天下了班收拾家、洗衣服……拿我来说我开会穿正装，休息穿休闲装，攀岩工作又穿运动装。这样一周下来衣服换的也非常多，我妻子任劳任怨帮我打理，还有在疫情期间又养狗养猫，家里整个是鸡飞狗跳，其实他做了很多值得我欣赏的事情，我在空闲时间罗列出一个清单，然后第二步。找关联。我每周出现的场合比较多，需要各类型服装，有时候去开会需要正装，那有时候我运动需要运动装，我有时候我又参加休闲活动需要休闲服。衣服经常换，每次换下的衣服下一次穿的时候都是干干净净的。第三步，就是我应该找一个机会表达出我的感受。告诉我的妻子她默默帮我收拾、洗衣服让我非常非常的感动。然后最后也会明确的告诉她：“你的默默付出满足了我那种被照顾的需求”，因为我的家庭情况你们也清楚，其实小时候还是比较缺乏关爱的，在这个点上我妻子给到了我满足被照顾的需要。\u003c/p>\u003cp>【拆书家反馈】感受到爱就要用心表达出来，掌声送给龙肖行。感谢龙肖行的分享，看来你今天充分学习到了拆页的内容。首先罗列出你爱人值得你欣赏的方方面面，然后又找到和你相关联的部分，其次，又表达了她做这些事情你的感受，之后你又提出了她满足了你被照顾的需求，表达非常完整。谢谢你给我们的分享，同时我也感受到家人之间表达欣赏是多么重要的一件事。\u003c/p>\u003cp>\u003cstrong>拆页二\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A3促动参与】22‘19&quot;-22’41&quot;\u003c/strong>\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>我们刚刚学习了诚实表达的四步法。为了让大家更好的理解学到的知识，现在请大家一起做个现场演练，我会给大家一个场景，请大家针对这个场景，使用诚实表达的四个步骤来进行演练。请大家认真听要演练的场景：\u003c/p>\u003cp>场景1.\u003c/p>\u003cp>（角色一）旺仔爸爸 （角色二）旺仔妈妈\u003c/p>\u003cp>周五上午，旺仔兴趣班老师通知下午2：30上书法课，当时旺仔妈妈有事儿就安顿旺仔爸爸去送娃娃，旺仔爸爸怕忘还写在备忘录上，结果下午把正事抛诸脑后而是带着娃娃去逛了游乐园。晚些时间书法老师就给妈妈打过电话来。问旺仔妈妈孩子怎么没去上课呢？一听这话，旺仔妈妈气不打一处来。平时就她自己带孩子，今天她有事儿，结果就这。想等父子俩回来劈头盖脸骂他们一顿，但是，旺仔妈妈坐在沙发仔细一想，“骂一顿也不是好的解决办法呀，可能骂完爸爸更帮不上忙了”，那妈妈该如何运用诚实沟通的四步法向爸爸提出具体要求呢?\u003c/p>\u003cp>【指令】小伙伴们对角色有没有疑问，或者有没有不理解的地方？我可以给解释。\u003c/p>\u003cp>给小伙伴们2分钟分别在小组内讨论一下，可以分别扮演场景中旺仔爸爸和旺仔妈妈的角色，帮助旺仔妈妈运用诚实沟通四步法向爸爸提出具体要求的同时还避免一场争吵。\u003c/p>\u003cp>【讨论时间到】小伙伴们都回到我这里，现在邀请一组小伙伴进行角色演练\u003c/p>\u003cp>【演练分享】\u003cstrong>26’46&quot;-31‘25&quot;\u003c/strong>\u003c/p>\u003cp>角色一旺仔爸爸-饰演者冉馨\u003c/p>\u003cp>角色二旺仔妈妈-饰演者尚老师\u003c/p>\u003cp>旺仔爸爸：等等……我们回来啦。\u003c/p>\u003cp>旺仔妈妈：你们回来了。\u003c/p>\u003cp>旺仔爸爸：今天可是玩儿好了，游乐场关门儿了都不回家，\u003c/p>\u003cp>旺仔妈妈：哎呀！你俩可是开心了是哇？\u003c/p>\u003cp>旺仔爸爸：挺开心的。\u003c/p>\u003cp>旺仔妈妈：那你能不能坐在沙发上，让娃娃先进屋玩儿一会儿，我有事情跟你谈一谈。\u003c/p>\u003cp>旺仔爸爸：能呀！\u003c/p>\u003cp>旺仔妈妈：说实话，其实我现在可生气了。\u003c/p>\u003cp>旺仔爸爸：为什么？\u003c/p>\u003cp>旺仔妈妈：这一下午气的我肚子都快要炸了。\u003c/p>\u003cp>旺仔爸爸：为什么生气？\u003c/p>\u003cp>旺仔妈妈：我看你到现在都没反应过来自己干了啥？今天两点半孩子是不是有书法课？我是不是之前嘱咐你一定要记得带孩子去上兴趣课？到现在你还没想起这件事呢？这你能不让我生气吗？\u003c/p>\u003cp>旺仔爸爸：哎呀！不好意思，你不说我还真给忘。你看我的备忘录上边儿还记着两点半去上书法课，但是后来就真的忘了。\u003c/p>\u003cp>旺仔妈妈：对，我能感觉到你开始自责了。就是之前我确实跟你千叮咛万嘱咐，让你记得上两点半的书法课，结果你到点儿竟然没去。书法老师给我打电话说孩子没去上课的时候，我当时一下子就气炸了。我想立即跟你打电话去责备你，我真的是要被气死了。但是，我又静下心想了想，生气也不能让你马上送孩子去上课。其实我特别需要你帮我分担一些孩子的教育，还有就是孩子上兴趣班的时候，你可不可以接送一下孩子，这样我心里面就会特别特别感激你。比如说下个周六咱家孩子还有兴趣班嘛，我希望你能准时准点儿的送到教室，你看可不可以？\u003c/p>\u003cp>旺仔爸爸：行，首先我对我今天这个粗心的行为跟你道歉，因为平时孩子就你带的多，我带的比较少，那这样的话，下周上课的话我就接送他去上课。然后慢慢也就习惯接送孩子这个事儿了。\u003c/p>\u003cp>旺仔妈妈：今天下午刚面对这个事儿的时候就特别想骂街，觉得已经忍无可忍一定要爆发一次，然后坐在家想了一想，觉得咱们俩之间应该好好沟通一下，然后你今天晚上这样跟我讲话的我心里觉得舒服多啦。\u003c/p>\u003cp>旺仔爸爸：我也很感谢你没有一进门就骂我，而是和我好好沟通。\u003c/p>\u003cp>旺仔妈妈：哈哈，我上午听了非暴力沟通的课，学习怎么进行诚实沟通，这不就在实践中练习到啦，如何提出自己的需要。我也反思了一下自己在过去总是指责你，也没提出自己的需求，今天能清晰的把自己的需求说出来也挺不容易的。\u003c/p>\u003cp>旺仔爸爸：我也感觉欣慰哪。\u003c/p>\u003cp>【拆书家反馈】感谢俩位小伙伴，我想给你们鼓掌。两位小伙伴清晰运用到今天学习的四个步骤，首先提到没有带孩子上兴趣班这个具体事情，然后表达出爸爸没带孩子上课这件事让妈妈气炸了，但是妈妈顺利的提出自己内心深处的需求，没有一味指责爸爸，明确告知爸爸需要得到爸爸的帮助。感觉大家已经很好的吸收了本篇拆页内容。谢谢俩位小伙伴的分享。\u003c/p>\u003cp>\u003cstrong>【A2催化反应】32‘02&quot;-31‘25&quot;\u003c/strong>\u003c/p>\u003cp>分步催化1（2分钟）拆书家提问设计\u003c/p>\u003cp>【拆书家描述使用场景的案例】\u003c/p>\u003cp>三天后的一个傍晚，你想要计划下周的生活和工作，你就想起今天学的拆页内容，你内心一阵热血沸腾，决定好好留意一下生活中需要调整的沟通的情况。比如你日常和你的另一伴因为孩子教育问题有分歧；你的孩子每天一放学回到家把衣服扔得到处是；你的合作伙伴总是临时改变你们的既定方案；你朋友们在一起老是揭你的短儿…你采用诚实沟通四步法如何与他们沟通一下，并且顺利提出你的具体要求。接下来请你设想一个你自己的场景并和小组成员分享一下。\u003c/p>\u003cp>由于时间关系我请一位学习者给大家分享一下你设想的情景。\u003cstrong>33‘52&quot;-38‘35&quot;\u003c/strong>\u003c/p>\u003cp>1.【冉馨分享】\u003c/p>\u003cp>你今天过的这个级的拆页，让我立即想起今天发生的事儿。感觉特别好。我们单位今天下午要开一个比较大的一个党委会，然后我徒弟和我在上午要准备一些会议的相关的准备工作。我们首先要做那个喜卡和椅子上贴的名字。我一直觉得我徒弟她是一个执行力非常强、且也善于动脑的人。但是，这一次我却注意到她没有思考，打坐签竟然是用白纸打。因为白纸不是很合适嘛，这是我经历的一个场景。\u003c/p>\u003cp>2.【尚老师分享】\u003c/p>\u003cp>我家孩子辅导作业上是需要爸爸经常帮助的。因为我不懂蒙语，我是汉族，爸爸是蒙古族。我们家小朋友如果蒙语作业上遇到不懂的时候，爸爸的第一反应，就是你去查字典，事实上孩子在问问题之前，他也就已经查过字典了，字典查不到，爸爸就说他查的不仔细，每次在这个时候，我容易跟他起冲突。\u003c/p>\u003cp>3.【龙肖行分享】\u003c/p>\u003cp>我和尚老师的挺接近的。因为家里有娃，而且我家老大现在不是刚上一年级嘛，其实玩儿性还比较大，老二还上幼儿园。所以老大写作业，老二在玩儿，这老大心就飘了，他就老想看她妹妹在干啥。在老大没上一年级以前我设想自己一定会正面去对待，也不会把情绪发泄在孩子身上。但是，现实往往都是情绪的表达，我觉得今天学完这个拆页，其实应该可以把自己内心真正的想法表达出来，哪怕她只是个孩子，也需要诚实的沟通啊，这是我想到的一个场景。\u003c/p>\u003cp> \u003cstrong>【A2】分步催化2（12分钟）\u003c/strong>（\u003cstrong>44‘41&quot;-56‘05&quot;\u003c/strong>）\u003c/p>\u003cp>谢谢冉馨、尚老师、龙肖行三位小伙伴的分享，看来在座的都是渴望进步的小伙伴，那么接下来请小伙伴们选定一个最贴近你生活的场景，运用刚学习的诚实沟通四步法，列出在你未来的生活中如何运用诚实是沟通四步法的计划。完成计划表的小伙伴可以在组内先分享一下你的计划。\u003c/p>\u003cp>时间到，接下来请小伙伴分享下\u003c/p>\u003cp>1. 【冉馨计划分享】：就我们准备喜卡和椅子上贴的名字这件事我打算明天去跟她谈谈。因为今天我看了他这个行为我其实什么也没做。然后明天我就去和她沟通一下。她用白纸打名字的事情让我很意外，首先我对他的期望值是比较高的。觉得我每个月在开会前准备资料她看我们在做的时候，我认为他是应该学到了。但是，没想到她没注意我平常怎么做。然后我要表达的感受就是：“你用白纸打名签我感到很意外，可能是因为我平时教的没有那么全面，然后导致你没意识到不可以用白纸打名签。”表感受。因为我对你的要求是比较高的，认为我不用教，你自己可以从别人那里自学到的，我一直认为认为你是学习力很强的人。当你出现这种不应该犯的错误时我觉得很意外。表达需求。会议上拿白纸打名字是会议禁忌，这算是会议事故。我的需要让会议顺利完成，不能有一点点的差错瑕疵。具体要求就是以后有不管是党委会或者其他会议，只要涉及到行政相关的一些会议呀，我们需要注意不能用白纸打名字。\u003c/p>\u003cp>【拆书家反馈】掌声送给冉冉姐，谢谢你分享，不能用白纸打名签这个禁忌我其实也不知道，今天冉冉姐讲了这个事情，让我也意识到了以后就打名字切记用白色的纸打。算是一个很好的警醒。那接下来有请尚老师。\u003c/p>\u003cp>2. 【尚老师计划分享】我计划明天晚上八点和我老公谈谈，今天正好人不在家。\u003c/p>\u003cp>【反馈】蓄势待发呀！\u003c/p>\u003cp>蓄势待发的事件就是陪孩子写蒙语作业，第一步是孩子有不会的题，我会跟孩子他爸说；“孩子有不会做的题，你就让他查字典，他没有查到，你就觉得他粗心，实际上他不会，蒙语里词中词尾的那些个变化对于新学的人来说很难，它从左边绕弯弯和从右边绕弯弯，它就是一个词尾的变化，就是孩子是没有掌握好，不是他粗心，我觉得孩子其实一直觉得很委屈，而且他被你批评之后仍然不会，还觉得自己很笨，作为母亲我看到这些也挺难过的，我不希望学习带给他的都是挫败的感受。“第三步就是我好希望你可以更好的理解孩子一些，他是真的不懂，也不是他懒，他心里面也特别着急。第四步。我特别希望你可以给他讲一讲蒙语里面词尾词中的变化，如何从字典里能够高效的查到这个词，希望在你的陪伴之下，掌握一些高效的查字查词的方法，让孩子慢慢掌握，我相信咱家孩子会学的很好。\u003c/p>\u003cp>【拆书家反馈】尚老师的要求非常具体和清晰，教给爸爸要怎么去帮助孩子去学习蒙语，如果我是孩子的，我一定会感谢有这样的妈妈。作为老师首先我能理解，孩子不是不想学，他可能是真的有困难，尚老师清晰的要求对我都很受用，谢谢尚老师的分享。\u003c/p>\u003cp>3. 【龙肖行计划分享】刚才尚老师的分享我听的很认真，我的同事也有很多是蒙古族的，然后也知道这个蒙语不太好学，和我们汉语其实差别特别的大。然后刚才听完，原来是这么个原因---关键是词尾不一样阿，在我看来都长得都一样，今天我也受教了。\u003c/p>\u003cp>那我说一下我的例子啊，还是关于我女儿写作业的事情。大家都知道我计划星期五下午要带着我女儿去长沙，参加咱们拆书帮十周年庆典，机票也都订。我给我女儿周五下午请了一下午假，拿这就涉及到一个提前完成作业的事情，以前别提前完成作业了，就是当天作业完成起来都比较拖沓。所以，这一次就借着这个机会要和他去谈一谈，这周周2、3、4怎么提前能把周末的作业写完。要聊的具体的事情。我说：“女儿我看到你把今天的作业写完了，非常好，但是老爸想和你商量一下咱们星期五下午就要坐飞机去长沙玩儿，期间我们就没有时间去写作业，而且你的作业又要必须在周日完成，因为星期一你要交的。”第二呢，说感受。我会和女儿说：“老爸我非常信任你一定会提前完成周末作业的。”因为我知道他写作业写的挺慢，当然我一直也不是很着急，因为我总觉得就是慢归慢，但是他只是去做就很好。毕竟刚上小学专注力还比较短，还老受妹妹的影响，或者旁边儿有个啥好玩儿的他的注意力就会跑掉，但是如果他要认真去做还是一定能完成的。所以我一定会去表达我对女儿的信任的。第三，提出具体需求。姑娘我们要一起出去玩儿，那这就是我们两个人的事情，我把我的工作交接完，你把你的作业写完。这样我们去了长沙就可以全身心投入不管是玩儿，还是参加活动，我们就心无旁骛的去做，对吧？第四步呢，我就要提出具体的要求。那你从明天开始，你就要周二就要把周三，甚至周四的作业写了，那你周四就要把周五甚至周六的作业写了，最差的结果也是你只留下一点作业，我们周日晚上回来以后可以少补一点作业。我们应该是周日晚上七点回来，这样留下的作业也是简单的作业比如说预习课文这类的，这样的作业也可以顺利完成。\u003c/p>\u003cp>【拆书家反馈】我觉得无论计划还是安排都非常的合理，你给女儿讲清楚这个事情，她可能心里面儿也会抓紧要完成这个事情，我们相信你姑娘一定能按时完成。\u003c/p>\u003cp>三位小伙伴们的分享的故事很贴近生活，相信你们肯定也会达成好的沟通效果，以一种特别高效的方式去解决问题。诚实沟通，它可以很好的帮助我们建立更好的关系。\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>仁者见仁，智者见智。好的沟通能减少80%的困惑，遇到正能量的事情积极表达我们的欣赏，遇到不如意的事情也可以平和的处理。让我们能更好的做到知彼解己。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1680487443000,"updated_at":1683562232000,"ria":true},{"id":15441,"topic":"沟通四步法，有效表达需求","learn_goal":"","remark":"恋人吵架“你不爱我”背后要什么\n工作时“那个人真烦”要怎么合作\n教育孩子“你这么不听话”想说什么\n非暴力沟通四步法\n帮助我们有效表达需求","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"琛君","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>大家好，我是张琛君。今天我的拆书主题是《\u003cstrong>沟通四步法，有效表达需求》\u003c/strong>。\u003c/p>\u003cp>关于我的\u003cstrong>三个标签\u003c/strong>是：培训与人才发展从业者、生涯咨询师培训师、一级拆书家。 \u003c/p>\u003cp>我在酒店地产互联网3个行业，进行了12年+的培训及人才发展工作。 \u003c/p>\u003cp>作为国家认证的生涯咨询师、培训师，专注于为在校大学生、0-3年职场人提供生涯培训及咨询。\u003c/p>\u003cp>一级拆书家是新标签，我在拆书帮学会让阅读 “拆为己用”，让每次阅读解决自己的问题，形成良性循环。\u003c/p>\u003cp> 2月份，我刚在工作中组织了一次兵荒马乱的大型活动，因为老板要参加、活动很重要，但过程中跟同事有很多冲突和碰撞，我经常情绪上头，影响沟通效果也影响自己的心情。保持良好情绪、有效表达需求成了我的课题。《非暴力沟通》正好是当下能帮我的书。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp> 希望通过今天拆页的学习，我们能结合自己的实际情况，选择一个近期比较重要的沟通场景，运营非暴力沟通中的4个要素步骤，制定一个自己的沟通步骤和话术，后续能够按照这4个步骤尝试沟通，表达自己的需求。\u003c/p>\u003cp>\u003cstrong> 书籍介绍1.5分钟\u003c/strong>（330字）\u003c/p>\u003cp>【F】《非暴力沟通》的作者马歇尔·卢森堡，他是全球首位非暴力沟通专家。这本书介绍了非暴力沟通的4个核心要素并解释每个要素对应的异议，让我们在沟通中能表达自己、聆听他人。\u003c/p>\u003cp>【A】对比同类书籍来说，非暴力沟通实操相对简单，把4个核心要素运用到表达自己的意愿、倾听他人的感受上即可。同时应用很广，书中的提供的例子基本覆盖我们日常的沟通场景、借鉴性高。\u003c/p>\u003cp>【B】运用非暴力沟通，我们能够更关注自己的需求、也更理解他人，在实现沟通目标的同时融洽工作、生活关系。今天拆页的学习，可以让我们在沟通中学会有效表达出自己的需求，在他人接纳的情况下影响对方的行为，达成沟通目标。\u003c/p>\u003cp> 接下来，让我们一起走进今天的拆页。请各位伙伴用2分钟的时间阅读一下拆页，阅读完成后，请举手示意我一下，谢谢。\u003c/p>","ratings_count":1,"texts":[{"id":19499,"quote":"\u003cp>\u003cstrong>【书籍】\u003c/strong>选自《非暴力沟通》英文版最新修订\u003c/p>\u003cp>\u003cstrong>【页码】\u003c/strong>P7-8\u003c/p>\u003cp>要达到让双方都能发自内心地相互给予，我们需将注意力聚焦在四个方面——它们是非暴力沟通模式的四个要素。\u003c/p>\u003cp>首先，\u003cstrong>我们观察实际上发生了什么\u003c/strong>。不论他人的言行是否有益于我们，我们只是去观察。要做到\u003cstrong>清晰表达所观察到的，我们的挑战在于不夹杂任何评判\u003c/strong>。不论喜欢与否，我们只是说出人们做了什么。\u003cstrong>第二步表达出我们看到这些行为时的感受: 是感到伤心、害怕、喜悦、有趣还是心烦呢\u003c/strong>? \u003cstrong>第三步，表达出我们的感受与什么需要相关联\u003c/strong>。通过对这三个要素的觉察，我们清晰和诚实地表达出自己的状态。\u003c/p>\u003cp>例如，一位母亲想和正值青春期的儿子用非暴力沟通的方式来说话，她可以这样来表达以上三个要素：“菲利克斯，看到咖啡桌下的两团脏袜子和电视机旁边的三团脏袜子，我很生气，因为我希望在我们共用的空间里能多些整洁。”\u003c/p>\u003cp>紧接着，她可以表达\u003cstrong>非暴力沟通的第四个要素——一个具体的请求\u003c/strong>：“你愿意把你的袜子放在你房间或放进洗衣机里吗？”我们借助这个要素提出对他人的期许，希望他（她）怎么做来满足我们的需要，让我们的生命更加美好。\u003c/p>\u003cp>非暴力沟通的一部分是对这四个要素的清晰表达，表达的形式也不拘泥于语言。\u003c/p>","explains":"\u003cp>拆页阅读就到这里，暂时没读完也可以。我们看到拆页中非暴力沟通的4个要求，我们看看如何在生活中用在4个要素表达需求。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>开头我提到的活动，因为当天老板要来且四点开始，我们需要在两点前完全准备好。一点时会场有一堆垃圾，我请同事联系保洁过来清理。\u003c/p>\u003cp>同事说：哎呀，咱们行政是第三方，午休时间是不会过来的。\u003c/p>\u003cp>我脑袋嗡得一下，心里想说：之前说过你联系行政，先问一下怎么了？老板参加的会行政会不重视么？你怎么这么不负责。我这段内心戏全是指责，说了不仅解决不了问题还容易矛盾升级。如果用4步法表示自己的需求应该是：\u003c/p>\u003cp>1-观察：我们的活动14:00需要准备好，目前还有1个小时的时间。你刚刚没有给行政打电话确认。\u003c/p>\u003cp>2-感受：我现在很着急。\u003c/p>\u003cp>3-需求：我希望活动前置准备在两点前完成，给其他突发事件预留点时间。\u003c/p>\u003cp>4-请求：请你现在先给行政前台打电话确认一下，如果行政说不行，我会再找行政领导沟通。\u003c/p>\u003cp>这种情况下，比单纯的指责更能使沟通有效。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>要注意的是，在表达请求环节时，不要带着否定的词语，要用肯定的、积极的、清晰的语言说请求。如果我们说带有否定性的词语，积极效果会打折。\u003c/p>\u003cp>比如，我们可以把：我希望你不要迟到，替换成：希望咱们后续见面时都能准时到约定地点。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2分步催化-激活应用场景\u003c/strong>（5分钟）\u003c/p>\u003cp>\u003cstrong>【提出问题】\u003c/strong>\u003c/p>\u003cp>现在请大家想一想，接下来的半个月，自己有没有需要使用非暴力沟通表达自己需求的场景？\u003c/p>\u003cp>比如：\u003c/p>\u003cp>你希望同事或下属能调整一些不合适的习惯或工作方式\u003c/p>\u003cp>希望孩子玩儿了玩具后简单收拾一下\u003c/p>\u003cp>希望爱人在吃完饭后能帮忙简单整理一下厨房\u003c/p>\u003cp>希望老人减少在某音或某多买一些质量不太好的东西，等……\u003c/p>\u003cp>\u003cstrong>【发出指令】\u003c/strong>\u003c/p>\u003cp>我们两两成组，大家可以根据自己的需要，参考这些例子选一个自己最近半个月需要沟通的场景。在小组内分享一下。\u003c/p>\u003cp> \u003cstrong> 【学习者的场景分享】\u003c/strong>\u003c/p>\u003cp> \u003cstrong>欣艾：\u003c/strong>跟女儿沟通一下她看动画片超时的问题，设定30分钟时间，实际会延长至40-50分钟。（希望孩子控制住、看动画片按照约定的时间控制时长）\u003c/p>\u003cp> \u003cstrong> 曹姐：\u003c/strong>跟母亲沟通听到电话及时接听的问题。（目前在电话旁边不听电话）\u003c/p>\u003cp> \u003cstrong>丹娜：\u003c/strong>跟孩子沟通自己主动制定学习目标和计划的问题。\u003c/p>\u003cp>\u003cstrong>【A2催化应用-规划应用步骤】\u003c/strong>（8分钟）\u003c/p>\u003cp>\u003cstrong>【提出问题】\u003c/strong>\u003c/p>\u003cp>下面请大家用非暴力沟通的4个要素法（观察、感受、需要、请求），来给自己规划一下，你在这个场景中将怎么表达你的需求。\u003c/p>\u003cp>\u003cstrong>1、观察：\u003c/strong>观察发生了什么并不带评价的说出事实。\u003c/p>\u003cp>\u003cstrong>2、感受：\u003c/strong>说出当你看到这个事情发生时你的感受是什么。 \u003c/p>\u003cp>\u003cstrong>3、需要：\u003c/strong>说出我们的感受与什么需要相关联。\u003c/p>\u003cp>\u003cstrong>4、请求：\u003c/strong>提出一个具体的、明确行为的请求。\u003c/p>\u003cp>\u003cstrong>【发出指令】\u003c/strong>\u003c/p>\u003cp> 大家可以根据刚刚第一步分享的场景，制定一下自己表达需求的步骤和话术，小组内分享一下。讨论结束后，邀请大家进行分享。\u003c/p>\u003cp> 【学习者的行动步骤】\u003c/p>\u003cp> \u003cstrong>丹娜分享：\u003c/strong>放学后这么长时间妈妈看你一直在玩儿玩具（观察），我担心你今天的作业要很晚才能完成，睡觉也会晚一些、影响第二天的状态（感受），我还是希望你第二天有好的学习状态（需要），期待你到家后能安排先写作业，作业完成后的时间都可以自主安排（请求）。\u003c/p>\u003cp>\u003cstrong> 欣艾分享：\u003c/strong>我看到你在看动画片基本都是在40-50分钟关掉平板，没有准时（观察），我担心这种不遵守承诺的行为会让他人对你的做事原则保持怀疑、影响关系，长时间看动画片也对眼睛不好（感受），我看重你遵守承诺的品格、也希望你有良好的用眼习惯（需要），我希望我们能做到2点，一是每次看动画片时能按照约定的时间关掉平板，如果当时间到了剩余的动画可以看完，不再多看；二是希望我们能好好沟通，如果哭了的话可以等情绪稍微稳定了我们再继续沟通（请求）。\u003c/p>\u003cp> 以上就是我今天的全部分享。如果后续我们遇到可能会有冲突或者自己情绪受到影响的沟通场景事，我们都能先观察事实并不带评价得陈述，描述自己看到事情发生的感受，表达自己的需求，最后提出一个正面的、明确的请求。帮助我们开启非暴力沟通的第一步。\u003c/p>\u003cp>也期待我们后续在每个沟通场景中，能感受到到爱和被爱，同时，能达成所愿。\u003c/p>\u003cp>谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1679990731000,"updated_at":1680520594000,"ria":true},{"id":15438,"topic":"非暴力沟通的四要素","learn_goal":"","remark":"F-特征Feature\n今天给大家带来的这本《非暴力沟通》为沟通类书籍，作者是美国著名的心理学家马歇尔 卢森堡，书里介绍的是一种神奇而平和的沟通方式，就是非暴力沟通，它让人关注于彼此的感受与需求，依照它来谈话和聆听，可以使人情愿相通，和谐相处。\nA-优势Advantage\n这本书是沟通类书籍的经典之作，在豆瓣上的评分高达8.4分，与同类书籍相比，它简单易懂，并且书中运用大量贴切的案例加深理解应用。可以满足各类读者的需求。\nB-利益Benefit\n本书倡导学习者通过全身心的观察、感受、倾听，真诚的表达感受和需求，代替原来指责、抱怨、批评和愤怒等负面情绪的思维方式及表达，与他人发生连接，让爱流动起来，使沟通畅通无阻。当你遇到与他人沟通不畅时，学会运用本片段“非暴力沟通的四要素”的方式去表达，可以让你与他人不知所措的交谈或相处，能够化险为夷，和睦相处。","level":"TF2-1","duration":26,"status":30,"type":0,"chaishujia":{"username":"裴红如","city":"邢台市"},"club":{"name":"邢台筹备分舵","city":"邢台"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>1分钟 \u003c/p>\u003cp>大家好，欢迎来到我TF2-1线上晋级现场，我是来自河北邢台的裴红如，\u003c/p>\u003cp>我的三个标签:\u003c/p>\u003cp>1.儿科医生，我在基层医院儿科工作了近20年，目前主要做儿童康复方面的工作。\u003c/p>\u003cp>2.心理治疗师，由于工作和个人爱好，侧重亲子关系、儿童心理方面;非暴力沟通践行者。\u003c/p>\u003cp>3.终身学习者，正在通往3级拆书家的旅程中，希望能提高自己的学习力，不断成长，使自己能发挥能量，助人达己。\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>在学习之前，我们先分一下组，请问，今天在线的伙伴们谁可以参与分享？如果你可以参与分享，请你在聊天区回复1，如果参加不了分享，请回复2，并在个人名称后加上“旁听”二字。（根据实际人数决定是否要分组来分享，还是全部在大组里，6人即分组。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>1分钟\u003c/p>\u003cp>今天的学习目标是通过本次RIA的现场学习，让学习者在面对曾经与他人沟通不畅的场景，不再不知所措，不逃避，不对抗，而是诚实地表达自己的感受和需要，以及提出具体的请求，让沟通更加顺畅，能轻松解决问题。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>3分钟\u003c/p>\u003cp>\u003cstrong>F-特征Feature\u003c/strong>\u003c/p>\u003cp>今天给大家带来的这本《非暴力沟通》为沟通类书籍，作者是美国著名的心理学家马歇尔 卢森堡，书里介绍的是一种神奇而平和的沟通方式，就是非暴力沟通，它让人关注于彼此的感受与需求，依照它来谈话和聆听，可以使人情愿相通，和谐相处。\u003c/p>\u003cp>\u003cstrong>A-优势Advantage\u003c/strong>\u003c/p>\u003cp>这本书是沟通类书籍的经典之作，在豆瓣上的评分高达8.4分，与同类书籍相比，它简单易懂，并且书中运用大量贴切的案例加深理解应用。可以满足各类读者的需求。\u003c/p>\u003cp>\u003cstrong>B-利益Benefit\u003c/strong>\u003c/p>\u003cp>本书倡导学习者通过全身心的观察、感受、倾听，真诚的表达感受和需求，代替原来指责、抱怨、批评和愤怒等负面情绪的思维方式及表达，与他人发生连接，让爱流动起来，使沟通畅通无阻。当你遇到与他人沟通不畅时，学会运用本片段“非暴力沟通的四要素”的方式去表达，可以让你与他人不知所措的交谈或相处，能够化险为夷，和睦相处。\u003c/p>","ratings_count":1,"texts":[{"id":19496,"quote":"\u003cp>下面请大家阅读我为大家准备的原文片段，给大家2分钟时间阅读，完成后的小伙伴请在对话框回复1，示意我一下。\u003c/p>\u003cp>\u003cstrong>【R】原文片段\u003c/strong>\u003c/p>\u003cp>\u003cstrong>《非暴力沟通》\u003c/strong> \u003cstrong>P6-7 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>非暴力沟通的四要素\u003c/strong>\u003c/p>\u003cp>\u003cstrong>为了彼此能乐于互助，我们专注于四个方面——非暴力沟通模式的四个要素。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>首先，留意发生的事情。我们此刻观察到什么？不管是否喜欢，只是说出人们所做的事情。要点是，清楚地表达观察结果，而不判断或评估。接着，表达感受，例如受伤、害怕、喜悦、开心、气愤等等。然后，说出哪些需要导致那样的感受。一旦用非暴力沟通诚实地表达自己，前三个要素就会得到体现。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>举例来说，一位母亲可能对她处于青春期的儿子说：“费利克斯，看到咖啡桌下的两只脏袜子和电视机旁的三只，我不太高兴，因为我看重整洁。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>接着，她立即提出非暴力沟通的第四个要素——具体的请求：“你是否愿意将袜子拿到房间或放进洗衣机？”这一要素明确告知他人，我们期待他采取何种行动，来满足我们。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这样，这位母亲就清楚地说出非暴力沟通的四个要素。借助这四个要素诚实地表达自己，是非暴力沟通的一个方面。\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导 7分钟\u003c/strong>\u003c/p>\u003cp>我看大家都完成了阅读。接下来咱们一起来学习这个拆页。\u003c/p>\u003cp>\u003cstrong>What:\u003c/strong>这个拆页告诉我们要想在生活和工作中做到良好沟通，和睦共处，可以应用非暴力沟通的四个要素“观察、感受、需要、请求”。\u003c/p>\u003cp>\u003cstrong>【常见错误做法】\u003c/strong>\u003c/p>\u003cp>在日常生活或者工作中，我们与他人进行沟通对话时，经常是站在自己的立场去对一件事请做出定义或者评判，对对方实际情况不考虑或者考虑不周，这样的沟通，使对方的反馈往往不是对抗就是默不作声，影响进一步的沟通。\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Why:\u003c/strong>导致问题不能解决，甚至使彼此的关系恶化。陌生人也还好，以后不会相见或者相见次数少，如果是家人或者朋友或同事，就会非常苦恼。\u003c/p>\u003cp>\u003cstrong>【举反例】\u003c/strong>\u003c/p>\u003cp>下面说一个我的失败案例:在我家里，如果儿子放假在家时，都是由他来收拾碗筷的，洗碗刷锅的，以前都是吃完饭就收拾利索了，在寒假里有两天我发现他不是吃完饭立马上去收拾，而是在饭桌旁刷手机，我对他说：“你先把这些收收拾好，再干别的”，他说：“好”，但不动；过了几分钟，我再说：“你把那个锅碗收拾干净再看手机”，他说“昂”，还是不动；再说他，他不耐烦的说：“你别管了，一会儿我弄了就是了”。我挺生气，没理他，就去别的屋了，因为我知道再说我俩就开始吵吵了，但我心里是不舒服，相信他心里也不好受，直到过2个多小时后他才收拾了。\u003c/p>\u003cp>\u003cstrong>【行动步骤】\u003c/strong> \u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>如何做到非暴力沟通呢，需要做好以下四步：\u003c/p>\u003cp>第一步、述事实\u003c/p>\u003cp>观察你所看到的他人的言行，不做任何定义和评判，只需说出他们具体的言行。\u003c/p>\u003cp>第二步、表感受\u003c/p>\u003cp>当你看到、听到别人的所做的言行时，你当时内心真实的感觉。\u003c/p>\u003cp>第三步：说需求\u003c/p>\u003cp>对对方说明你当下的感受是因为对方的言行没有达到你的什么需求。\u003c/p>\u003cp>第四步：提请求\u003c/p>\u003cp>提出你的请求，让对方知道如何做能够满足你的请求。\u003c/p>\u003cp>\u003cstrong>【反例变正例】\u003c/strong>\u003c/p>\u003cp>如果回到上面那种情况时：\u003c/p>\u003cp>我会选择这样做：一、述事实：对儿子说“乐乐”，我看到碗筷盘子还在饭桌上摆着没收拾里？二、表感受：看到饭桌上的一片狼藉，厨房里乱糟糟的，我就不舒服。并且锅碗瓢盆时间长了还不好刷；三、说需求：我喜欢咱们家生活的环境干净舒服，饭桌上干净，厨房整洁。四、提请求：你现在就收拾，完了在做其他的事情，可以吗？他说：“好吧，妈妈，我先收拾好”！\u003c/p>\u003cp>\u003cstrong>Where：\u003c/strong>这个方法适用于在生活和工作中与对方沟通不畅时，希望能继续沟通，解决问题情况时。\u003c/p>\u003cp>不适用于冲动想起冲突的情况时。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1显像提问】7分钟\u003c/strong>\u003c/p>\u003cp>学习要学以致用，拆为已用，想问一下大家，你是否也有与他人沟通不畅的经历：\u003c/p>\u003cp>比如:在家你与老公沟通让他收拾家务时，老公反过来一堆理由不做；\u003c/p>\u003cp>比如:或者吃完饭让孩子写作业而他执意要看电视；\u003c/p>\u003cp>比如:与同级别的负责人协商事情时，各执一词时；\u003c/p>\u003cp>比如:到银行办理业务时你看到工组人员磨磨蹭蹭，办的特别慢时，与他理论他还特别生气时。\u003c/p>\u003cp>请大家回忆一下，近一个月内有过类似的经历吗？是什么时候？是什么事情？结果怎么样？请想一想，大家按照之前的分组，在小组内和伙伴们分享，时间是3分钟。3分钟后我们请每组的1位小伙伴给大家分享下他沟通不畅时遇到的的场景。好的，现在开始。…分享（3分钟）\u003c/p>\u003cp>\u003cstrong>案例分享1：\u003c/strong>王丽老师分享与怀孕的弟媳妇相处中，关于做饭，做什么饭，谁做，沟通少并且不舒畅而心生埋怨的经历。\u003c/p>\u003cp>\u003cstrong>案例分享2：\u003c/strong>俞静分享的早上女儿不想上幼儿园，而她有急事要去处理，与女儿的不顺畅沟通引起的女儿苦闹，她焦急愤怒的经历。\u003c/p>\u003cp>\u003cstrong>感谢小伙伴的分享。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1+】反思加工\u003c/strong>\u003c/p>\u003cp>通过今天的学习，请大家结合咱们学习的拆页内容和大家刚分享的案例，如果时光倒流，回到从前那个时刻，应用非暴力沟通的四个要素“观察（述事实）、表感受、需要（说需求）、提请求”的沟通方式去沟通，你会如何沟通？下面邀请2位小伙伴来分享\u003cstrong>（4分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>案例分享：\u003c/strong>王丽老师分享到，通过今天的学习，如果时光倒流，她会在看到（观察）弟媳妇吃饭时吃得少或不吃的时候；主动和她沟通，我看到你吃的很少或不吃，我感觉困惑，委屈；我需要和谐、接纳、理解；我愿意帮助你，并能得到你的反馈，你有什么需要及时给我说，咱们一起商量，和睦相处。\u003c/p>\u003cp>\u003cstrong>感谢小伙伴的分享。\u003c/strong>好，鉴于时间的关系，我们今天的学习就先到这儿，学以致用，拆为已用。最后总结一下今天的拆书，我们学习了在日常生活和工作中出现沟通不畅时，可以灵活应用非暴力沟通四要素1、述事实2、表感受3、说需求4、提请求。帮助你有效顺畅沟通，也能解决问题，使我们的生活和工作更加和谐幸福！\u003c/p>\u003cp>我今天的分享就到此结束了，感谢大家积极参与和互动，希望这个小片段对各位小伙伴有帮助。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1679926541000,"updated_at":1680358229000,"ria":true},{"id":15404,"topic":"非暴力沟通的四要素","learn_goal":"","remark":"如何用不带伤害的方式化解人际间的冲突？\n如何建立更为和谐的生命体验？\n如何提升自己的沟通能力？\n如果你也有这些困惑，相信《非暴力沟通》这本书能带给你启发。\n\n非暴力沟通是一种以爱为出发点的沟通模式，也被称为爱的语言。\n可以让人们沟通后彼此尊重、相互理解。\n良言一句三冬暖，恶语伤人六月寒。\n你说出口的话将会改变你的人生！\n让我们一起踏上非暴力沟通的旅程吧！","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"吴超","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>各位好，我是吴超。我的三个标签是：铁三玩家、拆书家、非暴力沟通践行者\u003c/p>\u003cp>1、第一个标签是铁人三项。酷爱游泳，跑步和骑行。跑过很多次马拉松，累计跑量一万多公里，也喜欢长距离骑行，曾一人环滇池骑行一圈，游泳相对较弱，但在不断的精进之中。\u003c/p>\u003cp>2、第二个标签是一名拆书家。这是我非常喜欢的一个标签，因为我非常喜欢阅读，我平均每年的阅读量在100本左右，同时我也坚持绘制了100多本书籍的思维导图；\u003c/p>\u003cp>3、第三个标签是非暴力沟通的践行者。因为非暴力沟通的方法对我的生活影响深远，非暴力沟通让我收获了更为融洽的人际关系，帮助我减少了很多不必要的烦恼。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>今天和大家分享的拆页内容选自《非暴力沟通》，刚刚提到了非暴力沟通对我影响很大，所以想要把它分享给大家。\u003c/p>\u003cp>F：\u003c/p>\u003cp>《非暴力沟通》这本书的作者是马歇尔.卢森堡博，书中主要从观察，感受，需要和请求四个维度来教会我们如何与他人友好又高效的沟通。\u003c/p>\u003cp>A：\u003c/p>\u003cp>这本书豆瓣上的评分高达8.4分，被称为心理学的经典之作；相比起市面上大部分沟通类的书籍，这本书算是经典中的经典，也被称为沟通领域的圣经，这是一本非常值得我们阅读和学习的书籍。\u003c/p>\u003cp>B1：\u003c/p>\u003cp>阅读非暴力沟通这本书，不仅能帮助我们提升沟通能力，更能帮助我们建立起和谐的生命体验。\u003c/p>\u003cp>B2：\u003c/p>\u003cp>如果你曾因为不恰当的沟通产生冲突，拥有关于沟通的困惑，今天要和大家分析的拆页，相信能带给你启发。\u003c/p>","ratings_count":1,"texts":[{"id":19461,"quote":"\u003cp>【R:原文拆页】\u003c/p>\u003cp>《非暴力沟通》P007-008\u003c/p>\u003cp>非暴力沟通过程。\u003c/p>\u003cp>要达到让双方都能发自内心地相互给予，我们需将注意力聚焦在四个方面——它们是非暴力沟通模式的四个要素。\u003c/p>\u003cp>首先，我们观察实际上发生了什么。不论他人的言行是否有益于我们，我们只是去观察。要做到清晰表达所观察到的，我们的挑战在于不夹杂任何评判。不论喜欢与否，我们只是说出人们做了什么。\u003c/p>\u003cp>第二步，表达出我们看到这些行为时的感受：是感到伤心、害怕、喜悦、有趣，还是心烦呢？\u003c/p>\u003cp>第三步，表达出我们的感受与什么需要相关联。通过对这三个要素的觉察，我们清晰和诚实地表达出自己的状态。\u003c/p>\u003cp>例如，一位母亲想和正值青春期的儿子用非暴力沟通的方式来说话，她可以这样来表达以上三个要素：“菲利克斯，看到咖啡桌下的两团脏袜子和电视机旁边的三团脏袜子，我很生气，因为我希望在我们共用的空间里能多些整洁。”\u003c/p>\u003cp>紧接着，她可以表达非暴力沟通的第四个要素——一个具体的请求：“你愿意把你的袜子放在你房间或放进洗衣机里吗？”我们借助这个要素提出对他人的期许，希望他（她）怎么做来满足我们的需要，让我们的生命更加美好。\u003c/p>\u003cp>非暴力沟通的一部分是对这四个要素的清晰表达，表达的形式也不拘泥于语言。而另一部分则是从对方的表达中了解这四个要素。我们通过感知对方此刻的观察、感受和需要，与他们建立连结，进而聆听他们的请求，来找到通过什么方式让他们的生命变得更丰富。\u003c/p>","explains":"\u003cp>【I拆书家讲解指导】\u003c/p>\u003cp>WHAT：\u003c/p>\u003cp>非暴力沟通是马歇尔·卢森堡博士发现的一种沟通方式，依照它来谈话和聆听，能使人们情谊相通，和谐相处，非暴力沟通有非常重要的四个要素：“观察、感受、需要、请求”。\u003c/p>\u003cp>WHY：\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>暴力语言不仅会影响到我们的沟通，还会伤害感情。比如，“你总是不讲道理。你从来都这么自以为是。你这个人太自私了。你听不懂人话吗？”……这些都属于暴力语言，这些都非常容易引发对方的抵触情绪，或者说把对方激怒了，最终导致两败俱伤。正如《增广贤文》里的一句话：良言一句三冬暖，恶语伤人六月寒。学习非暴力沟通对我们非常重要。\u003c/p>\u003cp>HOW：\u003c/p>\u003cp>【正确做法】\u003c/p>\u003cp>怎么做到非暴力沟通，需要做好以下四步：\u003c/p>\u003cp>第一步：描述事实\u003c/p>\u003cp>正如哲学家克里希那穆提所言：“不带评论的观察是人类智力的最高形式”。在沟通之前我们首先要去留意发生的事情，就是你此刻观察到了什么?不管你是否喜欢，只是说出对方所做的事情，要点是清楚的表达你观察到的结果，而不去判断或者评估。表达事实的好处是不会引起反驳，因为事实是客观存在的，是无法让人辩驳的。\u003c/p>\u003cp>第二步：表达感受\u003c/p>\u003cp>表达你的感受，就是你观察到对方所做的事情，你的感受是什么样的。比如这件事情是让你感到，受伤，害怕，还是说让你感到喜悦或者开心呢。\u003c/p>\u003cp>第三步：体会需要\u003c/p>\u003cp>说出是哪些需要导致了你那样的感受。一个人之所以会生气往往是因为他内心的某种需要没有被满足，去觉察我们内心的需要无比重要。\u003c/p>\u003cp>第四步：提出请求\u003c/p>\u003cp>当我们觉察到自己的需要之后，使用正向具体的语言委婉地提出请求。即明确告诉对方你希望他采取何种行动来满足我们。注意是请求而不是要求。\u003c/p>\u003cp>反例：\u003c/p>\u003cp>我举一个生活中真实的例子，之前周末回家，我在家里玩手机，玩了一两个小时的手机，我妈妈看不下去了生气的和我说：”你一整天都无所事事，怎么那么懒。“当时我觉得她说这句话，其实就是一种暴力的语言在来表达。这种表达在我们每一个人的生活中其实非常常见。但是在我学了非暴力沟通这本书之后。把我自己换到她的位置，我会如何去用非暴力沟通进行表达呢？“整天都”、“无所事事”、“这么懒”，这些词都特别容易引发对方的抵触情绪。而当我们说的是自己的感受或者事实，而不再是评判的时候，往往更容易让对方理解和接受。\u003c/p>\u003cp>反思+正例：\u003c/p>\u003cp>我们把刚才的沟通用非暴力沟通的四要素来重新表达一下：\u003c/p>\u003cp>描述事实：我看到你坐沙发上刷视频已经两个多小时了\u003c/p>\u003cp>表达感受：这让我有一点不开心\u003c/p>\u003cp>体会需要：还有很多家务要做，需要帮忙\u003c/p>\u003cp>提出请求：你能帮忙把卫生打扫一下吗？\u003c/p>\u003cp>而当我们用非暴力来表达：我看到你在沙发上刷视频已经两个多小时了，这让我有一点不开心，因为还有很多家务要做，你能帮忙把卫生打扫一下吗？显而易见，这种表达一定要比：“你一整天都无所事事，怎么那么懒。“要好。\u003c/p>\u003cp>WHERE：\u003c/p>\u003cp>这种沟通方法运用相对比较广泛，在我们需要对方做出改变的时候，就可以用这种沟通方法来提出我们的请求。但是如果当对方情绪非常激动，场面混乱的时候，或者不愿意沟通的时候，我们可以另择时机再沟通。\u003c/p>","interaction":"\u003cp>【A1:激活学习者经验】\u003c/p>\u003cp>请小伙伴们想一想，在我们的日常生活中，或者在我们身边遇到的，有没有哪次对话让你或者让对方感到不开心，或者激怒了对方的情况出现，或者有没有那种给别人贴标签，进行道德评判，或者进行比较的情况出现，比如说你想要同事哪个方面作出改变，但是你却用要求的语言去表达，结果闹得很不开心等等。接下来会给大家1-2分钟的时间去讨论，然后会请一位小伙伴来分享。分享的时候请直接描述出当时场景终你自己或者对方说的那一句暴力的语言是什么！\u003c/p>\u003cp>郑勇：\u003c/p>\u003cp>我以前管孩子比较简单粗暴，我儿子在他上小学的阶段的时候，他就感觉他成绩不是很好，我就经常去说他不求上进。其实这样也帮助不了孩子。我当时完全陷入自我的一种情绪和感受当中。就是给孩子贴标签，而且当时是完全无意识的。\u003c/p>\u003cp>吴超：这是一个非常好的例子，因为这种情况在我们生活中其实是非常常见的。直接说孩子不求上进，这其实就是一种暴力的语言。我们刚刚学习了非暴力沟通表达的方法，描述事实，表达感受，体会需要，提出请求。如果我们运用这个方法回到当时的场景去和孩子沟通，应该怎样去沟通呢？大家按刚刚的分组再讨论一下后再进行分享。\u003c/p>\u003cp>【A1+ 请学习者反思加工经验】\u003c/p>\u003cp> 感谢小伙伴们的分享。假如再给你一次机会，回到当初的情景，用上今天学习到的非暴力沟通的四个要素，也就是描述事实、表达感受、体会需要、提出请求。你会如何去回应呢？再给大家3分钟，按照我们刚才的分组的情况，在小组内进行交流，然后请一位小伙伴进行分享。\u003c/p>\u003cp>郑勇：\u003c/p>\u003cp>首先把自己的情绪控制住，这是第一步。冷静下来，真正的去从事实去角度思考。比如我会说，诶你看最近你这字写的，包括这个考试的成绩，有几次都得的不是优秀，诶，我们就说我们已经连续几次考试了，你干嘛就这样。\u003c/p>\u003cp>第二个表达感受。我感觉你总是考试成绩处于这种阶段，我也是感到有些担心。因为随着年级不断地上升，可能面对学习的压力会越来越大，到时候你会自己也会有一些压力这些感受。\u003c/p>\u003cp>体会需要。可能是我们要不要制定一个计划，如何去一起来帮助你去解决学习上的困难，去突破评定，就这样的一个需求。\u003c/p>\u003cp>提出请求可能就是这个了，我特别期待你能够在学习上能够做一个比较轻松而不太有压力的状态去面对学习，不一定让你到非常优秀拔尖的状态，但是至少对于学习来说，不会给我们造成太多的负担。基本上就是这样的四个步骤。\u003c/p>\u003cp>吴超：对四个要素的掌握非常的到位，把分析过程都表达得特别清楚，特别精彩！那么，在我们分析的时候完之后，对于说孩子不求上进这个点，如果重新去跟孩子沟通，该如何去跟孩子沟通呢？可以再稍微概括地阐述一下。\u003c/p>\u003cp>郑勇：对于直接说他不求上进，重新根孩子沟通我可能会这样说：“我看你最近有时间你也不学习，周末的时候也不写作业，爸爸为你的学习有一些担忧，你不用特别的努力，但还是需要对学习花一点心思，一会吃完饭，希望你能够去写一会儿作业。”这样把非暴力沟通的四个要素运用进去。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>我们今天主要的分享的就是非暴力沟通的 4 个要素。我们回顾一下，第一步描述事实；第二步能够表达感受；第三步体会需要；第四步：提出请求。其实它是一个非常温和的沟通的一种模式，也是对我们生活是非常有帮助的。短期来说我们说了暴力语言，可能影响不是很大，但是在我们人生的一个长期的过程中，你总是说一些暴力的语言，总是会引发冲突或者给别人贴标签，长期来我们的人际关系一定是会受到很大的影响的。如果我们能够去真正地去践行非暴力沟通，其实它是真正能够帮助我们改善我们的人际关系，同时也能让我们收获更多，其实我觉得它是真的是能够帮助我们去获得幸福的。我们今天的分享就到这里，希望今天的分享对大家有帮助。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1679478090000,"updated_at":1679873466000,"ria":true},{"id":15348,"topic":"非暴力沟通解决冲突的步骤","learn_goal":"","remark":"《非暴力暴力沟通》出自马歇尔·卢森堡博士之手，是一本在心理学应用领域的经典著作。这本书我在几年前入手，粗略翻过一遍之后，尝试解决自己在亲子沟通上遇到的一些问题，浅尝辄止。直至参加了便签训练营的学习，让我突然意识到，这是座金矿，而自己差一点就错过了。\n\n这本书有几个牛的地方：\n\n第一、建基于心理学之上，有深厚的理论基础，用到的工具也被心理咨询等领域验证有效；\n\n第二、强调建立人与人之间的连接，相互理解并彼此看见，追求双方的需要都能得到满足；\n\n第三、实践效果显著，通过学习非暴力沟通，世界上各地无数的人收获了爱、和谐和幸福。\n","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"张培成001","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp> 各位好，我是\u003cstrong>张 培 成。\u003c/strong>张是弓长张，培是培育的培，成是成才的成，寓意简单明了，我的父母希望把我培育成一个对社会有用的人。我是一名互联网公司的产品经理，也是一个有两个孩子的父亲，这两个身份有一个共同点是经常会遇到各种各样的冲突，一旦处理不好，不是影响工作就是影响生活，怎么提升冲突解决的有效性是我非常关注的问题，也是我今天准备和大家分享的内容，希望大家在这个过程中能有所收获。\u003c/p>\u003cp> 下面呢，给大家介绍下拆书法和拆书帮，先看下什么是“拆书”，这里不能直接从字面意思来理解，拆是转化和内化的意思，书是拆的对象，拆书就是把书中的知识内化吸收、为己所用的意思。\u003c/p>\u003cp> 先有拆书，后有拆书法，拆书法就是对拆书实践中的相关方法的归纳总结，分为面向个人学习的和面向组织学习的。个人学习的应用是便签法，RIA三张便签，R便签是原文片段，I标签是用自己的话重述原文，A便签用来关联自己过去的经验和规划未来的运用，通过写便签促进理解和行动，从而让书中知识能够真正服务于自己的目标；组织学习的应用就是现场学习，拆书家通过对一本书的加工，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp> “拆书帮”是个社群，方便拆书法学习爱好者交流互动，在全国设有多处分舵，是一个非营利性的组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":19393,"quote":"\u003cp>\u003cstrong>非暴力沟通化解冲突的步骤\u003c/strong>\u003c/p>\u003cp> 在详细讨论化解冲突的核心要素之前，我先大致介绍一下在化解自己和他人的沖突过程中所涉及的5个步骤。任何一方都可以先表达自己为需要，简便起见，假设先由我方表达。\u003c/p>\u003cul>\u003cli>首先，我们要表达自己的需要。\u003c/li>\u003cli>其次，不论对方说什么，设法找出他们其正的露要。如果发現他们表达的是想法、评判\u003c/li>\u003c/ul>\u003cp>或分析，而不是需要，我们可以继续寻找话语背后的需要。\u003c/p>\u003cul>\u003cli>第三，确认我们都准确理解了彼此的需要，否則，继续寻找话语背后所隐含的需要。\u003c/li>\u003cli>第四，尽可能地同理对方，以便让双方都能确切地了解彼此的需要。\u003c/li>\u003cli>第五，当双方都澄清了事件中的需要后，我们就可以用正向的描述行动的语言提出化解冲\u003c/li>\u003c/ul>\u003cp>突的策略。\u003c/p>\u003cp> 在整个过程中，我们要仔细聆听彼此的心声，避免在言语中影射对方有错。\u003c/p>","explains":"\u003cp> 非暴力沟通化解冲突涉及到五个步骤，分别是：表达自己的需要、找出对方的需要、理解彼此的需要、同理彼此的需要，提出化解的策略。后一个步骤建立在前一个步骤已经完成的基础上，在整个过程中，我们要仔细聆听彼此的心声，以避免在言语上产生冲突。\u003c/p>\u003cp> 这段话中提到了一个最重要的概念——需要，那什么是需要，以及它为什么那么重要呢？需要是我们的生命赖以维持生存和发展的资源，包括了生理上的需要（譬如空气、水、食物、休息等），和心理上的需要（理解、支持、关心等），是人与人之间实现连结的基础。冲突之所以发生，根本原因在各自的需要没有得到满足。为什么呢？一方面，受到以&quot;自我&quot;为中心的表达习惯的影响，我们把大量的时间花费在对错的争论上，没有关注到自己和对方的需要；另一方面，我们表达的不是真正的需要，而是要自己/他人要采取的行动，或者是找出对方的问题，这样的表达无益于冲突的化解。理解和表达需要是非暴力沟通冲突解决的核心，上面提到的五个步骤建立在怎样更好地理解和表达需要的基础上，并以提出化解冲突的策略收尾，是一个完整的使用非暴力沟通化解冲突的过程。\u003c/p>\u003cp>下面，我们分步骤做一下拆解：\u003c/p>\u003cp>第一步：表达自己的需要\u003c/p>\u003cp>如何来表达呢？有一个固定的句式：我们观察到了什么事实+这个事实带给自己什么感受+这个感受和什么需要相关联。譬如，看到你每天晚上10点后才能做完作业，我很着急，因为我希望你能够保证足够的睡眠时间。这里有几个要注意的点，在表达的时候不加评判，不对感受做二次加工，以及不要给到行动的建议。\u003c/p>\u003cp>第二步：找出对方的需要\u003c/p>\u003cp>除了能够从对方表达的内容中区分中哪些是真正的需要，还可以通过其他非语言的信息来识别需要。这些非语言的信息包括语音语调、情绪状态、肢体动作、反馈方式等，需要也隐藏在这些信息当中，只有熟练掌握倾听的技能才能提取的出来。如果从现有的信息中仍然很难找出来，可以让对方多讲讲，&quot;刚才讲到的XX部分，可以再详细说说不？&quot;，或者反馈自己的感知向对方求证，&quot;你是有XX这么需要，是这样吗？&quot;或者给一些时间让那个对方想一会儿再说。举个例子，你正在自以为是地给孩子讲道理，结果她没听两句就直接打断你。可以这么问：&quot;为什么打断我？&quot;孩子可能会说：&quot;不想听你唠叨了，我想要一人静静。&quot;可以接着问：&quot;你是想有一个自主的空间，是这样吗？&quot;如果孩子给到了肯定的答复，那想有一个自主的空间就是孩子的需要了。\u003c/p>\u003cp>第三步：理解彼此的需要\u003c/p>\u003cp>经过了以上两步，各自的需求都表达出来了，一方的需要是否能被另一方准确理解呢？这里就涉及到一个对齐理解的工作。&quot;XX这个需要，可以讲讲你的理解吗？&quot;可以邀请对方用自己的话来重述你的需要，以验证对方理解的准确度，如果存在一些偏差，就要及时予以补充说明。譬如，你对孩子说：&quot;我希望呵护你们的成长，你是怎么理解的？&quot;如果孩子说：&quot;还不就是刷更多题，上更多兴趣班，动不动就说教&quot;，就是典型的孩子没有理解你的需要的情况了。\u003c/p>\u003cp>第四步：同理彼此的需要\u003c/p>\u003cp>听到了不一定听见，冲突中的人们，很容易沉浸在自己感受到的痛苦中，很难听进去别人讲的话。这个时候要先同理，不光是你要同理对方，对方也要同理你，让你们各自感受到的被看见、被理解，在情绪平复之后才能理性地看待对方的需要。可以使用这样的句式：我能体会到你什么样的感受，你希望自己付出的努力被看见。譬如，孩子没有办法接受我呵护她们成长的需要，我可以这么说，&quot;我能体会到你的压力，你希望爸爸相信你可以处理好自己的事情。&quot;当然，不是说一两句话就可以做到同理，会有一个过程，语言外其他表示关心、认可的非语言信息也很关键。\u003c/p>\u003cp>第五步：提出化解的策略\u003c/p>\u003cp>充分聆听彼此的需要，找到满足所有需要的行动策略，用清晰地、此刻可回应的、正向行动的语言来表述策略，冲突才能走向和解。用此刻可回应的语言，有利于保持连结，保证双方在讨论时保持相互尊重的态度。\u003c/p>\u003cp> 非暴力沟通化解冲突虽然只有五个步骤，但是对不了解非暴力沟通技术的人，要走完这五步也非常困难。如果自己不掌握这项技术，可以邀请熟悉非暴力沟通的第三方调解人来参与这个过程。冲突双方不限个人还是团体，更适用于解决各类关系型的冲突。\u003c/p>","interaction":"\u003cp>上个周日，因为写作业的事情和孩子产生了一场冲突。原因是下午6点多了，假期作业一点儿没动，我就有点生气了，说了孩子几句，结果作业倒是做了，一样做到了晚上10点多，一点儿也没提前，还闹的都不开心。\u003c/p>\u003cp>事后反思，在整个冲突过程中，我并没有表达清楚我的需要，也没有去了解孩子的需要，采取了强制的手段，默认以为早点开始了就会早点结束，结果事与愿违。\u003c/p>\u003cp>学习了非暴力沟通化解冲突的这五个步骤后，准备用在和孩子就负面情绪问题的冲突解决上，计划在下周三晚上做一次沟通。\u003c/p>\u003cp>我：听到你经常说一些负面的话，我很担心，我希望能够呵护你的成长。（表达自己的需要）\u003c/p>\u003cp>孩子：我不喜欢上学，不喜欢考试，不喜欢听你们唠叨。\u003c/p>\u003cp>我：说说你喜欢的。\u003c/p>\u003cp>孩子：我喜欢玩游戏，喜欢和妹妹聊天。\u003c/p>\u003cp>我：这些事情带给你的感受是怎样的？\u003c/p>\u003cp>孩子：很开心，没有压力。\u003c/p>\u003cp>我：希望少一些外部压力，自己安排好自己的事情，是这样吗？（找出孩子的需要）\u003c/p>\u003cp>孩子：是的，如果能这样就很好了。\u003c/p>\u003cp>我：我理解，你希望有一个不受干扰的自主空间，在这个空间里你说了算（理解孩子的需要）\u003c/p>\u003cp>我：爸爸能体会到你的压力，你希望爸爸相信你可以处理好自己的事情（同理孩子的需要）\u003c/p>\u003cp>孩子：你刚才说要呵护我们的成长，能说详细一点吗？\u003c/p>\u003cp>我：过去我总用&quot;为你们好&quot;当借口，要求你们刷题、上课外班，完全没有考虑你们的感受，动不动还喜欢发火，我希望做一些调整，多理解你们的需要，关注你们身心的健康成长。\u003c/p>\u003cp>孩子：就是以后不用刷题，也不用上课外班了吗？\u003c/p>\u003cp>我：看是不是你们自己的需要，不强求。\u003c/p>\u003cp>孩子：就是说，如果我想上钢琴课，你还是会支持的；考试考不好，你也不会再要求刷题了，是吗？\u003c/p>\u003cp>我：是的，从你们的真实需要出发，如果考试考不好是其他其他方面的问题，刷题也不管用。\u003c/p>\u003cp>孩子：那我理解了，就是换了一种方式，该做的事情还得做，该养的习惯还得养，就是从理解我们的需要出发了，也能尊重我们的选择。（理解我的需要）\u003c/p>\u003cp>孩子：爸爸真是不容易，我们看到你的努力了。（同理我的需要）\u003c/p>\u003cp>我：那我们先约定每天晚上9点写完作业，放学后到上床睡觉前这段时间怎么安排你自己决定，怎么样？（提出化解的策略）\u003c/p>\u003cp>孩子：我想写完作业后，再看会儿书。\u003c/p>\u003cp>我：可以的，那就每天晚上9:30之前睡觉。\u003c/p>\u003cp>孩子：好的。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1679100433000,"updated_at":1679146933000,"ria":true},{"id":15316,"topic":"表达感激","learn_goal":"","remark":"作者是美国的卢森堡博士。马歇尔.卢森堡博士由于在促进人类和谐共处方面的突出成就，2006年他获得了地球村基金会颁发的和平之桥奖。卢森堡博士早年师从心理学大师卡尔.罗杰斯，后来他发展出极具启发性和影响力的非暴力沟通的原则与方法，不仅教会人们如何使个人生活更加和谐美好，同时解决了众多世界范围内的冲突与争端。此书共13章，190余页。看这本书给人的感觉总体来说用三个词来形容：有趣、温暖、实用。有趣是因为书中不仅文字排版有趣，还兼插有图画，给人感觉新潮，所以在边读边品之中不失风趣；温暖是因为书中有的文字段落给人温馨有力量的感觉，让人读完不尽心中有暖流流动，这种暖流如涓涓细流持续且平滑；实用是因为书中不仅有沟通技巧的介绍，还有案例练习的讲解，在你了解沟通技巧后，有案例练习帮助你更好的理解，以便掌握沟通方法与技巧，这种设身处地的为他人着想的写作方法让我确实感觉到买和读这本书是不吃亏的，而是值得和有意义的！\n\n","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"三宝","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>大家好，我叫三宝。我的三大标签是非典型狮子座，北方化南方人， HR。我的名字来源于许多人对于HR的刻板印象。他们认为HR混迹职场只靠三个法宝，那就是“招人，扣绩效，算工资”。其实HR的工作可远不止这三样哦。\u003c/p>","ratings_count":2,"texts":[{"id":19358,"quote":"\u003cp>来自马歇尔▪卢森堡的《非暴力沟通》 微信读书P445\u003c/p>\u003cp>在使用非暴力沟通表达感激时，我们会清楚地包含以下三个要素：\u003c/p>\u003cp>·他人做了什么增进了我们的福祉。\u003c/p>\u003cp>·我们有哪些需要因此得到了满足。\u003c/p>\u003cp>·因为这些需要得到了满足，引起了我们什么样的愉悦感受。\u003c/p>\u003cp>表达这三个要素时，如果我们想要确保对方能够充分收到我们的心意，用语言完整地表达这三个要素是有意义的。\u003c/p>","explains":"\u003cp>本片段摘自于马歇尔▪卢森堡的《非暴力沟通》，这本书致力于为我们提供一种一直能保有善意的沟通方法。虽然使用非暴力沟通表达感激并不能算是这本书最为核心的内容，但作为表达感激的有效方法来说，是值得我们学习及掌握的。\u003c/p>\u003cp>从小到大，我们的父母、老师都曾教导我们，面对他人的好心帮助时，需要表达我们的感激。我们也的确照做了，但因为中国人普遍内敛，对于他人的帮助，我们会记在心里，并在他日给予行动上的反馈，但在口头致谢时，我们却相对羞涩的，经常只是说声“谢谢”。\u003c/p>\u003cp>通过使用本片段提供的这3个步骤，可以让他人清楚的明白我们为何而感激，充分感受到我们表达感激的诚恳态度。\u003c/p>\u003cp>为了帮助大家能够更好的理解操作步骤，步骤拆解举例环节我会用自己的一个案例。\u003c/p>\u003cp>1.他人的帮助行为\u003c/p>\u003cp> 通常情况下，当我们需要感激他人时，主要是因为他人为我们提供了某种帮助，如果不知道这个方法，我们最多回报一句“谢谢”，有时甚至羞于开口说“谢谢”，只用微笑或点头给予回应。这是无法将我们的感激充分表达的。正确的方式应该是在我们说完谢谢后，紧接着说他人的行为。举例：上周五我要参加全天的培训，早上来的太晚，没时间接水就进会议室参加培训了，中途休息出来时，发现同事帮忙倒了一壶水。此时，我该这样表达我的感激：“小马，谢谢你，帮我接的这壶水。”\u003c/p>\u003cp>2.帮助让需要得到满足\u003c/p>\u003cp> 正是因为他人的帮助，使我们的需要得到了满足。根据马斯洛理论，人类都有需要，但是需要有所分类，主要可以分为生理需要、安全需要、情感需要、尊重需要、自我实现的需要等，一般通过他人给予帮助所能实现的需要主要集中在生理、安全、情感、尊重需要方面。接着上面的例子继续表达我的感激：“小马，谢谢你，帮我接的这壶水，你这水太是时候了，我正渴的慌，超级想喝水。” \u003c/p>\u003cp>3.需要满足引发的愉悦情绪\u003c/p>\u003cp> 当需要得到满足后，我们会产生愉悦的心情，但是在实际表达感激中，这个因素恰恰是最容易忽略的。接着上面的例子继续说：“小马，谢谢你，帮我接的这壶水，休你这水太是时候了，我正渴的慌，超级想喝水。真的是太开心了，有你这样的同事可正好。”表达愉悦的常见用词（开心、高兴、幸福、满足、欣喜、愉快…………）\u003c/p>","interaction":"\u003cp>【A1】激活经验\u003c/p>\u003cp>接下来，我先分个组，我们按组进行讨论，然后从邀请一位小伙伴向我们进行分享。讨论时间为3分钟。\u003c/p>\u003cp>其实在我们的生活中，无论是工作还是学习，表达感激的场合是很多的。\u003c/p>\u003cp>Q1：现在让我们试着想想，（可以是在过去的一个月，一周，或者是上周末，甚至是一两个小时之前），其他人为你做了哪些事情，你是如何表达感激的？\u003c/p>\u003cp>参与者便签内容：\u003c/p>\u003cp> 昨天我从广西坐火车回北京，因为带的行李有点多，而且行李箱也特别重，在火车上尝试了好几次，还是无法把行李放到行李架上，正当我一筹莫展之时，边上有个小哥哥主动帮我把行李箱放到了行李架上，特别感动，很想好好感谢这位小哥哥，但是因为比较羞涩，仅仅只是说了一声“谢谢。”。\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp> 给大家1分钟的时间，根据这个方法提供的步骤，在便签之上，写下当未来某个时候，自己面临他人提供帮助时，表达感激的应用或行动步骤。\u003c/p>\u003cp>参与者便签内容\u003c/p>\u003cp>背景：弟弟帮我给小侄子买了个儿童餐椅当作礼物送给弟妹，弟妹收到后发给我，说谢谢大姑买的餐椅。\u003c/p>\u003cp>2.22号，跟弟弟表达感激，王丽涛，谢谢你帮我买了特别好看的餐椅并寄回家，帮我送了礼物，即让小侄子方便吃饭，又使弟妹开心，我内心特别感动，也很得安慰，谢谢你！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1678602661000,"updated_at":1680705853000,"ria":true},{"id":15272,"topic":"非暴力沟通","learn_goal":"","remark":"“沟者，构筑管道也；通者，顺畅也。”\n人人都希望自己即便不是沟通高手起码也要能沟通顺畅，但事实往往不尽如人愿。学习掌握非暴力沟通四要素，用请求反馈的方式，可以快速构建沟通框架，统一信息理解，为沟通顺畅打造良好的基础。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"徐辉","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>大家都拿到拆页了吧\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好！我是徐辉，我的三个标签是：\u003c/p>\u003cp>1.一级拆书家   \u003c/p>\u003cp>2.职业生涯规划师\u003c/p>\u003cp>3.职场中后期职业转型探索实践者\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【总学习目标】\u003c/strong>\u003c/p>\u003cp>大家在跟随我完成本次RIA现场学习，能够学会应用“非暴力请求四步法”和“请求反馈四步法”完成课堂沟通练习。\u003c/p>\u003cp>\u003cstrong>【拆页一学习目标】\u003c/strong>\u003c/p>\u003cp>希望大家在跟随我完成本次RIA现场学习后，在遇到沟通不顺畅的时候，能够运用非暴力请求四步法，转变谈话方式，设计话术表达出自己的感受和请求，达成和谐沟通。\u003c/p>\u003cp>\u003cstrong>【拆页二学习目标】\u003c/strong>\u003c/p>\u003cp>希望大家在跟随我完成本次RIA现场学习后，在与人沟通，发现双方的信息可能没有传达准确，或者有可能产生偏差的时候，能够使用请求反馈四步法进行信息反馈，设计话术以通过沟通提升沟通双方信息理解的一致。\u003c/p>\u003cp>\u003cstrong>【介绍拆页关系】\u003c/strong>\u003c/p>\u003cp>今天我们会学习两个拆页，两者呈递进关系，是两个“四步法”。\u003c/p>\u003cp>通过学习第一个拆页，大家将了解并掌握非暴力沟通的四个要素，以及如何具体运用“非暴力请求四步法”，让你的表达既可以让对方感觉舒服，又能让自己的需求得以满足；\u003c/p>\u003cp>第二个拆页片段，是“请求反馈四步法”，通过表达请求反馈，让对方能够复述请求内容，确认对方信息接收的准确性，发现偏差及时进行纠正和补充，最终实现双方理解的一致性。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>我们还延续上一位拆书家的分组方式，来进行接下来的分组讨论\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【F】特征（核心是“书”，用于满足好奇心）：\u003c/strong>\u003c/p>\u003cp>今天我们要一起阅读的拆页来自《非暴力沟通》。\u003c/p>\u003cp>作者是著名的马歇尔.卢森堡博士，他是人本主义心理学家，全球首位非暴力沟通专家。这本书于1963年问世，存续60年，但书中的理论知识仍然备受追捧，堪称沟通类图书的经典。\u003c/p>\u003cp>\u003cstrong>【A】优势（重点是“比较”，用于建立安全感）\u003c/strong>\u003c/p>\u003cp>想比其他沟通类书籍，这本书，第一次提出了‘非暴力沟通’的理念，他几乎可以解决所有因需求未被满足而造成的沟通类难题，案例详细易懂，方法实操性强，让我们全面了解怎样解决冲突达成良好的沟通效果，学会转变谈话和聆听方式，被誉为是沟通类图书的《圣经》。\u003c/p>\u003cp>\u003cstrong>【B】利益（强调的是“学习者”的利益，用于引发兴趣）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【B1】（学完本书可得利益）\u003c/strong>\u003c/p>\u003cp>这本书从十二个方面向我们阐述了如何让我们与他人之间的沟通品质得到提升。提出了与人沟通所需的四个要素。通过学习这本书，就能帮你转变对沟通的思维方式，改善人际关系，管理好自己的沟通能力。\u003c/p>\u003cp>\u003cstrong>【B2】（学完此片段可得利益）\u003c/strong>\u003c/p>\u003cp>今天的两个片段是递进关系，是从沟通的四个要素出发，用两个“四步法”教会大家在沟通中如何表达才能让对方满足自己的需求以及如果避免出现沟通信息理解偏差，引起误解。\u003c/p>\u003cp>\u003cstrong>过渡语：\u003c/strong>下面请大家阅读拆页一，因为前面的伙伴已经拆解了这个片段，所以给大家短一点时间，1分钟来回顾一下，看完请抬头示意我。\u003c/p>","ratings_count":1,"texts":[{"id":19307,"quote":"\u003cp>\u003cstrong>【片段1】\u003c/strong>P7-P8\u003c/p>\u003cp>\u003cstrong>【主\u003c/strong> \u003cstrong>题】非暴力请求四步法\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【原\u003c/strong> \u003cstrong>文】\u003c/strong>\u003c/p>\u003cp>要达到让双方都能发自内心地相互给予，我们需将注意力聚焦在四个方面-- 它们是非暴力沟通模式的四个要素。\u003c/p>\u003cp>首先，我们观察实际上发生了什么。不论他人的言行是否有益于我们，我们只是去观察。要做到清晰表达所观察到的，我们的挑战在于不夹杂任何评判。不论喜欢与否，我们只是说出人们做了什么。第二步，表达出我们看到这些行为时的感受:是感到伤心、害怕、喜悦、有趣，还是心烦呢?第三步，表达出我们的感受与什么需要相关联。通过对这三个要素的觉察，我们清晰和诚实地表达出自己的状态。\u003c/p>\u003cp>例如，一位母亲想和正值青春期的儿子用非暴力沟通的方式来说话，她可以这样来表达以上三个要素:“菲利克斯，看到咖啡桌下的两团脏袜子和电视机旁边的三团脏袜子，我很生气，因为我希望在我们共用的空间里能多些整洁。&quot;\u003c/p>\u003cp>紧接着，她可以表达非暴力沟通的第四个要素--一个具体的请求:“你愿意把你的袜子放在你房间或放进洗衣机里吗?”我们借助这个要素提出对他人的期许，希望他(她)怎么做来满足我们的需要，让我们的生命更加美好。\u003c/p>","explains":"\u003cp>\u003cstrong>What\u003c/strong>\u003c/p>\u003cp>这个拆页给到了我们怎样用非暴力请求来进行沟通的方法，也就是使用“观察、感受、需求、请求”这非暴力请求四步法来提升沟通质量，解决沟通难题。\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【通常做法】\u003c/strong>\u003c/p>\u003cp>在人们惯常的沟通中，都是采取下意识的表达方式，按照每个人个体的思路和表达习惯去直接输出，从来没有系统思考过要具备什么样的沟通步骤才能让沟通顺畅，要怎样沟通才能达到沟通目的。\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处】技能点1\u003c/strong>\u003c/p>\u003cp>在生活和工作中，我们每天都在进行沟通，但是沟通和会沟通是两回事，否则也不会出现诸如：管教孩子根本不听，夫妻俩经常因为一两句话不对付就大吵一架。和同事沟通不畅等等这些情况了。\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>\u003c/p>\u003cp>那到怎么做才能让对方清晰准确地了解导自己的需求，达成让对方接受的效果呢？拆页中给了我们明确的四步方法：\u003c/p>\u003cp>\u003cstrong>1.观察事实\u003c/strong>：仔细观察他人的言行，并且不掺杂任何评判地说出观察到的语言和行为。比如：早上孩子上学，但是还在磨蹭不肯走。可以说：“现在距离上课时间还有半小时了，如果现在不走，应该会迟到”，而不是说：“天天磨磨唧唧，不知道干什么”。前者是事实，后者是评判。\u003c/p>\u003cp>\u003cstrong>2.表达感受：\u003c/strong>表达出自己当下的感受，让对方知道和了解自己的情绪。例如：“我很担心你迟到了会被老师批评”，担心就是感受。\u003c/p>\u003cp>\u003cstrong>3.阐述需要：\u003c/strong>感受产生的背后，实际上是我们的真实需要，这也是需要向对方明确表述的，这样可以让对方能够充分理解我们的想法。例如：我希望我们现在就出门，尽可能保证按时到达。\u003c/p>\u003cp>\u003cstrong>4描述请求\u003c/strong>：给出对方一个具体的请求，来帮助对方达成我们的需求。例如：“你现在其他的事情都放下，去穿衣服穿鞋背书包，我们出发。”\u003c/p>\u003cp>\u003cstrong>（反面案例）\u003c/strong>\u003c/p>\u003cp>之前关于我女儿收拾房间的问题，我们就经常发生不愉快的对话，一般都是以我的评判开始的：\u003c/p>\u003cp>“你这屋子跟狗窝一样，什么时候能利索点？”（评判）\u003c/p>\u003cp>“我看着挺好，00后都这样。”（反驳）\u003c/p>\u003cp>“00后的特点就是不讲卫生吗？再说你管人家干嘛，赶紧收拾收拾。”（挖苦和命令）\u003c/p>\u003cp>“现在没心情，有空再说。”\u003c/p>\u003cp>这种类似的沟通基本上都是以失败告终，没有一次是因为我的催促达成收拾的结果。\u003c/p>\u003cp>\u003cstrong>（反例变正例）\u003c/strong>\u003c/p>\u003cp>今年春节前，家里进行大扫除的时候，我灵机一动，试了试上面四个步骤，得到了不错的效果：\u003c/p>\u003cp>1、观察事实：马上要过春节了，咱们要打扫一下家里的环境，你这个屋子里堆满了各类物品。\u003c/p>\u003cp>2、表达感受：我看着闹心也特别生气。\u003c/p>\u003cp>3、阐述需要：希望你能在阖家欢乐的时刻，给家里的卫生做出点贡献。\u003c/p>\u003cp>4、描述请求：请你今天把自己的房间整理好，以便于我们可以在春节期间有个清爽的环境。\u003c/p>\u003cp>这次的沟通效果出乎我的意料，不但在约定的时间完成了整理，而且历史性的保持了近一个月。\u003c/p>\u003cp>所以清晰准确的表达非常有助于达成沟通双方的相互理解。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验（显像提问）】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书家提问设计】\u003c/strong>\u003c/p>\u003cp>为了便于大家更好地理解和运用，接下来我们一起做一个练习。\u003c/p>\u003cp>请大家想一想，你在过去一个月里有没有遇到过沟通不顺畅的场景？\u003c/p>\u003cp>比如：老公天天抱着手机玩儿游戏不做家务，说了几句就吵架。\u003c/p>\u003cp>同事工作不认真，拖延整个项目的进度，自己还不觉得有错。\u003c/p>\u003cp>孩子写作业马虎，纠正的时候老顶嘴等等。\u003c/p>\u003cp>接下来请大家2分钟的时间先在组内讨论，然后会请小伙伴来给大家进行分享。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>曹姐：我老公退休以后经常出去玩儿，每天回来特别晚，老是后半夜回家，我跟他抱怨他也不爱听。\u003c/p>\u003cp>\u003cstrong>【A1+反思加工】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书家提问设计】\u003c/strong>\u003c/p>\u003cp>感谢曹姐的分享，那接下来呢，我们既然学习了这个四步法，我们现在就运用这个非暴力请求四步法再回到当时的那个场景，你又会跟对方怎么沟通呢？\u003c/p>\u003cp>还是给大家两分钟先在小组里讨论一下，然后一会儿请哪位分享一下。\u003c/p>\u003cp>好，我们讨论结束，曹姐看您讨论特别有感觉，请您给我们分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>曹姐：\u003c/p>\u003cp>1、观察事实：你连着出去玩儿在外面吃饭已经五天了。\u003c/p>\u003cp>2、表达感受：这五天我很生气也很孤单。\u003c/p>\u003cp>3、阐述需要：希望你能多陪陪我，家里的事情能分担一些。\u003c/p>\u003cp>4、描述请求：请你后面每星期要有两天要在家里，或者吃晚饭或者十点前就要到家。\u003c/p>\u003cp>\u003cstrong>【回应与反馈】新技能1\u003c/strong>\u003c/p>\u003cp>特别棒，而且把刚才说到的观察、感受、需求和请求都从头到尾地串起来了，感觉特别扎实，\u003c/p>\u003cp>感觉一下子吸收了方法的精华。\u003c/p>\u003cp>\u003cstrong>拆页1过渡到拆页2：\u003c/strong>\u003c/p>\u003cp>看来大家对非暴力的四个步骤已经基本掌握，可以学以致用了。都非常棒！大家给自己鼓个掌吧！\u003c/p>\u003cp>通过第一个片段的学习，我们学会了如何进行沟通表达提出请求。但是在现实沟通中，经常会发现，我们说的话、提出的请求、传递的信息并不是所有人都可以理解，或者表面上理解了，结果却和我们的期待有差距。那如何避免倾听失误、准确接收信息呢？下面我们进入第二个片段“请求反馈四步法”的学习。\u003c/p>\u003cp>给大家3分钟的时间先进行阅读，看完后请抬头示意我。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":19308,"quote":"\u003cp>\u003cstrong>【片段2】\u003c/strong>P83-P84\u003c/p>\u003cp>\u003cstrong>【主\u003c/strong> \u003cstrong>题】请求反馈四步法\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【原\u003c/strong> \u003cstrong>文】\u003c/strong>\u003c/p>\u003cp>我们的本意和他人的理解有时可能是两回事。通常我们会在对话中捕捉线索，来确定他人是否理解力我们的意识。但如果不确定，我们就需要提出明确的请求，请对方告诉我们他们听到了什么，以便在有误解的时候做出修正。有时简单地问一句“这样清楚吗”就够了，但有些时候，即便对方说“是的，我明白了”，我们还是无法确保他们是否真正理解了我们的意思。这时我们可以请对方再多回应一些，这样，一旦对方的理解与我们的意思有所不同或者有所遗漏，我们就有机会做出补充。\u003c/p>\u003cp>例如，一位老师和她的学生说：“皮特，我昨天批改作业时没有看到你的作业本。我想和你确认这件事。请你在课后来我办公室一下，好吗？“托尼咕哝着说：“好，我知道了。”便转过身准备离开。这位老师不确定皮特是否准确了解她的意思，便立即请他重述一次：“\u003cstrong>可否告诉我你听到的，我请你做的事情是什么？\u003c/strong>”皮特回答说：“你让我在课后留下来，不能去踢足球，因为你对我的作业不满意。”皮特果然没有听见她要传达的信息，于是她决定重新尝试，并在这一次更加注意自己的表达方式。\u003c/p>\u003cp>诸如“你没有听明白我的话”“这不是我的意思”“你误会了”这样的判断，很容易被他人视为指责。因为皮特很坦率地回应了她，这位老师先向他表达了谢意。她说：“\u003cstrong>谢谢你告诉我你听到我说了什么。我想我说得不够清楚，所以请允许我再试一次\u003c/strong>。”\u003c/p>","explains":"\u003cp>\u003cstrong>What\u003c/strong>\u003c/p>\u003cp>这个拆页给我们介绍了一个怎样避免信息传递出现偏差的方法，也就是在沟通请求时，要求接收信息的一方重述信息，双方进行确认的方法。\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>\u003c/p>\u003cp>这个方法可以有效避免沟通双方因为理解的偏差造成误会，确保沟通的内容准确有效并且能够顺利往下执行。\u003cstrong>（这么做的原因和好处）\u003c/strong>\u003c/p>\u003cp>在生活和工作中，我们经常会碰到某些事情自己觉得已经说得很清楚了，但是到了其他人那里就被误解成另一个意思，不是引起了不必要的矛盾就是要花时间纠偏，即影响心情又影响效率。\u003cstrong>（不这么做的坏处）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>\u003c/p>\u003cp>原文案例中描述了老师在和学生的沟通时用了重述和根据重述修正内容两个步骤来纠正沟通信息理解上的差异。为了让大家能更清晰明了地理解这个步骤，我进行了细化，把步骤进行了拆分，具体如下：\u003cstrong>细化行动步骤：技能点3\u003c/strong>\u003c/p>\u003cp>１. 观察言行：通过观察对方语言、行为或者表情来判断对方是否听明白了我要表达的意思。\u003c/p>\u003cp>２. 请求复述：请求对方复述一下他理解的意思，比如：你可以重述一下我刚才说的话吗？\u003c/p>\u003cp>３. 表达感谢：当对方对我们说的话进行了复述给出了反馈后，我们要本着平等尊重的原则来感谢对方。比如：看着对方真诚地说：“谢谢你给我的反馈”。\u003c/p>\u003cp>４. 补充修正：会有两种可能性\u003c/p>\u003cp>第一，如果对方给出了正确的反馈，我们可以说：“听完你刚才的复述，感谢你完全理解了我的意思。”\u003c/p>\u003cp>第二，如果对方没有理解我们的意思，不要指责对方，更不能用否定的话去纠正，这种表达会让对方产生抵触情绪，无法平和地沟通下去，可以调整为：“我想是我说的不够清楚，我的意思是…。”\u003c/p>\u003cp>\u003cstrong>Where\u003c/strong>\u003c/p>\u003cp>这个方法适用于工作和生活中，与信息接收能力不足、经常出现鸡同鸭讲状况的人进行沟通的场景，以及需要传递重要信息不能出现偏差的场景。在与长辈和领导沟通时不适用，会显得冒犯。\u003c/p>\u003cp>\u003cstrong>【意译案例】技能点2\u003c/strong>\u003c/p>\u003cp>其实这种情况在我的工作中还挺常见的，\u003c/p>\u003cp>春节假期回来审核工作，我找到负责采购的小刘说：“小刘，我昨天审核方案进度时没有看到那你的那部分，想和你确认这个事情，你下午四点来我办公室一下，好吗？”小刘咕哝着说：“好，我知道了。”，便转过身准备离开。我不确定她是否准确聊了我的意思，便立即请她重述一次：“可否告诉我你听到的，我请你做的事情是什么？”小刘回答说：“你让我到办公室挨批，不能按时下班，因为你对我的工作不满意。”她果然没听见我要传达的信息，于是我觉得重新尝试，并在这一次更加注意自己的表达方式，我说：“谢谢你告诉我你听到我说了什么，我想我说得不够清楚，所以请允许我再试一次。我的意思是咱们一起讨论一下你的方案，以便尽快确认落实下去，避免延误。”\u003c/p>\u003cp>\u003cstrong>【预防异议】技能点4\u003c/strong>\u003c/p>\u003cp>可能会有伙伴觉得，交代一个事情还要用四步反馈来确认，太麻烦了。我想说的是，首先只有在事情很重要或者感觉对方可能有误会时，才需要使用四步请求反馈；其次与由于沟通误会带来经济损失、时间浪费或者亲密关系破裂想比，短短四步是非常值得的。\u003c/p>\u003cp>也有人说，我请求别人反馈的时候，对方反感不配合怎么办？如果这种情况是经常出现，那就要看看我们在请求对方反馈的时候是不是语言表达或肢体语言有不当的地方需要修正。多加觉察和使用会使这个方法使用得更加纯熟，也更有利于帮助大家达到清晰表达请求的目标。\u003c/p>\u003cp>\u003cstrong>过渡语：\u003c/strong>看了我的案例，大家可以发现一个平平常常的小对话都有可能造成信息误解，可见这个方法和我们是息息相关的，那我们学习了就要用起来，下面我们运用刚才学习到的请求反馈法进行一下现场讨论和演练，以便我们在今后遇到类似场景可以使用起来。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3现场演练】 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>场景设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【具体场景】\u003c/strong>\u003c/p>\u003cp>有这样一个场景：\u003c/p>\u003cp>销售部办公室里，销售经理老张在给本部门销售助理小张布置了工作：\u003c/p>\u003cp>要完成的工作：提交一份月度销售情况统计表\u003c/p>\u003cp>工作要求：表格中要有本月每个销售人员的销售额，计划完成和实际完成的比率，与上个月的对比分析，与去年同期的对比分析。\u003c/p>\u003cp>提交时间：周五中午前，以便周五下午进行修改，周一提交总经理办公会讨论。\u003c/p>\u003cp>老张说完后，小张点了点头说：“好的”，转身准备离开。\u003c/p>\u003cp>老张叫住了小张......\u003c/p>\u003cp>\u003cstrong>【发出指令】\u003c/strong>\u003c/p>\u003cp>请小伙伴们在小组内，一人扮演老张，一人扮演小张，应用今天学到的“请求反馈四步法”，来帮助老张确认小张是否理解了老张的意思，如果没理解，怎样表达可以达到让双方信息一致。\u003c/p>\u003cp>给大家5分钟的时间，结束后我会邀请小伙伴来分享对话。\u003c/p>\u003cp> 哪个组小伙伴给我们分享一下？\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>案例一：\u003c/p>\u003cp>老张（丹娜）：小张，你方便重复一下我刚才说的内容吗？因为内容有点多，我们再进行一下明确。\u003c/p>\u003cp>小张（王皓）：好的，您是要我整理一份这个月的销售情况统计表，在这个表中要有本月每个销售人员的销售额，计划完成和实际完成的比率，与上个月的对比分析和与去年同期的对比分析。提交时间是周五中午前，周一提交总经理办公会讨论。您看我说的对吗？\u003c/p>\u003cp>老张（丹娜）：好的，你刚才说得非常准确到位，谢谢你完全理解了我的意思。\u003c/p>\u003cp>小张（王皓）：谢谢领导。\u003c/p>\u003cp>案例二：\u003c/p>\u003cp>老张（丹娜）：小张，我刚才说的内容你方便复数一下吗？我们来明确一下你是否完全理解了。\u003c/p>\u003cp>小张（欣艾）：您让我提交一份月度销售统计表，里面要每个人的销售额，还有上个月的对比，还有去年的同期对比，周五下午让我给你。\u003c/p>\u003cp>老张（丹娜）：我想我刚才可能没有说清楚，我的意思是，你提交的表当中，除了有每个人的销售额之外，同时还要有这个人的计划完成和实际完成的比率，不但有计划还要有实际完成，刚才你可能没有注意到这点。关于时间的话，我希望你能周五上午能提交给我一稿，这样的话，我在中午看一下，下午咱们可以讨论修改。\u003c/p>\u003cp>小张（欣艾）：好的，谢谢领导，我知道了，我尽快按照你的要求做出来发给你。\u003c/p>\u003cp>\u003cstrong>【回应与反馈】新技能1\u003c/strong>\u003c/p>\u003cp>小组重组所以这组变成了三个人，我们可以看到，同一组不同的人，都会有不同的认知，给我们展示了正反两个案例，充分诠释了他们对于四步法的理解。\u003c/p>\u003cp>\u003cstrong>过渡语：\u003c/strong>\u003c/p>\u003cp>上面我们用一个案例，练习了遇到的沟通信息出现偏差的请求反馈四步法，那具体结合到我们自己的工作生活中该怎样应用呢？我们现在的练习是为了应用在我们未来可能面对的场景。\u003c/p>\u003cp>\u003cstrong>【A2分步催化】\u003c/strong> \u003c/p>\u003cp>\u003cstrong>【拆书家提问设计】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【提出问题】\u003c/strong>\u003c/p>\u003cp>下面我想邀请大家来试想一下：在未来一个月当中的，会在哪些场景下，需要你提出请求反馈？比如：进行工作分工以后，给老公交待完带孩子注意事项后，给同事或下属提出工作要求时；委托他人办理一些事项时等等。\u003c/p>\u003cp>例如：前段时间让我老公去留学中介去咨询孩子报考雅思辅导班的事情，就得反复跟他确认孩子的时间表，计划考雅思的时间，冲刺的目标分数等等这些信息。\u003c/p>\u003cp>\u003cstrong>【发出指令】\u003c/strong>\u003c/p>\u003cp>请大家打开想象，思考一下自己可能会遇到的场景，在小组里跟小伙伴们讨论。\u003c/p>\u003cp>注意：这个环节我们只分享场景，不需要具体使用四步法去解决。\u003c/p>\u003cp>时间为5分钟，之后我会邀请小伙伴来分享。\u003c/p>\u003cp>\u003cstrong>【回应与反馈】新技能1\u003c/strong>\u003c/p>\u003cp> 我补充一点，就是刚才王姐说到的，在管理过程当中，出现多个任务要交待下去，但是接受信息的人因为各种原因造成信息偏差，也依然可以应用这个步骤。形式可以用口头、可以用文字、可以一次也可以多次按照这个步骤来澄清信息。并且都是可能达到效果的。在这里也建议王姐，如果未来想更少地面对下属的这种信息接收能力不足的状况，在现在用这个四步法去多次落实，一定会提高他的信息接收能力，未来会形成他的工作习惯和沟通习惯。\u003c/p>\u003cp> 刚才是跟王姐分享的我的想法，下面请哪位伙伴给大家分享一下？\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>欣艾：马上春天了，我老公带孩子出去玩儿的时候， 要带什么？今天要做什么？注意什么？要把这些都得确认清楚。\u003c/p>\u003cp>丹娜：我这边是孩子开学了，得跟老人沟通确认每天几点接孩子、今天有什么课外班什么的。\u003c/p>\u003cp>王皓：和我的下属在工作中关于一些工作进度，时间安排等等的确认。\u003c/p>\u003cp>曹姐：儿子孙女周末来家里，得跟老伴反复说要买什么肉蛋奶？要买什么价位？买多少？什么时间买回来等等。\u003c/p>\u003cp>琛君：我下周要提交一个报告，需要请同事帮忙整理好数据给我，我来以此为准做数据分析完成报告\u003c/p>\u003cp>\u003cstrong>【A2催化应用】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书家提问设计】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【提出问题】\u003c/strong>\u003c/p>\u003cp>我们场景有了，请大家结合今天所学习请求反馈四步法，应用到刚才你想到的场景中，实现请求反馈的目标。\u003c/p>\u003cp>\u003cstrong>【发出指令】\u003c/strong>\u003c/p>\u003cp>给大家5分钟时间，把你在未来发生的场景下，使用四步法的步骤写下来，之后我再邀请一个小伙伴分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>琛君：\u003c/p>\u003cp>1、观察言行：重要信息所以需要进行确认\u003c/p>\u003cp>2、请求复述：雷哥，我下周要交这次比赛的报告，麻烦你帮忙把初赛、决赛的基本信息整理给我一下好吗？需要在周二中午前给我，初赛、决赛分开，包含项目课题、小组刺成员姓名/所属部门、导师姓名/所属部门、评分标准及得分。麻烦你说一下数据标准，咱俩保持一致，好吗？\u003c/p>\u003cp>3、表达感谢：是的，你说的没错。那就期待周二中午的数据啦\u003c/p>\u003cp>4、补充修正：感谢你完全理解了我的意思\u003c/p>\u003cp>曹姐：\u003c/p>\u003cp>1、观察言行：跟老公说这些他一般都很不耐烦\u003c/p>\u003cp>2、请求复述：我会说：我说明白了吗？请你复述一遍吧。\u003c/p>\u003cp>3、表达感谢：谢谢你的反馈（他一般都会重复说一遍，但一般都会不全面）\u003c/p>\u003cp>4、补充修正：我补充几点，牛奶一定要是保质期内的别过期，蔬菜买孩子能吃的有机菜，星期五前买回来就可以。\u003c/p>\u003cp>\u003cstrong>【回顾】\u003c/strong>\u003c/p>\u003cp>我们的练习就到这里，我们回顾一下，今天在第一个拆页离学习的是“非暴力请求”四步法，第二个拆页里学习的是“请求”元素中的“请求反馈四步法”。\u003c/p>\u003cp>\u003cstrong>【强有力的结语】新技能2\u003c/strong>\u003c/p>\u003cp>感谢大家今天全情投入的学习，希望大家在未来的生活和工作中对今天学习到的沟通技法多多练习和使用，让自己能够用爱的语言交流，成为沟通管理的高手。同时也把马歇尔.卢森堡先生的一句话送给大家：“我渴望我的生命活出善意和慈悲，由衷的给与，在你我之间流动。”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1677726204000,"updated_at":1680179328000,"ria":true},{"id":15238,"topic":"表达感谢的三个要素","learn_goal":"","remark":"生活中，我们是怎样理解感谢和感激的呢？\n当我们做了一件事，有意或无意收到别人的一个“谢谢”时，我们是什么心情呢？\n是心里非常愉悦的感受，还是觉得没有什么大不了呢？\n《非暴力沟通》一书中让我们学习一种沟通的技巧，既能让对方清晰的了解我们的意图，又能感受到我们的诚意，同时还能提升我们的教养和礼貌。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"季草集美业","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>\u003cstrong>一、自我介绍、分组\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>各位老师，大家晚上好！非常感谢大家在百忙之中抽空来参加我的过级线下活动。\u003c/p>\u003cp>我叫陈芳，一个很大众普通的名字。我有个姐姐叫陈芬，我妈妈希望我们姐妹俩像花朵一样美丽，所以给我们取名“芬芳”。\u003c/p>\u003cp>三个标签简单介绍一下我自己：\u003c/p>\u003cp>第一个标签：季草集美妆宣传官\u003c/p>\u003cp>第二个标签：孩子的学习提升导师\u003c/p>\u003cp>第三个标签：正在努力晋级的准拆书家\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>由于今天的过级环节需要分组讨论，下面我来进行一下分组。刚好我们有 8 个人，那么宋老师这边四个人为一组，唐老师旁边的 4 个人为一组。\u003c/p>\u003cp>\u003cstrong>二、图书介绍\u003c/strong>\u003c/p>\u003cp>【拆书技能】：选择图书是实用类或理论类图书\u003c/p>\u003cp>今天我要给大家分享的这本书是 2021 年最新修订版的《非暴力沟通》。作者是美国的马歇尔·卢森堡博士。这本书被联合国教科文组织列为全球教育和非正式教育领域非暴力解决冲突的最佳实践之一。\u003c/p>\u003cp>同时也是我们我们拆书帮很多拆书家拆过很多次的畅销书籍，由此可见这本书的影响力还是很大的。\u003c/p>\u003cp>\u003cstrong>【指令】\u003c/strong>\u003c/p>\u003cp>这份是我准备的今天的拆页片段，请大家花2分钟的时间阅读拆页。阅读完成的伙伴可以举手向往示意一下，谢谢大家！\u003c/p>","ratings_count":1,"texts":[{"id":19274,"quote":"\u003cp>\u003cstrong>三、阅读原书拆页\u003c/strong>\u003c/p>\u003cp>【拆书技能】：拆页内容未超过2页图书内页。所选拆页包含有具体行动或做法。\u003c/p>\u003cp>片段来源：P225-226\u003c/p>\u003cp>当我们用非暴力沟通来表达赞赏和感激时，纯粹是为了庆祝生命，不为获取任何回报。我们唯一的意图就是去庆祝他人的作为如何使我们的生命变得更加丰盛。\u003c/p>\u003cp>\u003cstrong>表达感激的三个要素\u003c/strong>\u003c/p>\u003cp>在使用非暴力沟通表达感激时，我们会清楚地包含以下三个要素：\u003c/p>\u003cp>· 他人做了什么增进了我们的福祉。\u003c/p>\u003cp>· 我们有哪些需要因此得到了满足。\u003c/p>\u003cp>· 因为这些需要得到了满足，引起了我们什么样的愉悦感受。\u003c/p>\u003cp>表达这三个要素时，并不一定要遵照以上的顺序。有时哪怕是一个微笑或一句简单的“谢谢你”就足以传递这一切。不过，如果我们想要确保对方能够充分收到我们的心意，用语言完整地表达这三个要素是有意义的。在下文的对话中，大家可以看到如何用这三个要素来表达“赞赏”。\u003c/p>\u003cp>学员：（在工作坊结束后来找我）马歇尔，你太棒了！\u003c/p>\u003cp>马歇尔：我好像不太理解你为什么要这么称赞我。\u003c/p>\u003cp>学员：为什么？你的意思是？\u003c/p>\u003cp>马歇尔：人们给过我无数的头衔，但我却完全无法从这些表述中学到什么。我想从你对我的赞赏中有所学习，并且因此感到喜悦，但我需要你再多说一些。\u003c/p>\u003cp>学员：比如说？\u003c/p>\u003cp>马歇尔：首先，我想知道我说了什么或者做了什么让你的生命变得更加美好。\u003c/p>\u003cp>学员：嗯，你很有智慧。\u003c/p>\u003cp>马歇尔：恐怕你刚刚又给了我另一个评判。我依然想知道我做了什么让你的生命更美好。\u003c/p>\u003cp>学员：（思索了一会儿后，她指着自己在工作坊上写下的笔记）看这两处，就是你说的这两点。\u003c/p>\u003cp>马歇尔：噢，所以你赞赏的是我说的这两点？\u003c/p>\u003cp>学员：是的。\u003c/p>\u003cp>马歇尔：接下来，我想要知道这些话带给你的感受。\u003c/p>\u003cp>学员：感到充满希望，并且释然。\u003c/p>\u003cp>马歇尔：那么现在我想知道，我说了这两点满足了你哪些需要。\u003c/p>\u003cp>学员：我一直无法和我18岁的儿子沟通，一直在努力寻找一种更加情意相通的方式和他相处，你说的这两点让我找到了方向。\u003c/p>","explains":"\u003cp>\u003cstrong>四、【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>【拆书技能】【I】拆书家讲解引导中包括了：1）行动建议步骤；2）与行动各步骤对应的案例\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>好的，我看到大部分伙伴都已经看完了，没有看完的小伙伴也不用着急，我等会会详细的讲解。\u003c/p>\u003cp>\u003cstrong>What：\u003c/strong>\u003c/p>\u003cp>我们生活中，每个人表达感谢的方式和语言都不一样。《非暴力沟通》提供了一种更具体的表达方式，通过说出别人帮助我们的具体行为，指出这个行为解决了我们的困难，让我们的情绪得到了转变，从而使我们由衷地表达感谢。\u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>\u003c/p>\u003cp>我们通常习惯性的的用“谢谢”或者一个微笑简单的带过，往往对方会不明白我们的诚意。那么用非暴力沟通表达感激，这样不仅能让对方清晰地了解我们的意图，还能提升我们的教养和礼貌。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>我们要怎样使用这个方法呢？\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>\u003c/p>\u003cp>非暴力沟通表达感激可分为三个步骤：\u003c/p>\u003cp>1. 指出具体行为\u003c/p>\u003cp>描述出他人做了什么行为增进了我们的福祉。\u003c/p>\u003cp>（例：年前，新年快到的时候，我看到物业的保洁阿姨，把楼道里、走道里，还有墙顶的扬尘灰都打扫的很干净，还把我们的进户门外面都擦得很干净。）\u003c/p>\u003cp>2. 说明满足需求\u003c/p>\u003cp>描述一下我们有哪些需求因为对方的行为而得到了满足。\u003c/p>\u003cp>（例：过年了，每家每户打扫卫生都是必不可少的。有些公共区域，都是我们每天进进出出的必经之路，需要它保持一个良好的卫生环境。）\u003c/p>\u003cp>3. 表达自身感受\u003c/p>\u003cp>描述一下引起了我们什么样的愉悦感受。\u003c/p>\u003cp>（例：我可以说：“阿姨，看到您把楼道墙顶的扬尘灰都打扫了，您还顺手把我们的进户门都做了清洁。这么干净整洁的环境，会让我们回到家，还没进家门，就感受到了一丝温馨和舒适。”）\u003c/p>\u003cp>当我们表达感激的时候，能将上面这三个要素都表达出来，不一定按顺序。只要有这3个要素即可，我们相信对方一定会感受到我们的诚意。\u003c/p>\u003cp>\u003cstrong>【反例】\u003c/strong>\u003c/p>\u003cp>下面我分享一个我自己的小故事。\u003c/p>\u003cp>由于现在我和先生白天的工作都很繁忙，大部分的家务工作都是在每天的晚饭后分工完成的。他主要负责孩子的学习，我主要负责家里的环境卫生打扫。前一段时间，我家小宝生病了，所以我那天提前哄她睡觉去了，家里的卫生就落下来了。哄孩子睡觉前，我衣服放进了洗衣机里了。结果，哄孩子睡觉的时候，把我自己也哄睡着了。第二天早上醒来后，脑袋一下子炸了，想起来衣服好像还没有晾晒。我就赶紧跑去阳台，一看衣服已经整整齐齐地晾晒好了。当时心情特别激动的。因为我老公平时是扫把倒了都不扶的人，还恨不得要踩上一脚的。看到他有这样的举动，我感到很欣慰。当时他还在睡梦中，我就扑过去，给了他一个大大的 Kiss，可能搞得他一头雾水。\u003c/p>\u003cp>\u003cstrong>【反思】\u003c/strong>\u003c/p>\u003cp>现在回想起来，这个动作似乎过于抽象了，可能先生到现在还以为我又发啥神经呢。\u003c/p>\u003cp>如果我能就事情的本身作出描述性的感谢，结果就会不一样了。\u003c/p>\u003cp>比如，我可以这样说：“哇！老公我看到你把衣服都整齐的晾晒好了呢（指出具体行为），非常感谢你体谅我的辛苦！（说明满足需求）这样我就轻松多了（表达感受）。”\u003c/p>\u003cp>\u003cstrong>Where：\u003c/strong>\u003c/p>\u003cp>通过学习了这三个表达感谢步骤，在以后的生活中、工作中，我们都可以尝试着去运用。\u003c/p>","interaction":"\u003cp>\u003cstrong>五、【A1】激活经验\u003c/strong>\u003c/p>\u003cp>【拆书技能】【A1】指令清晰，学习者在小组内分享了自己的经验，并有一位代表分享了本组的一个经验。\u003c/p>\u003cp>\u003cstrong>【指令】\u003c/strong>\u003c/p>\u003cp>好的，刚刚我讲解了原文片段，还分享了我自己的一个小故事。那么接下来请每组的伙伴们一起讨论一下，在你们自己身边经历过类似的情景吗？在生活中、工作中，别人做了什么事情让我们得到了满足和愉悦。\u003c/p>\u003cp>请大家用 2 分钟时间讨论一下，现在开始。\u003c/p>\u003cp>\u003cstrong>【2分钟后】\u003c/strong>\u003c/p>\u003cp>好的，2分钟时间到了。我看到张老师讨论得很激烈，我听到都有点小感动。下面请张老师给我们分享一下吧。\u003c/p>\u003cp>\u003cstrong>【邀请分享】\u003c/strong>\u003c/p>\u003cp>张老师：我主要是因为你分享的案例有了共鸣。我就想到我老公也是类似的，门倒了都不扶的。\u003c/p>\u003cp>昨天，我儿子发烧，我跟我老公都不太放心。晚上回来后，我赶紧跑到厨房去做饭了。因为我本身工作很忙，回来也挺累的，还要坚持做饭。我以为我老公正躺在床上刷手机呢。结果他没有这样，而是找到药箱里去找了药拿出来，剥了一颗，跑到厨房，默默地放到我嘴里。我啥都没说呢，我老公说：“小心，别被你儿子传染了。赶紧把药吃了。”\u003c/p>\u003cp>我突然觉得，我当时应该用这种方法表达我的感谢的。其实我很感动的。因为他还想到了我，不仅仅是把儿子放在心里，也把我放在了心里。\u003c/p>\u003cp>非常感谢张老师给我们的精彩分享。如果我们之前了解到这种表达感谢的三个步骤，那么，当时就可以做出描述性的感谢了。\u003c/p>\u003cp>\u003cstrong>六、【A2】催化应用1分钟\u003c/strong>\u003c/p>\u003cp>【拆书技能】【A2】指令清晰。提醒每个学习者都写下了一个包含具体做法，其中包含具体的行动方案，有明确时限和可衡量或可观测预期结果的便签。\u003c/p>\u003cp>\u003cstrong>【指令】\u003c/strong>\u003c/p>\u003cp>我们学习了这三个步骤，那么未来一个月，如果我们遇到类似的情形，我们会怎样运用这三个步骤进行表达感激呢？\u003c/p>\u003cp>请大家花1分钟的时间，把行动写在便签上。\u003c/p>\u003cp>\u003cstrong>七、总结\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【过渡】\u003c/strong>\u003c/p>\u003cp>好的，我看到大家已经写下了具体的行为，为以后表达感激做好了准备。\u003c/p>\u003cp>最后，简单总结一下今天学习的非暴力沟通表达感激的三个步骤：\u003c/p>\u003cp>第一：指出具体行为\u003c/p>\u003cp>第二：说明满足需求\u003c/p>\u003cp>第三：表达自身感受\u003c/p>\u003cp>以上就是我今天的分享，希望今天的学习可以让大家收获到如何运用非暴力沟通表达感激。我的分享就到这里，谢谢大家！\u003c/p>\u003cp>【拆书技能】总时长没有少于10分钟，没有超过15分钟。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1677306042000,"updated_at":1677678244000,"ria":true},{"id":15102,"topic":"确认信息四步法","learn_goal":"","remark":"我们的本意和他人的理解有时可能是两回事。如果不确定，我们就需要提出明确的请求，请对方告诉我们他们听到了什么，以便在有误解的时候做出修正。\n跟随拆书家徐辉一起学习确认信息四步法，解决掉信息误解，让沟通更准确通畅。","level":"TF2-3","duration":20,"status":30,"type":0,"chaishujia":{"username":"徐辉","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好！我是徐辉，我的三个标签是：\u003c/p>\u003cp>1.互联网企业管理 \u003c/p>\u003cp>2.职业生涯规划师\u003c/p>\u003cp>3.职业转型\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>大家在跟随我完成本次ＲＩＡ现场学习后，能够了解使用反馈沟通的方式进行信息确认的四个步骤，在与人沟通时运用这种方法达成准确的信息传递。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F 特征（核心是“书”，用于满足好奇心）：\u003c/strong>\u003c/p>\u003cp>今天我们要一起阅读的拆页来自《非暴力沟通》。\u003c/p>\u003cp>作者是著名的马歇尔.卢森堡博士，他是人本主义心理学家，全球首位非暴力沟通专家。这本书于1963年问世，在这60年中备受追捧，长期在各大排行榜上居个人成长类图书的首位。\u003c/p>\u003cp>\u003cstrong>A 优势（重点是“比较”，用于建立安全感）\u003c/strong>\u003c/p>\u003cp>这本书被誉为是沟通类图书的《圣经》。与其他同类型书籍相比，他几乎可以解决所有因需求未被满足而造成的沟通类难题，和案例相结合，简洁易懂，实操性强，能让我们全面了解，解决冲突，达成良好沟通效果的方法，让我们学会转变谈话和聆听方式，\u003c/p>\u003cp>\u003cstrong>B\u003c/strong> \u003cstrong>利益（强调的是“学习者”的利益，用于引发兴趣）（学完本书可得利益）\u003c/strong>\u003c/p>\u003cp>这本书从十二个方面向我们阐述了如何让我们与他人之间的沟通品质得到提升。提出了与人沟通所需的“观察、感受、需要、请求”四个要素。通过学习这本书，就能帮你转变沟通的思维方式，改善人际关系，管理好自己的沟通能力。\u003c/p>\u003cp>今天拆解的这个片段，运用确认信息的四步法可以帮助我们在与人沟通和交流时，有效确认对方接收到的信息是否是自己要表达的内容，发现差异，及时修正补充。\u003c/p>","ratings_count":1,"texts":[{"id":19110,"quote":"\u003cp>【选择书籍】《非暴力沟通》P83-P84\u003c/p>\u003cp>我们的本意和他人的理解有时可能是两回事。通常我们会在对话中捕捉线索，来确定他人是否理解力我们的意识。但如果不确定，我们就需要提出明确的请求，请对方告诉我们他们听到了什么，以便在有误解的时候做出修正。有时简单地问一句“这样清楚吗”就够了，但有些时候，即便对方说“是的，我明白了”，我们还是无法确保他们是否真正理解了我们的意思。这时我们可以请对方再多回应一些，这样，一旦对方的理解与我们的意思有所不同或者有所遗漏，我们就有机会做出补充。\u003c/p>\u003cp>例如，一位老师和她的学生说：“皮特，我昨天批改作业时没有看到你的作业本。我想和你确认这件事。请你在课后来我办公室一下，好吗？“托尼咕哝着说：“好，我知道了。”便转过身准备离开。这位老师不确定皮特是否准确了解她的意思，便立即请他重述一次：“\u003cstrong>可否告诉我你听到的，我请你做的事情是什么？\u003c/strong>”皮特回答说：“你让我在课后留下来，不能去踢足球，因为你对我的作业不满意。”皮特果然没有听见她要传达的信息，于是她决定重新尝试，并在这一次更加注意自己的表达方式。\u003c/p>\u003cp>诸如“你没有听明白我的话”“这不是我的意思”“你误会了”这样的判断，很容易被他人视为指责。因为皮特很坦率地回应了她，这位老师先向他表达了谢意。她说：“\u003cstrong>谢谢你告诉我你听到我说了什么。我想我说得不够清楚，所以请允许我再试一次\u003c/strong>。”\u003c/p>","explains":"\u003cp>\u003cstrong>What\u003c/strong>\u003c/p>\u003cp>这个拆页给我们介绍了一个怎样避免信息传递出现偏差的方法，也就是在沟通时，要求接收信息的一方重述信息，双方进行确认的方法。\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>\u003c/p>\u003cp>这个方法可以有效避免沟通双方因为理解的偏差造成误会，确保沟通的内容准确有效并且能够顺利往下执行。（这么做的原因和好处）\u003c/p>\u003cp>在生活和工作中，我们经常会碰到某些事情自己觉得已经说得很清楚了，但是到了其他人那里就被误解成另一个意思，不是引起了不必要的矛盾就是要花时间纠偏，即影响心情又影响效率。（不这么做的坏处）\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>\u003c/p>\u003cp>原文案例中描述了老师在和学生的沟通时用了重述和根据重述修正内容两个步骤来纠正沟通信息理解上的差异。为了让大家能更清晰明了地理解这个步骤，我进行了细化，把步骤进行了拆分为四步，具体如下：\u003c/p>\u003cp>１. 观察言行：通过观察对方语言、行为或者表情来判断对方是否听明白了我要表达的意思。\u003c/p>\u003cp>２. 请求复述：请求对方复述一下他理解的意思，比如：你可以重述一下我刚才说的话吗？\u003c/p>\u003cp>３. 回馈感谢：当对方对我们说的话进行了复述给出了反馈后，我们要本着平等尊重的原则来感谢对方。比如：看着对方的眼睛，微笑并真诚地说：“谢谢你给我的反馈”。\u003c/p>\u003cp>４. 补充修正：反馈会有两种可能性\u003c/p>\u003cp>第一种，如果对方给出了正确的反馈，我们可以说：“听完你刚才的复述，感谢你完全理解了我的意思。”来结束这次沟通。\u003c/p>\u003cp>第二种，如果对方没有理解我们的意思，不要指责对方，更不能用否定的话去纠正，这种表达会让对方产生抵触情绪，无法平和地沟通下去，可以调整为：“我想是我说的不够清楚，我的意思是…。”\u003c/p>\u003cp>\u003cstrong>Where\u003c/strong>\u003c/p>\u003cp>这个方法适用于工作和生活中，与信息接收能力不足、经常出现鸡同鸭讲状况的人进行沟通的场景，以及需要传递重要信息不能出现偏差的场景。在与长辈和领导沟通时不适用，会显得冒犯。\u003c/p>\u003cp>\u003cstrong>【例子】\u003c/strong>\u003c/p>\u003cp>其实这种情况在我的工作中还挺常见的，上周，我想起之前布置的一个统计表应该到提交日期了，但由于战略调整，我想在数据当中增加一项新的统计类目，就给负责这项工作的下属打了个电话：“那个统计表我要调整一下，你下午来趟我办公室”，他声音低沉地回答了声：“好的”，我当时就觉得他语气不对头。跟了一句“你理解我说的意思了没，你重复一下我听听。”他说：“领导，我们基本上都弄完了，就剩二次复核就能提交了，你这是要推翻重做吗？那要想按时交，得牺牲在岗位上了”。一听这话，就知道他误解了我的本意，我赶紧说：“感谢你直言不讳地反馈了你的理解，我应该是没说清楚，我不是想推翻重来，就是想在后边增加一列类目，你们前面数据完整的话，公式可以直接设定拉出数据，不影响你们的效率”。\u003c/p>\u003cp>你看，一个平平常常的小对话都有可能造成信息误解，可见这个方法和我们是息息相关的，那我们学习了就要用起来，下面我们运用刚才学习到的信息确认四步法进行一个现场讨论和演练，以便我们在今后遇到类似场景可以使用起来。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3现场演练】\u003c/strong> \u003c/p>\u003cp>\u003cstrong>场景设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【场景描述】\u003c/strong>\u003c/p>\u003cp>元旦上班第一天，办公室里，行政主管老李给新来的小李安排工作：\u003c/p>\u003cp>老李：你把2022年全年的合同，按照部门分类，每个部门里面分成业务工作、日常工作、专项工作三部分，最后进行编号、登记、归档。\u003c/p>\u003cp>小李点了点头：“好的，我知道了”。\u003c/p>\u003cp>正准备转身离开，老李叫住了她......\u003c/p>\u003cp>\u003cstrong>【发出指令】\u003c/strong>\u003c/p>\u003cp> 好，下面给大家进行分组，请小伙伴们在小组内，一人扮演老李，一人扮演小李，应用今天学到的“确认信息四步法，用观察言、请求复述、回馈感谢和补充修正这四步来演练老李和小李接下来的对话。来确认小李是否理解了老李表达的内容。\u003c/p>\u003cp>5分钟练习后，我会邀请小伙伴来分享对话。\u003c/p>\u003cp> 哪组伙伴愿意和大家分享一下你们的对话？\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>第一组：\u003c/p>\u003cp>琛君（老李）: 小李，新年快乐，咱们新年过完了，2022年的合同，需要归档，这个事儿呢，就麻烦你来负责。就按照部门先分个大类，然后每个部门的工作，业务工作、日常工作、专项工作再进行分类。最后把合同进行一下编号、登记、归档好吗？\u003c/p>\u003cp>欣艾（小李）：好的，我知道了。\u003c/p>\u003cp>琛君（老李）: 好，那你帮忙确认重复一下，看看咱们对这个工作的标准，咱俩理解的是不是一样的。\u003c/p>\u003cp>欣艾（小李）：好的领导，您看我理解对不对，就是把去年一年所有的合同共12个月的，按照部门分类，比如说按照人力资源部，客服部，技术部，销售部等等，按照部门分类是大的分类，然后在部门分类后再进行小分类，比如刚才说的客服部，再把客服部的合同分成三类，就是小分类，就是跟客户签合同的业务工作，还有日常的工作分类，还有一些专项项目工作合同，分为这三种合同。把这些合同进行编号，然后我登记下来，登记完了以后，再归档到我们的档案室，这样后面再查找就很便捷。我理解对吗？\u003c/p>\u003cp>琛君（老李）: 说的特别好，感谢你的反馈，那这工作就交给你了，过程中有啥问题咱们多沟通。\u003c/p>\u003cp>欣艾（小李）: 嗯，好的没问题。\u003c/p>\u003cp>第二组：\u003c/p>\u003cp>嘟噜（老李）：小李啊，2023年来了，2022年的这个合同也该归档了，你看这周你就做这个事情吧，把2022年的合同按照部门分类，每个部门儿里边儿分成业务工作，日常工作和专项工作三个部分，把这个合同编一下号，最后登记归档，你看行吗？\u003c/p>\u003cp>恩美（小李）：好的，我知道了。\u003c/p>\u003cp>嘟噜（老李）：小李，咱这个元旦假期可能放假也时间比较长，你再重复一下咱们刚刚这个任务吧，我担心时间太长了，咱们有点儿忘记这个工作怎么做了，毕竟一年也没整理了，你重复一下刚才这个事情。\u003c/p>\u003cp>嘟噜（老李）：好的，主要的任务呢，就是要整理2022年全年合同。整理的方式呢，就是按照部门来分类，同时呢，每一个部门里边又要分成三个部分，最后要进行一个归档。\u003c/p>\u003cp>嘟噜（老李）：嗯，谢谢小李，谢谢你复述了这个工作步骤和内容，那我觉得我可以给你再补充一下，咱们每个部门分的三个类别，是业务工作，日常工作和专项工作，然后归档之前呢，还要进行两个重要的步骤，是做编号和登记，那编号，咱们就在文件夹前面，按照这个合同签订日期来编，这样这个合同的文件就会比较整齐和清晰。那登记呢，就以咱之前的Excel表格的形式，上传到公司的网站上面。然后归档呢，你那边存一份，也发给我这儿存一份。\u003c/p>\u003cp>恩美（小李）：好的，这项工作有截止日期吗？\u003c/p>\u003cp>嘟噜（老李）：你下周一给我就可以了，合同还是比较多的。\u003c/p>\u003cp>恩美（小李）：好的领导。\u003c/p>\u003cp>\u003cstrong>【总结回顾】\u003c/strong>\u003c/p>\u003cp>以上就是我们今天学习的内容，来自《非暴力沟通》P83-P84，我们学习了怎样使用观察言行、请求重述、表达感谢和补充修正四个步骤进行反馈式沟通，希望大家在未来需要的沟通场景中加以应用，提升自己的沟通能力，成为沟通高手。\u003c/p>\u003cp> 以上就是我今天拆解的片段，希望对大家有所帮助，感谢大家的聆听！谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1674220976000,"updated_at":1675310133000,"ria":true},{"id":14894,"topic":"非暴力沟通表达感激","learn_goal":"","remark":"家通过今晚的学习，可以掌握如何更好的表达感谢，感激，让感谢更有温度。","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"李墨染","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>【分组】\u003c/p>\u003cp>等会有个讨论环节，为了更方便讨论，我们先来分组，根据人数我们就分成两组。\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>各位老师晚上好，我叫李墨染，木子李，“烟雨入江南，山水如墨染”的墨染。三个标签介绍我自己1.常州龙城分舵新进拆书会员2.创业两年的初级创业者3.自我管理实践者\u003c/p>\u003cp>【图书介绍】 \u003c/p>\u003cp>今天和大家拆解的这本书叫《非暴力沟通》作者马歇尔 卢森堡博士是非暴力沟通中心创始人，全球首位非暴力沟通专家，有着50多年的实践经验。《非暴力沟通》这本书2003年出版被选入香港大学推荐的50本必读书籍，被樊登老师称为是《关键对话》的升级版，这两本书里面的对话逻辑有类似的地方，但是《非暴力沟通》这本书写的更加深刻。\u003c/p>\u003cp>【过渡语】\u003c/p>\u003cp>接下来请大家花1分钟的时间阅读原文拆页，阅读完的可以在评论区扣1,示意我一下。\u003c/p>","ratings_count":3,"texts":[{"id":18910,"quote":"\u003cp>【R阅读原文拆页】《非暴力沟通》P179 用非暴力沟通表达感激\u003c/p>\u003cp>用非暴力沟通的方式表达感激时，我们只是为了庆祝他人的行为提升了我们的生活品质，而不是想得到任何回报。\u003c/p>\u003cp>非暴力沟通表达感激的方式包含三个部分：\u003c/p>\u003cp>1.对方做了什么事情使我们的生活得到了改善\u003c/p>\u003cp>2.我们有哪些需要得到了满足；\u003c/p>\u003cp>3.我们的心情怎么样？\u003c/p>\u003cp>在表达感激时，这三个部分的先后次序并不重要；有时，我们甚至可以通过微笑或说声“谢谢”来表达这三个部分。然而，如果我们要确保对方能够明白我们的意思，那么，用语言具体地描述这三个部分是值得的。\u003c/p>","explains":"\u003cp>【过渡语】好，我看到大家都有读完，下面请跟随我学习原文拆页\u003c/p>\u003cp>I便签：\u003c/p>\u003cp>What：这个片段讲了什么方法和概念？\u003c/p>\u003cp>这个片段讲了如果我们能够在平时运用非暴力沟通的三个步骤来表达感谢代替“谢谢”两个字，这样能让我们的感谢显得具体，对方也能清楚明白我们表达的意思。\u003c/p>\u003cp>Why：这个方法对我有什么用？\u003c/p>\u003cp>我们平时表达感谢都是简单的说声“谢谢”听着平淡无味又略带敷衍的感觉，像是为了“谢谢”而“谢谢”。用了非暴力沟通表达感激的方法这样做的好处是对方能够让被感谢的人感受到满满的诚意和温暖，这样的表达更加的生动具体，瞬间提高了我们的语言表达、思维能力和情商，锻炼我们善于发现别人的优点，激发我们的善意，心情愉悦，发现生活的美好，从而获得幸福感。\u003c/p>\u003cp>How：这个方法怎么用？\u003cbr>第一步：具体说明：说明对方做了什么事让我们的生活得到了改善？\u003c/p>\u003cp>第二步：满足需求：说明我们哪些需求得到了满足\u003c/p>\u003cp>第三步：表达心情：表达我们的心情怎么样？\u003c/p>\u003cp>Where：这个方法的适用边界？\u003c/p>\u003cp>这个方法适用于有一个短暂的停留或者相处了一段时间为前提的表达感谢，因为如果是即时的帮助恐怕也没有过多的时间让你去这样表达。\u003c/p>\u003cp>1. 我家一直都是我父亲做饭，不要说感谢了，有时候菜烧的好夸一下：今天菜口味不错，有时候会抱怨菜有点咸了，今天的菜不合口味等等。如果用上非暴力沟通来表达感激效果一定会不一样：\u003c/p>\u003cp>1.具体说明：您在家为我们做美味可口的饭菜，让我们不用为买菜做饭而伤脑筋。\u003c/p>\u003cp>2.表达满足：省去了我们做饭的时间，让我们吃的舒心吃的健康。\u003c/p>\u003cp>3.表达心情：让我体会到了家的温馨，满满的幸福感，感到非常的开心。\u003c/p>","interaction":"\u003cp> 【A1指令】\u003c/p>\u003cp>现在我们读完这个拆页，我也分享了1个例子，接下来，每个人跟组内的小伙伴一起，想想你们自己有没有经历过类似的情境，在过往的工作或者生活中，别人做了什么事情，让你运用到类似的方法进行感谢，也可以是你原本可以很好的表达感谢但是没有去表达的，只是简单的说声“谢谢”。给大家时间3分钟的时间讨论一下，最后我选一个代表进行分享。\u003c/p>\u003cp>【案例记录】\u003c/p>\u003cp>都讨论了，然后我们每个小组请一个，小伙伴分享一下吧。\u003c/p>\u003cp>分享者叫露娜，是一位中学老师：\u003c/p>\u003cp>案例1：有一次外出开会，一直到晚上有匆匆赶回去，因为担心早上学生送的作业还没来得及批改，然后还有其他作业要布置，然而两个课代表已经把作业改完并让组长发下去让组员订正了，知道结果后的老师非常的开心就和他们说：啊，你们今天你们今天可帮了我一个大忙了，你们的作业已经让我一整天不能安心了啊。你们你们要是能早点告诉我的话，我会更开心的，然后说你们以后要是再有这样的事情，你会怎么做啊？最后，被夸奖的两位小朋友也开心得不得了。\u003c/p>\u003cp>案例2：第二位老师分享了最近刚发生的事情，就是两个人在家都阳了，在这期间老公生着病还依然无微不至的照顾她，她认为是理所当然的，后来自己带病做了一次饭之后就体会到了老公的不容易，正好通过这次的学习她决定回去运用这个方法感谢一下老公。\u003c/p>\u003cp>【A2指令】\u003c/p>\u003cp>我发现能够运用到非暴力沟通表达感激的场景有很多，现在请拿出一张便签，在接下来的这一周或者一个月内如何应用今天所学习的非暴力沟通表达感激。\u003c/p>\u003cp>写完之后，如果时间够的话我再请一位小伙伴给大家分享一下~\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>最后做一下总结，今天主要学习了非暴力沟通表达感激。\u003c/p>\u003cp>第一步：具体说明\u003c/p>\u003cp>第二步：满足需求\u003c/p>\u003cp>第三步：表达心情\u003c/p>\u003cp>希望今天的学习可以让大家收获到如何运用非暴力沟通表达感激，我的分享就到这里感谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1671846293000,"updated_at":1671874910000,"ria":true},{"id":14888,"topic":"学会在日常生活中运用非暴力沟通的四个要素","learn_goal":"","remark":"大家通过今晚的学习，可以掌握非暴力沟通的基本逻辑，沟通的方式方法，掌握一种更高效的沟通方法。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"李墨染","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>各位老师晚上好，欢迎参加常州龙城分舵线上的拆书学习，我叫李墨染，木子李，“烟雨入江南，山水如墨染”的墨染。三个标签介绍我自己1.常州龙城分舵新进拆书会员2.创业两年的初级创业者3.自我管理的实践者\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>拆书法是一种成人学习法，强调以学习者为中心，而不是知识为中心，是一种以解决问题为目标的成人学习。要把知识关联学习者的经验、规划具体的运用。\u003c/p>\u003cp>“拆书”的“拆”不是“拆散”而是转化，内化知识的一种方式。“拆书”强调的是把书籍里面的知识转化为学习者的能力。“拆书”分为个人学习拆书法和组织学习的拆书法：个人学习的应用是便签法，让人读一本书就能达到参加同主题培训的效果；组织学习的应用是以为拆书家那一本书加工成一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>拆书帮是基于拆书学习爱好者组成的非营利性青年自组织，其体现的形式是在各地开展的拆书帮分舵，其使命是帮助更多的学习爱好者成长为拆书家。\u003c/p>\u003cp>【过渡语】\u003c/p>\u003cp>今天由我来带领大家拆解《非暴力沟通》这本书里面的其中一个片段，非暴力沟通的四个要素。下面给大家一分钟的时间阅读，阅读完的可以在评论区扣1示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":18904,"quote":"\u003cp>【R阅读原文拆页】\u003c/p>\u003cp>非暴力沟通的要素\u003c/p>\u003cp>为了彼此能乐于互助，我们专注于四个方面——非暴力沟通模式的四个要素。\u003c/p>\u003cp>首先，留意发生的事情。我们此刻观察到什么?不管是否喜欢，只是说出人们所做的事情。要点是，清楚地表达观察结果，而不判断或评估。接着表达感受,例如受伤、害怕、喜悦、开心、气愤等等。然后，说出哪些需要导致那样的感受。一旦用非暴力沟通诚实地表达自己，前三个要素就会得到体现。\u003c/p>\u003cp>举例来说，一位母亲可能对她处于青春期的儿子说：“费利克斯，看到咖啡桌下的两只脏袜子和电视机旁的三只，我不太高兴，因为我看重整洁。”\u003c/p>\u003cp>接着，她立即提出非暴力沟通的第四个要素——具体的请求:“你是否愿意将袜子拿到房间或放进洗衣机?”这一要素明确告知他人，我们期待他采取何种行动，来满足我们。\u003c/p>\u003cp>这样，这位母亲就清楚地说出非暴力沟通的四个要素。借助这四个要素诚实地表达自己，是非暴力沟通的一个方面。非暴力沟通的另一方面是借助它们关切地倾听。我们首先通过体会他人此刻的观察、感受和需要，与他们建立联系，然后聆听他们的请求，来发现做什么可以帮助他们。\u003c/p>","explains":"\u003cp>【过渡语】好，我看到大家都有读完，下面请跟随我学习原文拆页\u003c/p>\u003cp>What：这个片段讲了什么方法和概念？\u003cbr>这个片段和我们讲了利用非暴力沟通的四个要素，我们需要诚实的表达自己同时也能很好的倾听他人与他人建立联系，从而达到相互帮助相互成就的目的。\u003c/p>\u003cp>✨Why：这个方法对我有什么用？\u003cbr>这种沟通的方式能使我们心存爱意，心存善意，比起一味的指责、批评或是责怪。非暴力沟通无疑是一种更好的沟通方式，如果我们用指责、批评的方式，会立马的触发对方自我保护意识的开关，对方会立刻反驳，甚至恼羞成怒。而运用非暴力沟通的方式无论是表达自己还是倾听他人都是一个好的开始，别人至少会愿意倾听，因为他得到了应有的尊重，伸手不打笑脸人，通常情况下我么也不会和一个心存善意的人乱发脾气…\u003cbr>✨How：这个方法怎么用？\u003cbr>四个要素分别为：\u003c/p>\u003cp>1.描述事实：说出所观察到的结果，并且不做判断或评估。\u003c/p>\u003cp>2. 表达感受：诚实的表达感受，例如：害怕、、受伤、气愤、喜悦、开心。\u003c/p>\u003cp>3.说出需要:我们之所以有第二要素的感受有害怕、受伤、气愤、喜悦、开心等是因为我们的这些感受没有被满足，我们需要把它表达出来。\u003c/p>\u003cp>4.具体请求：明确的告知他人，我们期待他采取什么样的行动，可以满足我们的需要。\u003c/p>\u003cp>✨Where：这个方法的适用边界？\u003cbr>无论自我对话、与人交谈，还是小组讨论，非暴力沟通都能使我们心存 \u003c/p>\u003cp>爱意。因此，它适用于各个层面的交流和各种环境。例如：家庭、学校、工作单位等。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>例子1：\u003c/p>\u003cp>我家里人总会在我的书橱里面放一些杂物，导致我的书橱很乱，我会直接指责：你们把我的书橱里放一些杂物，搞的整个书橱乱七八糟的····他们就会说你平时又不在家，书橱放的也是平时能用到的东西····\u003c/p>\u003cp>例子2：\u003c/p>\u003cp>最近的热门话题都是你有没有阳，身边的人有没有阳，无一例外，我们家都阳了，疾控中心给我爸打电话让他跟社区报备，社区的人就让他把信息通过微信发给她，他身体不舒服手机操作也比较慢，就由我来帮他编辑发送，发送完手机给他，他很激动的指责说：你怎么把信息发群里了？我被他说的很懵，我明明是搜索名字发送的怎么会发群里呢？我说你再看清楚，他再次确认之后就不说话了。\u003cbr>✨反思：\u003cbr>如果我们不能够心存善意的和别人沟通不但不能解决问题，还容易将矛盾激化，伤害彼此的感情。\u003cbr>\u003cbr>A2:通过学习以上片段我决定将学习到的知识运用起来。\u003c/p>\u003cp>1. 目标：运用非暴力沟通的四要素和家里人进行一次对话。\u003cbr>行动：\u003cbr>利用本周在家休息的时间和家里人就书橱的事情运用非暴力沟通的四个要素进行一次对话\u003c/p>\u003cp>1.你们把我书橱里放了很多杂物（事实），\u003c/p>\u003cp>2.这让我看起来很不舒服（感受），\u003c/p>\u003cp>3.书橱是放书的地方，我希望能干净整洁一点（需求），\u003c/p>\u003cp>4.麻烦可以把这些杂物归类放在它应该放的位置（请求）。\u003c/p>\u003cp>[结束语]\u003c/p>\u003cp>最后做一下总结，今天主要学习了非暴力沟通的四个要素。\u003c/p>\u003cp>1.描述事实\u003c/p>\u003cp>2.表达感受\u003c/p>\u003cp>3.说出需要\u003c/p>\u003cp>4.具体请求\u003c/p>\u003cp>希望今天的学习可以让大家收获到如何运用非暴力沟通的四个要素，我的分享就到这里感谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1671789355000,"updated_at":1671853338000,"ria":true},{"id":14524,"topic":"用非暴力沟通的方式表达感激","learn_goal":"","remark":"晋级","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"米老鼠vera","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>\u003cstrong>请问观察家老师拿到记录表、准备表和拆页了么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请问各位小伙伴都拿到我的拆页了么？好，现在正式开始今天的晋级。\u003c/strong>\u003c/p>\u003cp>自我介绍：大家好，我是周玲，我是一个特别感激自己的人，为什么呢？因为我可以为了留更多学习时间，而在初入职场的第一个月就独自在公司通宵加班完成一些前员工的遗留问题；我还在面试新工作时，毫无压力的与新领导手舞足蹈的谈论了3个多小时并拿下offer；我也在新婚后抛下老公一个人去巴厘岛度假。这些人生种种让我感受到快乐、自信、自由和满怀希望，因为我一直都在努力寻找和实现自我价值和进行友好社交。\u003c/p>\u003cp>【分组】由于今天有讨论环节，所以我们先分一下组。但是由于今天人员不多，咱们就不分小组了，就一个大组。\u003c/p>\u003cp>今天给大家分享的拆页选自2021年最新修订版的《非暴力沟通》，作者是美国的马歇尔·卢森堡。\u003c/p>\u003cp>\u003cstrong>Feature\u003c/strong>\u003c/p>\u003cp>本书向我们展示了一种人与人之间的和谐的沟通方式。它不仅仅指沟通中用不带伤害的方式的好好说话，更是一种美妙的生命语言，让我们拥有爱的能力去撑起生命中的各种关系，引导我们去思考和践行：我究竟想怎样与世界上的其他人相互联系呢？\u003c/p>\u003cp>\u003cstrong>Advantage\u003c/strong>\u003c/p>\u003cp>· 非暴力沟通不仅教会人们如何使个人生活更加和谐美好，同时解决了众多世界范围内的冲突和争端。所以，它被联合国教科文组织列为全球正式教育和非正式教育领域非暴力解决冲突的最佳实践之一。 \u003c/p>\u003cp>· 目前中文版书籍已经发行超过200万册；\u003c/p>\u003cp>· 它在当当的人际交往畅销榜是第一名；\u003c/p>\u003cp>· 樊登读书超过6000万人次阅读量；\u003c/p>\u003cp>· 喜马拉雅上超过1000万人次点播收听；\u003c/p>\u003cp>· 微信读书也有超过100万人阅读。\u003c/p>\u003cp>\u003cstrong>Benefit\u003c/strong>\u003c/p>\u003cp>今天想要跟大家分享的片段就是书中的用非暴力沟通的方式来表达感激。学习完之后，我们将掌握如何使用3个要素来正确表达感激的方法，真正提升我们与他人的正向积极关系。\u003c/p>","ratings_count":1,"texts":[{"id":18530,"quote":"\u003cp>\u003cstrong>下面请大家花2分钟的时间阅读拆页，读完后请举手示意我。\u003c/strong>\u003c/p>\u003cp>当我们用非暴力沟通来表达赞赏和感激时，纯粹是为了庆祝生命，不为获取任何回报。我们唯一的意图就是去庆祝他人的作为如何使我们的生命变得更加丰盛。\u003c/p>\u003cp>在使用非暴力沟通表达感激时，我们会清楚地包含以下三个要素:\u003c/p>\u003cp>· 他人做了什么增进了我们的福祉。\u003c/p>\u003cp>· 我们有哪些需要因此得到了满足。\u003c/p>\u003cp>· 因为这些需要得到了满足，引起了我们什么样的愉悦感受。\u003c/p>\u003cp>· \u003c/p>\u003cp>表达这三个要素时，并不一定要遵照以上的顺序。有时哪怕是一个微笑或一句简单的“谢谢你”就足以传递这一切。不过，如果我们想要确保对方能够充分收到我们的心意，用语言完整地表达这三个要素是有意义的。\u003c/p>","explains":"\u003cp>\u003cstrong>好，我看到大家已经看完拆页了。接下来，我分享一下自己的理解和体会。\u003c/strong>\u003c/p>\u003cp>【WHAT】片段告诉了我们如何使用非暴力沟通的方式，不图回报的向他人纯粹的表达我们的感激之情。\u003c/p>\u003cp>【WHY】沟通的目的一定是达到人际关系的和谐，并促进相互发展。首先呢，我觉得每一份善意都值得被尊重与感激，及时和他人一起庆祝这份善意，让自己更加体验到生命的美好，同时也避免出现对重要之人没有表达感激的懊悔。\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>片段告诉我们，在表达感激的时候要清晰的包含以下3个要素：\u003c/p>\u003cp>1. 说出他人做的具体什么行为，让我有了比较好的感受。（你把我们想了解的问题都写进了报告里vs你这份报告做的真好）\u003c/p>\u003cp>2. 这件事使我的哪些需求得到了满足？（我们常常只表达谢谢别人的什么，却忽略或不愿意明确说出别人帮助我们实现了什么。“谢谢你帮我倒了一杯水，谢谢你给了我一个面包”，这其实让对方听了感谢后并不能真正感受到赞赏的真诚性，听起来就像一个随意的口头禅）\u003c/p>\u003cp>3. 当我的需求得到满足后，我现在的心情感受怎么样？（除了简单的说个“谢谢”，我们去使用更多的表达感受的词汇，是可以让感激更加生动贴切。例如：满足、受启发、自豪、信赖、期待、舒适等等）\u003c/p>\u003cp>当我们表达感激的时候，将上面这3个要素都表达出来，不一定按顺序，只要包含了3个要素就行。相信接收感激的对方一定会感受到我们的真诚。\u003c/p>\u003cp>【WHERE】如果想更大的拓展自己的人生宽度，不希望对重要之人有所遗憾，就大胆的去表达自己的感激，有进有出才是正向循环。但是这份感激的表达一定不能是以控制对方为目的，一旦感激带有索取回报之意，它就一定会失败的，因为虚假煽情并不是人际关系的正向沟通。\u003c/p>","interaction":"\u003cp>好了，以上就是我对于片段内容的一些分解，现在我们应该知道了，当想要表达感激的时候，一定要记得真心诚意的、纯粹的利用非暴力沟通的方式。现在请大家想想自己有没有过类似表达感激成功或者失败的沟通经历呢？接下来请大家配合完成以下练习： \u003c/p>\u003cp>1. 请大家在小组内相互分享过去的一次经历\u003c/p>\u003cp>2. 每人1分钟时间进行分享，而且必须分享哦\u003c/p>\u003cp>3. 小组内分享完成后，请选出一个代表进行当众分享\u003c/p>\u003cp>好，时间到，下面我们请这位伙伴进行分享，大家欢迎。\u003c/p>\u003cp>\u003cstrong>学习者案例记录\u003c/strong>：\u003c/p>\u003cp>【实录1】：今年我过生日的时候，妈妈给我打电话想祝福我，我就是简单的说了句“谢谢”，但其实我是想更加真心、完整的表达出我的感激，我也希望妈妈能够感受到我的真心，而不是觉得我在敷衍的回复，可是当时不知道应该可以怎样去表达。\u003c/p>\u003cp>【实录2】：昨天我的女儿发现我没有吃早餐，她就主动给我一个馒头让我吃，我也是很随意的说了句谢谢，现在想想我还是真的应该向孩子表达清楚这份感激，让她可以明白妈妈是真心认真的在看待她的这个行为，希望她可以感受到行善的力量。\u003c/p>\u003cp>【实录3】：上个月我们参加一个视频比赛，当时有个老师借给了我们很多器材，同时也给了我们很多指导，我们整个过程内心其实是非常感谢他的，可是我们在表达的内容上说的很简单。我其实觉得这样不是很妥当，也有些遗憾。\u003c/p>\u003cp>\u003cstrong>（拆书家提问设计）\u003c/strong>\u003c/p>\u003cp>好，非常感谢这位小伙伴的分享。接下来，我们就规划一下，在不久的将来，怎样运用今天学习的使用非暴力沟通的方式表达感激。\u003c/p>\u003cp>我会给大家2分钟的时间，把行动规划写到便签纸上。\u003c/p>\u003cp>注意要符合以下格式：\u003c/p>\u003cp>\u003cstrong>我计划在未来的什么时间期限内（最好是一两个星期以内），在什么样的场景下，运用非暴力沟通的方式表达感激，想要达到什么样的效果，注意这个效果一定要是运用我们今天讲的方法去达成的，并且是可以达成的哟。\u003c/strong>\u003c/p>\u003cp>写完的小伙伴请举手示意我。\u003c/p>\u003cp>\u003cstrong>（学习者案例记录）：\u003c/strong>\u003c/p>\u003cp>【实录1】：我计划用一周时间，利用非暴力沟通表达感激的内容，每天写一封感激信给我的朋友或家人，并得到他们的反馈，并且他们的反馈信息中不能表现有压力，也不能有反击我的意图的反应。我大致会这样写“xx，您在xx(时间)做了XX这样一件事，我真的感觉很xx，因为我确实需要xx”。\u003c/p>\u003cp>【实录2】：我计划在下个月过生日的时候，用非暴力沟通的方式去表达对妈妈的感激，我会这样说“妈妈，谢谢你给了我生命，因为这样我才能来到世界上感受到这么多真实的存在，我真的觉得太幸福了”。希望在我表达完感激以后，妈妈也会很认真的回复些心里话，而不是只有一句生日快乐后就挂了电话。\u003c/p>\u003cp>【实录3】：我计划在一周以内，重新整理好想对那位老师的所有感激（包括他所做的事，我们的感受，帮助我们达到了什么目标），找到合适的时间，给老师打电话去进行表达感激。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>以上就是我今天分享的使用非暴力沟通的3要素内容去表达感激，即对方做了什么，我对此有何感受，以及这满足了我的哪些需求。\u003c/p>\u003cp>希望这个方法可以帮助到大家去提升与他人的正向积极关系。\u003c/p>\u003cp>我的TF1-2晋级就到这里，感谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1667835560000,"updated_at":1667970288000,"ria":true}]};